INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 15, 'ruRU', 'Здравствуй, Морган!\r\n\r\nДела в Златоземье идут бойко, так бойко, что у меня не было времени отправить тебе товар! \r\n\r\nЯ нанял человека, который принесет эту записку, доставить тебе пачку больших восковых свечей (тех, что кобольды обычно носят на голове). \r\n\r\nБудь добр, отблагодари этого человека и заплати ему как следует.' FROM `page_text` WHERE `ID`=15 AND MD5(`Text`)='04ba0a66c27f2242e94318d9acd382cb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=15 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 16, 'ruRU', 'Досточтимый директор Криллиан!\r\n\r\nНаставник, я пишу вам затем, чтобы поведать о своей нынешней жизни. Прислушавшись к вашему совету, я покинул наш любимый Штормград в поисках знаний. Во время своих странствий я побывал во многих местах, но решил остановиться в славном городке Луноречье. С приближением жатвы поля Западного Края становятся особенно красивы...' FROM `page_text` WHERE `ID`=16 AND MD5(`Text`)='228f0813b59a6cfb494908137c350ec8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=16 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 17, 'ruRU', 'Прибыв в этот городок, я уже через несколько дней стал учить местных детишек с близлежащих ферм. Уроки проходили так успешно, что местный глава города поручил мне организацию школы, и строительство здания уже началось! Я прошел от Серебряного бора до Штормграда, и вот сейчас живу в Луноречье – кто бы мог подумать, что я обойду чуть ли не пол-Азерота?\r\n\r\nС наилучшими пожеланиями,\r\n\r\nСталван Мистмантл' FROM `page_text` WHERE `ID`=17 AND MD5(`Text`)='95838e60f55f445043010828c7c5facf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=17 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 18, 'ruRU', 'Досточтимый господин!\r\n\r\nДо меня дошли слухи, что вы ищете учителя для своих детей. Сейчас я остановился в Златоземье, в таверне "Гордость льва" – из-за произошедших в регионе событий мне пришлось покинуть пост директора школы в Луноречье. Я хотел бы стать учителем ваших детей. При необходимости вы можете поговорить с директором Академии Крилланом о моей компетентности.' FROM `page_text` WHERE `ID`=18 AND MD5(`Text`)='3f98f7730801d5a2bf002ab247e6656e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=18 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 19, 'ruRU', 'Я приеду, чтобы лично с вами встретиться, когда зимние ливни закончатся и по дорогам снова станет можно ездить.\r\n\r\nС уважением,\r\n\r\nСталван Мистмантл из Серебряного бора' FROM `page_text` WHERE `ID`=19 AND MD5(`Text`)='6f80936c4797ad3642677eceed732908' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=19 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 20, 'ruRU', '...Джайлс, мальчик, показался мне непослушным, с его обучением, возможно, будут проблемы. А вот девочка постарше, Тиллоа, – исключительно сообразительный ребенок. Я также обратил внимание на ее пленительную красоту. Она уже превращается из подростка в женщину. Господин, кажется, в будущем году собирается выдать ее замуж... Но я что-то отвлекся. На этой неделе я отправлюсь со всем семейством в летний домик рядом с Лесопилкой Восточной Долины в Элвиннском лесе, это совсем недалеко от Красногорья. Рассчитываю там продолжить работу.' FROM `page_text` WHERE `ID`=20 AND MD5(`Text`)='8d6c0fe77bdf6c0b29bec63106704624' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=20 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 21, 'ruRU', '...какое странное и неконтролируемое чувство. Я никогда еще не чувствовал ничего подобного. Пока я занимался с Джайлсом историей, Тиллоа прогуливалась в палисаднике снаружи. Через несколько минут она вернулась к нам, положила мне в ладонь ярко-красную бегонию и так улыбнулась мне, что у меня чуть сердце не выскочило из груди...' FROM `page_text` WHERE `ID`=21 AND MD5(`Text`)='1517212a0f267e78da27e9fa8d41ef35' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=21 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 24, 'ruRU', '...жизнь мне не мила. Сначала она надо мной потешалась – и вот уже обручена. Жестокая обманщица притворялась, что любит меня, а на самом деле хотела надо мной поиздеваться. Меня переполняет злоба, и с каждым днем она становится все сильнее. Кровь, что вот-вот прольется, – ничто в сравнении с количеством выплаканных мной слез...' FROM `page_text` WHERE `ID`=24 AND MD5(`Text`)='ce7c8a76c5bb13f10c3818ec0958da1e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=24 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 25, 'ruRU', 'Томми Джо -\r\n\r\nМое сердце увядает с каждой минутой, проведенной вдали от тебя. Ах, если бы только наши родственники могли забыть о своей глупой вражде и преступлениях и понять, что единственное настоящее преступление – это их взаимная ненависть! Ненависть убивает, и, боюсь, в это тяжелое время она овладеет не только нашими семьями.\r\n\r\nЕсли они это поймут, мы сможем быть вместе. Надеюсь, так оно и будет, я живу мечтами об этом.\r\n\r\nС любовью,\r\nМэйбелл' FROM `page_text` WHERE `ID`=25 AND MD5(`Text`)='49218d209ddabe8b6b66fae8ef958f3d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=25 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 28, 'ruRU', 'Аргус, как тебе известно, я сейчас занимаюсь различным ремонтом в армии. Работа спорится, но вот мои запасы железа иссякли.\r\n\r\nУ меня не хватает материалов на подковы. Зная, что ты всегда хранишь большой запас, хочу одолжить у тебя 50 пар, пока я не получу следующую партию железа.\r\n\r\nЗаранее благодарю,\r\n-Вернер' FROM `page_text` WHERE `ID`=28 AND MD5(`Text`)='dd0d57ac8df3f5f342b19bcf715a6b94' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=28 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 29, 'ruRU', 'К ящику прилагается записка. В ней значится:\r\n\r\n"Вернер, грустно слышать, что в Красногорье нехватка ресурсов. Вот подковы, которые ты просил. Когда будет возможность, пришли мне 100 серебряных монет."\r\n\r\n"Или, если хочешь, можешь расплатиться брюшной чешуей детенышей черного дракона (слышал, что в Красногорье их полно). Так как ты мой друг... Четырех чешуек будет более чем достаточно. Благодарю. -- Аргус"' FROM `page_text` WHERE `ID`=29 AND MD5(`Text`)='d8acf31d0c27e0166f7177232cb624eb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=29 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 30, 'ruRU', 'Господин мой!\r\n\r\nВойна близко. Злой рок стучит нам в двери.\r\n\r\nЯвляясь чиновником магистрата города Приозерье, считаю своим долгом сообщить вам о недавнем вооруженном столкновении в крайней восточной колонии Его Величества.\r\n\r\nНиже вы найдете рассказ об Озерном государстве, что лежит среди отрогов Красногорья.' FROM `page_text` WHERE `ID`=30 AND MD5(`Text`)='83f6b6c027a9a1deb7889268c6143a0d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=30 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 31, 'ruRU', 'Потеря крепости Каменной Стражи стала для нас сильным ударом. Я уже сообщал ранее о союзе между орками Черной Горы и колдуном Моргантом. Эти орки сражаются с наводящим ужас неистовством, и, похоже, здесь не обошлось без черной магии Морганата. Храбрейшие из воинов его Величества отдали свои жизни при обороне крепости, но поражение было неминуемо.' FROM `page_text` WHERE `ID`=31 AND MD5(`Text`)='ecf856977e848c2f6c78262a262d5813' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=31 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 32, 'ruRU', 'Странно, но Моргант отверг свое орочье войско сразу же после их жалкой победы. Чернокнижник возвел магическую башню на северо-востоке и использовал всю свою силу, чтобы создать небольшую армию гноллов из стаи Темношкуров, которые воплощают его злые замыслы. Орки и люди стали жертвами звероподобных монстров, служащих чернокнижнику. Что до того, почему Моргант предал Гат\'Илзогга, вождя Черной горы, – об этом остается только догадываться.' FROM `page_text` WHERE `ID`=32 AND MD5(`Text`)='47d65ff82243f10c19a4927cd5bf4aac' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=32 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 33, 'ruRU', 'К несчастью, эти вонючие орки, кажется, всерьез принялись за истребление подданных Его Величества. Две недели назад клан Черной Горы устроил безжалостную резню в Приозерье. Много отважных воинов полегло в тот ужасный день. Орки пошли на штурм с таким напором и яростью, что мост через Озеро Безмолвия был разрушен до основания. Наши запасы истощены. Нечем даже перевязывать раненых.' FROM `page_text` WHERE `ID`=33 AND MD5(`Text`)='10ac061398897210eea9db42ea9b5f50' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=33 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 34, 'ruRU', 'Сейчас я прошу Его Величество помочь в эти трудные времена добрым гражданам Озер. Нам нужны люди для защиты нашей земли и боевые орудия взамен разрушенных на поле боя. Запасы еды и питья истощились. Умоляю, государь, окажите нам поддержку в защите последнего бастиона на пути ненавистных орков! Враг должен быть изгнан за пределы королевства Штормград!' FROM `page_text` WHERE `ID`=34 AND MD5(`Text`)='734fd57268e18c1562f769f656eee7b5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=34 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 35, 'ruRU', 'Боюсь, за происходящим в Северных землях стоит более могущественное и ужасное зло, чем мы предполагали. Королевство Штормград обязано принять меры, иначе нас ждет погибель или, что хуже, мы станем послушными рабами нашего врага.\r\n\r\nПодпись,\r\n\r\nЧиновник Соломон\r\nПриозерье\r\nКоролевство Штормград' FROM `page_text` WHERE `ID`=35 AND MD5(`Text`)='d1de5a09d009ab9f9d3dae3900eab1b8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=35 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 36, 'ruRU', 'Достопочтенный мировой судья Соломон!\r\n\r\nОплакиваю павших вместе с вами. Я лично доложу королю о случившемся и надеюсь, что смогу убедить его отправить в Приозерье подкрепление. Его Величество в последнее время совершенно удалился от дел, и его поступки, признаться, меня удивляют. Надеюсь, это останется между нами.\r\n\r\nИскренне ваш,\r\n\r\nГенерал Маркус Джонатан\r\nКоролевство Штормград' FROM `page_text` WHERE `ID`=36 AND MD5(`Text`)='ad23f73637165ff530f591fb1c41ac87' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=36 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 38, 'ruRU', 'Сильноплечий --\r\n\r\nОднако же нужно обладать немалой наглостью, чтобы посылать чужака обсуждать дела Братства Справедливости! Некогда тебе удалось спасти мне жизнь, а вот теперь ты подвергаешь ее серьезной опасности.\r\n\r\nОднако я перед тобой в долгу. Братство Справедливости сильнее, чем ты думаешь. Любой рудник от Западного Края до леса находится под их контролем. Кобольды и гноллы делают за них всю грязную работу. У них также есть созданные гоблинами металлические монстры, которые расхаживают по полям Западного Края и вселяют ужас в местных жителей.' FROM `page_text` WHERE `ID`=38 AND MD5(`Text`)='0b90c1c1dbb2a52ec578760d0934e53b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=38 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 39, 'ruRU', 'У них действует обширная подземная система. Больше, чем тебе кажется, Сильноплечий. От Пиратской бухты до Крепости Штормграда. Ты храбрый паладин, но глупец, если считаешь, что можешь победить их. Они занимаются разработкой оружия массового поражения. В общем, Каменщики знают только, как строить масштабные сооружения. Надеюсь, ты не подумал, что я о фермах и виноградниках? Я отплатил тебе за услугу. Теперь оставь меня!\r\n\r\n--В' FROM `page_text` WHERE `ID`=39 AND MD5(`Text`)='53db71ecfe34405fd07c06dc93ce27ab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=39 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 41, 'ruRU', 'Лорд Сильноплечий -\r\n\r\nВозглавляемое Эдвином ван Клифом братство Каменщиков состояло из лучших строителей среди людей. Каменщики помогали восстанавливать Штормград, разрушенный до основания орками во время Первой войны. ван Клиф и его товарищи были непревзойденными зодчими. Их вкус и чутье отразились в величии Храма Света и Крепости Штормграда.' FROM `page_text` WHERE `ID`=41 AND MD5(`Text`)='93d0a278d1f6a68a257e7d1a33148761' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=41 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 42, 'ruRU', 'Однако благородные мужи Штормграда влезли в огромные долги, расширяя военное присутствие королевства в Элвиннском лесу и Тернистой долине. Огромные долги опустошили казну, и ван Клиф со своими товарищами не получили обещанных денег. Потратив несколько лет на возведение великого города, Каменщики остались ни с чем, забытые продажными чиновниками столицы.' FROM `page_text` WHERE `ID`=42 AND MD5(`Text`)='9f415e2064dc54d0548c351561be9d02' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=42 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 43, 'ruRU', 'Зная Эдвина ван Клифа всю свою жизнь, я могу сказать, что видеть в нем своего врага мне неприятно. Понимаете, он был моим другом детства, и я лично наставлял его в магии Теней, надеясь, что однажды он будет работать вместе со мной. Если ван Клиф стоит во главе Братства Справедливости, то да помилует Свет наши души!\r\n\r\nМастер Матиас Шоу\r\nГильдия убийц Штормграда' FROM `page_text` WHERE `ID`=43 AND MD5(`Text`)='2b94316aab794df57cb04e5e99c5c375' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=43 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 47, 'ruRU', 'За то, что ты нашел для меня бутылочку старого доброго виски, я скажу, где находится сокровище! Иди вдоль берега, двигаясь на запад от бутылки. Дойдешь до воды – плыви дальше на запад. Через некоторое время ты приплывешь на остров, где и найдешь мой сундук с сокровищами!' FROM `page_text` WHERE `ID`=47 AND MD5(`Text`)='078ca7972362b559cfd207ff46fce0eb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=47 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 48, 'ruRU', 'Чернокоготь--\r\n\r\nМоре ждет нас. Нам нужны ресурсы с севера. Несите все: рельсы, ведра. Нам нужен металл. Ожидается прибытие груза из ПБ, но поставка задерживается. Потрудитесь как следует, Чернокоготь! В этот раз посылайте припасы прямо в "амбар". Времени в обрез.\r\n\r\n--ван Клиф' FROM `page_text` WHERE `ID`=48 AND MD5(`Text`)='ae64b671eec663c84948d29120710a84' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=48 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 49, 'ruRU', 'Лорд Сильноплечий --\r\n\r\nГородской совет Озер смиренно просит у вас военной помощи. В то время как я пишу эти строки, нас держат в осаде орки Черной Горы и гноллы из стаи Темношкуров, прислужнивающие Морганту. Я бы никогда не попросил о помощи, но мы в тяжелом положении. Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу вас оказать нам поддержку. Падет королевство – и все люди будут обречены.\r\n\r\nМировой судья Соломон' FROM `page_text` WHERE `ID`=49 AND MD5(`Text`)='3ed55d3c8c81db75269caf0fdc51a3fb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=49 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 50, 'ruRU', 'Ваша честь--\r\n\r\nВсе жители Западного Края скорбят вместе с вами, но здесь, в Западном Крае, идет своя война. Крестьяне покидают район из-за воров и механических големов. Штормград отозвал войска, лишив нас всякой защиты. Я организовал местное ополчение на случай, если Штормград не предпримет попыток нас спасти. Направить людей в Красногорье – все равно что подписать приговор Западному Краю.\r\n\r\nСожалею,\r\nГриан Сильноплечий' FROM `page_text` WHERE `ID`=50 AND MD5(`Text`)='6e4131a15cfb22511031208b723451c1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=50 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 51, 'ruRU', 'Лорд Элло Чернодрев--\r\n\r\nГород Приозерье смиренно просят Ночной дозор о помощи. Нас осаждают, нас держат в осаде орки Черной Горы и гноллы из стаи Темношкуров, прислужнивающие Морганту. Я бы никогда не попросил о помощи, но мы в тяжелом положении. Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу Вас оказать нам поддержку. Падет королевство – и все люди будут обречены.\r\n\r\nМировой судья Соломон' FROM `page_text` WHERE `ID`=51 AND MD5(`Text`)='924eab8eef74854e0e41e1c3545e3170' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=51 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 52, 'ruRU', 'Ваша честь--\r\n\r\nС сожалением сообщаю, что в настоящее время Ночной Дозор не может покинуть свой пост в Темнолесье. Возможно, вы еще не знаете, но Штормград больше не оказывает военной поддержки нашему региону. Ночной Дозор был создан и подготовлен для защиты Темнолесья в отсутствие поддержки Штормграда. Без защиты Дозора город будет уничтожен. Желаю удачи.\r\n\r\n--Лорд Элло Чернодрев' FROM `page_text` WHERE `ID`=52 AND MD5(`Text`)='24d34b0a3a7169a99cd49b086c1e7222' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=52 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 53, 'ruRU', 'Буквы вспыхивают на записке и исчезают. Уловить их смысл невозможно...' FROM `page_text` WHERE `ID`=53 AND MD5(`Text`)='7e7ea5566e04b24c3d6a883cdb51d0f5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=53 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 54, 'ruRU', 'Привет тебе, Элло Чернодрев, мэр Темнолесья. Боюсь, у меня плохие вести для вашего города.\r\n\r\nВидишь ли, я создатель. Я обманом заставил того, кто доставил это письмо, помочь мне в создании моего последнего, самого ужасного творения – демона из плоти, костей и металла! Когда ты читаешь эти строки, он находится рядом с моим скромным жилищем, скрежеща зубами. Одно мое слово – и он начнет убивать и крушить все на своем пути.\r\n\r\nИ в скором времени вы испытаете это на себе.\r\n\r\n-Бальзамировщик' FROM `page_text` WHERE `ID`=54 AND MD5(`Text`)='a91b8a6bbcd52523c294de80e4ac8b85' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=54 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 58, 'ruRU', 'Луна над долиной взошла,\r\nОсвещая ночные джунгли,\r\nГде воины сошлись на зов\r\nЗащищать свой народ и святыни. \r\n\r\nЛуна над долиной взошла,\r\nРаздаются крики битвы,\r\nИ кровь ручьями струится,\r\nПогибают враги и побратимы.' FROM `page_text` WHERE `ID`=58 AND MD5(`Text`)='ea7717f5632d41d045516e812fa60163' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=58 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 59, 'ruRU', 'Когда наши побратимы уходят\r\nВ мир иной, потусторонний,\r\nДуша застывает\r\nВ глубине подземелий долины.\r\n\r\nКогда наши побратимы уходят\r\nВ Храм Горы,\r\nМы на защиту встаем их духу,\r\nСокрытому в святом синем кристалле.\r\n\r\nКогда наши побратимы уходят,\r\nВосходит Луна над долиной.' FROM `page_text` WHERE `ID`=59 AND MD5(`Text`)='67fd95d5361079d48da899e93a0e07e9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=59 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 62, 'ruRU', 'Заклятый солнцем и луной,\r\nОставь сей камень роковой,\r\nНетленны рока письмена:\r\nВ гробнице Смерть заточена,\r\nХранит недрогнувшей рукой\r\nОна властителя покой.' FROM `page_text` WHERE `ID`=62 AND MD5(`Text`)='0449f3578d77861c9004a2e93a4b2ed9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=62 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 72, 'ruRU', 'бродит сейчас по Сумеречному лесу, терзаемый горем от потери жены, детей и ненавидящий себя за это. Мор\'Ладим, как он теперь себя называет, скитается по Сумеречному лесу и из мести убивает все живое.' FROM `page_text` WHERE `ID`=72 AND MD5(`Text`)='26fce48248c58300ce0b742e1e6359d0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=72 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 73, 'ruRU', 'Ужас этих последних недель становится невыносимым; и все же, написав увиденное мною, я чувствую себя немного лучше. И я буду продолжать свое занятие, так как это единственное мое успокоение в эти страшные дни.' FROM `page_text` WHERE `ID`=73 AND MD5(`Text`)='5a8c86fae5786a00445c3f7174c4ec85' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=73 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 74, 'ruRU', 'ПЕРВЫЙ ДЕНЬ\r\n\r\nМы с учеником приехали сегодня в Холодную Долину. Путешествие мимо пещеры прошло без приключений. Мы разбили лагерь подальше от нее, так как нас предупредили, что там водятся тролли.\r\n\r\nВТОРОЙ ДЕНЬ\r\n\r\nПроклятый волчий вой не давал мне спать всю ночь.\r\n\r\nНе пройдет и нескольких дней, как у меня будет накидка из шкуры этой твари.\r\n\r\nПаренек столкнулся сегодня с троггом, ввязался в бой и' FROM `page_text` WHERE `ID`=74 AND MD5(`Text`)='df867fd32d5de4fb5190c9d765ad3909' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=74 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 78, 'ruRU', 'Этот знак брони можно обменять на изделие из кожи или ткани у Тимберлейнов на Лесопилке Восточной долины.' FROM `page_text` WHERE `ID`=78 AND MD5(`Text`)='eb453b9dfa84bf6084b3c633861c5ff6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=78 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 79, 'ruRU', 'Ниже представлена схема и расписание перевозки золота Братством Справедливости из шахт Элвиннского леса в наш штаб в Западном Крае.\r\n\r\nРасписание:\r\n\r\nВоскресенье: 12:30\r\nСреда: 12:30\r\n\r\nВ указанные дни золото, добытое в шахтах Элвин, будет доставляться на тыквенное поле Бреквеллов. Лицо, отвечающее за весь процесс – "Собиратель" – будет носить на пальце специальное кольцо, которое я дал ему лично.' FROM `page_text` WHERE `ID`=79 AND MD5(`Text`)='20267dae1e6a85c7b270656ebf3865c9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=79 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 80, 'ruRU', 'Грелин, у меня мало времени и много забот; надеюсь, ваш интерес к троллям не сильно отвлечет меня от моих дел. Тем не менее я разрешаю вам ссылаться на меня при необходимости, если вы, разумеется, не станете выходить за рамки целесообразности.\r\n\r\nМагни Бронзобород' FROM `page_text` WHERE `ID`=80 AND MD5(`Text`)='42d99e37080c087e7bfe1c262c112d3c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=80 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 81, 'ruRU', 'попытался проучить монстра, но в итоге получил глубокий порез на руке. Похоже, придется накладывать швы.\r\n\r\nТРЕТИЙ ДЕНЬ\r\n\r\nПохолодало. Ночью выпало немного снега.\r\n\r\nЧЕТВЕРТЫЙ ДЕНЬ\r\n\r\nУченик поправился и пребывает в хорошем расположении духа, поэтому мы рискнули посмотреть на троллей. Или скорее, Снежную Гриву, исходя из отметок на их коже и различных амулетов, которые они носят.' FROM `page_text` WHERE `ID`=81 AND MD5(`Text`)='eb4b4e8767262b7e88d3af0580d4a95a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=81 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 82, 'ruRU', 'ПЯТЫЙ ДЕНЬ\r\n\r\nОставил парня присматривать за лагерем, а сам прокрался к пещере, чтобы немного осмотреться. Троллей здесь огромное количество. Чтобы очистить пещеру от этих паразитов потребуется немало солдат.\r\n\r\nЯ вспомнил, что в последнее время я вообще не видел троггов. Они появляются в регионе в огромных количествах, но они настолько примитивны, что вряд ли представляют угрозу. Хотя поживем – увидим.' FROM `page_text` WHERE `ID`=82 AND MD5(`Text`)='c233e3e7c5eb739d51f155e2d2437491' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=82 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 83, 'ruRU', 'Уже почти неделю нет ни капли эля.\r\n\r\nШЕСТОЙ ДЕНЬ\r\n\r\nОпять похолодало. Идет снег. Тролли. Эля нет.\r\n\r\nСЕДЬМОЙ ДЕНЬ\r\n\r\nСнег белеет,\r\nНебо синеет,\r\nВолки воют,\r\nА эля все нет.\r\n\r\nВОСЬМОЙ ДЕНЬ\r\n\r\nТролли, возможно, не такая уж проблема. Их много,' FROM `page_text` WHERE `ID`=83 AND MD5(`Text`)='45edde47e11e23b6352641d1291434ed' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=83 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 84, 'ruRU', 'но вооружение у них никудышное и нет дисциплины. Небольшое проявление силы – вот и все, что нужно для устранения "угрозы".' FROM `page_text` WHERE `ID`=84 AND MD5(`Text`)='40037a7d62be658213e92cf2c5a4614e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=84 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 85, 'ruRU', 'Мой дневник\r\n\r\nУжасы последних недель почти лишают меня разума; единственное, что меня спасает, – записи в дневнике. Я как будто исповедуюсь в своих грехах перед безмолвным собеседником или как будто освобождаю свою голову от мрачных мыслей, перенося их на бумагу. \r\n\r\nЭто второй мой дневник, первый остался в месте, куда я не могу вернуться. Поэтому я начал все с нуля. Но в этот раз я буду писать только правду.' FROM `page_text` WHERE `ID`=85 AND MD5(`Text`)='3748de4eeb5b413e1dc824896552d437' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=85 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 86, 'ruRU', 'Отчет о положении дел с троллями из племени Мерзлогривов в регионе Холодной долины.\r\n\r\nПодготовлен Грелином Белобородом, особым посланником Сената\r\n\r\nЯ потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфским поселениям в этом районе. Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии. Учитывая помощь горных пехотинцев, уже находящихся в' FROM `page_text` WHERE `ID`=86 AND MD5(`Text`)='e628756a77d51ac8f215f02d24e0b6f7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=86 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 87, 'ruRU', 'Холодной долине и наемников (нанятых на деньги, выделенные мне старейшиной Сената), я уверен, что проблема будет решена в ближайшее время. \r\n\r\nВся кампания официально одобрена королем Бронзобородом.' FROM `page_text` WHERE `ID`=87 AND MD5(`Text`)='1bb85113f7fd7a317308a5a43a838ed3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=87 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 88, 'ruRU', 'Отчет о положении дел с троллями из племени Мерзлогривов в регионе Дун Морога\r\n\r\nБольшая часть троллей, обитающих в Дун Мороге, сконцентрирована в форте Мерзлогривов, горной пещере на западной границе. Их численность может вызывать некоторые опасения, однако, похоже, они не собираются покидать свою пещеру. Вне всяких сомнений, они не хотят вызывать гнев дворфов и рисковать своей шкурой. Они всего лишь обороняют свою территорию, и' FROM `page_text` WHERE `ID`=88 AND MD5(`Text`)='1c46208e510826114445e5a49522df24' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=88 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 89, 'ruRU', 'не представляют для нас реальной угрозы до тех пор, пока мы не нарушаем их границ. Возможно, народу дворфов неприятна сложившаяся ситуация, но, учитывая дефицит военных сил, будет благоразумнее перенести решение этой проблемы на более поздний срок и бросить все усилия на борьбу с троггами и дворфами Черного Железа.\r\n\r\nВ письме вы также найдете отчет моего брата Грелина о Старой Наковальне.\r\n\r\nПодписано:\r\nСенир Белобород' FROM `page_text` WHERE `ID`=89 AND MD5(`Text`)='d156737ea4605015a6649560b2ed165a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=89 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 90, 'ruRU', 'Отчет о положении дел с троллями из племени мерзлогривов в регионе Холодной долины.\r\n\r\nПодготовлен Грелином Белобородом, особым посланником Сената\r\n\r\nЯ потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфским поселениям в этом районе. Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии. Учитывая помощь горных пехотинцев, уже находящихся в' FROM `page_text` WHERE `ID`=90 AND MD5(`Text`)='bffc197ae0ea48c4f9f47ef7f34ee2b6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=90 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 91, 'ruRU', 'Холодной долине и наемников (нанятых на деньги, выделенные мне старейшиной Сената), я уверен, что проблема будет решена в ближайшее время. \r\n\r\nВся кампания официально одобрена королем Бронзобородом.' FROM `page_text` WHERE `ID`=91 AND MD5(`Text`)='fe38482760ecfa53180998a2cd2393bd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=91 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 92, 'ruRU', 'Дорогой Таррел! -\r\n\r\nПрости за поспешность, с которой написано это послание, однако сейчас время для нас роскошь.\r\n\r\nРаскопщики достигли неплохих результатов в поиске артефактов титанов. Но мы обнаружили также другие древние предметы – в частности, огромные кости.' FROM `page_text` WHERE `ID`=92 AND MD5(`Text`)='e8eb4dc6f8dfe9c43bf3f0236743b146' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=92 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 93, 'ruRU', 'Спустя некоторое время после этой находки мы подверглись нападению ящеров. Батальон Длинной Косы сражался мужественно. Но силы были не равны. Почти все погибли. Спаслись только трое. Рабочий Ормер Сталеплет был самым отважным бойцом, он спас меня и геолога Велгара.' FROM `page_text` WHERE `ID`=93 AND MD5(`Text`)='f754f30be9887e80f21df4497b0e0da6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=93 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 94, 'ruRU', 'Мы спрятались в укромной пещере; похоже, это достаточно безопасное место. Но мы все равно находимся в ловушке до тех пор, пока не прибудет подкрепление. Вельгар пытается продолжать работу, но, похоже, он все еще слишком напуган. Мы находимся в тяжелом положении, Таррел. Пожалуйста, поторопи Длинную Косу со сбором дополнительных сил.\r\n\r\nЯ все также сильно тебя люблю, даже в эти ужасные времена.\r\n\r\n--Меррин' FROM `page_text` WHERE `ID`=94 AND MD5(`Text`)='448f8f8fdc887aff8254c6563f6dbe99' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=94 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 95, 'ruRU', 'Зеленые холмы Тернистой долины\r\n\r\nНаш первый день прошел, как обычно проходят первые дни. Большую часть времени мы обустраивали лагерь. Мне удалось найти идеальное место у небольшой чистой заводи. Старые, обветшавшие мостки указывали на то, что в этом месте когда-то жили. Кто именно там жил, мы пока не знали.' FROM `page_text` WHERE `ID`=95 AND MD5(`Text`)='825542242d9b71ba9c7341829cb051e7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=95 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 98, 'ruRU', 'В последующие годы, после того как Штормград обманул братство Каменщиков, сэр Эрлгедин разочаровался в аристократии Королевства. Он больше не хотел принадлежать к Благородным Домам, хотя право это унаследовал от отца.\r\n\r\nНо не будем отвлекаться. Мое повествование не политический трактат и не биография. Я всего лишь делюсь опытом участия в большой охоте среди зеленых холмов Тернистой долины.' FROM `page_text` WHERE `ID`=98 AND MD5(`Text`)='332a6a146162281f750198898007c9ce' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=98 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 100, 'ruRU', 'Когда я уже собирался спросить, почему Ажек не участвует в обсуждении плана сегодняшней охоты, она выхватила стрелу из колчана, натянула тетиву и выстрелила в бедного Барнила. Однако стрела пролетела мимо. Разинув рот, Барнил наблюдал за тем, как возле него на поверхность реки всплыл огромный кроколиск, а между глаз у него торчала стрела Ажек.' FROM `page_text` WHERE `ID`=100 AND MD5(`Text`)='b06829c3540ca6431fda409001d368b2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=100 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 102, 'ruRU', 'После очередного неверного шага Барнила Эрлгедин положил свою тяжелую руку ему на плечо. Мы с Ажек переглянулись, уверенные, что он решил-таки напомнить Барнилу о необходимости соблюдать осторожность. Но  вместо этого Эрлгедин кивнул головой в сторону лежащего неподалеку дерева. Оттуда на нас пристально смотрели два черных глаза, а под ними была пасть, полная острых зубов.' FROM `page_text` WHERE `ID`=102 AND MD5(`Text`)='5af5e05a9bf7d48ecdcb8a67e4bd76bd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=102 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 104, 'ruRU', 'Первое убийство взбодрило нашу команду. Барнил налил всем меда, чтобы отметить его. Но нашему празднованию не суждено было продолжаться долго. Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рев. Я в жизни не слышал такого леденящего кровь звука.' FROM `page_text` WHERE `ID`=104 AND MD5(`Text`)='ba1070bb5e35c33afd37ef01bfae2ae9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=104 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 105, 'ruRU', 'На скалистом склоне, возвышавшемся над нами, в лучах заходящего солнца вырисовывался силуэт самой большой кошки, которую я когда-либо видел. Мне удалось сделать неловкий выстрел из ружья, но кошка не двинулась с места. Она издала еще один ужасный рык, громче прошлого, и исчезла.\r\n\r\nМы собрали вещи и мрачно двинулись в лагерь.' FROM `page_text` WHERE `ID`=105 AND MD5(`Text`)='bde7b7989d4533f00d0b017e619f554e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=105 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 108, 'ruRU', 'В тот день мы пошли на юг, двигаясь по свежим следам пантеры. Вскоре мы пришли к ущелью, через которое был перекинут длинный веревочный мостик. При виде этого чуда инженерной мысли мне сразу вспомнилось, как описывал этот район Бранн. Тролли, коренные жители этих мест, всегда считались примитивной расой, но мастерство, с которым они сконструировали этот мост через непреодолимую пропасть, было неоспоримо.' FROM `page_text` WHERE `ID`=108 AND MD5(`Text`)='6b6584e383db71d71c3f179be50c4610' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=108 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 110, 'ruRU', 'Ажек и сэр Эрлгедин стояли наготове, направив ружья в сторону колючего кустарника у подножия раскачивающихся деревьев. Полуденное солнце нещадно палило. Капля пота медленно скатилась по виску Эрлгедина, когда он взводил курок. В момент щелчка из кустов на поляну выпрыгнула огромная черная пантера – невероятно грациозное животное.' FROM `page_text` WHERE `ID`=110 AND MD5(`Text`)='24923736b285a7f6f916260444e033ab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=110 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 112, 'ruRU', 'Ружье резко подалось назад в его руках. Дуло ушло в сторону и попало под ствол ружья Ажек. И именно в этот момент Ажек спустила курок. Неуклюже вздернувшееся к кронам деревьев ружье отчетливо и громко выстрелило. Стая птиц, крича, вспорхнула в небо, разлетаясь во все стороны. Струйка дыма вилась из дерева. Мы в оцепенении смотрели, как гигантская ветка рухнула прямо на убегающую пантеру и сломала ей хребет.' FROM `page_text` WHERE `ID`=112 AND MD5(`Text`)='439b472a50aa467283bfe0b15d153a0a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=112 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 114, 'ruRU', 'С первыми лучами солнца мы отправились на охоту на юг, за руины Ткаши. Барнил беспокоился, что мы можем наткнуться на троллей племени Кровавого Скальпа. Мои слова о том, что это племя сейчас занято войной со своими заклятыми врагами из племени Дробителей Черепов, конечно же, ничуть не успокоили его. Меня же возможность засады беспокоила гораздо меньше: в моих руках была заряженная винтовка, на поясе – полная сумка пороха, а рядом – трое отличных охотников.' FROM `page_text` WHERE `ID`=114 AND MD5(`Text`)='53de5ef45b939ca8c283107c8cef7144' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=114 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 115, 'ruRU', 'Я помню битву с армией Пылающего Легиона: враги надвигалась со всех направлений, а прямо передо мной возвышался огромный инфернал. Толпа злобных троллей по сравнению с этим кажется безобидной, как заяц в горах Дун Морога.\r\n\r\nК величайшей радости Барнила, мы миновали руины Ткаши без всяких приключений. Мы продолжали двигаться на запад к Великому морю, обходя руины Зул\'Кунды. Взобравшись на высокий утес над морем, мы увидели нашего первого ящера.' FROM `page_text` WHERE `ID`=115 AND MD5(`Text`)='47f9a6e6dec18443476f48a2681e9a92' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=115 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 118, 'ruRU', 'Наших суматошных выстрелов оказалось достаточно, чтобы дать Барнилу время убежать. Барнил скатился с холма и присоединился к нашей группе. Мы побежали в джунгли, преследуемые стаей свирепых ящеров-кнутохвостов.\r\n\r\nОхотники превратились в добычу.' FROM `page_text` WHERE `ID`=118 AND MD5(`Text`)='1db2cf8151cb9245dea8ebb1724c9367' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=118 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 119, 'ruRU', 'Я вел отряд по направлению к морю в надежде, что вода остановит ящеров. Но в спешке мы зашли слишком далеко на север, на возвышенность. Исправлять ошибку было уже поздно. И вина была в этом моя. Мы остановились на краю отвесной скалы, а ящеры были уже в нескольких шагах от нас.' FROM `page_text` WHERE `ID`=119 AND MD5(`Text`)='83b0c102184f5fc5106e053cdb889af1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=119 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 120, 'ruRU', 'Я медленно шагнул вперед, держа ружье наготове. Я привел этих отважных охотников к гибели. И готов был погибнуть сам, защищая их. Ящеры-кнутохвосты известны своей свирепостью и неумолимой жаждой крови. Их было намного больше нас. Но я бы себе не простил, если бы позволил расправиться с собой и моими товарищами, не прикончив сначала несколько этих тварей!' FROM `page_text` WHERE `ID`=120 AND MD5(`Text`)='cfe6208b15ee32291c92aad7b1d68492' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=120 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 121, 'ruRU', 'Ажек и сэр Эрлгедин вскинули свое оружие, прикрывая меня с боков, спиной к морю. Барнил обреченно вздохнул и обнажил свой топор. Кнутохвосты были практически рядом с нами. Их уверенные шаги замедлились. Они крадучись подбирались к своим жертвам, зная, что загнали нас в ловушку.' FROM `page_text` WHERE `ID`=121 AND MD5(`Text`)='213fcdcdbd112997b010ce2945623ce9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=121 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 153, 'ruRU', 'Наш первый день прошел, как обычно проходят первые дни. Большую часть времени мы обустраивали лагерь. Мне удалось найти идеальное место у небольшой чистой заводи. Старые, обветшавшие мостки указывали на то, что в этом месте когда-то жили. Кто именно там жил, мы пока не знали.' FROM `page_text` WHERE `ID`=153 AND MD5(`Text`)='3462a21366c030407f4484533bf37833' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=153 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 154, 'ruRU', 'В эту экспедицию со мной отправились Ажек Руак и сэр С. Дж. Эрлгедин, а также мой верный слуга Барнил Каменный Горшок. С отцом Ажек мы когда-то сражались за Альянс плечом к плечу. Удивительно, как она выросла за это время. Отец обучил ее искусству владения оружием. Ее навыки стрельбы из лука настолько хороши, что невольно заставляют задуматься, не течет ли в ее жилах кровь эльфов.' FROM `page_text` WHERE `ID`=154 AND MD5(`Text`)='b4090a7a462222a90ee69d49b0187f52' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=154 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 155, 'ruRU', 'Сэр С. Дж. Эрлгедин принадлежит к знатному людскому роду. Его отец, граф Эрлгедин, славился своей щедростью. Именно граф выступал за улучшение условий труда для Гильдии каменщиков во время восстановления Штормграда после Второй Великой войны.' FROM `page_text` WHERE `ID`=155 AND MD5(`Text`)='6e7b3d50d846bb58f48c2c2813421549' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=155 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 156, 'ruRU', 'В последующие годы, после того как Штормград обманул братство Каменщиков, сэр Эрлгедин разочаровался в аристократии Королевства. Он больше не хотел принадлежать к Благородным Домам, хотя право это унаследовал от отца.\r\n\r\nНо не будем отвлекаться. Мое повествование не политический трактат и не биография. Я всего лишь делюсь опытом участия в большой охоте среди зеленых холмов Тернистой долины.' FROM `page_text` WHERE `ID`=156 AND MD5(`Text`)='f77d0b3ce863d5794b5ae3225e674fa1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=156 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 157, 'ruRU', 'Мы проснулись чуть свет. Барнил занялся приготовлением завтрака. Мне показалось, что мысли Ажек в этот момент были где-то далеко. Впереди нас ждал долгий день и немало опасностей. Нужна была полная сосредоточенность, иначе последствия могли быть печальными. Но Ажек была не в состоянии отвести взгляд от Барнила, занятого мытьем столовых принадлежностей.' FROM `page_text` WHERE `ID`=157 AND MD5(`Text`)='f08abea0fb51c139a2d1c90ad19e37a1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=157 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 158, 'ruRU', 'Когда я уже собирался спросить, почему Ажек не участвует в обсуждении плана сегодняшней охоты, она выхватила стрелу из колчана, натянула тетиву и выстрелила в бедного Барнила. Однако стрела пролетела мимо. Разинув рот, Барнил наблюдал за тем, как возле него на поверхность реки всплыл огромный кроколиск, а между глаз у него торчала стрела Ажек.' FROM `page_text` WHERE `ID`=158 AND MD5(`Text`)='b06829c3540ca6431fda409001d368b2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=158 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 159, 'ruRU', 'Мы отправились на запад через дикие непроходимые джунгли. В поисках добычи мы медленно, но верно прокладывали себе путь сквозь густую растительность. К нашему сожалению, утром все было тихо. Даже ветер не шумел в кронах деревьев. К полудню мы начали волноваться. Шаги Барнила уже не были столь осторожными и тихими, как раньше. Теперь он неуклюже переваливался с ноги на ногу, с треском ломая упавшие на землю сухие ветки.' FROM `page_text` WHERE `ID`=159 AND MD5(`Text`)='33973107fcabf02164aeece61ea9bf42' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=159 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 160, 'ruRU', 'После очередного неверного шага Барнила Эрлгедин положил свою тяжелую руку ему на плечо. Мы с Ажек переглянулись, уверенные, что он решил-таки напомнить Барнилу о необходимости соблюдать осторожность. Но вместо этого Эрлгедин кивнул головой в сторону лежащего неподалеку дерева. Оттуда на нас пристально смотрели два черных глаза, а под ними была пасть, полная острых зубов.' FROM `page_text` WHERE `ID`=160 AND MD5(`Text`)='5af5e05a9bf7d48ecdcb8a67e4bd76bd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=160 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 161, 'ruRU', 'Этим чудищем был самец тигра Тернистой долины. Прежде чем мне удалось взвести винтовку, Эрлгедин поднял свой арбалет и выстрелил в зверя. Стрела ушла немного в сторону и вонзилась в левый бок тигра. Зверь попытался убежать, но его рана была слишком глубокой. Он сумел сделать лишь несколько шагов, а затем его настиг метательный топор Барнила.' FROM `page_text` WHERE `ID`=161 AND MD5(`Text`)='61555a5421df7a9662e83d325bdb6e4e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=161 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 162, 'ruRU', 'Первый успех взбодрил нашу команду. Барнил налил всем меда, чтобы отметить его. Но нашему празднованию не суждено было продолжаться долго. Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рев. Я в жизни не слышал такого леденящего кровь звука.' FROM `page_text` WHERE `ID`=162 AND MD5(`Text`)='8810377a7bd978746aa49a74848466ae' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=162 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 163, 'ruRU', 'На скалистом склоне, возвышавшемся над нами, в лучах заходящего солнца вырисовывался силуэт самой большой кошки, которую я когда-либо видел. Мне удалось сделать неловкий выстрел из ружья, но кошка не двинулась с места. Она издала еще один ужасный рык, громче прошлого, и исчезла.\r\n\r\nМы собрали вещи и мрачно двинулись в лагерь.' FROM `page_text` WHERE `ID`=163 AND MD5(`Text`)='bde7b7989d4533f00d0b017e619f554e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=163 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 164, 'ruRU', 'Я обещал своим товарищам, что на следующий день мы отправимся охотиться на пантер, так как их мех очень высоко ценится по всему Азероту. Учитывая, что большинство охотников и торговцев мехом сейчас храбро отдавали свои жизни, сражаясь за Альянс, этот мех еще больше возрос в цене.' FROM `page_text` WHERE `ID`=164 AND MD5(`Text`)='23d416448ffb0e86cb1bcea1b1b3d8c0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=164 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 165, 'ruRU', 'Ажек и сэр Эрлгедин страстно желали научиться стрелять из дворфийских винтовок. Я велел им оставить свое примитивное оружие в лагере. Мы с Барнилом снарядили их лучшими образцами стальгорнских ружей.' FROM `page_text` WHERE `ID`=165 AND MD5(`Text`)='8436af36243c5f93d91000309ef7097e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=165 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 166, 'ruRU', 'В тот день мы пошли на юг, двигаясь по свежим следам пантеры. Вскоре мы пришли к ущелью, через которое был перекинут длинный веревочный мостик. При виде этого чуда инженерной мысли мне сразу вспомнилось, как описывал этот район Бранн. Тролли, коренные жители этих мест, всегда считались примитивной расой, но мастерство, с которым они сконструировали этот мост через непреодолимую пропасть, было неоспоримо.' FROM `page_text` WHERE `ID`=166 AND MD5(`Text`)='490dc9bcd57f6341368eb12b451fe4b3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=166 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 167, 'ruRU', 'Ажек не понадобилось много времени, чтобы выследить пантеру; она ушла на юго-запад. Мы шли быстрым шагом, с оружием наготове, и уже предвкушали успех. Треск веток, донесшийся из рощи неподалеку, немедленно привлек наше внимание. Там кто-то был. Одного взгляда на Барнила хватило, чтобы он понял меня. Он медленно опустил винтовку. Эта добыча – не для нас, а для наших спутников-людей. Сколько пантер уже погибло от наших пуль! Нет, эта добыча – не для нас.' FROM `page_text` WHERE `ID`=167 AND MD5(`Text`)='c818dfeafb3e11bbab96d0ba40f87ade' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=167 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 168, 'ruRU', 'Ажек и сэр Эрлгедин стояли наготове, направив ружья в сторону колючего кустарника у подножия раскачивающихся деревьев. Полуденное солнце нещадно палило. Капля пота медленно скатилась по виску Эрлгедина, когда он взводил курок. В момент щелчка из кустов на поляну выпрыгнула огромная черная пантера – невероятно грациозное животное.' FROM `page_text` WHERE `ID`=168 AND MD5(`Text`)='0f98685bbcbe6525ec950e980f13ee49' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=168 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 169, 'ruRU', 'Пантера понеслась вдоль опушки леса, а люди ни на секунду не спускали с нее взгляда. Стволы их ружей медленно двигались, оставаясь идеально параллельными друг другу. Барнил посмотрел на меня нетерпеливым взглядом, но я отрицательно покачал головой. Это была охота людей, а не наша. Эрлгедин выстрелил. Раздался оглушительный грохот, но пантера осталась цела. Вероятно, Эрлгедин не был готов к такой мощной отдаче.' FROM `page_text` WHERE `ID`=169 AND MD5(`Text`)='8ba8b7a43dfe61c5155add2ecad226c1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=169 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 170, 'ruRU', 'Ружье резко подалось назад в его руках. Дуло ушло в сторону и попало под ствол ружья Ажек. И именно в этот момент Ажек спустила курок. Неуклюже вздернувшееся к кронам деревьев ружье отчетливо и громко выстрелило. Стая птиц, крича, вспорхнула в небо, разлетаясь во все стороны. Струйка дыма вилась из дерева. Мы в оцепенении смотрели, как гигантская ветка рухнула прямо на убегающую пантеру и сломала ей хребет.' FROM `page_text` WHERE `ID`=170 AND MD5(`Text`)='439b472a50aa467283bfe0b15d153a0a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=170 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 171, 'ruRU', 'Шли недели, шкур пантер и тигров становилось все больше. Мне показалось, что настало время сосредоточить наши силы на более серьезной добыче: ящерах.\r\n\r\nЛюди поблагодарили нас с Барнилом за уроки, но отказались использовать огнестрельное оружие. Ажек чувствовала себя куда более уверенно с луком в руках, а сэр Эрлгедин не расставался со своим мощным арбалетом.' FROM `page_text` WHERE `ID`=171 AND MD5(`Text`)='6ffc5c746d7b1522f8300a310aa45879' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=171 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 172, 'ruRU', 'С первыми лучами солнца мы отправились на охоту на юг, за руины Ткаши. Барнил беспокоился, что мы можем наткнуться на троллей племени Кровавого Скальпа. Мои слова о том, что это племя сейчас занято войной со своими заклятыми врагами из племени Дробителей Черепов, конечно же, ничуть не успокоили его. Меня же возможность засады беспокоила гораздо меньше: в моих руках была заряженная винтовка, на поясе – полная сумка пороха, а рядом – трое отличных охотников.' FROM `page_text` WHERE `ID`=172 AND MD5(`Text`)='1df3f1a94c66d612cab3e8de53861be3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=172 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 173, 'ruRU', 'Я помню битву с армией Пылающего Легиона: враги надвигалась со всех направлений, а прямо передо мной возвышался огромный инфернал. Толпа злобных троллей по сравнению с этим кажется безобидной, как заяц в горах Дун Морога.\r\n\r\nК величайшей радости Барнила, мы миновали руины Ткаши без всяких приключений. Мы продолжали двигаться на запад к Великому морю, обходя руины Зул\'Кунды. Взобравшись на высокий утес над морем, мы увидели нашего первого ящера.' FROM `page_text` WHERE `ID`=173 AND MD5(`Text`)='887731e4dde01a75e08aaa682d2bc501' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=173 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 174, 'ruRU', 'Зверь даже не обнаружил нашего присутствия. Если быть честным, единственное приветствие, которое он получил от экспедиции, – это пулю между глаз.\r\n\r\nАжек одобрительно кивнула мне, а сэр Эрлгедин радостно крикнул: “Ура!” Настало время отпраздновать успех, выкурив трубку, затерявшуюся в глубинах моего рюкзака. Барнил отправился на вершину утеса за трофеем. Вид поверженного чудища доставлял мне немалое удовольствие, как и любая значительная победа.' FROM `page_text` WHERE `ID`=174 AND MD5(`Text`)='663d1de70ec77200c3e6a06a0dd41ef0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=174 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 175, 'ruRU', 'Но мне не пришлось долго наслаждаться успехом. На вершине утеса, прямо над несчастным Барнилом, появились несколько силуэтов.\r\n\r\n“Беги, Барнил!” – закричали мы. Ажек, сэр Эрлгедин и я выстрелили поверх головы Барнила в сторону преследующих его ящеров. Кто-то даже убил одного из них.' FROM `page_text` WHERE `ID`=175 AND MD5(`Text`)='b02dc83369aa41ddb8d28961d428cfe3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=175 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 176, 'ruRU', 'Наших суматошных выстрелов оказалось достаточно, чтобы дать Барнилу время убежать. Барнил скатился с холма и присоединился к нашей группе. Мы побежали в джунгли, преследуемые стаей свирепых ящеров-кнутохвостов.\r\n\r\nОхотники превратились в добычу.' FROM `page_text` WHERE `ID`=176 AND MD5(`Text`)='a3bcd66e089ecffd8675cf2b44fdbdb8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=176 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 177, 'ruRU', 'Я повел группу по направлению к морю, надеясь, что линия берега послужит нам защитой от ящеров. В спешке мы забрались слишком далеко к северу, на особенно высокий холм. Это было ошибкой. Я был виноват. Мы остановились прямо перед обрывом, заканчивающимся отвесной скалой, а ящеры были всего в нескольких шагах позади нас.' FROM `page_text` WHERE `ID`=177 AND MD5(`Text`)='83b0c102184f5fc5106e053cdb889af1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=177 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 178, 'ruRU', 'Я вел отряд по направлению к морю в надежде, что вода остановит ящеров. Но в спешке мы зашли слишком далеко на север, на возвышенность. Исправлять ошибку было уже поздно. И вина была в этом моя. Мы остановились на краю отвесной скалы, а ящеры были уже в нескольких шагах от нас.' FROM `page_text` WHERE `ID`=178 AND MD5(`Text`)='b668df41d172f751ad83d06c88e4646d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=178 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 179, 'ruRU', 'Ажек и сэр Эрлгедин вскинули свое оружие, прикрывая меня с боков, спиной к морю. Барнил обреченно вздохнул и обнажил свой топор. Кнутохвосты были практически рядом с нами. Их уверенные шаги замедлились. Они крадучись подбирались к своим жертвам, зная, что загнали нас в ловушку.' FROM `page_text` WHERE `ID`=179 AND MD5(`Text`)='213fcdcdbd112997b010ce2945623ce9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=179 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 180, 'ruRU', 'И тогда случилось чудо. Прямо рядом с нами раздался резкий, ужасающий рев огромного белого тигра. Несмотря на количество, ящеры развернулись и бросились врассыпную. Мы увидели лишь белый сполох, когда тигр минул нас и помчался за одним из ящеров. Нам не требовалось команды. Все четыре члена нашего отряда знали, что пришло время бежать.' FROM `page_text` WHERE `ID`=180 AND MD5(`Text`)='3b4b676a8566883dd22ea2d1e6a0e58f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=180 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 181, 'ruRU', 'Мы без остановки мчались назад, к нашему лагерю. Позже той ночью мы тихо сидели у костра, зная, что наши жизни были спасены по странной прихоти судьбы. Этому риску подвергается любой участник большой охоты. Мы – игрушки в руках судьбы. Когда-нибудь каждый из нас встретится с хищным оскалом смерти. И ваш покорный слуга рад, что эта встреча не произошла на зеленых холмах Тернистой долины.\r\n\r\n--Конец--' FROM `page_text` WHERE `ID`=181 AND MD5(`Text`)='c5f2ac0f5557fa09b3ddef46e15fe9b6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=181 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 182, 'ruRU', 'Достопочтенные коллеги и искатели правды.\r\n\r\nРаскопки продолжаются, но они были приостановлены из-за троггов, о которых я сообщал в моем последнем докладе. Я уверен, их проблему можно решить даже несмотря на то, что некоторые трогги гораздо более агрессивны, чем обычно.\r\n\r\nМы нашли еще больше артефактов, хотя во всех случаях, кроме одного (о котором я напишу ниже), эти находки были такие же, как и раньше, – интересные, если не сказать более.' FROM `page_text` WHERE `ID`=182 AND MD5(`Text`)='d208e6d6fb3b32528b8ceec874571967' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=182 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 183, 'ruRU', 'За одним лишь исключением. Странно высеченные идолы, что мы обнаружили недавно (краткое их описание прилагалось к моему последнему докладу), похоже, возымели побочный эффект на троггов на месте раскопок. Их притягивают эти высеченные фигуры, и некоторые трогги впадают из-за них в ярость!\r\n\r\nНеобходимо изучить этих идолов внимательнее, чтобы сделать по поводу них какие либо выводы, но я все еще надеюсь, что они прольют свет на связь между троггами и титанами.' FROM `page_text` WHERE `ID`=183 AND MD5(`Text`)='6ef3f61c7a82016af60f6e799fd39f55' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=183 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 184, 'ruRU', 'И в заключение я должен вновь напомнить о моей просьбе доставить взрывчатого порошка. Мои запасы подходят к концу, что серьезно препятствует успеху экспедиции. Мне обещали, что взрывчатый порошок вскоре будет доставлен, но я до сих пор его не получил.\r\n\r\nКакова причина, позвольте спросить, этой задержки?\r\n\r\nС уважением,\r\nгеолог Дартеус Железняк' FROM `page_text` WHERE `ID`=184 AND MD5(`Text`)='10c11b76c154c488c4c7377c5bc1fc5e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=184 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 185, 'ruRU', 'Все началось с находки этой проклятой косы в Погибели Роланда. До того, как я нашел косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья.\r\n\r\nНо с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил ее, Погибель Роланда превратилась в место ужасной смерти!' FROM `page_text` WHERE `ID`=185 AND MD5(`Text`)='02ab635a3c9929d35913234de4e2e343' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=185 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 186, 'ruRU', 'Все началось с находки этой проклятой косы в шахте, которую называют Погибелью Роланда. Да, тогда все и началось. Прежде чем это случилось, Братство Справедливости радовалось нашим успехам в Сумеречном лесу. До того, как я нашел косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья.\r\n\r\nНо с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил ее, Погибель Роланда превратилась в место ужасной смерти!' FROM `page_text` WHERE `ID`=186 AND MD5(`Text`)='1c5c9ebd59f1e97f54afdb293654573b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=186 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 187, 'ruRU', 'Если бы я знал, что произойдет, я бы отрезал свою собственную руку, лишь бы не вытаскивать этот кусок дерева, покрытый рунами. Как сильно я жалею об этом! Я всегда думал, что сожаления – привилегия старости. Теперь я знаю, что не старость, а отчаяние надевает на нас мантию из сожалений, не способную и не желающую спадать с плеч, сгорбленных страданием.\r\n\r\nНо достаточно стенать, как какой-нибудь недоделанный поэт. Я должен продолжать свои хроники...' FROM `page_text` WHERE `ID`=187 AND MD5(`Text`)='6a85d176255da02ff5f4bdf78853250d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=187 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 188, 'ruRU', 'После того как я вытащил косу, волна изменений прокатилась по шахте. Свет от наших мерцающих факелов заметался, и казалось, что мы больше не контролируем силу нашего голоса. То шепот звучал, как рев, мечущийся по туннелям, заставляя зажимать уши руками, то наши крики на расстоянии нескольких шагов переставали быть слышны и становились подобны легкому дуновению ветра.\r\n\r\nЭто нервировало, да, но недолго мы пытались понять странную природу этих явлений. Это стало лишь предвестником того, что в действительности изгнало нас из шахты. Воргены.' FROM `page_text` WHERE `ID`=188 AND MD5(`Text`)='2be00f392e728d023f1f0286007a285f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=188 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 189, 'ruRU', 'Они нападали на нас отовсюду, выползая из укромных щелей под ногами и падая на нас откуда-то с потолка. Половина моих товарищей погибла в эти первые минуты паники. Оставшиеся, включая меня, пытались бежать. Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье.\r\n\r\nВсе, что я знаю, – это то, что я – единственный, кто смог спастись из этого места.' FROM `page_text` WHERE `ID`=189 AND MD5(`Text`)='b9ae5499439875a8c05dbd1b67a045fd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=189 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 190, 'ruRU', 'Я могу лишь гадать, как я смог выжить в ту ночь. Я всегда был осторожен, всегда быстро уворачивался от ударов и не раздумывая спрыгивал с обрывов. Мое прозвище, Трясунчик, досталось мне из-за этой моей черты. Так что, возможно, лишь эта способность всегда быть настороже спасла меня...\r\n\r\nИли, возможно, коса, что я вытянул из-под груды щебня. Это не могла быть сама коса, ее я потерял во время моего безумного бегства. Но если это я привел воргенов в Сумеречный лес, то, возможно, воргены отплатили мне неслыханной любезностью. Да будут они прокляты.' FROM `page_text` WHERE `ID`=190 AND MD5(`Text`)='aa8471311fb0edefaa8844551d745eea' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=190 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 191, 'ruRU', 'Или, возможно, я был обречен стать свидетелем тех перемен, что навлек я на Сумеречный лес. Возможно, мой жребий – наблюдать, как воргены врываются на эту землю, окрашивая ее в еще более темный цвет своей злобой.\r\n\r\nЕсли это и правда мой жребий, то он выпал мне дважды. Поскольку воргены – не единственная сила, что пыталась ворваться в Сумеречный лес: монстры со стороны Мертвого Ветра также пытались вторгнуться в него.\r\n\r\nЭто будет в следующей главе моей истории, и я молюсь, чтобы она была последней...' FROM `page_text` WHERE `ID`=191 AND MD5(`Text`)='84ca018617431997d16fb2d4be43a472' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=191 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 192, 'ruRU', 'После того как я выжил при побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен. Я провел в нем несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза. Но оттуда, с моего места я мог видеть, что эти фермеры – славные ребята. Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять. И стало еще тяжелее после случившегося ужаса в шахте.\r\n\r\nТак что я оставался в укрытии. И это спасло мне жизнь.' FROM `page_text` WHERE `ID`=192 AND MD5(`Text`)='70f9914752abc89c910a762b2e78e3aa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=192 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 193, 'ruRU', 'Спустя несколько дней после того, как я начал прятаться в сарае, Свен отправился со своей фермы в Темнолесье. Он поцеловал жену и улыбнулся детям, и обещал вскоре вернуться с игрушками и сладостями. Несчастный человек. То был последний раз, когда он видел свою семью живой.\r\n\r\nПо крайней мере, они расстались счастливыми. И по крайней мере, его жена умерла первой, и ей не пришлось смотреть, как убивали ее детей. Но этот малый жест благоволения судьбы мне ничем не помог. Я видел все, что случилось, и это преследует меня в моих кошмарах.' FROM `page_text` WHERE `ID`=193 AND MD5(`Text`)='728a6c85058373088c15b16c4ef79b61' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=193 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 194, 'ruRU', 'Мои руки дрожат, когда я вспоминаю о подробностях той ночи, когда Свен ушел и его семья была обречена встретиться с черными всадниками один на один. Вновь сожаления гложут меня, ибо я был там и мог восстать против монстров из Мертвого Ветра. Но это никчемные сожаления. Подобные сомнения терзают любого, выжившего после трагедии. Я знаю, что если бы я покинул мое убежище, я тоже был бы убит, мое тело было бы разорвано и раскромсано, а его части разбросаны так далеко, что никто не смог бы меня опознать.' FROM `page_text` WHERE `ID`=194 AND MD5(`Text`)='0441609d891a8c4d643a34705c5f852d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=194 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 195, 'ruRU', 'Но несмотря на то что я был бессилен и не мог остановить это ужасное убийство, одно истинное сожаление все же остается: ведь это я привел черных всадников к ферме Свена. Моя находка не только высвободила воргенов по всему Сумеречному лесу – она привлекла всадников из Мертвого Ветра.\r\n\r\nЯ знаю это, потому что прежде чем они начали убивать, они задали жене Свена один вопрос в тот момент, когда она прижимала к себе своих детей, пытаясь успокоить их и ободрить, зная, что вскоре их ожидает смерть.' FROM `page_text` WHERE `ID`=195 AND MD5(`Text`)='40cc0090170458caf36d23e46b98e05e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=195 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 196, 'ruRU', '"Коса Элуны," – проскрежетал один из всадников голосом одновременно грубым и пронзительным, как звук точильного камня по лезвию секиры. И последнее слово – Элуны – он прокаркал, как будто заглушая звук.\r\n\r\nУжас сковал меня, когда я услышал этот голос, и от страшного его звука, и потому что... я знал, о какой косе говорил всадник. Должно быть, это была та самая проклятая вещь, что я вытащил из-под камней в Погибели Роланда несколькими днями раньше. Вот что искали черные всадники!\r\n\r\nИ вот что убило семью Свена.' FROM `page_text` WHERE `ID`=196 AND MD5(`Text`)='9a0064c835da232fe71d65992aafa54a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=196 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 197, 'ruRU', 'Я никогда не знал, как зовут жену Свена, поскольку ее всегда звали "дорогая", "любовь моя" или "мамочка". Но я хотел бы знать. Я – единственный, кто знает о ее подвиге в тот день, и несмотря на то, что она лишь простая жена фермера, никогда не видел я женщину или мужчину, действующих столь храбро.\r\n\r\nКонечно же, она не знала ничего о косе, но она поняла, что всадники ищут ее, и мгновенный план сформировался в ее голове.\r\n\r\nОн был прост и ясен. Если бы он только сработал.' FROM `page_text` WHERE `ID`=197 AND MD5(`Text`)='2d0ecd6ccae11715df2ba81301513138' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=197 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 198, 'ruRU', '"Коса?" – спросила она спокойным голосом."Конечно, знаю. А кто о ней здесь не знает?" Она посмотрела на всадников твердым взглядом, и я бы поклялся, что она говорит правду, если бы не знал, что это не так. Она не могла знать ничего о косе.\r\n\r\nЕе уловка сработала. Тот же всадник, что задал вопрос, нагнулся к ней и проскрежетал: "Где?"\r\n\r\n"Я отведу вас. Всех вас," – сказала она, и я увидел проблеск надежды в ее глазах.' FROM `page_text` WHERE `ID`=198 AND MD5(`Text`)='c7745c89fa00a6835d138e3cc8b221e7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=198 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 199, 'ruRU', '"Но это далеко отсюда, а у меня на руках дети. Мы должны оставить их здесь."\'\r\n\r\nЕе уловка была проста, но лишь простая уловка могла увенчаться успехом. Если бы она сработала, она бы увела всадников далеко от фермы. Она была бы убита, но ее дети были бы спасены. Это было бы так, если бы всадники поверили ее благородной лжи.\r\n\r\nНесмотря на то что я никогда не был последователем Света, я яростно молился за жену Свена, когда она стояла перед ужасными всадниками.\r\n\r\n"Пожалуйста, – молился я. – Пусть они поверят".' FROM `page_text` WHERE `ID`=199 AND MD5(`Text`)='9f45cf74197a8c5b36038feaae194600' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=199 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 200, 'ruRU', 'Они стояли, замерев, а она спокойно смотрела им в глаза. И тогда один из всадников посмотрел вверх, как будто услышал далекий зов. Он вытащил из-под одежды небольшой камень и заглянул в него. Затем он жестом указал на него жене Свена. Свет полился из всадника в сторону женщины, формируясь в страшную белую руку. Она решительно смотрела на этот свет, но я видел неуверенность за ее маской спокойствия. Когда рука достигла ее, она обхватила пальцами голову женщины.\r\n\r\nИ сжала ее.' FROM `page_text` WHERE `ID`=200 AND MD5(`Text`)='6ca137175b68c4829d6175138f7106b8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=200 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 201, 'ruRU', 'Тело жены Свена стояло прямо, как доска, а ее глаза распахнулись. И хотя ее губы широко открылись в крике, не раздалось ни звука. После нескольких секунд этой пытки рука отпустила ее, и она упала на колени. Всадник, державший драгоценность, сел прямо в своем седле и громкий голос раздался из камня.\r\n\r\n"Эта женщина лжет," – раздался голос, пугающий меня теперь в кошмарах. "Она никогда не видела косу"."' FROM `page_text` WHERE `ID`=201 AND MD5(`Text`)='2441b7585403098b033df3c11a3ab406' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=201 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 202, 'ruRU', 'После этого всадник поник, как будто чей-то дух покинул его. И тогда прежним визгливым голосом старика он произнес последние слова:\r\n\r\n"Повелитель сказал свое слово. Убить их".' FROM `page_text` WHERE `ID`=202 AND MD5(`Text`)='fb245acad599506f045834b73cd27f0b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=202 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 203, 'ruRU', 'Я не могу описать того, что случилось дальше. Я ясно помню все, но даже моя истерзанная душа не может изложить на бумагу последовавшие за тем несколько ужасающих минут.\r\n\r\nЯ могу лишь написать, что семья Свена была убита. И вскоре вернулся Свен, чтобы увидеть эту страшную картину смерти. Такое горе исказило его черты, что я боялся выйти к нему. И я так боялся, что он может обнаружить меня сам, что покинул свое убежище в сарае. Я не знаю, где теперь Свен, но я молюсь, что когда-нибудь он обретет покой.' FROM `page_text` WHERE `ID`=203 AND MD5(`Text`)='5c4a5a81f183b680ae59017a61b97969' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=203 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 205, 'ruRU', 'После того как я вытащил косу, они напали на нас отовсюду, выползая из укромных щелей под нашими ногами и падая на нас откуда-то с потолка. Половина наших людей погибла в эти первые минуты паники. Оставшиеся, включая меня, пытались бежать. Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье.' FROM `page_text` WHERE `ID`=205 AND MD5(`Text`)='21641d4f4833e5c46b537e376a3777b3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=205 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 206, 'ruRU', 'Не понимаю, как мне удалось выжить в ту ночь. Я всегда был осторожным, не ввязывался в драки и не попадался в ловушки. Я даже получил за это свое прозвище. Наверное, эта природная осторожность спасла меня от смерти...\r\n\r\nИли Коса, которую я вытащил из хлама. Хотя вряд ли сама Коса, ее я потерял во время своего отчаянного бегства. Но если воргены появились в Сумеречном лесу из-за меня, тогда, похоже, они оказали мне ответную любезность. Чтоб им провалиться!' FROM `page_text` WHERE `ID`=206 AND MD5(`Text`)='abccf657fdb43e320e46fc18e9646209' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=206 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 207, 'ruRU', 'После того как я выжил в побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен. Я провел в нем несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза. Но оттуда, с моего места, я мог видеть, что эти фермеры – славные ребята. Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять. И стало еще тяжелее после случившегося ужаса в шахте.\r\n\r\n Так что я оставался в укрытии.' FROM `page_text` WHERE `ID`=207 AND MD5(`Text`)='4d2be878b13b8c6330c10909db5e0c9b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=207 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 208, 'ruRU', '<Оставшаяся часть книги пуста.>' FROM `page_text` WHERE `ID`=208 AND MD5(`Text`)='c1bc6aa679f102ead7f04c1a39dfdc21' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=208 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 211, 'ruRU', 'ОТЧЕТ: Волки\r\n\r\nАтаки животных на Североземье, о которых я сообщал ранее, увеличились. Эоган считает, что появление волков в долине связано с тем, что их спугнули из Сумеречного леса.\r\n\r\nНесмотря на то что волки редко охотятся на людей, растущее их число привело к нескольким стычкам с фермерами. И пропало очень много домашнего скота.' FROM `page_text` WHERE `ID`=211 AND MD5(`Text`)='70357dab12b93a5a2dbfc8d65fcda47f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=211 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 213, 'ruRU', 'Похлебка Западного Края\r\n\r\n3 куска жилистого мяса стервятника \r\n3 рыла кровоклыка\r\n3 глаза мурлока \r\n3 окры\r\n\r\nСмешать и довести до кипения. Тушить на медленном огне по крайней мере часа два и подавать на стол.' FROM `page_text` WHERE `ID`=213 AND MD5(`Text`)='d662382180e6dd7918de6332fa6f5ce4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=213 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 214, 'ruRU', 'Дорогая Иветта, я доверяю это письмо нашему самому быстрому бегуну. Я молюсь, чтобы он смог пробраться сквозь кольцо окруживших нас сил. И молюсь, что ты прочитаешь мои слова, поскольку это последнее, что ты услышишь от меня.\r\n\r\nЕдинственное, что меня успокаивает в эти мрачные дни, – это чувство облегчения от того, что я знаю: ты не разделишь мою участь.' FROM `page_text` WHERE `ID`=214 AND MD5(`Text`)='bdfa900b49f5e55b2ac245ca372fb384' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=214 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 218, 'ruRU', 'Я боюсь, что война между Стоунфилдами и Маклурами убьет начинающийся роман между Томми Джо и Мейбелл. В такие времена, когда мрачные новости и слухи о войне доходят до нас, о молодости и любви должно заботиться.\r\n\r\nТак вот, просьба: я прошу тебя использовать свои умения и создать зелье или эликсир, который бы помог этим молодым влюбленным встретиться друг с другом.\r\n\r\nСпасибо тебе, Вильям. И пожалуйста, когда найдешь время оторваться от работы, заходи в гости. У нас есть о чем вспомнить и посмеяться.\r\n\r\nМилдред' FROM `page_text` WHERE `ID`=218 AND MD5(`Text`)='bfe859111aafb808c6e3cdd85ccb5e4d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=218 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 219, 'ruRU', 'От Бароса Алекстона,\r\nгородского архитектора\r\nШтормград\r\n\r\nВаше Величество,\r\n\r\nЕсть множество причин, по которым, мне кажется, должен быть составлен и предоставлен рапорт о недавних аферах "Братства Справедливости" и их активности в королевстве.\r\n\r\nДля начала немного истории. Как вы можете знать – а может быть, и нет – мое служение городу Штормград началось в качестве члена гильдии Каменщиков. Спустя годы работы мы закончили восстановление' FROM `page_text` WHERE `ID`=219 AND MD5(`Text`)='0228801b895ac152b1a7d4ff840111e6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=219 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 220, 'ruRU', 'Штормграда. К тому времени счета все еще не были оплачены, а о вознаграждениях и заработных платах гильдии Каменщиков старательно умалчивалось.\r\n\r\nВ то время Эдвин ван Клиф был избранным главой гильдии Каменщиков, и он в открытую требовал возмещения за нашу работу. В ответ Благородный дом Штормграда приказал распустить гильдию Каменщиков, что, естественно, разозлило ван Клифа. Возглавив бунт, ван Клиф вывел Каменщиков из города.\r\n\r\nПрежде чем я продолжу, я бы хотел рассказать о других событиях, случившихся' FROM `page_text` WHERE `ID`=220 AND MD5(`Text`)='51759471062efca61533795daf3a8e0b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=220 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 221, 'ruRU', 'в то же время, к которым я хотел бы привлечь ваше внимание.\r\n\r\nВо-первых, в то время мне предложили пост городского архитектора с условием, что я не стану присоединяться к ван Клифу. Исходя из явственных идеологических разногласий, я принял решение остаться в Штормграде.\r\n\r\nВо время восстания лейтенанта и самого доверенного помощника ван Клифа, Базиля Тредда, поймали и заключили в тюрьму. В ожидании суда и следствия Тредд был практически забыт в тюрьме Штормграда.\r\n\r\nВозвращаясь к ван Клифу: после того как он вывел оставшихся' FROM `page_text` WHERE `ID`=221 AND MD5(`Text`)='1db68dd48e0fa833f2823c7a6c1f57d5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=221 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 222, 'ruRU', 'Каменщиков из Штормграда, он воспользовался относительно незащищенным статусом Западного Края и использовал свое превосходство в силе, чтобы выгнать оттуда множество фермеров и захватить несколько золотых рудников.\r\n\r\nВоспользовавшись ресурсами, оказавшимися в его распоряжении, ван Клиф составил план возмездия правительству Штормграда.\r\n\r\nЭта информация стала известна лишь недавно благодаря помощи носителя этого документа, который сыграл важную роль в пролитии света на этот громадный заговор.' FROM `page_text` WHERE `ID`=222 AND MD5(`Text`)='6731323068ce58c7c0077f175cd5cb01' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=222 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 229, 'ruRU', 'День первый.\r\n\r\nМой танк сломался, но я знаю, что залежи руды хирона – где-то в этих холмах. Я велел Молотоногу оставаться и присматривать за нашими танками.\r\n\r\nПродолжил поиск в одиночку. Если я не смогу вернуться назад, то журнал останется моим последним завещанием.\r\n\r\n--Бурон Хилдельв, пилот\r\nПаровая бригада Стальгорна' FROM `page_text` WHERE `ID`=229 AND MD5(`Text`)='7a13da97bdf28b52fd213739e4e6995d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=229 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 230, 'ruRU', 'День второй\r\n\r\nМой поиск продолжается, но до сих пор нет следов руды. Интересно, не пошутил ли Каменный Убор по поводу этой руды. Если так, то он получит хорошую затрещину от меня, когда я вернусь в Поселок Сталежара!\r\n\r\nКогда я размещал свой лагерь, то услышал эхо рычания в каньонах.\r\n\r\nЭто был не волк. Это, должно быть, медведь.' FROM `page_text` WHERE `ID`=230 AND MD5(`Text`)='a558b59ffc733290515507e7786500f1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=230 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 231, 'ruRU', 'Третий день\r\n\r\nРычание не прекращалось всю ночь и преследует меня даже днем. Я не могу сосредоточиться на добыче руды. Думаю, это медведь!\r\n\r\nПусть только подойдет поближе, мне уже не терпится всадить кирку в его череп!' FROM `page_text` WHERE `ID`=231 AND MD5(`Text`)='9dc9d25bccfb75f6fea3919ab0aa3155' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=231 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 232, 'ruRU', 'День четвертый.\r\n\r\nМои запасы подходят к концу. У меня все еще очень много еды, но я не планировал столь долго оставаться в лесу, так далеко от моего танка, и взял с собой лишь два кега эля.\r\n\r\nЯ не спал обе прошлые ночи, прислушиваюсь к этому проклятому реву, и практически до дна выпил оба кега!\r\n\r\nЗавтра мне придется повернуть назад к Молотоногу и нашим паровым танкам. Я не хочу здесь пропасть без выпивки.' FROM `page_text` WHERE `ID`=232 AND MD5(`Text`)='f0e7e293ca7f1461579d00cd20c4ed2a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=232 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 233, 'ruRU', 'День пятый.\r\n\r\nЭтот проклятый медведь добрался до меня! Он бросился на меня в полдень и напал со спины.\r\n\r\nЯ бы унюхал его задолго до этого, если бы он напал на меня не с подветренной стороны – запах от него шел ужасный! Одна только вонь от его грязной шкуры и гнилое дыхание заставили бы меня сбежать оттуда!\r\n\r\nЯ сражался с ним, но он хорошо подрал мою ногу. Теперь я не могу двигаться, эля нет, и я так и не нашел эту руду. Проклятье!' FROM `page_text` WHERE `ID`=233 AND MD5(`Text`)='96af9cfa40609dbfe29995428384a9a8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=233 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 234, 'ruRU', 'День шестой.\r\n\r\nМедведь еще не вернулся; должно быть, я задал ему хорошую трепку! Но я все еще слышу его рычание. Я думаю, он ждет, когда я умру!\r\n\r\nКто бы ни нашел эту книгу, я прошу тебя. Убей этого грязного медведя. Убей его и отнеси книгу моему другу Молотоногу. Он захочет узнать, что произошло.\r\n\r\nИ возьми мою броню. Она понадобится тебе в бою со старым Паршивым Когтем!' FROM `page_text` WHERE `ID`=234 AND MD5(`Text`)='82e35c704e0547d0aa19dcdfbb8f18a8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=234 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 235, 'ruRU', 'Мое почтение Элло Чернодреву, мэру Темнолесья. Боюсь, что у меня есть новости для вашего города. Важные новости.\r\n\r\nВидите ли, я – создатель. Я обманул носителя этого письма, чтобы он помог мне создать мое последнее, наиболее ужасающее творение – монстра из плоти, костей и перекрученного металла! В тот момент, когда вы читаете эти слова, оно находится снаружи моего скромного жилища, скрежеща зубами и ожидая одного моего слова, чтобы отправиться убивать.\r\n\r\nНо вскоре вы сами обо всем узнаете.\r\n\r\nБальзамировщик' FROM `page_text` WHERE `ID`=235 AND MD5(`Text`)='d455658cce9369314aaa23f2c44beef1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=235 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 236, 'ruRU', 'Исследуя окаменелости, я пришел к выводу, что в древние времена великая чума свирепствовала у озера Лордамер. Что послужило ее причиной? Мы никогда не узнаем. Но уровень загрязнения весьма высок, исходя из насыщенной концентрации останков, представленных в залежах озерного пласта.' FROM `page_text` WHERE `ID`=236 AND MD5(`Text`)='18d7b709670092db3302434404a15891' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=236 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 237, 'ruRU', 'В попытке понять прошлое я начал изучать создания настоящего, надеясь обнаружить недостающие ключи к загадке. Озерные тихоходы и озерные ползуны – древние создания, населяющие остров в центре озера Лордамер. Мох, растущий на них, содержит следы частиц тех самых окаменелостей. Необходимо провести больше исследований, прежде чем я смог бы сделать выводы о том, что означает эта связь.' FROM `page_text` WHERE `ID`=237 AND MD5(`Text`)='0a6cf59ae3038c52f173ffbb4405b32f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=237 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 238, 'ruRU', 'Собирая образцы мха, я случайно стал свидетелем сцены кровавой битвы. Клан мурлоков Коварного Плавника подвергся нападению мародерствующих банд гноллов. Трупы и гноллов, и мурлоков были разбросаны по всему полю боя. Когда я проходил мимо растерзанного тела мурлока, я заметил странно затвердевшую опухоль, выступающую из раны. Когда я начал изучать ее, стало ясно, что похожие свойства я обнаружил у мха, который собирал. К сожалению, больше я не смог больше найти ни одной опухоли.' FROM `page_text` WHERE `ID`=238 AND MD5(`Text`)='d9d2ddf7233b37c1d9d8aef27a17a90b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=238 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 245, 'ruRU', 'Без вести пропавший: капрал Кеешан\r\n\r\nВ последний раз его видели во время кровавого сражения за Башню Каменной Стражи, из докладов стало известно, что его утащили орки Черной Горы.\r\n\r\nПолагают, что он содержится в плену в качестве военного заложника в лагере Черной Горы, севернее Приозерья, южнее дороги, ведущей в Пылающие степи.\r\n\r\nВ соответствии с приказом мирового судьи Соломона – любому, кто поможет спасти капрала Кеешана, будет выдана награда маршалом Маррисом.' FROM `page_text` WHERE `ID`=245 AND MD5(`Text`)='ce0962a3172b5a568a32bf05f338df09' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=245 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 246, 'ruRU', 'Я провел следующие недели, перебегая с места на место, нигде не задерживаясь, из страха перед всадниками. Сейчас я остановился в заброшенном городе Вороньем холме – прячусь, как обычно. Я не могу встретиться с той силой, что они использовали на жене Свена, и я знаю, что она рыщет по Сумеречному лесу, все еще ищет косу. Я потерял ее, и за это я благодарю Свет, ибо если бы я оставил ее у себя, я знаю, меня бы обнаружили. Даже теперь в глубине моего сердца я уверен, что меня найдут.\r\n\r\nЯ так устал...' FROM `page_text` WHERE `ID`=246 AND MD5(`Text`)='c0690adf8690fda521fd7259f91c6040' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=246 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 248, 'ruRU', 'Приветствую вас, Господин,\r\n\r\nПриношу свои извинения за то, как мое послание попало к вам. Темные маги в Альтераке сосредоточили все свои силы на выполнении поставленной задачи, и я был вынужден передать вам сообщение с этим гонцом – новобранцем из рядов наших новых "союзников". Однако я зашифровал послание самым тайным из наших шифром. Эта деревенщина не поймет ни слова.' FROM `page_text` WHERE `ID`=248 AND MD5(`Text`)='e56cf74a1dab3630254beeefc1ff5d8a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=248 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 249, 'ruRU', 'Валлик,\r\nохраняй раба до нашего возвращения. Теперь здесь небезопасно, мы не можем больше хранить ЕГО тут. Мы отправимся на север, обходя стороной любые места, где нас могли бы заметить.\r\n\r\nОни – животные, но животные безжалостные – мы достаточно от них натерпелись, у нас есть причины для беспокойства. Лучше спрятать любые знаки, что могли бы заставить собраться их вместе. Меньше всего мы бы хотели дать им повод воссоединиться и напасть на нас.' FROM `page_text` WHERE `ID`=249 AND MD5(`Text`)='269e9b5c0f03f76f37316567fa06c182' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=249 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 250, 'ruRU', 'Группа из Братства Справедливости встретится с Собирателем, после чего он переправит собранное золото.\r\n\r\nУбедитесь, что этот процесс произойдет без ошибок и в условиях строжайшей секретности. Собиратель ответственен за переправку золота, но в конечном счете каждый член Братства Справедливости должен убедиться, что его роль будет выполнена со всем тщанием и осторожностью.' FROM `page_text` WHERE `ID`=250 AND MD5(`Text`)='e7447d5f5f0c6865d8dddf20e476e2d2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=250 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 251, 'ruRU', 'Помните, мои братья, когда-то мы были гордыми ремесленниками. Мы будем исполнять наши сегодняшние обязанности с тем же тщанием, что когда-то использовали в нашем ремесле.\r\n\r\n-ЭВК' FROM `page_text` WHERE `ID`=251 AND MD5(`Text`)='bb92cc4e2f81d649d4191dc199c3fb7e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=251 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 252, 'ruRU', 'Боюсь, мой отец сделал огромную ошибку, решившись остаться и защищать наш дом. Силы Плети свирепствуют в Тирисфальских лесах, и несмотря на то что мы достаточно укреплены и у нас хватает запасов, после предательства моего брата Девлина у нас не хватает сил и рук, чтобы противостоять их постоянным атакам.\r\n\r\nКогда ты получишь мое письмо, Иветта, то будешь знать, что Девлин – предатель.' FROM `page_text` WHERE `ID`=252 AND MD5(`Text`)='43f546d494bfa37c0dd8524c4aeaec88' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=252 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 253, 'ruRU', 'Девлином завладело отчаяние, и он искал, как избежать ожидающей нас печальной участи, и вот почему он заключил договор с Плетью. Я не знаю, сколько ему пообещали за предательство, но я уверен, все это было ложью.\r\n\r\nЕсли ты встретишь моего брата, беги от него. Он – монстр. Несколько ночей назад он убил двоих наших часовых и провел небольшую группу Плети через эту брешь к тому месту, где спало большинство из нас.' FROM `page_text` WHERE `ID`=253 AND MD5(`Text`)='5f28ac8ee48a8d74ead00200fcc043b0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=253 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 254, 'ruRU', 'Нападение было ужасным. Они убили треть из нас к тому моменту, когда мы смогли их уничтожить. И теперь у нас едва хватает людей для защиты наших границ. Это лишь вопрос времени, когда наши утомленные стражники падут и Плеть атакует нас.\r\n\r\nИ хотя я видел лицо Девлина среди доведенных до отчаяния мужчин и мрачнолицых воинов Плети в ту проклятую ночь, он ускользнул от меня прежде, чем я смог до него добраться. Возможно, он мертв – а возможно, выжил, и стал агентом Плети.\r\n\r\nКак бы то ни было, он – монстр.' FROM `page_text` WHERE `ID`=254 AND MD5(`Text`)='4f49b12a3d19c733a326b9554508e91b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=254 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 255, 'ruRU', 'Девлин предупреждал нас, что если мы попробуем противостоять Плети, все мы будем обречены. Он говорил нам об этом, когда они только ступили в Тирисфальские леса, задолго до того как они достигли нашего дома. Возможно, он умолял нас покинуть его, а может быть, злорадствовал.\r\n\r\nВсегда было сложно понять истинные мотивы Девлина. Еще будучи ребенком, он был для нас всех загадкой.' FROM `page_text` WHERE `ID`=255 AND MD5(`Text`)='b5ec63691eef487e4dc4ea671452de59' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=255 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 256, 'ruRU', 'Но он был прав. Мы обречены. Линия семьи Агамондов прервется. Несмотря на то что я все еще жив, скоро я погибну.\r\n\r\nЯ не боюсь, и не сожалею о том, что остался со своей семьей. Но мои последние мысли – о тебе.\r\n\r\nПродолжай жить, моя возлюбленная Иветта, и я обрету покой.\r\nТармен' FROM `page_text` WHERE `ID`=256 AND MD5(`Text`)='16853171cc7482e77a1fbb4f0d8040fc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=256 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 257, 'ruRU', 'Наши планы продвигаются споро; как я уже упоминал, мы заключили союз с группой людей, называющих себя Синдикатом. Их лидеры когда-то принадлежали к Альтеракской знати, и они жаждут вновь править там.\r\n\r\nИтак, они заключили с нами сделку. Сделку, о которой они пожалеют.' FROM `page_text` WHERE `ID`=257 AND MD5(`Text`)='61d45254c8789c09138144c150a0ecba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=257 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 258, 'ruRU', 'Сегодня Синдикат контролирует лишь малые силы, но они хорошо знают эту область и собрали достаточное количество воинов для выполнения задач. С должным руководством, я уверен, Синдикат захватит Альтерак довольно скоро.\r\n\r\nМы убедили Синдикат направиться в город Стромгард неподалеку в нагорье Арати. Этот город – поле боя между нашими силами, ограми и людьми Стромгарда, но мы думаем, что продумав тщательную тактику, мы завладеем этим когда-то великим городом.' FROM `page_text` WHERE `ID`=258 AND MD5(`Text`)='9328cd143cb36629a7a7ad55f139a518' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=258 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 259, 'ruRU', 'Воплотив наш замысел в жизнь, мы сможем перейти к следующему этапу плана. Необходимо сплотиться вместе и закрепиться в этом регионе, после этого мы сможем начать приготовления к Третьему Походу.\r\n\r\nСкоро владыки Легиона вознаградят нас за наши труды и снова низвергнут огонь с небес!' FROM `page_text` WHERE `ID`=259 AND MD5(`Text`)='4917aaa2c0721653892cdd9d4abd0c41' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=259 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 261, 'ruRU', 'Регистрационная книга Хилсбрада\r\n\r\nМы, народ Хилсбрада, торжественно клянемся верой и правдой служить Альянсу, ведомому великими монархами, – королем Стальгорна Магни Бронзобородом и королем Штормграда Андуином Ринном.\r\n\r\nВ этом документе содержатся результаты переписи населения для целей управления этим славным городом у подножия холмов в великих Альтеракских горах, также здесь указаны те, кто платил налоги своим королям и великому и могучему Альянсу.' FROM `page_text` WHERE `ID`=261 AND MD5(`Text`)='3d55c7ba3e5671827ef774b4cdbe17b3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=261 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 262, 'ruRU', 'Мировой судья Резерфорд Бернсайд\r\nВсе задолженности выплачены.\r\n\r\nКузнец Эйвери Веррингтан\r\nВсе задолженности выплачены.\r\n\r\nКлерк Гораций Белоконь\r\nВсе задолженности выплачены.\r\n\r\nСоветник Гиллис\r\nВсе задолженности выплачены.\r\n\r\nСоветник Крюкс\r\nВсе задолженности выплачены.\r\n\r\nФермер Гетц\r\nВсе задолженности выплачены.\r\n\r\nФермер Рей\r\nКрупный долг. Выплата долга сельскохозяйственной продукцией обещана в урожай.\r\n\r\nФермер Лаийон\r\nКрупный долг. Выселен с земли.' FROM `page_text` WHERE `ID`=262 AND MD5(`Text`)='591898b6068b3a7e90834807d5a3ac28' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=262 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 263, 'ruRU', 'Фермерша Калаба\r\nКрупный долг. Выплата долга сельскохозяйственной продукцией обещана в урожай.\r\n\r\nГражданин Уилкс\r\nВсе задолженности выплачены.\r\n\r\nГражданин Боноан\r\nВсе задолженности выплачены.\r\n\r\nШахтер Веллти\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.\r\n\r\nШахтер Сидней\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.\r\n\r\nШахтер Хакетт\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.' FROM `page_text` WHERE `ID`=263 AND MD5(`Text`)='ef9b39e1aed4dddf02e4159d2bf9805c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=263 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 265, 'ruRU', 'Шахтер Оруэлл\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.\r\n\r\nШахтер Фитцджеральд\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.\r\n\r\nГражданин Недранд\r\nВсе задолженности выплачены.\r\n\r\nГражданин Мэй\r\nВсе задолженности выплачены.\r\n\r\nСтаршина Бондс\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.' FROM `page_text` WHERE `ID`=265 AND MD5(`Text`)='9f85f39b203e111a92774588b284eced' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=265 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 266, 'ruRU', 'Кеган Мракмар, лидер небольшой группы нежити, пришедший к нам в поисках убежища для его "братьев", опроверг все обычные представления о таких, как он. Может быть, его кожа гнила, и кровь не течет по его жилам, но он держал себя очень достойно, и, похоже, заботился больше о безопасности своих товарищей, чем о самом себе.\r\n\r\nВ действительности, признаюсь честно, в нем было больше человечности, чем в некоторых окружающих.' FROM `page_text` WHERE `ID`=266 AND MD5(`Text`)='5980524aa6e9078319401f81274a4a21' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=266 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 267, 'ruRU', 'Но почему я вспомнила об этом? Я это сделала для того, чтобы вы поверили тому, что я собираюсь написать, словам, что произнесли губы Кегана, и надеюсь, мои коллеги, читая этот дневник, поймут, почему я поверила тому, что он сказал:\r\n\r\n"То, что осталось от Древних Богов, все еще влачит жалкое существование в глубоких расщелинах этого мира. Новые силы ищут способ обуздать эти древние силы, и тот, кто сумеет это сделать, получит в свое распоряжение ужасное орудие против своих врагов".' FROM `page_text` WHERE `ID`=267 AND MD5(`Text`)='24115d0a1597b443914b415b30e26f7e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=267 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 268, 'ruRU', 'Вот что произнес Кеган, когда протягивал мне свою подвеску Кровавого камня, и был страх и, может быть, благоговение в его глазах, когда он делал это. Когда его рука встретилась с моей, он замешкался, будто не желая расставаться с подвеской. Я содрогнулась от отвращения и по сей день не знаю, из-за того ли, что я ощутила касание его мертвой плоти, или это подвеска заставила меня поежиться.\r\n\r\nИбо я почувствовала в ней силу. Глубокую, скрытую, ненасытную силу. И острую жажду свободы.' FROM `page_text` WHERE `ID`=268 AND MD5(`Text`)='d19ceb86fde9ad1c2e87d282a4f97ff9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=268 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 269, 'ruRU', 'Несмотря на то, что мои коллеги в Даларане настороженно отнеслись к идее изучения кровавых камней, которые принесли с собой Кеган и его спутники, заключив в карантин четырех беженцев и оставив кровавые камни при них, искренность Кегана обязала меня изучить его подвеску Кровавого камня.' FROM `page_text` WHERE `ID`=269 AND MD5(`Text`)='fa8575417a6ff3c17255a04f46d1743a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=269 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 270, 'ruRU', 'Я надеялась доказать моим коллегам, что этот камень обладает магическими свойствами, и если мы, волшебники Даларана, не желаем использовать силу кровавых камней, мы должны по крайней мере изучить их свойства, поскольку однажды наши враги могут использовать их против нас.\r\n\r\nИ так начались мои исследования.' FROM `page_text` WHERE `ID`=270 AND MD5(`Text`)='4c012d5c5231a2fa9335db5aeee01764' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=270 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 271, 'ruRU', 'Я начала мои эксперименты с предположения, что кровавые камни были каким-то видом камня, как кварц или обсидиан. Посему я запустила серию экспериментов для опознания того, какие минералы содержатся в кровавом камне, какие силы использовались для придания ему такой твердости и цвета, и других свойств, сходных с камнем или рудой. Но подвеска Кровавого камня, к моему разочарованию, не отреагировала на мои процедуры так, как это сделала бы обычная руда.' FROM `page_text` WHERE `ID`=271 AND MD5(`Text`)='4eb5e86c94ee10c1d23d940c1599376b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=271 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 272, 'ruRU', 'В действительности она часто реагировала с точностью до наоборот! Как будто подвеска умышленно искажала результаты моих экспериментов.\r\n\r\nКак будто камень был думающим, живым существом.\r\n\r\nРазгневанная, но не сдавшаяся, я прекратила выдвигать предположения о том, что подвеска была инертным куском скалы, и начала считать, что она была живым существом.\r\n\r\nНо снова я была не права.' FROM `page_text` WHERE `ID`=272 AND MD5(`Text`)='e78bfa49e87ff58c70e20115dad758ae' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=272 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 273, 'ruRU', 'Ни один из моих тестов не пролил свет на загадку происхождения кровавого камня. В то время единственной загадкой, что мне удалось разгадать, было то, что кровавый камень – ни живое, ни мертвое существо!\r\n\r\nНо тогда, на грани поражения, я сделала прорыв. В моем последнем тесте не последнюю роль сыграла стеклянная колба с отколотым горлышком. Когда я закончила свой тест, опять ничего не обнаружив, я убирала инструменты со своего рабочего стола и порезалась об острый край колбы.' FROM `page_text` WHERE `ID`=273 AND MD5(`Text`)='cfc66f25251f59cbb0948a85c987c9cf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=273 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 274, 'ruRU', 'Порез был неглубокий, хотя обильно кровоточил. Прежде чем я обмотала мой палец бинтом, добрая порция моей крови пролилась на стол.\r\n\r\nИ когда я начала убирать ее, я заметила странную вещь…' FROM `page_text` WHERE `ID`=274 AND MD5(`Text`)='cc7d7cd03ecfc77fbc191660a3e33ae2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=274 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 275, 'ruRU', 'Кровь, что я пролила возле подвески Кровавого камня, медленно двигалась по направлению к драгоценности, как если бы ее притягивала к камню некая сила. А кровь, что попала на подвеску, похоже, исчезла, и красный цвет камня стал еще более насыщенным, когда тот всосал еще немного моей крови.' FROM `page_text` WHERE `ID`=275 AND MD5(`Text`)='cd3cb74593133b1d19e276d8626baef4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=275 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 276, 'ruRU', 'После того как я это увидела, моя голова просветлела, возможно, благодаря недавнему порезу (хотя я не верю, что потеряла настолько много крови), а может быть потому, что я, наконец-то, после стольких разочарований, обнаружила одно из свойств кровавого камня. Я добралась до своего стула и села, размышляя. Мысли и вопросы роились в моей голове, вызывая головокружение и угрожая свалить меня наземь.\r\n\r\nКровавый камень пьет кровь? Ему нужна кровь? Он притягивает кровь?' FROM `page_text` WHERE `ID`=276 AND MD5(`Text`)='462b11846ce574d94206bc60012ab168' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=276 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 277, 'ruRU', 'Или кровавый камень состоит из крови? И, если так, чьей крови? Моей? Крови другого человека? Животного?\r\n\r\nИли, может быть, кровавый камень – это кровь некоего неизвестного существа – того самого существа, которого Кеган одновременно почитал и боялся, когда отдавал мне эту подвеску?\r\n\r\nВот вопрос, на который нужно получить ответ. Это – ключ.' FROM `page_text` WHERE `ID`=277 AND MD5(`Text`)='149ce68897c1770374fd1e1ad61221a5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=277 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 278, 'ruRU', 'Я снова загорелась интересом и вернулась к своим экспериментам. В этот раз я не выдвигала никаких предположений, методично делая все тесты, что были в моем распоряжении. Это чрезвычайно увеличило понадобившиеся усилия, но шансы прояснить что-либо увеличились соответственно.\r\n\r\nИ, несмотря на то что моя лаборатория мала и у меня нет помощников, к которым я могла бы обратиться за помощью, я обнаружила еще одно интригующее свойство кровавого камня...' FROM `page_text` WHERE `ID`=278 AND MD5(`Text`)='4d937889bb464b3a6cfc956f17e27ca1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=278 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 279, 'ruRU', 'В дополнение к крови в камень были вплавлены силы стихий. Огонь, вода, гром и камни были перемешаны с кровью (но все же, с чьей кровью?), и несмотря на то, что эта смесь была внешне инертна, все эти силы внутри нее бушевали в неистовом противостоянии. Столь много вопросов возникло об этом поразительном, знаковом материале.' FROM `page_text` WHERE `ID`=279 AND MD5(`Text`)='9f8b61c52dddac034e0707f2629fab46' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=279 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 280, 'ruRU', 'Но чтобы ответить на эти вопросы, понадобятся еще тесты и исследования подвески, и я боюсь, что Лордамерские выселки не смогут снабдить меня ни помощниками, ни оборудованием для выполнения этой задачи. Поэтому я отправила подвеску Кровавого камня вместе с посыльным в Даларан с особыми инструкциями о том, как исследовать его, чтобы они могли избежать тех разочарований, что постигли меня с самого начала.' FROM `page_text` WHERE `ID`=280 AND MD5(`Text`)='9052a857cb9eea90ee66c3953aa0e956' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=280 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 281, 'ruRU', 'В ожидании результатов мы с Кеганом много беседовали. Мне хотелось побольше узнать от него о кровавых камнях, но он никогда не говорил мне больше, чем в тот день, когда отдал мне свою подвеску. И он нечасто говорил о времени, проведенном им среди тех, кого он называл "Отрекшимися", – так он именует свой клан нежити.' FROM `page_text` WHERE `ID`=281 AND MD5(`Text`)='526cf36b4a23634311d0b486bdef36c3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=281 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 282, 'ruRU', 'Зато Кеган очень охотно говорил о других вещах, особенно о своем детстве, проведенном в Лордероне до его падения. \r\n\r\nОн по-прежнему полон любви к этому потерянному королевству, хотя оно сейчас разрушено и мертво.\r\n\r\nРастущая привязанность к Кегану придавала мне терпения в ожидании результатов анализов.' FROM `page_text` WHERE `ID`=282 AND MD5(`Text`)='bfa0e768232776bbdfbd1a2631f9daef' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=282 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 283, 'ruRU', 'Но после нескольких недель отсутствия новостей терпение у меня иссякло. Из Даларана мне сообщили, что кровавый камень к моим коллегам так и не попал. Курьер каким-то образом пропал по дороге, а с ним была утрачена и подвеска кровавого камня!\r\n\r\nЭто очень печальные новости, так как, хотя у Кегана и его последователей есть еще образцы кровавого камня, с которыми мы можем экспериментировать, я опасаюсь, что подвеска попадет в неподходящие руки.' FROM `page_text` WHERE `ID`=283 AND MD5(`Text`)='60763c1302d0825377863e696041a75e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=283 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 284, 'ruRU', 'Пришлось отправить в Даларан другого посланца. Мне стало известно, что они прочесывают руины возле нашей защитной сферы в поисках подвески.\r\n\r\nОстается лишь надеяться, что мы не опоздали.' FROM `page_text` WHERE `ID`=284 AND MD5(`Text`)='916f3a50158afbcc157085c502e0a6a5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=284 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 285, 'ruRU', 'История Гри\'лека Странника\r\n\r\n[...Начало надписи, выбитой на камне, стерлось, но окончание все еще можно было прочитать...]\r\n\r\nГри\'лек топал по джунглям. Его глаза горели, и его грудь клокотала, ибо великий гнев переполнял его. \r\n\r\nВ ярости он рычал на небо и воздевал руку. Он воздевал левую руку, ставшую сильной и крепкой от охоты без своего близнеца. \r\n\r\nИбо правая рука Гри\'лека была утрачена безвозвратно.' FROM `page_text` WHERE `ID`=285 AND MD5(`Text`)='c0ed46bb5fd3a80693a594ce4becdd70' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=285 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 303, 'ruRU', 'Приказ пиратам Кровавого Паруса\r\n\r\nЧитайте и запоминайте, ребятки, другого такого удачного шанса напасть на Пиратскую бухту у нас не будет!\r\n\r\nСтарину Данкена я послал с разведкой на север и сказал ему ждать сигнала.\r\n\r\n"Госпожа Удача" бросит якорь у южного мыса, чтобы взять припасы. Наш коротышка, капитан Штиллец, со своей командой приготовится забрать все награбленное на борт. Ну а с остальным управится наш болван Брут.' FROM `page_text` WHERE `ID`=303 AND MD5(`Text`)='16d0277dbb77b16a740575dedce4f765' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=303 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 306, 'ruRU', 'Я хочу, чтобы капитан Кильватель привел "Бурун" к берегу с юго-востока. Мы отправим его команду по суше, когда будет дан сигнал. \r\n\r\nЭтот здоровый увалень, Соленое Копыто, может повести ребят в атаку. На Ревилгазе и Морском Роге я ставлю черную метку. Шлите их прямиком на дно моря.\r\n\r\nА вы, парни, отвечаете за то, чтобы спасти все, что может пригодиться для нашей затеи с ван Клифом в Мертвых копях.' FROM `page_text` WHERE `ID`=306 AND MD5(`Text`)='b02600d1290cbfb31e5ce0a8dba1fc4d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=306 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 307, 'ruRU', 'Я отдам приказ Многоглазу открыть огонь. Артиллерийский обстрел помешает кораблям Черноводья выходить из гавани и входить в нее.\r\n\r\nПосле того как "Багровый Парус" разрядит свои пушки, я поставлю его рядом с "Буруном" для поддержки и обеспечения резервов, если это понадобится.\r\n\r\nКогда Соленое Копыто и его парни вычистят город и все наши будут на борту, мы поднимем паруса и еще разок обстреляем Пиратскую Бухту со стороны Гибельного берега, для очистки совести.\r\n\r\n--Флотоводец Фираллон' FROM `page_text` WHERE `ID`=307 AND MD5(`Text`)='e5331f3fd511a45d0cdd47b1273f2ef7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=307 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 308, 'ruRU', 'Убежать от Занзила в этой гниющей лодке в то время казалось хорошей идеей, но я начинаю думать, что смерть могла быть лучшей судьбой.\r\n\r\nМне казалось, будто мне повезло, что предки позволили мне спастись от своего гнева. Но сейчас я не понимаю, какую мудрость обрету, если переживу свой плен.' FROM `page_text` WHERE `ID`=308 AND MD5(`Text`)='b48a47abf7dfbfcc2a2bcda71eae91a2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=308 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 309, 'ruRU', 'Зверь, который правит этим островом, действительно ужасен. Другие существа трепещут перед ним – и небогривые гориллы, и жагуары. Его рев постоянно звучит у меня в ушах и заставляет съеживаться от страха.\r\n\r\nЭти существа наверняка остановят любого, кто придет на остров. Но придется довериться воле предков...' FROM `page_text` WHERE `ID`=309 AND MD5(`Text`)='2811ebf440faa82e3e090e56552b7c76' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=309 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 310, 'ruRU', 'Я скучаю по своему племени и по дому. Как я тоскую по вольному ветру над равниной, по закатам над Громовым Утесом! Но кругом только жаркие джунгли...\r\n\r\nЯ вижу поблизости океан, но эти волны не охлаждают ни мое тело, ни мою тоску. Они только напоминают мне о заточении.' FROM `page_text` WHERE `ID`=310 AND MD5(`Text`)='123688d9bbcb5c202e42e3406319053b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=310 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 311, 'ruRU', 'День 1:\r\n6–11 утра – верхний лагерь\r\n11–11:30 утра – перерыв, обед\r\n11:30 утра–4:00 дня – проход через каньон\r\n4:00 дня–7:30 вечера – верхний лагерь\r\n\r\nДень 2:\r\nТо же расписание, что в день 1\r\n\r\nДень 3:\r\nТо же расписание\r\n\r\nДень 4:\r\nТо же расписание, с одним исключением. Перед самым закатом Торсен приказал мне прикрыть его, пока он пробирался по проходу через каньон. Ну, думаю, отправился встречаться с нашими агентами.\r\n\r\nНо он вернулся через час. Это меня удивило. Я-то думаю: сейчас встретится с нашими агентами, снова присоединится к Курцену... Но что-то пошло не так.' FROM `page_text` WHERE `ID`=311 AND MD5(`Text`)='7bdfb334b2bf6d4faa9a895b3b64bc5d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=311 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 312, 'ruRU', 'День 5:\r\nТорсен был сегодня очень взволнован. Кого бы или что бы он ни встретил на своей вчерашней прогулке, это его, должно быть, испугало.\r\n\r\nМне думалось, что с ним говорили наши агенты, но на мой вопрос, куда он ходил, Торсен ничего не ответил. Он считает, что я его друг, и думает, будто мне безопаснее не знать его тайны.\r\n\r\nОн служит не тем, кому следовало бы, но его преданность крепка. Когда он вернется к нам, он станет ценным приобретением для Курцена.' FROM `page_text` WHERE `ID`=312 AND MD5(`Text`)='76741aed004fa7fb1c360241f8e64201' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=312 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 313, 'ruRU', 'День 6:\r\nРано утром Торсен долго говорил с сержантом Йохвой. Мне пришлось притворяться, что сплю, так что подойти поближе мне не удалось. Но я думаю, что они говорили о том, куда ходил Торсен.\r\n\r\nЯ за ним пристально слежу – кстати, Йохва тоже. Позднее Торсена вызвал Дорен. У этих троих какая-то общая тайна. Дорен и Йохва, должно быть, знают, что Торсен встречается с вашими агентами.\r\n\r\nОн шпионит в пользу мятежников.' FROM `page_text` WHERE `ID`=313 AND MD5(`Text`)='6aa2bd077df626d492b330b0ca3c3357' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=313 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 314, 'ruRU', 'Не следует давать новых сведений Торсену. Его нужно убить. Он больше не принесет пользы нашему полковнику.\r\n\r\nЯ прикончу Торсена, если будет возможность, но если вы получите это письмо, знайте, что пока у меня такой возможности не было.\r\n\r\nВ этом случае я рекомендую, чтобы следующая встреча Торсена с нашими агентами закончилась его смертью.\r\n\r\nСлава Курцену!\r\n-M' FROM `page_text` WHERE `ID`=314 AND MD5(`Text`)='d9b38d7e0990f39ea935079e306a0266' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=314 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 315, 'ruRU', 'Совет поступил мудро, назначив вас главой Недремлющего Аргуса, исполнителем их предначертаний в землях людей и дворфов. И для меня большая честь служить проводником вашей воли в Альтераке.\r\n\r\nВо имя Саргераса!\r\n\r\nНагаз,\r\nЖрец Аргуса' FROM `page_text` WHERE `ID`=315 AND MD5(`Text`)='f4875e11737741064fe78de5d720758c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=315 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 316, 'ruRU', 'Никчемные глупцы!\r\n\r\nМой план требовал одновременного уничтожения обоих мостов. А вы что сделали, тупые головорезы? Вы сделали лишь полдела и предупредили весь Альянс о наших намерениях. Глупцы!\r\n\r\nНо у вас есть шанс исправить то, что вы натворили. У нас есть запас взрывчатки на нагорье Арати, недалеко от моста. \r\n\r\nЗакончите дело, если вам дороги ваши жалкие жизни!\r\n\r\n--Кам Гневливый' FROM `page_text` WHERE `ID`=316 AND MD5(`Text`)='48aa40efdbda2bb653fb4bb71c703bfb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=316 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 317, 'ruRU', 'Дун Модр, Болотина\r\n\r\nДорогая моя Сара!\r\n\r\nСудя по всему, через несколько дней мы сменим позиции, чтобы охранять Мост Тандола. Возможно, я больше не смогу писать тебе. Мне хочется написать несколько строк, которые могут попасться тебе на глаза, когда меня не станет.' FROM `page_text` WHERE `ID`=317 AND MD5(`Text`)='cca1f0e18a51b473c54b489bce4fdd10' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=317 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 318, 'ruRU', 'Наш поход может продлиться всего несколько дней и оказаться приятной прогулкой, а может завершиться кровопролитным сражением, в котором я погибну. Если уж мне суждено пасть, сражаясь за Альянс, то я готов.\r\n\r\nМеня не терзают никакие сомнения или колебания, моя храбрость несокрушима.' FROM `page_text` WHERE `ID`=318 AND MD5(`Text`)='9d67c4518e1097a4870d3f54440e980d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=318 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 319, 'ruRU', 'Я знаю, насколько судьба королевства Стальгорн зависит от победы или поражения Альянса и насколько велик наш долг перед теми, кто раньше нас прошел через кровь и страдания Великих войн. И я готов полностью отказаться от всех радостей жизни, чтобы помочь поддержать Альянс и вернуть этот долг.' FROM `page_text` WHERE `ID`=319 AND MD5(`Text`)='37a639d79541a0f732f37e8b640fb12d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=319 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 320, 'ruRU', 'Сара, моя любовь к тебе бессмертна, она словно связывает меня мощными путами, которые не разорвало бы ничто, кроме Всемогущества. А любовь к королевству подхватывает меня, словно ураган, и необоримо влечет меня вместе со всеми этими цепями на поле боя.' FROM `page_text` WHERE `ID`=320 AND MD5(`Text`)='be917394efbcc7d26645f74452b10d16' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=320 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 321, 'ruRU', 'Мне вспоминаются блаженные минуты, проведенные с тобой, и я испытываю огромную благодарность Свету и тебе за то, что наслаждался ими так долго. Но как же тяжело мне отказаться от них и спалить дотла надежды на будущие годы, в которых мы все еще могли бы жить вместе, любить друг друга и смотреть, как наши сыновья растут честными дворфами!' FROM `page_text` WHERE `ID`=321 AND MD5(`Text`)='c5f796e79522a0515adbb2b9f6070149' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=321 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 322, 'ruRU', 'Я знаю, что у меня немного оснований претендовать на благосклонность высших сил, но что-то мне подсказывает – может быть, до меня доносятся молитвы моего маленького Эдгара, – что я вернусь невредимым к тем, кого люблю. Если же я не вернусь, никогда не забывай, моя дорогая Сара, как сильно я любил тебя, и знай, что, умирая на поле боя, с последним вздохом я прошептал твое имя.\r\n\r\nПрости мне мои многочисленные недостатки и всю боль, которую мне случалось тебе причинить. Как бездумен, как глуп я зачастую бывал!' FROM `page_text` WHERE `ID`=322 AND MD5(`Text`)='ab61dcfc78557250dbd4f273814e0b85' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=322 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 323, 'ruRU', 'С какой радостью я бы смыл своими собственными слезами малейшее пятнышко на твоем счастье и боролся бы со всеми невзгодами этого мира, чтобы защитить тебя и наших дорогих деток!\r\n\r\nНо я не могу.\r\n\r\nМне придется наблюдать за тобой из Круговерти Пустоты и витать возле тебя, пока ты в одиночку противостоишь всем бурями со своей драгоценной маленькой ношей, выдерживаешь шторм со своим маленьким ценным грузом. Мне придется терпеливо ждать, пока мы встретимся, чтобы больше не расставаться никогда.' FROM `page_text` WHERE `ID`=323 AND MD5(`Text`)='93ee5ed6a6bbed262c9c3992e1a11c0c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=323 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 324, 'ruRU', 'Поднявшись из океана в струе воды, Нептулон послал великого Кракена к обреченному Илалаю. Настолько они были огромны, что целые джунгли водорослей качались на их конечностях, а левиафаны проплывали сквозь тела.$B$BСамый крупный Кракен тогда высоко поднял щупальца и ударил ими о море, поднимая волны вокруг себя. И направились они на Илалая.' FROM `page_text` WHERE `ID`=324 AND MD5(`Text`)='936cd2281dcc48d697fc5b2752fda83e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=324 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 325, 'ruRU', 'Кракен ревел, и его голос гремел, как океанская буря:$B$B"Я явился."$B$BМин\'лот, стоя твердо, призвал свою магию. Волны, посланные в Илалию, разошлись и омыли обе стороны, затопив джунгли за ними. Затем Мин\'лот приказал своим слугам произносить заклинания подчинения, и раздался грохот, и десятки голосов троллей поднялись.$B$BИ один голос возвысился над остальными.' FROM `page_text` WHERE `ID`=325 AND MD5(`Text`)='0a468359b08da8bf0e61e60564f298ab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=325 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 326, 'ruRU', 'Мин\'лот взревел, и его магия собрала силу заклинаний его слуг, и он направил её на приближающегося Краккена.$B$BМоре разошлось, и заклинание Мин\'лот устремилось к слугам Нептулона. Молния разорвала небо, и их поразило заклинание, и ударила тысяча молний, заставляя кипеть воду и оставляя горящие кратеры на земле.$B$BМин\'лот торжествующе закричал, зная, что его заклинание падет на огромных зверей. ' FROM `page_text` WHERE `ID`=326 AND MD5(`Text`)='205c13688447b75db51c935a72d34355' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=326 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 327, 'ruRU', 'Но Кракены старые, очень старые. Они помнили времена, когда земля впервые родилась из моря.$B$BОни помнили, когда правили Древние и когда пришли Странники и низложили их. Они помнили, когда магия была новой.$B$BОни старые и хранят много секретов. И хотя заклинание Мин\'лот было сильным, он был троллем, смертным.$B$BИ поэтому он потерпел неудачу.' FROM `page_text` WHERE `ID`=327 AND MD5(`Text`)='064ab4133403c177af42ecf95965cad4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=327 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 328, 'ruRU', 'Если не удастся подчинить Краккена, то это его взбесит. Никогда еще ни один смертный не причинял им боли, а заклинание тролля было болезненным.$B$BИ поэтому он сбросил оковы заклинания Минлота, но затем взревел и застыл в ярости.$B$BПослышался грохот, когда огромные волны поднялись из глубины и устремились к земле. Достигнув Илалая, они бросили тень на город.$B$BНо прежде чем его уничтожить, Кракен на мгновение остановился. ' FROM `page_text` WHERE `ID`=328 AND MD5(`Text`)='d1b810304d4a72c9ab12d6365652b61b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=328 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 329, 'ruRU', 'Тролли-знахари задрожали и закричали своему хозяину. Мин\'лот смотрел на горы из морской воды, обреченный и дерзкий. Он повернулся к своим адептам и прошептал, и тролли выгравировали его последние слова на камне. Затем Мин\'лот встретился с приближающимся Кракеном.$B$BОн поморщился и швырнул свой посох - его последний смелый поступок.$B$BЗатем Кракен направил свою ярость на Мин\'лота, и океан обрушился на Илалая.$B$BИ не стало его.' FROM `page_text` WHERE `ID`=329 AND MD5(`Text`)='318fc284a35e34b79aa78edcd4675143' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=329 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 330, 'ruRU', 'А затем вода упала на джунгли, смывая всех на своём пути. Тролли и звери кричали, когда вода настигала и топила их.$B$BМногие Гурубаши недоумевали, почему океан решил поглотил их, но потом они умерли, так и не поняв этого.$B$BИ, наконец, когда вода достигла гор, она остановилась. Умиротворенная, она отступила за берега и оставила после себя след смерти.$B$BОна отступила, но окружила Илалайа, остановилась, и навсегда поглатила его. ' FROM `page_text` WHERE `ID`=330 AND MD5(`Text`)='8c3a57899c50725c010e108f6bf6d8a2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=330 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 331, 'ruRU', 'И вождь Вар\'газул, находящийся в безопасности за горами в Зул\'Гурубe, вышел в джунгли и обнаружил, что вода опустошила земли его народа.$B$BИ он отчаялся, потому что его мечты о завоевании не суждено было сбыться.$B$BИ змей Мин\'лот так и не был найден. ' FROM `page_text` WHERE `ID`=331 AND MD5(`Text`)='9e5934ed6e85b9241b0d973d76f02a8c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=331 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 333, 'ruRU', 'Моему досточтимому королю:\r\n\r\n\'Не пристало скромной жене солдата подвергать сомнению действия великих военачальников, таких как вы. Битвы, бушующие в наших землях, ведутся, чтобы сохранить прекрасную жизнь, которую мы знаем и любим, – от прохладных вод озера Лок Модан до острых заснеженных пиков Дун Морога.' FROM `page_text` WHERE `ID`=333 AND MD5(`Text`)='d70f29c153c2674e707abe0b237e649e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=333 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 334, 'ruRU', 'Но какой ценой должны вестись войны за сохранение жизни? После которой смерти павшего в бою солдата мы поймем, что жизнь, которую мы стремимся спасти, ускользает от нас на поле боя?\r\n\r\nПод сколько мечей и топоров должны мы бросить наше будущее? Под сколькими метрами пропитанной кровью земли должны мы похоронить наше прошлое?' FROM `page_text` WHERE `ID`=334 AND MD5(`Text`)='b47756a41ba8181f8c91bf57547dd995' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=334 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 336, 'ruRU', 'Добрый день, Шнайдер!\r\n\r\nНадеюсь, дела в районе каналов идут хорошо. У нас тут, в торговом квартале, большой наплыв покупателей.\r\n\r\nНам нужно побольше вязаной одежды, наши запасы на исходе. Пожалуйста, пришлите мне стандартную партию при первой же возможности.\r\n\r\nУдачи. Надеюсь, занятия вашего сына Тармена тоже продвигаются неплохо. \r\n\r\n--Харлан Багли' FROM `page_text` WHERE `ID`=336 AND MD5(`Text`)='6288099cbbd649477c7fa956019d1622' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=336 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 337, 'ruRU', 'Официальный приказ флоту Кул-Тираса\r\n\r\nЯ, адмирал Праудмур, буду лично командовать первой высадкой на берега Калимдора.\r\n\r\nЛейтенант Бенедикт назначается моим заместителем на время моего отсутствия. Все вопросы обороны Кул-Тираса будут решаться им. Если от меня не поступит вестей из крепости Тирагард в течение 12 месяцев, лейтенант Бенедикт возглавит вторую экспедицию, которая должна будет захватить крепость.' FROM `page_text` WHERE `ID`=337 AND MD5(`Text`)='15f3fa9eb669986cd4d1d29cac05e182' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=337 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 338, 'ruRU', 'Тем временем я посылаю лейтенанта Элверолда в экспедицию вокруг континента Калимдор. После того как его силы завершат экспедицию, им следует воссоединиться с нашими силами в крепости Тирагард.\r\n\r\nПо расчетам, экспедиция лейтенанта Элверолда должна занять довольно много времени. Новый материк выглядит обширным и опасным. Но если со мной или Бенедиктом стрясется какая-либо беда, войска Элверолда сумеют снова захватить крепость. \r\n\r\nМы будем посылать одну экспедицию за другой, пока Тирагард не станет нашим!\r\n\r\n--Адмирал Праудмур' FROM `page_text` WHERE `ID`=338 AND MD5(`Text`)='09653d31133c733a1003c9ac8fe84679' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=338 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 341, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1>Призыв на службу в Орду</H1>\r\n<BR></BR>\r\n<P>Этот человек показал невероятные достижения силы и навыка во имя. Его следует немедленно назначить на работу на Перекресток.</P>\r\n<BR></BR>\r\n<BR></BR>\r\n<P>Почтительно ваш:</P>\r\n<BR></BR>\r\n<BR></BR>\r\n<BR></BR>\r\n<BR></BR>\r\n<P>Мне кажется, неплохо.<BR></BR>\r\n- Такрин Торитель Путей</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=341 AND MD5(`Text`)='d55c04eb207ae9350cab0485379eac5d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=341 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 342, 'ruRU', 'Раскопки Бейл Модана\r\n\r\nПервая исследовательская команда, отправленная Лигой Исследователей, не ошиблась в своих выводах. Здешняя земля содержит артефакты неограниченной ценности для нашего народа. Без сомнения, под песком и скалами Бейл Модана мы найдем много новых знаний.\r\n\r\nГеология этого региона, однако, заставляет нас прибегать к крайним мерам. Многие из залежей песка затвердели под воздействием суровой погоды и переменчивого климата.' FROM `page_text` WHERE `ID`=342 AND MD5(`Text`)='f62ba55d55bb2397356f3ea933d113cd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=342 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 343, 'ruRU', 'Решение, впрочем, весьма просто. Используя мякоть дерева в качестве адсорбента, мы можем соединить следы нитроглицерина с нитратом натрия, чтобы получить сильный взрывной заряд, способный пробиться даже через самые плотные массы.\r\n\r\nРабота будет шумной и разрушительной, но наши поиски гораздо важнее комфорта местных жителей. На самом деле нам уже пришлось выгнать из этой области стаю рогатых, которые мешали нам.' FROM `page_text` WHERE `ID`=343 AND MD5(`Text`)='4e61d5ca6efea6d24997f93504127e8a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=343 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 344, 'ruRU', 'То обстоятельство, что мы здесь имеем дело с различными мошенниками, заставляет меня считать, что нам понадобится поддержка армии короля. Помимо того что раскопки потребуют военной поддержки, на мой неопытный взгляд, Бейл Модана может представлять стратегическую ценность для Альянса, учитывая нестабильность мировой политики в ее текущем состоянии.\r\n\r\nУвы, я отвлекаюсь. Под скалой нужно проделать много работы. Я провел слишком много времени за письмом и недостаточно – за раскопками...' FROM `page_text` WHERE `ID`=344 AND MD5(`Text`)='1ee5512b3a520f7d67ff2334fa479def' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=344 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 350, 'ruRU', 'Панель управления самофланжа можно использовать, чтобы автоматически регулировать поток топлива, газов, жидкостей и связанные с этим механизмы. После завершения исходной регулировки она должна оперировать без проблем при минимальной поддержке.\r\n\r\nКраткий список компонентов элементов панели управления (слева направо)\r\n\r\nI. Тумблер включения\r\n\r\nПозиция "включено" задействует самофланж. Контрольный механизм не отключится автоматически при переводе рычага в положение "выключено". Это лишь' FROM `page_text` WHERE `ID`=350 AND MD5(`Text`)='1fae6f4f47f6ecd0cd914003cfb0d2a9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=350 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 355, 'ruRU', 'начнет процесс охлаждения, который в этот момент потребует примерно от одной до двух минут (в зависимости от ситуации) для своего завершения.\r\n\r\nВАЖНОЕ ЗАМЕЧАНИЕ: главным силовым рубильником можно манипулировать, только когда три контрольных клапана на самих машинах выключены. Выключать эти клапаны можно в любом порядке.\r\n\r\nПервый – ГЛАВНЫЙ КОНТРОЛЬНЫЙ КЛАПАН, который можно найти у основания большой вертикальной дымовой трубы. Далее – КЛАПАН УПРАВЛЕНИЯ ТОПЛИВОМ, его можно найти на большой трубе, которая ведет' FROM `page_text` WHERE `ID`=355 AND MD5(`Text`)='12d84c078189cbcc519c850fa43d5a80' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=355 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 356, 'ruRU', 'из баков с горючим (их должно быть три) к дымовой трубе. Наконец, РЕГУЛИРУЮЩИЙ КЛАПАН можно найти на нижнем из двух больших цилиндрических баков, соединенных с дымовой трубой. \r\n\r\nII. Индикаторы топлива\r\n\r\nОтображают текущее давление в первом, втором и третьем топливном баке.\r\n\r\nIII. Индикатор потока\r\n\r\nОтображает текущую скорость потока внутри системы.' FROM `page_text` WHERE `ID`=356 AND MD5(`Text`)='d9918bffa436ab99a737513d87ba7880' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=356 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 357, 'ruRU', 'IV. Регуляторы потока\r\n\r\nУвеличивают или уменьшают скорость потока. Это автоматически регулируется управляющим механизмом самофланжа.\r\n\r\nV. Индикатор температуры\r\n\r\nОтображает температуру внутри системы в целом.' FROM `page_text` WHERE `ID`=357 AND MD5(`Text`)='20384baae7539a4ba8b692f1c792ae30' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=357 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 358, 'ruRU', 'Долго дети звезд обитали на берегах мерцающих вод Источника Вечности. Всем было известно, что Элуна, свет вечной полуночи, аспект и богиня луны, обитала в его водах в то время, когда отдыхала от трудов. На берегах Источника построили свои дома дети звезд, любимцы Элуны, живущие, не отводя взора от неба, глядя в лунную ночь.\r\n\r\nХотя было построено много городов и мест обитания' FROM `page_text` WHERE `ID`=358 AND MD5(`Text`)='b4853c366e7e14a87ac95d0004bc56b9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=358 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 359, 'ruRU', 'Земля задрожала, когда выкорчевали и повалили древние деревья зачарованного леса. Рощи и лужайки, обихоженные сыновьями и дочерьми Кенария, и каменные башни детей звезд обрушились на землю. Там была наша королева, яркая даже в отчаянии, в хаосе сражения. Зачарованное небо меняло цвет с каждым новым всплеском магии, со взрывами, которые угрожали разорвать мир на части.\r\n\r\nБрат сражался с братом. Избранные сражались' FROM `page_text` WHERE `ID`=359 AND MD5(`Text`)='534a14b5a383d5e04ba821e5a05bc519' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=359 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 361, 'ruRU', 'Мастер Делгрен!\r\n\r\nВсе так, как ты опасался. Твоя теория о башне Алталакса оказалась верной. В башне собрался культ, среди них много чернокнижников, есть даже сатиры. Они называют себя кланом Темной Нити. Я не могу представить себе, какая недобрая цель свела их друг с другом, но это беспокоит меня.\r\n\r\nПожалуйста, прости краткость и резкость этого сообщения, но опасность таится в лесу вокруг, и я не могу посвятить много слов описанию происходящего. Я' FROM `page_text` WHERE `ID`=361 AND MD5(`Text`)='856f77aef8beafe678480e2f36345f83' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=361 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 364, 'ruRU', 'на берегу озера, Амет\'Аран и Башал\'Аран были впереди всех, обладая благословлением Азшары, возлюбленной королевы калдорай, при своем создании. Ее любимые слуги из высокорожденных прибыли вместе с ней для обитания в городах-близнецах; управлять ими она назначила Атрикуса Нарассина, хотя оказалось так, что он стал проводить большую часть времени в своей башне Алталакса, на некотором расстоянии от городов.\r\n\r\nЕго помощником, магом, известным своим мастерством в тайных искусствах наравне со своими физическими способностями,' FROM `page_text` WHERE `ID`=364 AND MD5(`Text`)='16bfc6933708f2d31e444555e6c540d8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=364 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 365, 'ruRU', 'был Астерион, живший среди народа Башал\'Арана и много раз отправлявшийся в Амет\'Аран, чтобы обеспечить нужды его людей.\r\n\r\nИтак, оно было на берегах Источника Вечности, города-близнецы росли и процветали, пока мир под звездами медленно скатывался в безумие.' FROM `page_text` WHERE `ID`=365 AND MD5(`Text`)='19c29146feb6292c4a51c168ff4ac977' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=365 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 366, 'ruRU', 'с благословенными. Сражались не все из высокорожденных. Многие стояли в оцепенении, словно охваченные безумием. Большие и маленькие города, как один, падали вокруг них.\r\n\r\nВ Амет\'Аране все было в руинах, его жители цеплялись за землю, словно это могло их спасти от уничтожения. Именно тогда Атрикус Нарассин, любимец Азшары, появился, чтобы спасти их.\r\n\r\nОн сказал, что может защитить их заклинаниями. Пока вокруг них погибали братья и сестры, отцы и матери,' FROM `page_text` WHERE `ID`=366 AND MD5(`Text`)='9e65b524e629453fd326cda82438287e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=366 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 367, 'ruRU', 'они обрели бы вечную жизнь и им было бы незачем бояться грядущего Раскола...' FROM `page_text` WHERE `ID`=367 AND MD5(`Text`)='1562e733e385225f82dc59af6d85cdd9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=367 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 371, 'ruRU', 'Л. Ф. приказал увеличить давление на дураков из Альянса. Ниже – список материалов, необходимых для важной миссии против Южнобережья:\r\n\r\nнедельные походные рационы для 20 человек\r\n20 черных ночных костюмов\r\n20 новых пар туфель\r\n25 новых мечей\r\n30 метательных ножей\r\n20 черных масок\r\n10 склянок зажигательного масла\r\n50 доз парализующего яда\r\n5 украденных униформ стражников Южнобережья, если есть\r\n100 серебряных монет\r\n\r\n--Барон В..\r\nквартирмейстер.' FROM `page_text` WHERE `ID`=371 AND MD5(`Text`)='66aa521c1051ca6407290cb0d24d0c42' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=371 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 372, 'ruRU', 'Звезда Ксиль\'и\r\n\r\nЗвезда у Грелборга Скряги. Он – жадный огр, который проводит свои дни в горах и руинах Альтерака в поисках блестяшек. Большая часть его коллекции бесполезна, но одна вещь, Звезда Ксиль\'и, обладает ценными свойствами.' FROM `page_text` WHERE `ID`=372 AND MD5(`Text`)='ce51f672d355d86701e67955f7a602e7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=372 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 373, 'ruRU', 'Рука Дагуна\r\n\r\nДревние тексты утверждают, что когти Дагуна источают яд, который не убивает жертву, но превращает ее в нечто иное – представителя старых рас. Его ценность для нас неоспорима.\r\n\r\nДагун живет глубоко в море, но его регулярно выманивает на поверхность племя мурлоков Болотного Плавника в Пылевых топях. Их оракулы призывают его при помощи зачарованных морских водорослей. Если ты убьешь достаточно оракулов, то соберешь необходимое количество этих водорослей. Положи их на алтарь мурлоков: так ты сможешь призвать Дагуна.' FROM `page_text` WHERE `ID`=373 AND MD5(`Text`)='51cecfe78fabf362cab349e50a10a52d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=373 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 374, 'ruRU', 'Сердце Наследия\r\n\r\nМогх Неумирающий – троллий знахарь из Тернистой долины. И он обладает сердцем Наследия, о котором говорят, что оно отвращает смерть от тех, кто открывает его секреты. Ты найдешь Могха на Руинах Зул\'Мамве. Одержи над ним победу, если сможешь, и принеси мне Сердце Наследия.' FROM `page_text` WHERE `ID`=374 AND MD5(`Text`)='8e9af80f92e200e85398d28dce04f557' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=374 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 375, 'ruRU', 'Принеси мне эти вещи, Звезду, Руку и Сердце, и Книга Йагина будет твоей.$B$B-Г.К.' FROM `page_text` WHERE `ID`=375 AND MD5(`Text`)='66c14780ba621b1e76a2ae7e11ea790c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=375 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 376, 'ruRU', 'Звезда Ксиль\'и\r\n\r\nОгр в долине Альтерака, Грел\'борг Скряга был последним известным владельцем этого камня, по слухам дававшего своему владельцу умение сообщаться с другими мирами. По нашим сведениям, Грел\'борг бродит по руинам Альтерака в одноименных горах в поисках других реликвий.' FROM `page_text` WHERE `ID`=376 AND MD5(`Text`)='311b163786eecd18d563e13ed2bf7f63' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=376 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 377, 'ruRU', 'Рука Дагуна\r\n\r\nДагун – существо из глубины, которому поклоняются мурлоки в Пылевых топях. Они заманивают его на поверхность при помощи особенных морских водорослей, зачарованных их шаманами. Найди мурлоков, собери их зачарованные водоросли, затем помести его на Алтарь Мурлоков. Дагун придет, когда будешь ждать его.\r\n\r\nМне нужна эта рука.' FROM `page_text` WHERE `ID`=377 AND MD5(`Text`)='151b7417a44b9d696b3a19d1f929aaac' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=377 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 378, 'ruRU', 'Сердце Наследия\r\n\r\nСтарые тексты говорят, что тот, кто обладает сердцем Наследия, не боится могилы. Возможно, это правда, ведь владелец сердца, Тролль Могх, известен как Могх Неумирающий. Знахарь клана Дробителей Черепов, Могх, обитает в Тернистой долине на Руинах Зул\'Мамве.' FROM `page_text` WHERE `ID`=378 AND MD5(`Text`)='3e1f8e4bbdcb3d55ade37404da93f009' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=378 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 379, 'ruRU', 'Принеси мне эти вещи, Звезду, Руку и Сердце, и я дам тебе копию Книги Йагина.\r\n\r\n-Хранитель' FROM `page_text` WHERE `ID`=379 AND MD5(`Text`)='71ffdefb01857b241a249afd53980000' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=379 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 387, 'ruRU', 'И так он бродил, и так он искал. И его рука оставалась потерянной для него. И так он изрыгал проклятия и рычал при ходьбе. \r\n\r\nНо Гри\'лек давно перестал слушать духов, и они были сердиты на него и не слышали его проклятий.\r\n\r\nГри\'лек был обречен. Обречен бродить без руки.' FROM `page_text` WHERE `ID`=387 AND MD5(`Text`)='bcc20ab243f8566c0699f8cb1978de6f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=387 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 394, 'ruRU', 'Тьмой они созданы – злу нет предела\r\nТому, что на Вершине Тумана Багрового воссело.\r\nНесется над миром смех наглеца,\r\nЧьим элементалям не видно конца.\r\n\r\nТебе с этим магом оружье скрестить\r\nИ в схватке смертельной его победить.' FROM `page_text` WHERE `ID`=394 AND MD5(`Text`)='4e8732addbf19fb9563429bf71e536ce' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=394 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 395, 'ruRU', 'Святилище Мел-Тандрис\r\n\r\n"Пусть свет Элуны вечно озаряет эту долину и освещает пути леса, как было с незапамятных времен".' FROM `page_text` WHERE `ID`=395 AND MD5(`Text`)='b1e4afda9e3ad5155fc5ad907ee1ff1b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=395 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 396, 'ruRU', 'Элуна услышала мои молитвы. Мои товарищи пали недаром, и коса Элуны поможет мне отомстить за них. Это древняя вещь, ветка, изогнутая и искореженная, из дерева, которое, должно быть, старше самих калдорай.\r\n\r\nМного часов я исследовала дар богини. С первого взгляда понятно, что это не обычное оружие и не простое магическое устройство. С ним... словно барьеры времени и пространства ослабели.\r\n\r\nДержа Косу' FROM `page_text` WHERE `ID`=396 AND MD5(`Text`)='642f08b7d2f228864bb3d42fa728f1ea' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=396 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 397, 'ruRU', 'в руках, я получила видение хаоса. Люди-волки... воргены... сражались с невероятным врагом. Воргены яростно сражались, как подобает их примитивной расе, но их враг был неодолим – повелители Изумрудного Пламени.\r\n\r\nИ именно тогда я осознала подлинную силу Косы. Сосредотачиваясь на ней, я смогла общаться с воргенами. Только не при помощи речи. Это было что-то другое... мне не описать это словами.\r\n\r\nВажно было то, что воргены слышали' FROM `page_text` WHERE `ID`=397 AND MD5(`Text`)='436f1a0f2ba5562de993a98d28fc32ee' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=397 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 398, 'ruRU', 'и понимали меня. Передав часть своей силы Косе, я ослабила барьеры мироздания настолько, что смогла привести воргенов в наш мир. С первой попытки мне удалось призвать тридцатерых. Они последовали в сражение за мной, и с их грубой силой в моем распоряжении мы вступили в бой с демонами Оскверненного леса.\r\n\r\nЭлуна исполнила мои желания. Лес будет очищен.\r\n\r\n\r\nДа пребудет со мной благословение Элуны, пока я не сделаю, что должно.' FROM `page_text` WHERE `ID`=398 AND MD5(`Text`)='851b68e2932bc0008732a3044524883e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=398 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 399, 'ruRU', 'Все идет хорошо. Я вызвала себе на помощь значительное число воргенов. Хотя они недалекие существа, они умеют отлично сражаться строем и координировать свои атаки.\r\n\r\nВ каждой стае я отыскала лидера. Им я доверил командование небольшими группами воинов. Мы атакуем сразу из многих мест в лесу, и моя кампания против демонов идет успешно.\r\n\r\n\r\nДа пребудет со мной благословение Элуны, пока не будет выполнена моя работа.' FROM `page_text` WHERE `ID`=399 AND MD5(`Text`)='adb910847419a9497d24450f2de3b9ea' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=399 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 400, 'ruRU', 'Одна стая потеряна. Я послала воргенов прочесать лес и выяснить, где кроются демоны, но они не вернулись. Я начинаю волноваться из-за лидеров, которым я доверила руководство. Они примитивны и немедленно начали злоупотреблять данной им властью. Сохраню ли я над ними власть? Может быть, я временно перестану вызывать новых воргенов.\r\n\r\n\r\nДа пребудет со мной благословение Элуны, пока не будет выполнена моя работа.' FROM `page_text` WHERE `ID`=400 AND MD5(`Text`)='10b7d5952b65509ec9e315c733407740' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=400 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 401, 'ruRU', 'Хотя я перестала призывать новых воргенов, их число по-прежнему растет. Коса словно больше не нуждается в моей помощи. Это призывает беспокойство. Я собрала все возможные стаи и приказала им оставаться в святилище Мел-Тандрис.\r\n\r\nТем временем я обыскала библиотеки Дарнасса и посоветовалась с Кругом Древних на Темных берегах. Я не нашла абсолютно никаких сведений об этих воргенах. До меня дошли слухи,' FROM `page_text` WHERE `ID`=401 AND MD5(`Text`)='ff56c3ca5084f7466eb59a46548aad99' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=401 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 402, 'ruRU', 'неясный шепот, о волшебнике из Кирин Тор по имени Аругал. Согласно тому, что я слышал, возможно, что он тоже вызывал воргенов. Как бы мне ни было неприятно, придется посоветоваться с этим волшебником, выяснить, что ему известно.\r\n\r\nВоргены опасны, и я желаю остановить их нашествие. Завтра же я отправлюсь в порт в Степях и оплачу путешествие в Новый мир.\r\n\r\n\r\nДа пребудет со мной благословение Элуны, пока не будет выполнена моя работа.' FROM `page_text` WHERE `ID`=402 AND MD5(`Text`)='eabc33663558c26fb588b5426131bd77' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=402 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 403, 'ruRU', 'Я начал вести этот журнал, чтобы делать заметки о своих попытках помочь Ясеневому лесу. Некоторые из недавних событий исполнены тайн, и я надеюсь, что смогу пролить свет на часть из них, чтобы помочь своему народу.\r\n\r\nНачну с того, что запишу некоторые факты, чтобы не забыть их потом.\r\n\r\nНедавно я нашел подтверждение слухам о деятельности волшебника Дартола.' FROM `page_text` WHERE `ID`=403 AND MD5(`Text`)='1ae05ee175c8f66b37df197903a4641f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=403 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 404, 'ruRU', 'Хотя когда-то предположение, что человек может прийти в наши земли и учиться у нас, казалось мне смехотворным, этот волшебник, этот злой человек, пришел сюда и не только выжил, но и обрел часть наших знаний. Я все еще не понимаю, как...\r\n\r\nЯ так и не понял, сам план довольно прост: с помощью магии друидов он хотел подружиться с фурболгами, а затем подчинить их себе. Если это была попытка повредить моим сородичам или совершить что-нибудь зловредное, я надеюсь узнать об этом прежде, чем закончится мой путь.' FROM `page_text` WHERE `ID`=404 AND MD5(`Text`)='28736056c688f0fad9faa280b89f7030' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=404 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 405, 'ruRU', 'В любом случае, по-видимому, его действия сопровождались определенным успехом. Хотел ли он потренироваться на фурболгах перед тем, как заняться моим народом? Было ли у фурболгов что-то, чем он желал завладеть? Кто знает?\r\n\r\nИспользуя созданную им вещь (какой-то жезл или посох), он попытался проникнуть в племена фурболгов Ясеневого леса. В какой-то момент – и именно здесь многое все еще не ясно – его обнаружили фурболги когда он пытался натравить их' FROM `page_text` WHERE `ID`=405 AND MD5(`Text`)='d14018f5ccc4de59fb77896af0e8c493' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=405 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 406, 'ruRU', 'друг на друга. Эльфы на месте фурболгов очень разозлились бы, но те отреагировали гораздо сильнее и убили Дартола.\r\n\r\nФурболги, по крайней мере в то время, не были теми порчеными существами, которыми они стали. Они были все еще рациональными и умными – их отношения с нашим народом были дружественными.\r\n\r\nЯ надеюсь, что, если я смогу воссоздать жезл с помощью дриады по имени Шаэл\'дрин, я смогу использовать его силу, чтобы помочь нашему народу... и фурболгам.' FROM `page_text` WHERE `ID`=406 AND MD5(`Text`)='c2b43546d3cd08ffe32f89acdacb105a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=406 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 407, 'ruRU', 'Не все фурболги подверглись порче. Некоторые еще живы и стараются защитить лес. Когда пришла порча, некоторые фурболги спаслись бегством, многие были убиты, а других изгнали из кланов.\r\n\r\nЯ нашел почтенного фурболга из клана Гиблой Чащи, живущего над озером Мистраль, – его зовут Кролг.\r\n\r\nЯ наблюдал за ним несколько дней, и мне кажется, что, приблизившись к нему в обличье фурболга, я мог бы помочь ему и найти способ снова установить связь между нашими народами.' FROM `page_text` WHERE `ID`=407 AND MD5(`Text`)='1a465c683bcb02fadf1826ecb9eddae3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=407 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 408, 'ruRU', 'После смерти Дартола фурболги разделили жезл на три части, чтобы уберечь себя от его воздействия. Найти их будет нелегко, но я знаю, где находится каждая из частей.\r\n\r\nСамоцвет\r\nПервая часть жезла – сверкающий драгоценный камень – была спрятана в святилище на северо-западе Ясеневого леса. От этого святилища остались только развалины, расположенные посреди озера Фалатим. Стражи сообщили мне, что сейчас там обитают мурлоки.' FROM `page_text` WHERE `ID`=408 AND MD5(`Text`)='ab9fd6bc7ba9ab707e15805ad5f76203' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=408 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 409, 'ruRU', 'Если я не смогу найти камень, спрятанный в храме, он может оказаться у одного из мурлоков.\r\n\r\nДревковая часть\r\nЭта часть жезла была дана древням возле леса, который сейчас называется Оскверненным. Ни фурболги, ни мой народ не могли заподозрить, что такие величественные создания падут жертвой порчи, охватившей эти земли.\r\n\r\nМои исследования говорят мне, что стражи хранили эту часть в сундуке, на небольшой лужайке. Чтобы узнать больше, мне нужно будет поговорить с Шаэл\'дрин.' FROM `page_text` WHERE `ID`=409 AND MD5(`Text`)='61b10eae4385def79fbdbce2424bb9a4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=409 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 411, 'ruRU', 'Шаэл\'дрин – это дриада, охраняющая лунный колодец к северо-востоку от озера Ирисов. Она отказывается покинуть лес и оставить его во власти порчи. Я знаю, что у нее достаточно сил и знаний, чтобы восстановить жезл или по крайней мере сказать мне, как я могу это сделать cамостоятельно.\r\n\r\nНавершие\r\nНавершие попало в руки друидов Дор\'Данила. Но тут все не так просто: эти друиды погибли.\r\n\r\nТеперь в Дор\'Даниле обитают их духи, которые не отличаются гостеприимством.' FROM `page_text` WHERE `ID`=411 AND MD5(`Text`)='219730afeb7fa1732a549b4f1c1e5a7d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=411 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 412, 'ruRU', 'Тут могут потребоваться дальнейшие исследования. Не знаю, хватит ли мне сил, чтобы сражаться с духами своих мертвых сородичей... не говоря уже о том, чтобы в одиночку отправиться в Дор\'Данил и отыскать это навершие.\r\n\r\n(Примечание: не так давно во время подготовки в Астранааре мне повстречался дворф-охотник, который провел много времени в Ясеневом лесу, пытаясь помочь моему народу. Он пришел из места под названием Штормград.\r\n\r\nОднажды вечером мы неплохо посидели за несколькими кружками эля, и его рассказ внушил мне надежду, что отыскать навершие все же удастся...' FROM `page_text` WHERE `ID`=412 AND MD5(`Text`)='56d8c1bd342b7e487bde1f980f8a8fd7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=412 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 413, 'ruRU', 'Он рассказал мне, что исходил Дор\'Данил вдоль и поперек, но ни разу не видел такого сундука или другого места, где могло бы храниться навершие.\r\n\r\nОн также рассказал мне, что в тех краях завелась гниющая слизь, которая пожирает почти все, что ей попадется. Он видел, как она "поедает" столы, скульптуры, медведей, и даже гномов!\r\n\r\nЭта слизь, похоже, обретает силу, поглощая магические предметы. Если сундук, в котором лежало навершие, был зачарован, слизь могла сожрать и его.' FROM `page_text` WHERE `ID`=413 AND MD5(`Text`)='808de30664c7e907a98472be7fdb60d1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=413 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 414, 'ruRU', 'Это риск, но сейчас у меня нет других зацепок...\r\n\r\nКогда я узнаю больше, я запишу детали сюда, но до тех пор я буду работать над тем, чтобы найти части жезла и помочь Ясеневому лесу.' FROM `page_text` WHERE `ID`=414 AND MD5(`Text`)='58a83ad52355e909029ff3c2dfb1b066' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=414 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 415, 'ruRU', 'Джин\'Зил,\r\n Прошло немало времени, но я подумал, что ты захочешь узнать, что были убиты последние представители Кровавого Пера. Но не благодари меня, убил человек, доставивший тебе это письмо. Если хочешь, я могу прислать тебе их головы, после того как караван пройдет через Степи. Я знаю, что ты любишь использовать такие вещи в своей магии вуду.\r\n Береги себя, старый друг.\r\n\r\n-Дарсок Быстрый Нож' FROM `page_text` WHERE `ID`=415 AND MD5(`Text`)='257249fe8558ca95ceddb7ddc4746479' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=415 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 417, 'ruRU', 'Хорошо, у тебя должны быть заряды и детонаторы NG-5. Я их пометил для тебя... Синий – для лесопилки. Красный – для Рудника Ветрорезов.\r\n\r\nЯ кое-что разведал и выяснил, что на Утесе Ветрорезов достаточно взрывчатки, чтобы тебе не было сложно зайти туда, установить детонаторы и выйти оттуда, перед тем как взрывать.\r\n\\Помни, это отвлекающий маневр. Отойди далеко от вагонов перед тем, как гоблины доберутся туда, чтобы проверить, что случилось, затем проскользни за ними.' FROM `page_text` WHERE `ID`=417 AND MD5(`Text`)='9849050ac577c00e0c47296372eef625' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=417 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 418, 'ruRU', 'Кстати, будь осторожен с ними. Один нитромирглицероний сам по себе может разнести тебя в пыль. Я поместил часть жидкости в медные пробирки, которые должны защитить от сотрясений и обеспечить безопасность.\r\n\r\nСвиток, который ты получил от Коллина, я использовал в коробках с детонаторами. Теперь они пошлют бесшумное сообщение зарядам NG-5 когда ты их включишь. Я использовал простой сталтваргонский механизм, чтобы обеспечить оптимальную проводимость проводов и скорость потока нитромирглицерония между разностными жидкостями лучше среднего.' FROM `page_text` WHERE `ID`=418 AND MD5(`Text`)='6fffb0d663561e852bd7d478abb3bc62' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=418 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 419, 'ruRU', 'Прежде чем я вернусь к подробностям своего плана, давай я объясню тебе, куда поместить взрывчатку.\r\n\r\nПлан альфа – лесопилка:\r\nПеред лесопилкой есть вагончик (это к северо-востоку от места, где они вырубают лес и собирают древесину). Я подозреваю, что инженерные планы находятся внутри лесопилки.\r\n\r\nЧтобы установить заряд, направляйся за вагончик. Установив его, поспеши удалиться на приличное расстояние.' FROM `page_text` WHERE `ID`=419 AND MD5(`Text`)='786a138a26174f58658b5360a4ff80b0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=419 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 420, 'ruRU', 'Когда ты будешь готов, нажми на взрыватель.\r\n\r\nЯ обеспечил сильный сигнал, соединив медные и серебряные провода с рядом мелтузианских антенн внутри коробки. Это должно обеспечить тебе хороший радиус действия. Но будь осторожен с гоблинами, шляющимися поблизости. Они не оценят мое творение, если поймают тебя на своей территории.\r\n\r\nДа, на случай, если это не очевидно, не находись рядом с вагончиком в момент взрыва... будет больно.' FROM `page_text` WHERE `ID`=420 AND MD5(`Text`)='5fc5303d1c64f03136b7b86578e67d3d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=420 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 421, 'ruRU', 'План бета – Рудник Ветрорезов:\r\n\r\nЯ видел, как гоблины используют другой вагончик со взрывчаткой к северу от входа на шахту. Я думаю, поместить заряд NG-5 (красный) там – это хорошая идея. Установив заряд за вагончиком, отойди на какое-то расстояние и нажми на кнопку.\r\n\r\nЕсли гоблины не прибегут, чтобы проверить, что случилось, – скорее всего, это потому, что гора обрушилась им на головы.' FROM `page_text` WHERE `ID`=421 AND MD5(`Text`)='b78cf908bb57777656712127f0a68b11' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=421 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 422, 'ruRU', 'Документы Торговой Компании снаружи шахты... Я думаю, лежат на каких-нибудь ящиках на нижнем уровне.\r\n\r\nУдачи, и помни...\r\n\r\nСиний заряд – лесопилка\r\nКрасный заряд – шахта\r\n\r\nА, и уничтожь это письмо, после того как выполнишь свое задание. Хм, может быть мне стоит поискать способ заставить эти штуки самоуничтожаться, после того как их прочитают. Это неплохая идея...' FROM `page_text` WHERE `ID`=422 AND MD5(`Text`)='d5cfe3cf95ecb3ca06d6a5e533361053' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=422 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 424, 'ruRU', '--День первый--\r\n\r\nНаконец-то я из Стальгорна добрался до Калимдора!\r\n\r\nГеолог Хазгорм из Бейл Модана отлично продвигается. Он сегодня раскопал окаменелость, которую местные ученые считают фрагментом кости древнего бога. Хазгорм уверен, что окаменелость – часть великой загадки. Пока он приглядывает за раскопками, но поручил мне найти еще окаменелостей, чтобы собрать эту историю воедино. \r\n\r\nМое задание: отправиться на юг в поисках дополнительных ключей к тайне.' FROM `page_text` WHERE `ID`=424 AND MD5(`Text`)='2e9356b6e2bb61cff9b080442a560482' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=424 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 425, 'ruRU', '--День второй--\r\n\r\nСтепи бескрайни. Мой поход был долог и утомителен, но пока что не дал никаких результатов, могущих заинтересовать Лигу Исследователей. \r\n\r\nЕдинственный примечательный инцидент произошел возле Золотого Пути. Вдали я заметил каких-то странных существ. Наполовину свиньи, наполовину люди – так мне показалось. Я быстро спрятался и дал мерзким животным пройти. Ну и вонь они оставили за собой!' FROM `page_text` WHERE `ID`=425 AND MD5(`Text`)='c4c3195c046c34bec68e6e3f1e261f8f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=425 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 426, 'ruRU', '--День третий--\r\n\r\nО, какое великолепное открытие!\r\n\r\nСегодня я нашел потрясающую вещь: массивные останки существа, похожего на кабана. Его череп возвышался надо мной на много ростов. Каждый зуб зверя мог заставить казаться карликом даже... ну, дворфа. Учитывая размер находки, я склонен полагать, что это останки одного из Древних Богов, о которых повествуют предания.' FROM `page_text` WHERE `ID`=426 AND MD5(`Text`)='8b9333ad310b7271f8b2b9580432b86f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=426 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 427, 'ruRU', 'Некоторое время назад в штабе Лиги Исследователей в Стальгорне нам читал лекцию главный археолог Седой Ус. Старикан упоминал такое божество, почитаемое странными эльфами Дарнаса за его, по слухам, бескорыстную натуру...\r\n\r\nБа! Один момент. Я слышу хрюканье за моей палаткой. Наверняка это просто щетинистые вепри пытаются добраться до моего запаса яблок...' FROM `page_text` WHERE `ID`=427 AND MD5(`Text`)='76e55d59e344d6247648780ec2dee2c0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=427 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 428, 'ruRU', '--День 4--\r\n\r\nЯ в плену!\r\n\r\nНужно... писать... быстро. \r\n\r\nНа меня напали свинолюди из племени Иглошкурых. Я думал, что они ведут меня к кабаньим останкам павшего бога. Вместо этого они обогнули окаменелость и направились прямо к западу от гигантского черепа, пересекая Золотой Путь.' FROM `page_text` WHERE `ID`=428 AND MD5(`Text`)='bd5e5e6f0ff76c3f98d06d8ea8e490eb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=428 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 429, 'ruRU', 'Меня грубо затащили в какие-то жутко колючие заросли под названием Лабиринты Иглошкурых. Меня бросили в убогую хижину и держали в плену вместе с умирающим ночным эльфом. \r\n\r\nУ меня не осталось ничего, кроме этого дневника, пера и карманных часов... \r\n\r\nКто-то идет...' FROM `page_text` WHERE `ID`=429 AND MD5(`Text`)='efacb89e520390afd69a23b84e3250b7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=429 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 430, 'ruRU', '--День 5--\r\n\r\nМой товарищ по заключению, ночной эльф, страдает от тяжких ран. Свинолюди долго истязали его хлыстом, и, сдается мне, он уже скоро испустит дух – если, конечно, в этом зловещем месте каким-то чудом не окажется отряда спасателей. Он то теряет, то вновь обретает сознание. Когда он приходит в себя, я пытаюсь поделиться с ним своим скудным запасом воды.' FROM `page_text` WHERE `ID`=430 AND MD5(`Text`)='ac2aad07604ee8b8f4013f0dee0ed833' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=430 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 431, 'ruRU', 'Вчера он впервые сумел заговорить. Он, друид по имени Гералат, послан в эти земли, чтобы проверить слухи о павшем боге-вепре.\r\n\r\nСлабеющим голосом он поведал мне, что считал, будто бы огромный кабаний череп лежит на том самом месте, где великий бог-вепрь Агамагган пал в битве с Пылающим Легионом примерно 10 000 лет тому назад, во время Войны Древних. Земля превратилась в равнину там, где рухнула его массивная туша, а кровь бога-вепря впиталась в почву – и там, куда пала кровь, растут острые шипы...' FROM `page_text` WHERE `ID`=431 AND MD5(`Text`)='322e1c078325b62334a84787b80e29a5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=431 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 432, 'ruRU', 'Гералат и его помощники хотят найти здесь источник зла. Он сказал мне, что Агамагган почитается за подлинного бога. А почему эта земля кишит зловредными тварями и колкими шипами – вот это тайна.\r\n\r\nЯ хотел узнать у Гералата больше, но он впал в очередное забытье...' FROM `page_text` WHERE `ID`=432 AND MD5(`Text`)='aab780d2d6ad8068799801290df6b82e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=432 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 433, 'ruRU', '--День 6--\r\n\r\nГералату становится хуже.\r\n\r\nСегодня он открыл глаза лишь однажды. Говорил он, превозмогая боль, но вполне ясно. Если мне удастся избежать зловещей судьбы в Лабиринтах Иглошкурых, я должен буду передать Хранителю дорог Фалфинделу в Таланаар, что Чарлга Остробок собирает своих приспешников в южных Степях. Его мощь крепнет с каждым днем. Эту ведьму нужно остановить, пока зло не вышло за пределы Лабиринтов.' FROM `page_text` WHERE `ID`=433 AND MD5(`Text`)='c0eb2d2ac3f81da8927cce4f1ecd1226' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=433 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 434, 'ruRU', 'Бедный Гералат бледен, точно смерть. Его с каждой минутой лихорадит все сильнее. А свинолюди без устали готовятся к какому-то крупному военному походу. Боюсь, что если я не попытаюсь вскоре бежать, мне будет уготована та же судьба, что и моему сотоварищу эльфу.\r\n\r\nЯ планирую тайком пробраться наружу, когда свинолюди в очередной раз уйдут на охоту. Стражники, охраняющие меня, ленивы и то и дело спят на посту.' FROM `page_text` WHERE `ID`=434 AND MD5(`Text`)='b4c5a2dd472b99add2ccf696d7fad8e8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=434 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 435, 'ruRU', 'Покинув Лабиринты, я направлюсь в Тысячу Игл, а затем на запад в сторону Таланаара, к границе с таинственным лесом Фералас. Там я найду друида, известного как Хранитель дорог Фалфиндел.\r\n\r\nПытаясь узнать прошлое моего народа, я, кажется, наткнулся на что-то большее. Теперь в моих руках – безопасность всего Альянса...' FROM `page_text` WHERE `ID`=435 AND MD5(`Text`)='8285ce57ea7bdb3149864bffd1d205ed' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=435 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 436, 'ruRU', 'НОМЕР ЗАКАЗА: 45TK-3\r\nПОКУПАТЕЛЬ: Крейвел Угольная Борода\r\n\r\nНАКЛАДНАЯ:\r\n\r\nГидромеханизмы (3)\r\nУсилительные болты (50)\r\n30-дюймовая медная труба калибра 20 (12)\r\nТабак марки Темная Ярость (1)\r\nВысококачественная призма (3)' FROM `page_text` WHERE `ID`=436 AND MD5(`Text`)='aa98b94704e2833a2b789e4848250e28' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=436 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 437, 'ruRU', 'доставил бы это письмо тебе сам, но боюсь отлучиться, поскольку могу пропустить нечто очень важное.\r\n\r\nЕсли ты желаешь побольше узнать о моих наблюдениях за Башней Алталакса, знай, что $gподатель:подательница; сего письма немало мне $gпомог:помогла; и $gему:ей; вполне можно доверять.\r\n\r\nСпешно заканчиваю,\r\nБалтул Удар Тени' FROM `page_text` WHERE `ID`=437 AND MD5(`Text`)='a320bde4dbe78cca2910173315eb432d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=437 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 438, 'ruRU', 'Гоблин Назз Паровой Котел на самом деле сын богатого гоблина-купца (какого купца? Ответ на этот вопрос дорогого стоит).\r\n\r\nПохоже, что ему больше нравится тратить заработанное семьей, а не зарабатывать самому. Поэтому он запустил руку в семейную казну и теперь прячется на Мерцающей равнине.\r\n\r\nЕсли бы его отец знал, где он скрывается, то наверняка бы нашел его и отволок домой... отрезав за нахальство палец на ноге.' FROM `page_text` WHERE `ID`=438 AND MD5(`Text`)='d2b5fe540459ac4196e2ae678093afe8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=438 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 439, 'ruRU', 'Г-н Шипучка!\r\n\r\nПодатель сего письма и я затеваем одно дело, к которому просим присоединиться и вас.\r\n\r\nКак вам известно, большую часть своего времени я провожу на Мерцающей равнине – упомянутое дело относится к проводимым там гонкам.\r\n\r\nЕсли гонки – а особенно ставки на их исход – вас интересуют, читайте, пожалуйста, дальше, ведь ваше знание Тернистой долины наверняка можно будет использовать во благо нашего плана.' FROM `page_text` WHERE `ID`=439 AND MD5(`Text`)='641e8f3eced9a3985e9ec974378557b9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=439 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 440, 'ruRU', 'Г-н Шипучка!\r\n\r\nНапиток, который вы дали моему помощнику, возымел большой успех. Мало того что он крепок и сильно затуманивает разум, он, похоже, еще и вызывает привыкание. Уверен: те, кто его отведали, будут просить добавки.\r\n\r\nМы в долгу перед вами, Кранк.\r\n\r\nТакже приглашаю вас посетить Мерцающую равнину либо послать свое доверенное лицо, дабы воспользоваться нашими новыми возможностями в азартных играх.\r\n\r\n--Крейвел' FROM `page_text` WHERE `ID`=440 AND MD5(`Text`)='72e2ca6dafd501f69cfbd1643da11cb0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=440 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 441, 'ruRU', 'Добрый мой Мартек, я в затруднении, мне нужна твоя помощь.\r\n\r\nМы с братом собираем гоночный автомобиль, и нам требуются крепкие поршни. Все поршни, что я пробую, недостаточно крепки. Ни один из них не может выдержать скорость нашей новой машины. И поэтому у нас то и дело ломается двигатель!\r\n\r\nТы мастер по работе с металлом. Ты должен помочь. Ты – единственная наша надежда.' FROM `page_text` WHERE `ID`=441 AND MD5(`Text`)='2c8438a9bc5c27be30e39f614d591910' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=441 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 442, 'ruRU', 'Чтобы встретиться с Ледочревом, его надо приманить мясом любимой добычи.\r\n\r\nОтравляйся в Альтеракские горы, что на Азероте, и поохоться там на крупных горных львов. Убей одного из них и отнеси тушу в Промерзшую пещеру, святое место для жестоких йети.\r\n\r\nПоложи тушу на Пламя Узеля, и из пещеры потянет ароматом жарящегося мяса.\r\n\r\nИ тогда, в свой черед, появится Ледочрев.' FROM `page_text` WHERE `ID`=442 AND MD5(`Text`)='d35651e337532c56ad14ae9c6641dbba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=442 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 443, 'ruRU', 'Я не устаю удивляться, как легко можно подчинять всех своей воле, играя на их ненависти. С орками и троллями было легче всего, ненависть к Альянсу сделала их прилежными учениками Темной Нити. Понимают ли они хоть отчасти, какой могучей силе служат?\r\n\r\nЭтот паладин, который меня бесит, Делгрен Очиститель, сует нос в наши дела в Ясеневом лесу, пока его прислужник, Балтул, шпионит за моей башней, думая, что мне о его присутствии неизвестно. Делгрен считает нас незначительной' FROM `page_text` WHERE `ID`=443 AND MD5(`Text`)='eb6f17278b06b45af8ad37a8d2c9371a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=443 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 444, 'ruRU', 'помехой – возможно, лишь еще одним культом смерти. Ему невдомек, что мы – не что иное, как одна из... нитей Совета Теней.\r\n\r\nРебенком я слышал историю о насекомом, один укус которого мог с легкостью убить жертву, хотя выглядело оно как обычная мушка, как пятнышко, вряд ли заслуживающее внимания. Именно то, что оставляют без внимания, и наносит нам самый крупный ущерб.' FROM `page_text` WHERE `ID`=444 AND MD5(`Text`)='949b442ffae196cd269247a604c29335' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=444 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 445, 'ruRU', 'Болиды, что участвуют в гонках на Равнинах, имеют очень тонкие настройки и требуют внимательнейшего ухода. Поэтому неудивительно, что у команды работа есть всегда.\r\n\r\nМеханики команды постоянно проверяют машины, чинят их и доводят. Только так можно содержать технику в идеальном состоянии.\r\n\r\nИтак... мы изыскиваем возможность немного притупить бдительность команды, поскольку при этом их машина быстро придет в негодность.' FROM `page_text` WHERE `ID`=445 AND MD5(`Text`)='fbbf6f64fe6a11e2b4f8f6cdf96472cb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=445 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 446, 'ruRU', 'Если мы сможем сами решать, какой машине быть в отличном состоянии, а какой нет... полагаю, излишне объяснять, какое преимущество это даст нам на ставках.\r\n\r\nИтак, от вас, милый Шипучка, мы ожидаем средство, которое ослабит прилежание техников.\r\n\r\nНет ли в Тернистой долине растений, трав или напитков, что могли бы размягчить мозги гномам и гоблинам?\r\n\r\n-- К. Углебород' FROM `page_text` WHERE `ID`=446 AND MD5(`Text`)='38696bdb2b19074cb86d36fc642d42e8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=446 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 447, 'ruRU', 'Я долго исследовал Аспекты и их создателей-титанов – так долго, насколько хватит человеческой жизни. Когда титаны покинули этот мир, Аспектов насчитывалось пять; это были могучие драконы, в задачи которых входила защита мира Азерота. О них сложено множество разных историй, и даже сейчас, когда я собрал множество сведений, я знаю, что нам еще очень многое предстоит узнать об этих величественных существах.' FROM `page_text` WHERE `ID`=447 AND MD5(`Text`)='5d60135a71e69771723a8c1e8c77688b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=447 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 448, 'ruRU', 'Аптекарь Лидон, я надеюсь, что это письмо дойдет до тебя быстро, а податель его будет в приличном состоянии. В далеком Калимдоре случилось то, что, как я считаю, потребует твоих умений.\r\n\r\nБуду кратка.\r\n\r\nВ Когтистых горах, недалеко от Мулгора, родины наших союзников тауренов, грядет несчастье. Торговая компания, управляемая гоблинами, вовсю ведет в этих горах добычу и вырубает там леса, гневя горных духов.' FROM `page_text` WHERE `ID`=448 AND MD5(`Text`)='3addd52607f0da1e9a45279bde6d8576' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=448 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 449, 'ruRU', 'Полагаю, что беспорядки, которые устраивают в недрах горы духи при поддержке тауренов-шаманов и друидов, отвлекают добытчиков – ведь таурены считают Торговую компанию в Когтистых горах явной угрозой.\r\n\r\nУгроза это или нет, мы должны помочь союзникам.\r\n\r\nЛидон, ты отлично разбираешься в ядах. Можешь ли ты придумать такую отраву, которой мы могли бы заразить гоблинов в Когтистых горах?\r\n\r\nС почтением к ученому,\r\nП.Зама.' FROM `page_text` WHERE `ID`=449 AND MD5(`Text`)='2bad58e5e3a475f3ca6abe86e77e54cc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=449 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 450, 'ruRU', 'Самому мне, наверное, никогда не удалось бы достичь нынешних вершин знания. Я очень благодарен ночным эльфам: без них я мало что сумел бы узнать. Из своего опыта могу заключить, что Аспекты значат для них много больше, чем я предполагал. Однако ночные эльфы бережно оберегают свои тайны, и даже я не могу быть до конца уверен в своей правоте.' FROM `page_text` WHERE `ID`=450 AND MD5(`Text`)='bb3de7459a51f0065a6f0e2689f930ff' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=450 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 451, 'ruRU', 'То, что я узнал об Аспектах, я привожу здесь для того, чтобы на это могли ссылаться другие. Я знаю, что от моих изысканий будет польза и что эти драконы со временем еще во многом повлияют на наш мир.' FROM `page_text` WHERE `ID`=451 AND MD5(`Text`)='f0a372146db471e3f12f62a21d79d0bf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=451 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 452, 'ruRU', 'Алекстраза:\r\nАлекстраза, древняя и могущественная царица драконов, была названа титанами Связующей Жизнь. Ее первую создали титаны для защиты мира после их ухода. Говорят, что она видела зарождение всех народов в мире Азерота. Предводительствуемые ею красные драконы, известные своим гордым нравом, некогда правили всем остальным драконьим племенем.' FROM `page_text` WHERE `ID`=452 AND MD5(`Text`)='e8e19c001bb9e9f38064564957a01cc2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=452 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 453, 'ruRU', 'Среди ночных эльфов ходят слухи, будто Алекстраза и полубог Кенарий были близкими друзьями и будто именно Кенарий призвал ее во время первого вторжения Пылающего Легиона.' FROM `page_text` WHERE `ID`=453 AND MD5(`Text`)='aad4a8c09e9e4d4ced1dd0ee52b740e2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=453 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 454, 'ruRU', 'Изера:\r\nИзера Спящая представляет подсознание смертных. Она олицетворяет Изумрудный Сон... Она благоволит к искусствам и амбициям смертных народов, но в то же время считает, как и все ее драконы, что настоящий мир – это лишь иллюзия. Изера – одно из самых могучих и грациозных созданий, которое только может узреть смертный.' FROM `page_text` WHERE `ID`=454 AND MD5(`Text`)='c0b694581cc074e1f381ef29b8825876' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=454 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 455, 'ruRU', 'Малигос:\r\nМалигос известен как Управитель или хранитенль магии. Его естественное обличье не типично для драконов, и говорят, что он может изменять свой внешний вид по желанию. Его редко видят после ухода далеко на север, а если и видят, то чаще всего в образе насекомоподобного создания, но, принимая форму драконов, он и его сородичи отливают различными оттенками синего цвета.' FROM `page_text` WHERE `ID`=455 AND MD5(`Text`)='2e17c2c53ad24b9031dcc69d3f644892' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=455 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 456, 'ruRU', 'Ноздорму:\r\nНоздорму известен как Хозяин Времени и Вневременный. Он и его драконы – бронзового цвета, показывают большую сметливость во всем. Внимание Ноздорму всегда привлекают артефакты прошлого, ведь о нынешних делах смертных народов, как и о замыслах его сотоварищей-Аспектов, он особо не заботится. Но его безразличие к задумкам других не означает, что он не уделяет внимания событиям, происходящим в мире.' FROM `page_text` WHERE `ID`=456 AND MD5(`Text`)='dd269e6b39a51b806538f7a8995d0cee' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=456 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 457, 'ruRU', 'Бронзовые драконы, что считаются защитниками, склонны обитать в обжитых местах. Вневременный и все его племя по натуре своей очень терпеливы и всегда обдумают все заранее, прежде чем действовать. Ноздорму неизменно будет защищать нормальное течение времени, а также и смертные народы, если им будут угрожать могущественные враги.' FROM `page_text` WHERE `ID`=457 AND MD5(`Text`)='fcc28588f655be2e063b6b19b1620877' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=457 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 458, 'ruRU', 'Нелтарион:\r\nНелтарион, названный при рождении Землестражем, был предан Азероту сильнее, чем кто-либо из другой из Аспектов. Его черные драконы создали горы и прочие возвышенности, включая и границы между землями смертных народов. До сих пор неизвестно, что толкнуло его в пучину зла: внешнее ли влияние, внутренняя ли слабость. Интересно знать, причастны ли этой порче, которой подвергся великий черный дракон, Древние Боги.' FROM `page_text` WHERE `ID`=458 AND MD5(`Text`)='97f68672dd5ba0a92284a3adbddf758a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=458 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 459, 'ruRU', 'Черный дракон прошел через полное преображение, после чего Нелтариона уже не существовало. Он стал Смертокрылом – злобным и яростным созданием. Он больше не был Землестражем в глазах Высших эльфов, теперь, вместо имени, данному ему титанами, его стали называть Аспектом Смерти и Заккасом. Смертокрыл – воплощение зла и хаоса, вечно алчущее разрушения. Возможно, он – первое зло Азерота, что появилось после изгнания Древних Богов.' FROM `page_text` WHERE `ID`=459 AND MD5(`Text`)='6861b310b441ae583f2f7e1db29b4b1f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=459 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 467, 'ruRU', 'ПОЗДРАВЛЯЕМ!\r\n\r\nВы стали владельцем замечательного шмыгуноса! Зверек довольно робкий, но вам непременно полюбятся его пушистое обаяние и невероятный нюх.\r\n\r\nНа следующих страницах приводится информация о:\r\n\r\n1. Кормлении и заботе о шмыгуносе\r\n2. Эксцентричном (и очаровательном) поведении шмыгуноса\r\n3. Применении запатентованной палочки-погонялочки для шмыгуносов(tm)\r\n\r\nПоздравляем вас еще раз. Вы не пожалеете,\r\n\r\n-Марвиг Ржавоболт\r\nВладелец "Шмыг Инк."' FROM `page_text` WHERE `ID`=467 AND MD5(`Text`)='5e28e1559f91fd7c9c671dd968da047e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=467 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 507, 'ruRU', '--День 13\r\nДвижение войск у Терамора усилилось. Крупные отряды людей оставили город и спешно идут на запад.\r\n\r\n--День 14\r\nИз города уходят все новые отряды. Я проследил за одной маленькой группой и видел, как все в ней сняли униформу, удалившись от Терамора на расстояние полета стрелы. Может быть, они дезертиры?\r\n\r\n--День 15\r\nСегодня я слышал, как солдаты в Тераморе говорили о часовых, оставляющих посты. Должно быть, мои подозрения о дезертирах верны' FROM `page_text` WHERE `ID`=507 AND MD5(`Text`)='87e3e3c3d79609a9b14b2e56afd80c4b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=507 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 528, 'ruRU', 'Йорген, мои худшие ожидания оправдались, сбылось то, чего я и представить не мог. Я никогда не думал, что они подберутся так близко, но это случилось. \r\n\r\nПожалуйста, помоги подателю сего письма и отправь его к НЕМУ. Откровенно говоря, я думаю, что он поможет нам из-за серьезности этого дела. Если бы нам грозило что-то другое, он, возможно, так и не обратил бы внимания на нас и на проблемы нашего славного города.\r\n\r\nСпасибо тебе, старый рыбак. Я, как обычно, у тебя в долгу.\r\n\r\nТвой друг \r\n Делавей' FROM `page_text` WHERE `ID`=528 AND MD5(`Text`)='bb19ab8e1b63a3ede32056ad559ea832' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=528 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 547, 'ruRU', 'Капитан, удачи тебе в путешествиях. К несчастью, в первой нашей попытке похищения удача нам не благоволила.\r\n\r\nКогда наша команда вышла на объект в тоннеле между Штормградом и Стальгорном, она обнаружила там лишь приманку. Очевидно, он куда умнее, чем мы о нем думаем.\r\n\r\nНо теперь уже задействован наш второй план. Агенты Братства Справедливости готовятся захватить объект, как только он приблизится к Терамору. Скоро в Штормграде узнают, как мы умеем кусаться...\r\n\r\n-М' FROM `page_text` WHERE `ID`=547 AND MD5(`Text`)='bf67b83cfd2ae421049ccb2eb5cbef52' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=547 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 548, 'ruRU', '--День 16\r\nУлег и Таргил вернулись с задания в доках Терамора. В порту они видели новый корабль – "Бешеный Воробей". Корабль прибыл из Гавани Менетилов.\r\n\r\nЗавтра Улег и Таргил вернутся в доки и прокрадутся на корабль. Они надеются найти там политические документы, раскрывающие отношения Терамора и Альянса.' FROM `page_text` WHERE `ID`=548 AND MD5(`Text`)='eec762296d183543bee372cbdd0ee880' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=548 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 572, 'ruRU', 'Благодаря успеху Кел\'Тузада в Лордероне Король-лич завершил последние приготовления к атаке на человеческую цивилизацию. Нер\'зул поместил вызывающие чуму сгустки энергии в несколько переносных артефактов, так называемых чумных котлов, и приказал Кел\'Тузаду доставить их в Лордерон, где они должны были быть спрятаны в различных селениях, находящихся под властью культистов.' FROM `page_text` WHERE `ID`=572 AND MD5(`Text`)='17d2a343cbcbdff48e8a508514c15ac9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=572 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 573, 'ruRU', 'Котлы, которые охраняют верные культисты, должны были действовать как генераторы чумы, рассылая ее по поместьям и городам северного Лордерона.\r\n\r\nПлан Короля-лича сработал идеально. Многие из северных деревень Лордерона заразились почти сразу же. Как и в Нордсколе, горожане, заболевшие чумой, умерли и возродились уже преданными рабами Короля-лича.' FROM `page_text` WHERE `ID`=573 AND MD5(`Text`)='db32fa983065f2fda1c0d1092499b903' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=573 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 574, 'ruRU', 'Культисты под командованием Кел\'Тузада жаждали смерти, после которой они могли бы восстать и служить своему темному властелину. В этом они увидели шанс на бессмертие и возрадовались ему. Чем дальше расходилась чума, тем больше ужасных зомби появлялось в северных землях. Кел\'Тузад, глядя на растущее войско Короля-лича, назвал его Плетью – ведь скоро она придет к воротам Лордерона... и могучим ударом бича снесет человечество с лица земли.' FROM `page_text` WHERE `ID`=574 AND MD5(`Text`)='07f0bb53958fde031e382c3775e45d06' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=574 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 575, 'ruRU', 'Никто не знает точно, как зародилась Вселенная. Кто-то предполагает, что после сильнейшего космического взрыва в Великой Тьме стали вращаться бесконечные миры – миры, в которых затем зародилось великое многообразие форм жизни. Другие же считают, что Вселенная в ее современном виде была создана одной-единственной всемогущей сущностью.' FROM `page_text` WHERE `ID`=575 AND MD5(`Text`)='721b86c14e149b3c72b4b87876ce8326' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=575 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 576, 'ruRU', 'Хотя доподлинное происхождение хаотичной Вселенной неизвестно, очевидно, что могущественные создания явились, дабы привнести в миры порядок и обеспечить тем, кто будет их населять, мир и спокойствие.\r\n\r\nТитаны – колоссальные железнокожие боги из далеких пределов космоса – занимались обустройством встреченных ими миров. Они возводили высокие горы и создавали морские пучины.' FROM `page_text` WHERE `ID`=576 AND MD5(`Text`)='8bedf37a56bc618992e34051b880ab4d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=576 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 577, 'ruRU', 'Они облекли планеты небесными слоями и бушующими атмосферами, воплощая свой непостижимый и дальновидный замысел, создавая порядок из хаоса. Они научили древние примитивные племена приглядывать за своими детищами и поддерживать целостность созданных миров.\r\n\r\nТитаны, которыми правила элитная группа – Пантеон, – создали порядок в сотнях миллионов миров, рассеянных по Великой Запредельной Тьме на заре творения.' FROM `page_text` WHERE `ID`=577 AND MD5(`Text`)='d554946d65236edd75a8f754795bd3a1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=577 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 578, 'ruRU', 'Благой Пантеон, желающий оградить свои упорядоченные миры от всякого зла, зорко наблюдал за действиями темных сил Круговерти Пустоты. Там, в неосязаемом мире неупорядоченных магических энергий, соединяющем мириады миров во Вселенной, обитали неисчислимые множества зловредных демонических существ, жаждавших лишь умерщвления и пожирания всего сущего в мирах.' FROM `page_text` WHERE `ID`=578 AND MD5(`Text`)='3e7bb73ee790ce2212e7930c3af0ca3b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=578 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 579, 'ruRU', '--День 17\r\nУлег вернулся с задания. Он потерпел неудачу, а Таргил попал в плен. Я послал Улега доставить это сообщение Назиру.\r\n\r\nЯ останусь здесь. Я видел, что от побережья Терамора все чаще отходят корабли. Продолжу вести наблюдение и буду лично сообщать о всяком заслуживающем упоминания событии.' FROM `page_text` WHERE `ID`=579 AND MD5(`Text`)='313175fd0458445bb2f4d62af10d2a98' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=579 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 580, 'ruRU', 'Наш первый план уже провалился!\r\n\r\nКулаку удалось поменять распорядок дежурства охранников в тоннелях, но из-за непредвиденного вмешательства некоторых жителей Штормграда объект смог улизнуть прежде, чем нам удалось его поймать. Но мы были готовы к неожиданностями. Сейчас мы действуем по плану 2, и все шло хорошо еще до засады в Штормграде.' FROM `page_text` WHERE `ID`=580 AND MD5(`Text`)='50eaf38e244d6d848a965bdef0fda093' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=580 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 581, 'ruRU', 'План 2 довольно прост, но потребует от нас большего терпения. Нашему сообщнику в Менетиле уже заплачено, и свою работу он выполнил блестяще. Теперь мы наверняка с легкостью захватим объект, как только отправимся в плаванье.' FROM `page_text` WHERE `ID`=581 AND MD5(`Text`)='3a34d5e8e6e2ea3b573d30db6e6f9937' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=581 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 582, 'ruRU', 'Нападение произойдет за несколько миль до места прибытия. Именно там будут ожидать наши союзники. Я не вполне понимаю, почему нам пришлось объединиться с этими созданиями, и меня не покидает ощущение, что союз этот – вынужденный. Но это, в общем-то, не важно. Захватив объект, мы сделаем большой шаг к тому, чтобы отобрать Штормград у тех, кто его у нас отнял!' FROM `page_text` WHERE `ID`=582 AND MD5(`Text`)='555c7d294239f844007d7fe3738123d9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=582 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 606, 'ruRU', 'Нападение произойдет за несколько миль до места прибытия. Именно там будут ожидать наши "союзники". Я не вполне понимаю, почему нам пришлось объединиться с этими созданиями, и меня не покидает ощущение, что союз этот – вынужденный. Но это, в общем-то, не важно. Захватив объект, мы сделаем большой шаг к тому, чтобы отобрать Штормград у тех, кто его у нас отнял!' FROM `page_text` WHERE `ID`=606 AND MD5(`Text`)='64ea4c7b667e67f8124d3d1a7c60c3c5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=606 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 607, 'ruRU', 'Мастер Длиннобородый, как тебе известно, мы в клане Грозовой Вершины разбираемся в отличной работе, так что качество твоих щитов для нас не новость.\r\n\r\nИменно поэтому я хотел бы заказать у тебя щит. Описание его я привожу на следующей странице:' FROM `page_text` WHERE `ID`=607 AND MD5(`Text`)='e3b4ed08c117a3e6dda19201e56487e2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=607 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 629, 'ruRU', 'В последней отчаянной попытке Молот Рока и его командиры храбро ринулись в атаку с Пика и схлестнулись с паладинами Лотара прямо посреди Пылающих степей. Молот Рока и Лотар сошлись в яростном бою, который изрядно измотал обоих могучих бойцов. И хотя Оргрим в итоге смог одолеть Лотара, смерть прославленного героя не возымела того эффекта, на который надеялся орочий вождь.' FROM `page_text` WHERE `ID`=629 AND MD5(`Text`)='3b9be5c650731b93768b63add44d00d0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=629 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 630, 'ruRU', 'Туралион, наиболее приближенный к Лотару командир, поднял его окровавленный щит и призвал своих пораженных горем собратьев нанести со всей яростью ответный удар. Под истрепанными знаменами Лордерона и Азерота воинство Туралиона разбило почти всю армию Молота Рока в славной, но жестокой сече.' FROM `page_text` WHERE `ID`=630 AND MD5(`Text`)='6887b008f79188c1f1b46bc23c27399a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=630 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 632, 'ruRU', 'Орки, уступавшие противнику числом и обезумевшие от собственной жажды крови, пали пред гневом Альянса. Молот Рока был взят в плен и препровожден обратно в Лордерон, как и его разбитые кланы.' FROM `page_text` WHERE `ID`=632 AND MD5(`Text`)='cf5e64a4f114dcdd17e106937ee5a9b7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=632 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 633, 'ruRU', 'Всего через несколько месяцев после завершения строительства Крепости Стражей Пустоты вся энергия Темного портала слилась воедино и открылся новый проход на Дренор. Оставшиеся кланы орков под предводительством старого шамана Нер\'зула вновь напали на Азерот. Собираясь украсть ряд магических артефактов, которые должны были увеличить могущество Нер\'зула, орки планировали открыть несколько новых порталов на Дреноре, которые позволили бы им навсегда покинуть свой обреченный мир.' FROM `page_text` WHERE `ID`=633 AND MD5(`Text`)='8fb8499f2e46d871661d30546577350d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=633 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 634, 'ruRU', 'Король Теренас из Лордерона, будучи уверенным, что Нер\'зул замышляет новое нападение на силы Альянса, послал свои войска на Дренор, чтобы раз и навсегда покончить с орочьей угрозой. Силы Альянса, ведомые Кадгаром и генералом Туралионом, сошлись с орками среди пылающих земель. Даже с помощью Аллерии из числа Высших эльфов, дворфа Курдрана и опытного воина Даната Кадгар не смог помешать Нер\'зулу открыть врата в другие миры.' FROM `page_text` WHERE `ID`=634 AND MD5(`Text`)='85c828d09e78e1a2aff4b05c14dd5253' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=634 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 635, 'ruRU', 'Чудовищные магические штормы, вызванные скапливающейся энергией портала, начали разрывать опустошенный мир на части. Нер\'зул, за которым пошли лишь самые преданные его слуги, смог убежать через один такой портал, пока Кадгар отчаянно сражался, чтобы вернуть своих товарищей в Азерот. Поняв, что они окажутся в ловушке в этом гибнущем мире, Кадгар и его спутники приняли самоотверженное решение уничтожить Темный портал, чтобы Азерот не пострадал от кошмарного разрушения Дренора.' FROM `page_text` WHERE `ID`=635 AND MD5(`Text`)='e869bab0b9c9c3859de9c90db35cac06' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=635 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 636, 'ruRU', 'Конечно, героям удалось разрушить портал и спасти Азерот, но сумели ли они выжить среди предсмертных мук Дренора – остается загадкой.' FROM `page_text` WHERE `ID`=636 AND MD5(`Text`)='a51816879ffce938d0ddc1651bf9d97d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=636 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 637, 'ruRU', 'За десять тысяч лет до того, как орки и люди сошлись в Первой войне, мир Азерота вмещал лишь один массивный континент, окруженный бескрайними бушующими морями. На этом континенте, известном как Калимдор, жило множество самых разных народов и существ, борющихся за выживание на просторах нового мира. В центре темного континента находилось таинственное озеро, бурлившее энергией.' FROM `page_text` WHERE `ID`=637 AND MD5(`Text`)='997da661d8e8d982c6f0ff1907384acf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=637 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 639, 'ruRU', 'Эти дикие кочевники, которых притягивала энергия Источника, построили на его безмятежных берегах свои хижины. Со временем космическая энергия Источника изменила племя, сделав его сильным, мудрым и практически бессмертным. Племя стало называть себя "калдорай", что на их родном языке означало "дети звезд". Прославляя расцвет своего общества, поселенцы воздвигли по берегам озера большие постройки и храмы.' FROM `page_text` WHERE `ID`=639 AND MD5(`Text`)='e6153cb7d98721327424866aaa9876fe' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=639 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 642, 'ruRU', 'Со временем любопытство ночных эльфов привело к тому, что они повстречали и подружились с самыми разными могущественными существами, не последним из которых был Кенарий, могучий полубог древних лесов. Благородному Кенарию пришлись по нраву любознательные ночные эльфы, и он потратил много времени на то, чтобы рассказать им о силах природы. Мирные калдорай прониклись большим сочувствием к живым лесам Калимдора и наслаждались гармонией природы.' FROM `page_text` WHERE `ID`=642 AND MD5(`Text`)='e11fc17f2a35031b1bd02c47c35bad0e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=642 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 643, 'ruRU', 'С неспешным течением времени росла как территория ночных эльфов, так и их культура. Храмы, дороги и жилища протянулись по всему темному континенту. Азшара, прекрасная и талантливая королева ночных эльфов, воздвигла на берегу Источника Вечности огромный, изумительный дворец, в роскошных залах которого проживали ее любимые слуги.' FROM `page_text` WHERE `ID`=643 AND MD5(`Text`)='0cc8469fef77157104e27ca13bac18ba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=643 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 645, 'ruRU', 'Высокорожденные с головой ушли в работу и беспрерывно изучали Источник. Со временем они развили в себе способности управлять его космической энергией. Чем больших успехов Высокорожденные достигали в своих опытах, тем явственней они понимали, что с помощью своих новообретенных навыков они могут как творить, так и разрушать. Злосчастные Высокорожденные зациклились на примитивной магии и твердо решили добиться мастерского владения ею.' FROM `page_text` WHERE `ID`=645 AND MD5(`Text`)='e4f502ca933e052b8f8f92454488ad53' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=645 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 646, 'ruRU', 'Хотя Азшара вместе с ее высокорожденными понимали, что при безответственном обхождении такая магия может быть опасна, они начали практиковать ее с неуемной страстью. Кенарий и многие из ночных эльфов-мудрецов предупреждали, что безрассудство при обращении со столь неуловимой магической силой неизбежно грозит бедой. Но Азшара и ее последователи упрямо продолжали усиливать свое растущее могущество.' FROM `page_text` WHERE `ID`=646 AND MD5(`Text`)='35afb6c991dfee8084491c8a369c253d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=646 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 647, 'ruRU', 'По мере того как могущество Высокорожденных и самой Азшары росло, в их характере наметились явственные изменения. И без того высокомерные и холодные, представители высшего класса становились все более чванливыми и жестокими по отношению к соплеменникам. Некогда завораживающую красоту Азшары окутал темный покров. Она начала отдаляться от любящих подданных и не хотела общаться ни с кем, кроме своих доверенных жрецов из числа Высокорожденных.' FROM `page_text` WHERE `ID`=647 AND MD5(`Text`)='e7c9ed6a60d63736a6a66983546f5366' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=647 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 648, 'ruRU', 'Молодой и талантливый ученый по имени Фурион Ярость Бури, который очень долго изучал эффекты Источника, начал подозревать, что Высокорожденными и обожаемой королевой овладела темная сила. И хотя он не мог постичь природы этого зла, он осознавал, что жизнь ночных эльфов скоро изменится навсегда...' FROM `page_text` WHERE `ID`=648 AND MD5(`Text`)='4cc43b33f481eb8faed27e901a2a3d9f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=648 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 649, 'ruRU', '-Идеально круглый, от центра до края – локоть длины.\r\n\r\n-По краю – заклепки. Серебряные.\r\n\r\n-В центре – большой шип, диаметр основания – три пальца. Серебряный.\r\n\r\n-Сам щит из дуба, укрепленный железом.\r\n\r\n-На наружном ободе выгравировать мое имя – Грингер Грозовая Вершина.' FROM `page_text` WHERE `ID`=649 AND MD5(`Text`)='2c2f4da090a53a4a72cf85c685ab821c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=649 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 650, 'ruRU', 'Оплата будет произведена обычным способом. И расплатись с подателем сего письма за доставку. Эти деньги можешь прибавить к цене щита.\r\n\r\nПремного тебе благодарен,\r\n--Грингер Грозовая Вершина.' FROM `page_text` WHERE `ID`=650 AND MD5(`Text`)='094222099c3d177af4d05711dc17f9ce' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=650 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 669, 'ruRU', 'Козни нежити на земле Азерота начались не с падения принца Артаса, они начались задолго до того, как и события, вызвавшие падение Лордерона. Началом всему послужило пришествие орочьих кланов и Пылающего Легиона.' FROM `page_text` WHERE `ID`=669 AND MD5(`Text`)='13de38a90757e993d1dedd34f6b46c18' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=669 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 670, 'ruRU', 'Орки Дренора (мира, из которого они изначально пришли) были благородными и стремились к знаниям. Они были могучими воинами, сильными телом и душой. Именно поэтому их упорно разыскивал Пылающий Легион. Кил\'джеден, демон великой мощи из рядов Легиона, возжаждал поработить орочьи кланы и напустить их полчища на те миры, которые еще только предстояло покорить Пылающему Легиону.' FROM `page_text` WHERE `ID`=670 AND MD5(`Text`)='4e7f88af6965313557085cd722b9e547' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=670 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 671, 'ruRU', 'Кил\'джеден пришел к предводителю кланов, могучему шаману по имени Нер\'зул. Он пообещал ему необычайную мощь и мудрость, если тот заключит с демоном пакт, который отдаст кланы во власть Пылающего Легиона. Этот пакт предопределил не только судьбу орков, но и судьбу всего их мира.' FROM `page_text` WHERE `ID`=671 AND MD5(`Text`)='18c050e49570be05e72532b893a1a364' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=671 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 672, 'ruRU', 'Со временем Нер\'зул осознал, что судьба кланов – в руках Пылающего Легиона, и тогда шаман бросил вызов Кил\'джедену. Демон, разъяренный поступком Нер\'зула, обратился к ученику шамана, Гул\'дану, склонить которого ко злу оказалось куда проще, чем Нер\'зула.' FROM `page_text` WHERE `ID`=672 AND MD5(`Text`)='3e062896743dc4eeb26ef69eaf5eb3af' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=672 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 673, 'ruRU', 'Именно Гул\'дан повинен в том, что шаманские знания в кланах пошли на убыль. Он обещал всем могущество и власть над врагами, и его охотно слушали. С помощью Кил\'джедена Гул\'дан начал манипулировать кланами. Орки, некогда благородные, превратились в злобных и неразумных дикарей. Когда же в их жилы попала кровь демонов, орки стали еще более безжалостными и одержимыми.' FROM `page_text` WHERE `ID`=673 AND MD5(`Text`)='6e6cea3490e1fe534661eab22a6706ba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=673 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 674, 'ruRU', 'Хотя Кил\'джедену удалось склонить к себе Гул\'дана после неудачи с Нер\'зулом, он по-прежнему ненавидел шамана и поклялся заставить его принять тот самый пакт. Кил\'джеден захватил Нер\'зула и начал истязать шамана невыносимой медленной пыткой. Нер\'зул молил о смерти, а Кил\'джеден все напоминал ему о пакте. Затем Кил\'джеден убил орка, но умертвил при этом лишь его тело. Душу орочьего шамана Кил\'джеден удерживал, пока она не нашла свой путь в Круговерть Пустоты.' FROM `page_text` WHERE `ID`=674 AND MD5(`Text`)='db7e691ddacce73aa8cf175c271c6ff6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=674 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 675, 'ruRU', 'Кил\'джеден поместил душу Нер\'зула в ледяную глыбу, принесенную из Круговерти Пустоты, и наделил ее еще большим могуществом. Потеря телесной оболочки и обладание невероятной силой привели к перевоплощению Нер\'зула.' FROM `page_text` WHERE `ID`=675 AND MD5(`Text`)='d9379b4a6e6a2acb535ae7b57bab5b64' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=675 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 676, 'ruRU', 'Кил\'джеден бросил в Азерот через иные измерения глыбу льда, и она упала на континенте Нордскол, принеся в наш мир великое зло. Нер\'зул исчез навсегда, вместо него там образовался Ледяной Трон, средоточие ненависти. Некогда уважаемый предводитель шаманов стал невероятно могущественным королем-личом.' FROM `page_text` WHERE `ID`=676 AND MD5(`Text`)='e36e732464c7bfeddc640c2d5886755e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=676 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 677, 'ruRU', 'Поскольку Кил\'джеден не доверял Королю-личу, он послал своих Повелителей ужаса надзирать за духом и следить, чтобы тот выполнял его приказания. Его слуги-вампиры охотно отправились в Азерот, их влекла мощь и ярость Короля-лича, а также возможность изничтожить население целой планеты.' FROM `page_text` WHERE `ID`=677 AND MD5(`Text`)='8a478dd9d3c895c843ed2892514bbb8c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=677 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 678, 'ruRU', 'Прошло больше десяти лет. За это время Король-лич использовал свою огромную мощь, чтобы обрести власть над умами обитателей Нордскола, и повелел им возвести огромную цитадель над его Ледяным Троном. Теперь, когда под его началом был весь Нордскол, Король-лич понял, что настала пора вторгнуться в Лордерон. Находясь в ледяном плену, бывший орочий шаман начал обдумывать новые способы захвата власти. Его призыв достиг всех земель.' FROM `page_text` WHERE `ID`=678 AND MD5(`Text`)='8a5e30b3d7cbc1bb70332d2566a777bd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=678 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 679, 'ruRU', 'Призывы Короля-лича не остались незамеченными, особенно в небольшой группе могущественных личностей. Среди них был верховный маг Кел\'Тузад, влиятельный участник правящего круга Даларана, Кирин-Тора. Его стремление овладеть всеми видами волшебства нарушало правила Кирин-Тора, возбраняющие практиковаться в черной магии. Кел\'Тузад оставил Кирин-Тор, порвал все связи с обычным миром и поклялся стать прилежным учеником Короля-лича.' FROM `page_text` WHERE `ID`=679 AND MD5(`Text`)='4a49b7431c5ae016de56e4232531a72b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=679 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 680, 'ruRU', 'Двое заключили между собой пакт. Кел\'Тузад получил бессмертие и великую силу в обмен на верность Королю-личу. Перво-наперво он должен был употребить в Лордероне все свое богатство и влияние, чтобы основать там Культ Проклятых. Этот культ обещал всем своим приверженцам равенство и вечную жизнь, если они присягнут на верность Нер\'зулу, богу Культа Проклятых.' FROM `page_text` WHERE `ID`=680 AND MD5(`Text`)='2923ad22ee56ab3997435f4479d6df2a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=680 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 681, 'ruRU', 'Затем Нер\'зул создал артефакты, чтобы распространить чуму среди народов Лордерона. Он отдал их Кел\'Тузаду и повелел волшебнику разнести их по земле. А служителям своего культа приказал защищать артефакты любой ценой.' FROM `page_text` WHERE `ID`=681 AND MD5(`Text`)='2c24e26efd353d60bf0becd6a106096b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=681 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 682, 'ruRU', 'Потом чума начала заполонять страну и заражать ее ничего не подозревающих обитателей. Под присмотром Кел\'Тузада войско Короля-лича быстро росло, и вскоре тот подчинил себе обширные земли. Это войско стало известным под именем Плеть, и единственной его целью было истребление всех жителей Азерота.' FROM `page_text` WHERE `ID`=682 AND MD5(`Text`)='e65aa88c5659a16643f7ab9d0243b03d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=682 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 690, 'ruRU', 'Слово "ПРЕДАТЕЛЬ" криво нацарапано поверх красиво высеченной эпитафии, гласящей:\r\n\r\n"Здесь покоится Юрив.\r\nОтец, муж, паладин.\r\nПусть же потомки знают, что преданность его Свету была неколебима.\r\nОн никогда не требовал от других того, чего не стал бы делать сам".' FROM `page_text` WHERE `ID`=690 AND MD5(`Text`)='5f607cd098ccd98c0936988ddc95c7ee' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=690 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 696, 'ruRU', 'Дневник – день 4\r\n\r\nЯ сижу на этом острове наедине со своими мыслями уже 4 дня. Бананы очень вкусные, вот только лазать за ними приходится высоко. В свободное от добывания еды или укрывания от дождя время я думаю лишь о спасении.\r\n\r\nЯ не питал бы такой радостной надежды, если бы на берег вместе со мной не выбросило ящики с бумагой и бутылки. Теперь мне смешно вспоминать о том, как недоволен я был, что застрял на корабле, полном алхимиков и писцов.' FROM `page_text` WHERE `ID`=696 AND MD5(`Text`)='4b8b76611a6cd7f6febbc1b25add8111' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=696 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 697, 'ruRU', 'Дневник – день 512\r\n\r\nБананы начали говорить со мной, и я многое узнал об их культуре. Теперь я перестал бездумно разрушать их дома и поедать их детей. Как же мало мне было известно о великой цивилизации, которую я уничтожал.\r\n\r\nКроме того, у меня, кажется, заканчиваются бутылки и бумага. Когда я впервые оглядел ту огромную кучу бумаги, что выбросило волнами на берег, то подумал, что она не переведется никогда. Увы, скоро мне придется прекратить свои записи.' FROM `page_text` WHERE `ID`=697 AND MD5(`Text`)='2ee46e1b4a8d8cd915e34b526137738a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=697 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 698, 'ruRU', 'Азерот – страна нескончаемых чудес. Здесь многообразно все – флора, фауна, культура, магия. Жаждущий знаний может многое здесь найти. Надо лишь внимательно смотреть.\r\n\r\nИ если заглянуть достаточно глубоко, то увидишь окна в новые миры, в каждом из которых есть свои чудеса.\r\n\r\nА есть и свои бедствия.' FROM `page_text` WHERE `ID`=698 AND MD5(`Text`)='bc5d69684e4052c3c8d81f344f0754f8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=698 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 699, 'ruRU', 'Вот цель моей книги: составить список этих существ, этих зловещих созданий, желающих уничтожить наши земли, чтобы те странники, кто на них наткнется, знали, чего им следует ожидать.\r\n\r\nПоэтому если ты считаешь себя стражем Азерота, читай дальше. Читай, чтобы знать своего врага.\r\n\r\n-Ур\r\nМаг из Даларана' FROM `page_text` WHERE `ID`=699 AND MD5(`Text`)='9081b0b55309925fd7c6ced1d5fd3081' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=699 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 700, 'ruRU', 'Тварь, о которой я пишу, – это ворген.\r\n\r\nО воргенах часто рассказывают в селах – какой же ребенок с фермы не слышал сказок о людях-волках, бродящих по лесам и болотам у его родной деревни?\r\n\r\nВ таких сказках может скрываться и правда – возможно, так нас предупреждают о воргенах, пугая страшными небылицами.' FROM `page_text` WHERE `ID`=700 AND MD5(`Text`)='da8129def7c5267caa5e9303b861ce8e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=700 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 701, 'ruRU', 'Но прежде чем читатель поспешит отбросить мысли о сказках, поспешу его уверить: воргены существуют на самом деле. Возможно, они не из нашего мира, но между мирами сейчас проложены свои тропы, и чудовищ можно призвать сюда из их миров с помощью сильной магии.\r\n\r\nНо лучше такой магией не пользоваться, ведь где бы ни появлялись воргены, с собой они приносят ужас и смерть.' FROM `page_text` WHERE `ID`=701 AND MD5(`Text`)='c7725a0c1cdf2434abee0ea37723bd3e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=701 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 702, 'ruRU', 'Воргена можно узнать по его сходству с волками из нашего мира. Глядя на воргена, каждый с легкостью заметит, как сильно его грубая шерсть, заостренные уши и длинная морда похожи на волчьи.\r\n\r\nНо сразу же станут заметны и отличия: грубая шерсть покрывает мощное тело с двумя ногами, из пасти торчат длинные клыки, а когти – словно кинжалы. В завываниях же его слышится такая злоба, которой нет ни у одного здешнего зверя.' FROM `page_text` WHERE `ID`=702 AND MD5(`Text`)='1d6f6bac160f64c6a5b5cc1ae6ead05f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=702 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 703, 'ruRU', 'Родина воргенов – темное место, обитель кошмаров. Если в том мире и есть места, куда не могут добраться проклятые воргены, то мне о таких бастионах не известно.\r\n\r\nЕсли же лицезреть воочию ярость и злобу воргенов, то на ум приходит, что быть таких мест не может.\r\n\r\nЕсть мнение, что воргенов вполне устраивает их собственный мир: ведь, хотя некоторые из них владеют очень сильной магией, они не предпринимали попыток перенестись в Азерот самостоятельно.\r\n\r\nИ для нас это очень хорошо.' FROM `page_text` WHERE `ID`=703 AND MD5(`Text`)='6abfacaae0de42a991454686007b22f7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=703 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 704, 'ruRU', 'Как уже упоминалось выше, некоторые воргены хорошо владеют тайными искусствами, и их магия – магия тьмы и зла.\r\n\r\nДля них обычны проклятия и жуткие яды, так что пусть читатель знает заранее: те, кто столкнется с воргенскими магами, должны уметь оградить себя от тьмы.' FROM `page_text` WHERE `ID`=704 AND MD5(`Text`)='be35efeec42a8acbed9588575ab72d7b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=704 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 705, 'ruRU', 'Я надеюсь, что ни один даларанский волшебник не станет разыскивать воргенов, даже из лучших побуждений. С этими тварями нельзя заключить союз, у них нельзя ничему научиться и нельзя узнать ничего полезного.\r\n\r\nБудет лучше, если они останутся в своем мире. Ведь если они придут в наш мир и не будут уничтожены – судьба наша незавидна...' FROM `page_text` WHERE `ID`=705 AND MD5(`Text`)='08425d70cac967269aa79083a6b58a8c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=705 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 710, 'ruRU', 'Я надеюсь, что ни один даларанский волшебник не станет разыскивать воргенов, даже из лучших побуждений. С этими тварями нельзя заключить союз, у них нельзя ничему научиться и нельзя узнать ничего полезного.\r\n\r\nБудет лучше, если они останутся в своем мире. Ведь если они придут в наш мир и не будут уничтожены – судьба наша незавидна...' FROM `page_text` WHERE `ID`=710 AND MD5(`Text`)='c0d5349d53ab535bb79914d968d7ba35' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=710 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 711, 'ruRU', 'Хелгрум, передай мою похвалу тому, кто приказал основать нашу базу в Каргате среди Бесплодных Земель. Это место идеально подходит для обучения наших войск. Тамошний суровый климат, злобные звери, воинственные аборигены и полное отсутствие помощи извне сделают так, что выйдут оттуда лишь лучшие из воинов и разведчиков.\r\n\r\nХорошая задумка. Превосходно.' FROM `page_text` WHERE `ID`=711 AND MD5(`Text`)='d71961b153ad5684c523aca8ade5d853' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=711 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 712, 'ruRU', 'Я опишу окружающие земли со слов разведчиков Каргата:\r\n\r\n-Бурые каменистые холмы и сухие равнины, малопригодные для жизни.\r\n-Палящее солнце и суровые ветры.\r\n-Озер или ручьев нет. Даже мелких луж нет. Чтобы найти воду, жители вынуждены копать глубокие и грязные колодцы или добывать скудную влагу из редких кактусов и прочих колючек.\r\n\r\nЕсли вкратце – жарко, жить трудно.' FROM `page_text` WHERE `ID`=712 AND MD5(`Text`)='95b3526f0fc7961e22faf160f565a940' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=712 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 713, 'ruRU', 'Бесплодные Земли кишат врагами. Огры рыщут по раскаленным пескам, нападая на неосторожных путников. Дворфы темной Стали, обитающие в казармах к востоку от Каргата, бьются со своими светлокожими сородичами у северного озера Лок Модан. Жестокие и примитивные создания, именуемые троггами, яростно сражаются за каждый клочок тени.\r\n\r\nА в Восточных Бесплодных землях, в Долине Летлор, живут драконы. Мы не знаем, много ли их там и насколько они велики, ведь разведчики, которые подбираются слишком близко к ним, назад уже не возвращаются.' FROM `page_text` WHERE `ID`=713 AND MD5(`Text`)='bd1b709bce78fd7304c09748d93303c6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=713 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 714, 'ruRU', 'Не стоит и говорить, что мы, служащие в Каргате, очень рады своему назначению. Мы все – как неприступная твердыня, ведь иначе нам не выжить.\r\n\r\nА ничего другого мне и не надо.\r\n\r\nНика Алый Шрам\r\nглава разведчиков, Каргат.' FROM `page_text` WHERE `ID`=714 AND MD5(`Text`)='bc4640ac2b04487714bec9b7f71a8fba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=714 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 731, 'ruRU', '<HTML>\r\n<BODY>\r\n<BR/>\r\n<BR/>\r\n<H1 align="center">\r\nЭлиза\r\n</H1>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<P align="center">\r\nВозлюбленная жена, пусть земля утолит твой голод.\r\n</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=731 AND MD5(`Text`)='570acd825b476bcacc4f219b3f73d723' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=731 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 751, 'ruRU', 'Вот параметры поршня:\r\n\r\nДлина: 32 ШУ\r\nДиаметр: 12 ШУ\r\nВес: от 23,5 ОМГ до 25,5 ОМГ\r\nПроводимость: 70 ПЗ\r\nПрочность на сдвиг: 98 или выше\r\nРейтинг перенаправления: "Суперпрочный" или выше\r\n\r\nНа случай, если ты забыл гномские сокращения:\r\nШУ = "Ширина Уса"\r\nОМГ = "Очень Мелкие Граммы"\r\nПЗ = "Пальцевые Завитки"' FROM `page_text` WHERE `ID`=751 AND MD5(`Text`)='d6df252bc2f34bdaf65bd331a3623165' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=751 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 752, 'ruRU', 'Ну что, друг, доставь-ка вот письмо Франгу в Долину Испытаний. Он обычно рядом с Логовом, гоняет там новобранцев, чтобы стали достойными воинами Орды.$B$BЕму нужны ловкие бойцы вроде тебя, чтобы показать оркам, как можно драться без грубой силы. Ты быстрее и ловчее многих там, но не очень-то бахвалься – орки оскорблений не любят. Друзья они хорошие, может, еще и научат тебя чему полезному.$B$B-Тар-сир' FROM `page_text` WHERE `ID`=752 AND MD5(`Text`)='812db6aac109ffae8536982988805126' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=752 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 771, 'ruRU', 'КОРМЛЕНИЕ И УХОД:\r\n\r\nМы хотим обеспечить вас всем необходимым для ухода за питомцем. Наши клиенты ожидают от "Шмыг Инк." именно такого уровня обслуживания, и мы с ними согласны!\r\n\r\nС этой целью мы разработали крепкие ящики для шмыгуносов, чтобы вы могли содержать питомца в безопасности и вне доступа света.\r\n\r\nДля вашего удобства в каждом ящике находится отделение для корма, пронизанное чарующим ароматом клубней синелиста (любимого лакомства шмыгуносов)!' FROM `page_text` WHERE `ID`=771 AND MD5(`Text`)='daedb72f1bde6e23dad71c2a6c8cec0a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=771 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 791, 'ruRU', 'Я опишу окружающие земли со слов разведчиков Каргата:\r\n\r\n-Бурые каменистые холмы и сухие равнины, малопригодные для жизни.\r\n-Палящее солнце и суровые ветры. \r\n-Озер или ручьев нет. Даже мелких луж нет. Чтобы найти воду, жители вынуждены копать глубокие и грязные колодцы или добывать скудную влагу из редких кактусов и прочих колючек.\r\n\r\nЕсли вкратце – жарко, жить трудно.' FROM `page_text` WHERE `ID`=791 AND MD5(`Text`)='356f8c6f5a470e499030724543aaf2c6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=791 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 792, 'ruRU', 'Бесплодные Земли кишат врагами. Огры рыщут по раскаленным пескам, нападая на неосторожных путников. Дворфы темной Стали, обитающие в казармах к востоку от Каргата, бьются со своими светлокожими сородичами у северного озера Лок Модан. Жестокие и примитивные создания, именуемые троггами, яростно сражаются за каждый клочок тени.\r\n\r\nА в Восточных Бесплодных землях, в Долине Летлор, живут драконы. Мы не знаем, много ли их там и насколько они велики, ведь разведчики, которые подбираются слишком близко к ним, назад уже не возвращаются.' FROM `page_text` WHERE `ID`=792 AND MD5(`Text`)='882832d8239a12eb8b86b41b4c920f79' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=792 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 793, 'ruRU', 'Не стоит и говорить, что мы, служащие в Каргате, очень рады своему назначению. Мы все – как неприступная твердыня, ведь иначе нам не выжить.\r\n\r\nА ничего другого мне и не надо.\r\n\r\nНика Алый Шрам\r\nглава разведчиков, Каргат.' FROM `page_text` WHERE `ID`=793 AND MD5(`Text`)='b3a896ef7e71028395ac4548794c0559' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=793 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 794, 'ruRU', 'Наш мир наполнен историей. Историей народов, новых и старых. Историей войн, тех, что давно угасли, и тех, что еще тлеют.\r\n\r\nИсторией богов юных, что приходят вниз с небес. Историей богов старых, что дремлют в земле.\r\n\r\nИменно о них мой рассказ, о Древних Богах. О тех, кто жил и бушевал по всему Азероту, когда мир был еще молод.' FROM `page_text` WHERE `ID`=794 AND MD5(`Text`)='c04b7ecc7ddc342e77c50457da7f34e6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=794 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 795, 'ruRU', 'Древние Боги – воля нашего мира. В каждом шторме слышен громовой хохот одного из них. В пламени каждого пожара виден блеск их глаз. Когда Древние Боги ходят, земля дрожит и трескается, а все, кто слабее их, кричат в отчаянии.\r\n\r\nИ одно лишь отчаяние им уготовано: как огонь не жалеет руки неразумного ребенка, так и Древние Боги не жалеют тех, кто ниже их. В лучшем случае мы для них пешки. В худшем случае – игрушки.' FROM `page_text` WHERE `ID`=795 AND MD5(`Text`)='59f501a0e29580df96c3a2758cefd3f5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=795 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 796, 'ruRU', 'Они были первыми хозяевами мира и правили железной рукой. И хотя теперь они закованы в цепи и спят, их слуги еще на свободе, а нам, жалким смертным, с мощью этих слуг не совладать.\r\n\r\nТе, кто пытался это сделать, изничтожены. Те же, кто знает свое место, кто склоняет колени в мольбе перед прислужниками Древних Богов, кто без раздумий жертвует им душу и разум... лишь они обретут их милость.' FROM `page_text` WHERE `ID`=796 AND MD5(`Text`)='492c4457445e17a835efd9fb1e7b900b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=796 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 797, 'ruRU', 'Аку\'май, Принцесса Глубин, служит Древним Богам. Она проживает в Непроглядной Пучине, озаряя тамошние подземелья своей древней мудростью. Аку\'май, пришедшая в Пучину по воле старейшин смертных, олицетворяет божественность. Она обладает лишь частичкой мощи и ярости Древних Богов, но и такая малость выше нашего разумения.\r\n\r\nПоэтому ей поклоняются. Поэтому ее боятся и любят.\r\n\r\n\r\n--Лоргалис' FROM `page_text` WHERE `ID`=797 AND MD5(`Text`)='6f39a2c6e287d04c1dc8225467dfb676' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=797 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 811, 'ruRU', 'План приведен в действие.\r\n\r\nСделай из этого некогда великого бастиона веры Геройской Стражи наш лагерь, и мы начнем перебрасывать туда подкрепление из Западного Края, как только узнаем от тебя, что лагерь должным образом подготовлен.\r\n\r\nЖители и солдаты Штормграда давно забыли об этом месте, и мы сможем успешно устраивать оттуда набеги.\r\n\r\nБратство Справедливости отобьет Штормград!\r\n\r\nЖду твоего ответа.' FROM `page_text` WHERE `ID`=811 AND MD5(`Text`)='466170c16ed6dcc566a07362030cb3ff' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=811 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 812, 'ruRU', 'Этих грязных троггов так просто обвести вокруг пальца! Их ненависть к нашему роду позволяет двигать ими, как пешками. Вообще непонятно, как они пошли хоть на какой-то союз, ведь мы для них самая страшная угроза... по крайней мере, пока\r\n\r\nКогда начнутся нападения, обе стороны ослабнут и не устоят перед нашим натиском. Захватите ферму к югу от озера Ложе Хелма и ждите дальнейших указаний.\r\n\r\nСтальгорн будет наш.' FROM `page_text` WHERE `ID`=812 AND MD5(`Text`)='db06894a7cc4502141c1cd225ccbac5b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=812 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 831, 'ruRU', 'На следующих страницах ты найдешь список материалов, необходимых для изготовления закаленного оружия. Удачи, воин.\r\n\r\n\r\n-Фьюрен Длиннобородый.' FROM `page_text` WHERE `ID`=831 AND MD5(`Text`)='3530a98140a54c9ceb9ff43e4cd9cab3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=831 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 851, 'ruRU', 'Опаленный паучий клык:\r\n\r\nОгневитовая жила, найденная в Пещере Тельгена, сожгла живших по соседству пауков.\r\n\r\nЯд из их жвал кипит и вступает в реакцию с самими их клыками, в результате чего получается очень стойкое вещество.' FROM `page_text` WHERE `ID`=851 AND MD5(`Text`)='12c56e236be4d829cf8c3eed1cbad1f5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=851 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 852, 'ruRU', 'Обугленные рога:\r\n\r\nКак и клыки пауков, обугленные рога химер, которые живут в Обугленной долине, что в Когтистых горах в Калимдоре, обладают весьма ценным свойством. \r\n\r\nРасплющенные и должным образом обработанные, они становятся чрезвычайно стойкими к физическому воздействию.' FROM `page_text` WHERE `ID`=852 AND MD5(`Text`)='7ca2e99695747bb0b7c85b91a1dd92e0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=852 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 853, 'ruRU', 'Гальванизированный рог:\r\n\r\nРедкостная твердость гальванизированного рога – основа всей детали доспеха, который я намереваюсь создать, так что его тоже надо добыть.\r\n\r\nЕго можно добыть у редких матриархов химер в Обугленной долине.' FROM `page_text` WHERE `ID`=853 AND MD5(`Text`)='e1894978a15c793914c836d59140dc6a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=853 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 854, 'ruRU', 'Сосуд флогистона:\r\n\r\nПоследняя стадия создания брони потребует чрезвычайно горячего кузнечного горна. Чтобы обеспечить необходимый уровень жара, мне понадобится сосуд флогистона.\r\n\r\nЕдинствено известный источник данной субстанции – легендарный иглогрив, Ругуг, и он не отдаст ее без боя. Ругуг обитает в глубинах Лабиринтов Иглошкурых, в южной части Степей.' FROM `page_text` WHERE `ID`=854 AND MD5(`Text`)='5bf0e68b75757d5b3213503f79938245' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=854 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 855, 'ruRU', 'Ниже ты найдешь список того, что мне понадобится для заклинания призыва великого Циклониана. Да сопутствует тебе удача.\r\n\r\n--Бар-ра Страж Ветра.' FROM `page_text` WHERE `ID`=855 AND MD5(`Text`)='3c95bb8c0ee0432ef687a2049eb1ba67' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=855 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 856, 'ruRU', 'Корень жизни:\r\n\r\nОн встречается в природе, а также может быть извлечен из тварей Сухой Лозы в Пылевых топях. Его сила будет необходима для привлечения жизненной эссенции Циклониана в этот мир.' FROM `page_text` WHERE `ID`=856 AND MD5(`Text`)='1220df2752fd4842098bcaa43362e2c7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=856 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 857, 'ruRU', 'Клык тролля из клана Кровавого Скальпа:\r\n\r\nКлыки троллей из клана Кровавого Скальпа из Тернистой долины обладают редким качеством. Все зло этого клана сконцентрировано в клыках, и если их истолочь в порошок, можно выпустить эту гибельную силу.' FROM `page_text` WHERE `ID`=857 AND MD5(`Text`)='981b9070748d55ae7dd5889d6f040149' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=857 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 858, 'ruRU', 'Субстанция изгнанников:\r\n\r\nЭта субстанция может быть получена путем слияния трех оберегов элементалей – изгнанников с Нагорий Арати. Собери с духов Громовой, Пылающий обереги и оберег Гребня, а затем помести по восемь штук каждой разновидности амулетов в мой котёл. \r\n\r\nИз смеси этих оберегов получится субстанция изгнанников.' FROM `page_text` WHERE `ID`=858 AND MD5(`Text`)='da9a76d6129dc4bd45d08ef310f3b61a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=858 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 871, 'ruRU', '$N,\r\nпрежде чем я продолжу, позволь мне поблагодарить тебя еще раз за то, что ты $gсделал:сделала; для меня и моей жены. Ты $gспас:спасла; ей жизнь, и за это я обязан тебе большим, чем смогу отплатить за сотни жизней. Она – все для меня. Если бы она умерла... ну, я не знаю, что бы я сделал.\r\n\r\nВот список того, что тебе нужно собрать, если ты хочешь, чтобы я сковал тебе оружие Света. Я записал их по порядку, от простого к сложному – надеюсь, так тебе будет проще.' FROM `page_text` WHERE `ID`=871 AND MD5(`Text`)='368304505b7e7ba2caae0aaa42f403bd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=871 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 872, 'ruRU', 'Немного хорошего белокаменного дуба – прежде чем шахты под Луноречьем в Западном Крае были захвачены, в них было полно такой древесины. Ее использовали для производства наиболее важных решеток и инструментов из-за ее жаростойкости и сопротивляемости нагрузкам.\r\n\r\nДуб завезли туда откуда-то из-за моря. Эта редкая древесина достаточно прочна, чтобы использовать ее при создании твоего оружия. Если хотя бы немного ее осталось в шахтах, то она найдется у гоблинских резчиков по дереву.' FROM `page_text` WHERE `ID`=872 AND MD5(`Text`)='107b71c730dc3078764811f580219295' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=872 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 873, 'ruRU', 'Очищенная руда – есть в Телcамаре дворф-кузнец по имени Балор Крепкорук, в свое время он учил меня. Он делает очень специфичный сплав, который, я думаю, идеально подошел бы для твоего оружия. По идее, партия сплава должна была прибыть еще во время моего пребывания в Стальгорне, но до сих пор ни слуху ни духу.\r\n\r\nНайди его и проверь, не готова ли моя партия товара. Если его нет на озере Лок Модан, то мне хотелось бы хотя бы узнать, что случилось с моим старым учителем.' FROM `page_text` WHERE `ID`=873 AND MD5(`Text`)='19ee3ce96722ebc4a8dd781969c8659e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=873 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 874, 'ruRU', 'Кузнечный молот – до прихода Чумы и предательства Артаса мы жили в деревне Погребальных Костров, в глубине прекрасного Серебряного бора. Теперь леса далеко не так красивы, как были раньше, и крепость, где меня обучали секретам литья стали, давно превратилась руины, и ее наводнили злобные твари.\r\n\r\nКогда я с женой убежал из этого места, что теперь называется крепостью Темного Клыка, мы оставили там некоторые дорогие для нас вещи.' FROM `page_text` WHERE `ID`=874 AND MD5(`Text`)='5809537432e8041656190e188d35cb87' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=874 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 875, 'ruRU', 'Среди них – кузнечный молот, что дал мне мой отец. В молодости я сомневался в этом, но он всегда говорил мне, что этот молот зачарован, и это последнее, что он сказал мне перед тем, как его погубила Плеть.\r\n\r\nПринеси мне этот молот, $N, чтобы я смог использовать его со всем своим пылом. Если он действительно зачарован, то он поможет нам обоим.\r\n\r\nЯ оставил его в стойлах в главном внутреннем дворе крепости. Если населяющие ее чудовища сами не занимаются кузнечным делом, то, я думаю, он все еще лежит там.' FROM `page_text` WHERE `ID`=875 AND MD5(`Text`)='a6d65e92c0b703c531e189458bd0aaaa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=875 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 876, 'ruRU', 'Самоцвет Кора – судя по тем историям, что я слышал, эти драгоценные камни используются некоторыми заклинателями для сосредоточения в них энергии, необходимой для их магии, что придает им еще больше смертоносной мощи. Ночной эльф, которому я однажды помог, Тандрис Ветропряд, может рассказать тебе более подробно, если ты скажешь ему, что ты от меня. Я считаю, что один из таких драгоценных камней, хранящих энергию, может быть использован для создания твоего оружия.\r\n\r\nКогда мы говорили с ним последний раз, Тандрис был в городе Аубердин, на Темных берегах, в глубине оскверненного леса, что окаймляет побережье в тени родины этого ночного эльфа.' FROM `page_text` WHERE `ID`=876 AND MD5(`Text`)='58925c039369c280ae55787716b5bcf5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=876 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 891, 'ruRU', 'Спиральные символы и пиктограммы, которыми испещрены страницы этого пособия, настолько запутанны, что их невозможно разобрать.' FROM `page_text` WHERE `ID`=891 AND MD5(`Text`)='249153f888100b3556cf6c5c74d431e1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=891 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 911, 'ruRU', 'Добудь нефрит. Он попадается в различных местах. Камень довольно редок, но если ты спросишь о нем у кузнеца или инженера, они, вероятно, смогут продать тебе несколько таких камней.' FROM `page_text` WHERE `ID`=911 AND MD5(`Text`)='993e060b58d50f86253344bea711bfab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=911 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 931, 'ruRU', '$N, ниже находится список предметов, необходимых для создания твоей брони:\r\n\r\nЗакопченные слитки железа кобольдов Утеса Ветрорезов, что обитают в Руднике Ветрорезов в Когтистых горах.\r\n\r\nТолченый азурит, который можно достать у хилсбрадских шахтеров.\r\n\r\nЖелезные слитки можно взять у горняков или добыть в месторождениях железа, если ты горняк.\r\n\r\nСосуд флогистона, который надо добыть у иглогрива по имени Ругуг из Лабиринтов Иглошкурых.' FROM `page_text` WHERE `ID`=931 AND MD5(`Text`)='31d354004627316afa21219f1af202ae' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=931 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 951, 'ruRU', '(Из-за пятен возможно прочесть лишь часть журнала.)\r\n\r\nУльдаман, день 3\r\n\r\nПоверить не могу, как я был глуп. Эти злобные дворфы Тенегорна провели меня, как простачка. Мои раны заживают медленно, я безусловно отравлен ядом. Я чувствую, как мои силы тают. Несмотря на это я должен двигаться вперед...\r\n\r\n...хуже того, ожерелье, что сделал для меня гном, треснуло! Три его самых больших драгоценных камня потеряны. Я должен найти их, без них ожерелье будет лишено всей своей силы..' FROM `page_text` WHERE `ID`=951 AND MD5(`Text`)='49e29c1d16e1d1f22049e51574b4d272' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=951 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 971, 'ruRU', 'Ульдаман, день 4\r\n\r\n...первым ключом к разгадке, что я обнаружил в глубинах Ульдамана, стал один из наиболее свирепых из виденных мною троггов, охранявший огромный сапфир, – один из тех, держу пари, что идеально бы подошел в ожерелье. Я слышал, как один из дворфов Тенегорна произнес имя этого чудища: Гримлок. И у этого свирепого Гримлока телохранители те еще, я скажу...' FROM `page_text` WHERE `ID`=971 AND MD5(`Text`)='0cb4010b6bbc2e299363872bfb8463ec' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=971 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 972, 'ruRU', 'Ульдаман, День 5-й\r\n\r\n...тот трогг, затем взял топаз с тела его убитого "брата", побежал в боковую пещеру у внешней стороны зала...\r\n\r\n...быстро положил топаз в большую, заметную вазу у задней стены комнаты...\r\n\r\n...надо же, дворфы! К тому же трое. Они забаррикадировались от троггов. Звать их на помощь было бы равносильно самоубийству, поскольку на меня бы тут же напали злобные трогги, а в моем ослабленном состоянии... Как только я узнаю, где третий камень, мне следует...' FROM `page_text` WHERE `ID`=972 AND MD5(`Text`)='862ba48688afb8328c5838795d2655f6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=972 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 973, 'ruRU', 'Ульдаман, День 6-й\r\n\r\n…страшно есть хочется. У меня кончились припасы, я полагаю, придется доедать заплесневелый хлеб. Голова проходящего мимо трогга на моих глазах превратилась в сочный стейк…' FROM `page_text` WHERE `ID`=973 AND MD5(`Text`)='3d0d685240f2776c69f83eff5903315d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=973 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 974, 'ruRU', 'Ульдаман, День 7\r\n\r\n...последний шанс исправить мои ошибки. Мне кажется, рубин находится за последней баррикадой дворфов, которую они построили против троггов. Несомненно, они сражаются за камень и другие артефакты, найденные здесь, и их постоянно атакуют. Похоже, эти презренные дворфы прячут его где-то у себя. Как бы то ни было, я должен выбрать, куда мне идти дальше. Возможно, бешеный рывок к выходу – самый лучший способ...' FROM `page_text` WHERE `ID`=974 AND MD5(`Text`)='d1b1b08a46277b90a2b74c36b23777d5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=974 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 991, 'ruRU', 'Мне нужен заряженный молнией жезл. Чтобы заполучить такой, собери 10 тотемных палочек у троллей из племени Сухокожих в Нагорьях Арати. Принеси палочки к Внешнему Кругу, кругу из камней на этом самом нагорье. Положи палочки на центральный камень круга и подожди, когда в них ударит молния. Когда это случится, заряженный молнией жезл будет готов.' FROM `page_text` WHERE `ID`=991 AND MD5(`Text`)='8972c8c6fce3f6d925ede90b8fe60b55' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=991 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 992, 'ruRU', 'Предъявитель данного свидетельства имеет права на уважение и почтение, которого заслуживает любой первостатейный жулик и вор.' FROM `page_text` WHERE `ID`=992 AND MD5(`Text`)='6b384f5a80e6749b51781ea93927c16e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=992 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1011, 'ruRU', 'Я нашел способ проникнуть в Чертог Хаз\'Мула!\r\n\r\nВозьми медальон Вогникив из моего сундука.\r\n\r\nПобеди трогга Ревлоша в зале перед комнатой с картой и забери у него стержень Хыннещихоп.\r\n\r\nСоедини медальон и стержень – и получишь посох Древнейшей Истории.\r\n\r\nИспользуй посох в комнате с картой, чтобы открыть двери, ведущие в чертог Хаз\'Мула.\r\n\r\nСделай это, и комната будет принадлежать нам!\r\n-Бейлог' FROM `page_text` WHERE `ID`=1011 AND MD5(`Text`)='7518a76a924f9fe81d1363194c4ede93' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1011 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1051, 'ruRU', 'Стражники этой башни, похоже, ослаблены и не могут противостоять моим атакам. При разведке с задней стороны башни патрулирующая ее стражница заметила меня и напала. Мне удалось легко ее зарезать, своевременно уклонившись и затем ударив ее в спину.\r\n\r\nНа шум пришел ее напарник. Стражник подошел прямо к тем кустам, куда мне пришлось оттащить труп и обыскать его. Мне пришлось подкрадываться к нему медленно и осторожно, чтобы меня не обнаружили.' FROM `page_text` WHERE `ID`=1051 AND MD5(`Text`)='3aba99c3dbfeede28e5e81a6d02f0601' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1051 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1052, 'ruRU', 'Когда представилась возможность, я всадила нож ему в спину! Его легкие не выдержали силы удара, и его тело упало на землю с глухим звуком.\r\n\r\nЭто было такое быстрое и молниеносное нападение, что бедный глупец даже не успел закричать от боли. Странно, но когда я вынула нож из его спины, из раны хлынул зловонный запах.' FROM `page_text` WHERE `ID`=1052 AND MD5(`Text`)='58b14b64951359428a0d5a0ed68f27fc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1052 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1053, 'ruRU', 'Похоже, то, что прятал в своем сундуке Клейвен, оно оказало неблагоприятный эффект на обитателей башни. Я подозреваю, что и другие стражники столь же слабы, и, возможно, даже сам Клейвен пал жертвой этих нежелательных побочных эффектов.\r\n\r\nАгент Эмбер Кеарнен\r\nШРУ:7 Полевой оперативник, Отд. 8' FROM `page_text` WHERE `ID`=1053 AND MD5(`Text`)='9ffd1cf1e29daf633a3a16382b0cc5fd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1053 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1071, 'ruRU', 'Командир!\r\n\r\nВозвращайтесь в Оргриммар. Ваши войска несостоятельны. Следует пересмотреть наше положение на основании поступившей новой информации.\r\n\r\nКрупные силы Приверженцев Тени и огров. Демоны охраняют Темный портал.\r\n\r\n-Тралл, Вождь Орды' FROM `page_text` WHERE `ID`=1071 AND MD5(`Text`)='12a697f616a16aa353332260b066910f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1071 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1091, 'ruRU', 'Молот Зул\'Фаррака\r\n\r\nЧтобы создать молот Зул\'Фаррака, следует отправиться к алтарю Зула и заполучить священный молот, хранящийся у тролля – хранителя.\r\n\r\nДалее следует принести молот к алтарю в городе троллей Джинта\'Алор.\r\n\r\nЕсли ударить молотом по алтарю, алтарь наполнит его силой и превратит его в молот Зул\'Фаррака.' FROM `page_text` WHERE `ID`=1091 AND MD5(`Text`)='2bed31c3ef54e7fdbedeb851b065da8a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1091 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1131, 'ruRU', 'СУПЕРВАЖНАЯ КАРТА ДАННЫХ С ТРОЙНЫМ КОДОМ\r\n\r\n01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111' FROM `page_text` WHERE `ID`=1131 AND MD5(`Text`)='e8aab7cf4e805991c52e279c5a2621db' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1131 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1151, 'ruRU', 'Торговая компания *неразборчиво*. Похоже, эти глупцы сорвали всю свою операцию в попытке стабилизировать зелье.\r\n\r\n*несколько страниц вырвано*' FROM `page_text` WHERE `ID`=1151 AND MD5(`Text`)='7510b4f92280087db972abafdcf2c95f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1151 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1152, 'ruRU', 'Этот побочный эффект невероятно смертоносен. Только представь, что *текст невозможно прочесть* Ха-ха-ха!' FROM `page_text` WHERE `ID`=1152 AND MD5(`Text`)='b95d2edd8af150657994ea9885e8ad6a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1152 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1153, 'ruRU', 'Я схожу с ума? Сегодня я оторвал голову одному из самых доверенных стражников под предлогом того, что я хочу получше рассмотреть его душу. И когда я смотрел, как воздух покидает его дыхательные пути, я вспомнил, что несколько дней не ел!' FROM `page_text` WHERE `ID`=1153 AND MD5(`Text`)='eb73cef8cb05c94247a0398c1905cd2c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1153 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1154, 'ruRU', 'Матиас Шоу послал какого-то рассыльного убить меня. *текст неразборчив*\r\n\r\nТеперь он бродит снаружи. Тупой, безжизненный чурбан.\r\n\r\nХа-ха-ха!' FROM `page_text` WHERE `ID`=1154 AND MD5(`Text`)='800a718b8b078adb3e8f9661686f0896' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1154 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1155, 'ruRU', 'ван Клиф...*неразборчиво*\r\n\r\nВызывает МЕНЯ? ДА КЕМ ОН СЕБЯ ВОЗОМНИЛ??? Я – Клавьен Мортвейк! И чтобы какое-то насекомое еще мне указывало?!\r\n\r\n*остальные страницы книги утеряны*' FROM `page_text` WHERE `ID`=1155 AND MD5(`Text`)='32121de67fa851c905c07a7e89f1e26c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1155 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1156, 'ruRU', 'Гурдл,\r\n\r\nя с нетерпением ожидаю, когда будет готово твое новое изобретение. Я жду не дождусь, когда смогу с его помощью записывать результаты моих исследований.\r\n\r\nПожалуйста, доверь его моему посланнику.\r\n\r\n\r\nС сердечным приветом,\r\n\r\nДарин Добрый Ветер' FROM `page_text` WHERE `ID`=1156 AND MD5(`Text`)='c3eb1bf48a27891aec85fca95821c9b0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1156 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1191, 'ruRU', 'ЖИЗНЕННО ВАЖНЫЕ ДАННЫЕ! УРОВЕНЬ СЕКРЕТНОСТИ 5122!\r\n\r\n01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101' FROM `page_text` WHERE `ID`=1191 AND MD5(`Text`)='c8ceb65309742d0538da569b205d5b9b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1191 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1192, 'ruRU', 'Не дай этой информации попасть в руки врага!\r\n\r\n01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010' FROM `page_text` WHERE `ID`=1192 AND MD5(`Text`)='565a2c6897ad549f456f1757036b6eda' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1192 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1193, 'ruRU', 'Уровень секретности 10^10000. Суперсекретные данные!\r\n\r\n01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001' FROM `page_text` WHERE `ID`=1193 AND MD5(`Text`)='dfdcdd1c50563d971dde3b0da477065b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1193 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1194, 'ruRU', 'Уровень секретности этой информации СТОЛЬ высок, что понадобится изобретение нового числа, чтобы описать его!' FROM `page_text` WHERE `ID`=1194 AND MD5(`Text`)='4cb1a2a27c561347ed1c1c5f75b050a6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1194 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1211, 'ruRU', 'КАК ВЫГУЛИВАТЬ ШМЫГУНОСА\r\n\r\nШмыгунос любит укромные, темные места. И он очень застенчив.\r\n\r\nЕсли вы хотите отправиться на прогулку с вашим шмыгуносом, то должны пойти в такое место, где бы он чувствовал себя как дома. И вы ДОЛЖНЫ отвести его туда, где бы он чувствовал запах его любимой еды – корней синелиста!\r\n\r\nБлижайшее такое место – это "котлован" в Лабиринтах Иглошкурых. Если вы откроете клетку неподалеку от нее и ваш шмыгунос почует запах клубней, то он решится отправиться вслед за вами.' FROM `page_text` WHERE `ID`=1211 AND MD5(`Text`)='dc474f513cc85a1d3cf629caeeab8fc9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1211 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1212, 'ruRU', 'ПАЛОЧКА-ПОГОНЯЛОЧКА ДЛЯ ШМЫГУНОСОВ(tm)\r\n\r\nШмыгунос – поразительное животное. Мало того что к нему может привязаться и полюбить его даже самый злобный долгоног, он может почуять запах корней синелиста за 50 метров!\r\n\r\nЕсли вы пожелаете отправить вашего шмыгуноса на поиски корней, то вам понадобится ваша (продается отдельно) запатентованная палочка-погонялочка для шмыгуносов.\r\n\r\nИнструкция по применению на следующей странице.' FROM `page_text` WHERE `ID`=1212 AND MD5(`Text`)='2a0e013a7258d20b55e3f4cd9b3e50f7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1212 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1213, 'ruRU', 'Все наши шмыгуносы хорошо обучены, и вам достаточно легкого взмаха вашей палочки-погонялочки, чтобы перевести ближайшего шмыгуноса в режим поиска. После этого шмыгунос начнет принюхиваться в поисках корней, и если он почует один из них, то двинется по направлению к нему и начнет его выкапывать.\r\n\r\nЕсли вы еще раз взмахнете палочкой-погонялочкой в сторону шмыгуноса, ищущего корни, он прекратит свои поиски и радостно вернется к вам.\r\n\r\nМы уверяем вас, что вы найдете наших шмыгуносов хорошо обученным, полезным и невероятно подходящим приобретением для вашей команды!' FROM `page_text` WHERE `ID`=1213 AND MD5(`Text`)='3dfec88182bc91a6a5aab7ac94b35108' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1213 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1214, 'ruRU', 'Нам, "Шмыг Инк.", неприятно говорить о том, что мы получили несколько жалоб на некоторых жадных охотников за корнями, мало заботящихся о своих милых питомцах и отправляющих их в темные, опасные места на поиски корней.\r\n\r\nМы не станем мириться с такими безответственными хозяевами, но, желая удовлетворить пожелания клиента, мы выдаем гарантию на каждого проданного шмыгуноса, позволяющую новым владельцам вернуть покупку или получить нового зверька взамен потерянного.\r\n\r\nУдачной охоты!' FROM `page_text` WHERE `ID`=1214 AND MD5(`Text`)='a7709f7bc584597e3fe874eda22e9b42' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1214 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1251, 'ruRU', 'В эти месяцы у меня было достаточно времени для раздумий о моих старых верованиях и фанатизме. Альянс? Орда? Добро? Зло? Значение этих слов, когда-то таких простых, теперь расплывалось перед моим взором, устремленным на бескрайнее море.\r\n\r\nТеперь я знаю, в чем причина. Эти бананы следят за мной. Сидят высоко и недоброжелательно следят за мной своими глазками. И когда последний раз я пытался съесть один из них, он чуть не задушил меня! Я почти слышал его крик, когда я размазал его, наполовину откушенного, по камням.\r\n\r\nЭто – война, и я ее выиграю.' FROM `page_text` WHERE `ID`=1251 AND MD5(`Text`)='3984c869a55703f52f7f91cf1d59324f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1251 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1271, 'ruRU', 'Инженерные дисцпилины\r\n\r\nНесмотря на то что вопрос о том, какая раса первой в Азероте додумалась до инженерного дела, является спорным, бесспорен тот факт, что лишь две расы преуспели в ней в настоящее время: гномы и гоблины. Их преданность инженерному делу не только вдохновила их на фантастические изобретения в смутный магический Век Изобретений, но и, как результат, породила интенсивную конкуренцию между расами. Нигде она столь очевидно не проявлялась, как на путях развития их науки.' FROM `page_text` WHERE `ID`=1271 AND MD5(`Text`)='19b3b4e35c1414ba0b71a5891d7129fc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1271 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1272, 'ruRU', 'Гномское инженерное дело\r\n\r\nРаса гномов достигла несравненных успехов в разработке предметов, манипулирующих и управляющих окружающим их миром. Несмотря на то что они обычно стремятся к совершенствованию взрывчатых веществ и оружия, их инженерное дело также сосредоточено на предметах, которые, буквально говоря, делают жизнь проще и удобнее. Эта наука о теоретических возможностях переделки реальности в соответствии с технологией гномских ноу-хау. Некоторые возможности, как бы то ни было, никогда не получится полностью реализовать.' FROM `page_text` WHERE `ID`=1272 AND MD5(`Text`)='61cf65d365f018eb820c8976f554741e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1272 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1273, 'ruRU', 'Гоблинское инженерное дело\r\n\r\nБудучи расой, нейтрально относящейся практически ко всем конфликтам, гоблины сумели сделать науку доходным делом. Они нашли практическое применение инженерному делу, столь очевидное в их великолепно разработанной взрывчатке, огнестрельном оружии и машинах. Гоблинское инженерное дело не слишком заинтересована в теории, их изобретения обычно не имеют тенденции не работать, скорее уж работают слишком хорошо. Они точно не для слабонервных.' FROM `page_text` WHERE `ID`=1273 AND MD5(`Text`)='467dbb8a4d32437b3374fe95dfeff9d2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1273 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1274, 'ruRU', 'Изучение инженерного дела\r\n\r\nГномы и гоблины столь яростно защищают свои знания друг от друга, что невозможно получить доступ к обоим направлениям этой науки одновременно. Каждая раса, независимо от ее политических союзов, дает доступ к знаниям лишь тем, кто согласен отказаться от стремления заняться другим направлением науки. Если ученик выбирает гномское инженерное дело, например, то ни одного урока гоблинского инженерного дела он никогда не получит.' FROM `page_text` WHERE `ID`=1274 AND MD5(`Text`)='2d712e5dbc78b8385a55ba86ace4688f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1274 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1275, 'ruRU', 'Необратимость выбора\r\n\r\nПредыдущий раздел осветил весьма важные моменты о двух направлениях инженерного дела, которые надо усвоить, чтобы начать обучение. Решение заняться тем или иным направлением науки означает, что схемы противополжного направления никогда не будут доступны для изучения. Хотя такая окончательность выбора может отпугнуть непрофессионала, опытный инженер понимает, что гномы и гоблины оберегают свои секреты с великим пылом и что знание о чем-то – все же лучше, чем никого знания.' FROM `page_text` WHERE `ID`=1275 AND MD5(`Text`)='e693ed8706f0855e5e61ddf1d93dbc1a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1275 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1276, 'ruRU', 'Цитаты\r\n\r\n"Ты хочешь узнать о гоблинском инженерном деле? Спроси об этом одного из их лучших и талантливейших инженеров – мне кажется, его имя Набби Толстопал. Хочешь знать, почему его так зовут? Таково гоблинское инженерное дело."\r\n-- Ринго Трагедикс, гномский инженер.\r\n\r\n"Говори, что хочешь, о нас, гоблинах, но я скажу тебе вот что: У НАС ЕСТЬ ВЗРЫВЧАТКА!"\r\n-- Блямс Динамиттер, гоблинский бомбардир' FROM `page_text` WHERE `ID`=1276 AND MD5(`Text`)='f99c6d4f2518930ca3d06d1e7b2594fd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1276 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1277, 'ruRU', 'Еще цитаты!\r\n\r\n"Знаешь это чувство, когда ты заканчиваешь делать что-то и включаешь это первый раз, чтобы испытать его силу и насладиться своим изобретением, когда оно начинает оживать? А вот гномы не знают".\r\n-- Никс Шепружин, главный гоблинский инженер из Прибамбасска\r\n\r\n"Инженерное дело – это когда берется фантазия и делается еще более фантастичной!"\r\n-- Ровис Мак-Хрясьшатун, гномский изобретатель.' FROM `page_text` WHERE `ID`=1277 AND MD5(`Text`)='db3a3aedd66831c624f09ffbf47eac58' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1277 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1291, 'ruRU', 'Сотворение зверя:\r\n\r\nЧтобы создать ищейку Скверны, необходимо использовать выданную сферу Скверны.\r\n\r\nПримечания:\r\n\r\nСотворенная ищейка Скверны сможет существовать в этом мире лишь тридцать минут.\r\n\r\nСотворенная ищейка Скверны будет помогать лишь в поиске отложений азшарита.\r\n\r\nСотворенная ищейка Скверны НЕ БУДЕТ делать следующее: фокусы, нападать на кого-либо, помогать в чем-либо, танцевать, уничтожать магических существ.\r\n\r\nПожалуйста, переверните страницу...' FROM `page_text` WHERE `ID`=1291 AND MD5(`Text`)='a263a9760d7948234b116a334823ecbe' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1291 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1292, 'ruRU', 'Контроль над зверем:\r\n\r\nИщейка Скверны понимает только звериные эмоции. Чтобы заставить вашу ищейку Скверны искать залежи азшарита, необходимо на нее бешено зарычать! (Нацельтесь на ищейку Скверны и изобразите /бешенство).\r\n\r\nКогда ищейка Скверны обнаружит залежь, она побежит к ней, не обращая внимания на окружающих существ. Хотя вам не нужно защищать ищейку Скверны, возможно, вы захотите быть рядом с ней, чтобы не потерять ее.' FROM `page_text` WHERE `ID`=1292 AND MD5(`Text`)='b0ff2f250dd5ee6bab8cc47980f06c00' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1292 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1293, 'ruRU', 'Отпустить зверя:\r\n\r\nСпустя 30 минут зверь вернется к себе домой в Пустоту.\r\n\r\nПримечание:\r\n\r\nВ этом своем стремлении зверь МОЖЕТ броситься со скалы или упасть с горы. Не горюйте о потере ищейки Скверны, лучше вызовите другую.' FROM `page_text` WHERE `ID`=1293 AND MD5(`Text`)='5871f87d37d10aaf4260428e70a87316' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1293 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1313, 'ruRU', 'О чем я думал?\r\n\r\nВозможно, более лучшим был бы вопрос: о чем я думаю, когда пишу письмо, находясь в брюхе великана?\r\n\r\nОба вопроса хороши, и ни на один у меня нет сейчас ответа…\r\n\r\nСледует признать, что моя миссия была не миссией доброй воли. Я пришел сюда в поисках азшарита, уникального кристалла из южной Азшары. О, я был бы так богат!\r\n\r\nБа! А теперь посмотрите на меня...' FROM `page_text` WHERE `ID`=1313 AND MD5(`Text`)='45dc8080852403f2686e2abc2f853e45' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1313 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1314, 'ruRU', 'Если какой-нибудь представитель разумной формы жизни найдет это письмо, пусть он спросит себя:"Какого черта они возятся с этими злобными десятиметровыми великанами?"\r\n\r\n-Муук' FROM `page_text` WHERE `ID`=1314 AND MD5(`Text`)='eb45933176efa2c5496b64ce3492b1ef' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1314 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1392, 'ruRU', 'Брат Нилз, мой виноград спасен! $N, предъявитель сего письма, $gспас:спасла; мой наводненный головорезами виноградник и $gсобрал:собрала; весь виноград, что я не успела собрать. Несмотря на то что бандиты все еще бродят у реки, практически весь мой урожай был спасен.\r\n\r\nТы можешь добавить к своим запасам полные корзины винограда.\r\n\r\nДа защитит нас Свет,\r\n-Милли Осворт' FROM `page_text` WHERE `ID`=1392 AND MD5(`Text`)='0568d8ff4aaba3b48a5162f69c58762f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1392 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1431, 'ruRU', 'Ворфалк Железнолоб\r\n\r\nВорфалк работает на складе "Угрюмого обжоры" и глубоко предан темным хранителям.\r\n\r\nДа укрепится его дух.\r\n' FROM `page_text` WHERE `ID`=1431 AND MD5(`Text`)='76b73ed5a013eed59ca2b774b65bcd38' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1431 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1432, 'ruRU', 'Бетек Штормоскал\r\n\r\nСтранствия Бетека завели его в глубины Черной горы. Секреты гор манили его.\r\n\r\nДа укрепится его дух.' FROM `page_text` WHERE `ID`=1432 AND MD5(`Text`)='5dcbf25b3c49788f2db13d066c3fc05e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1432 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1434, 'ruRU', 'Зимрел Чернозуб\r\n\r\nКогда безумие темного ключа овладевает Зимрелом, лишь крики умирающих могут успокоить его.\r\n\r\nЗа свою жертву он всегда будет иметь место над ареной. Да смягчит гнев его сердца наш кровавый спорт.' FROM `page_text` WHERE `ID`=1434 AND MD5(`Text`)='38f7c5795de073208c8a3260705504c9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1434 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1436, 'ruRU', 'Пелвер Вмятина\r\n\r\nТемный хранитель Пелвер – наш наиболее почетный последователь. Он хранит ключ гораздо дольше других, и это стоило ему многого. Когда его ноша взывает к нему, он содержится под стражей в Жилом квартале.\r\n\r\nМы склоняемся пред его жертвой, и он останется в наших сердцах на многие годы... после того как его поглотит тьма.' FROM `page_text` WHERE `ID`=1436 AND MD5(`Text`)='9acc5a3e27b18d2f3d0a01f5f8d67e1a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1436 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1471, 'ruRU', 'Соломон!\r\n\r\nПредъявителю данного приказа дарован официальный статус действующего представителя Штормграда. Вы можете воспользоваться <его/ее> помощью в поисках доказательства участия черных драконов в делах орков Черной Горы. В случае если подобное доказательство будет обнаружено, данный представитель должен будет вернуться с вышеуказанным доказательством ко мне в Штормград, и тогда я издам приказ об отправке необходимой военной помощи в Приозерье.\r\n\r\nС наилучшими пожеланиями,\r\n\r\n\r\n\r\nВерховный лорд Болвар Фордрагон' FROM `page_text` WHERE `ID`=1471 AND MD5(`Text`)='3a976c83b2d3c0f23eb515abc7b1d16f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1471 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1491, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nПИЛОНЫ: ИНСТРУКЦИЯ ПО ЭКСПЛУАТАЦИИ\r\n</H1>\r\n<BR/>\r\n<P align="center"> "Руководство по сбору и использованию кристаллов силы Кратера Ун\'Горо" </P>\r\n<BR/>\r\n<BR/>\r\n<P align="left">Глава 1: Северный пилон </P>\r\n<BR/>\r\n<P align="left">Глава 2: Восточный пилон </P>\r\n<BR/>\r\n<P align="left">Глава 3: Западный пилон </P>\r\n<BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1491 AND MD5(`Text`)='6fa98cc423baed1995c58ef9b062d21c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1491 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1511, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nГлава 1: СЕВЕРНЫЙ ПИЛОН\r\n</H1>\r\n<BR/>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\11482_crystals_mini_north" align="left"/>\r\n<P align="right">Северный<BR/>\r\nпилон принимает<BR/>\r\nжелтые, красные<BR/>\r\nи зеленые<BR/>\r\nкристаллы.</P>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<P align="left">Пилон фокусирует энергию, которая возникает при использовании желтых кристаллов в качестве основного источника энергии.</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1511 AND MD5(`Text`)='492e3cae21d22a9faff2584b114a6ad6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1511 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1512, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nСеверная комбинация кристаллов\r\n</H1>\r\n<BR/>\r\n<P align="left">Есть два возможных эффекта: наносящий урон и нейтрализующий его. </P>\r\n<BR/>\r\n<P align="left">КРИСТАЛЬНЫЙ ЗАРЯД: требует желтых и красных кристаллов.<BR/>Провоцирует сильный взрыв.</P>\r\n<BR/>\r\n<P align="left"> КРИСТАЛЬНОЕ ВОССТАНОВЛЕНИЕ: требует желтых и зеленых кристаллов. <BR/>Наделяет вас целительной аурой.\r\n</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1512 AND MD5(`Text`)='f8aa075dbd9bbd6ec3f77a7afdd75666' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1512 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1513, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nДИАГРАММА СЕВЕРНОГО ПИЛОНА\r\n</H1>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\11482_crystals_north"/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1513 AND MD5(`Text`)='0a9c5de773e168b104743f1adb999126' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1513 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1514, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nГлава 2: ВОСТОЧНЫЙ ПИЛОН\r\n</H1>\r\n<BR/>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\11482_crystals_mini_east" align="left"/>\r\n<P align="right">Восточный<BR/>\r\nпилон принимает<BR/>\r\nсиние, желтые<BR/>\r\nи зеленые<BR/>\r\nкристаллы.</P>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<P align="left">Пилон фокусирует энергию, которая может быть создана при использовании синих кристаллов в качестве основного источника энергии.</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1514 AND MD5(`Text`)='75d70de31b3678d81a62d1f3e748f660' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1514 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1515, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nВосточная комбинация кристаллов\r\n</H1>\r\n<BR/>\r\n<P align="left">Существует два возможных эффекта: один оказывает положительный эффект на дух, второй создает щит, наносящий урон.</P>\r\n<BR/>\r\n<P align="left">КРИСТАЛЬНАЯ СИЛА: требуются синие и зеленые кристаллы.<BR/>Повышает вашу характеристику "дух".</P>\r\n<BR/>\r\n<P align="left">КРИСТАЛЬНЫЙ ШИП: требует синих и желтых кристаллов.<BR/>Создает щит, который будет наносить урон атакующим.\r\n</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1515 AND MD5(`Text`)='b0ae3f1aaf211aaca79c62d99ad42b8a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1515 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1516, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nДИАГРАММА ВОСТОЧНОГО ПИЛОНА\r\n</H1>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\11482_crystals_east"/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1516 AND MD5(`Text`)='7dabfb36bd6cec064a9bf12b5b8acd52' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1516 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1531, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nГлава 3: ЗАПАДНЫЙ ПИЛОН\r\n</H1>\r\n<BR/>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\11482_crystals_mini_east" align="left"/>\r\n<P align="right">Западный<BR/>\r\nпилон принимает<BR/>\r\nкрасные, зеленые<BR/>\r\nи синие<BR/>\r\nкристаллы.</P>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<P align="left">Пилон фокусирует энергию, которая создается при использовании красных кристаллов в качестве основного источника энергии.</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1531 AND MD5(`Text`)='99852274a57d8fe3ad2cfe15b82038b0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1531 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1532, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nЗападные комбинации кристаллов\r\n</H1>\r\n<BR/>\r\n<P align="left">Существует два возможных эффекта: один повышает вашу защиту от урона, второй ослабляет защиту противника.</P>\r\n<BR/>\r\n<P align="left">КРИСТАЛЛ-ХРАНИТЕЛЬ: Требуются красные и зеленые кристаллы.<BR/>Повышает вашу характеристику "броня".</P>\r\n<BR/>\r\n<P align="left">КРИСТАЛЛ-ГУБИТЕЛЬ: Требуются синие и красные кристаллы.<BR/>Может снизить характеристику "броня" выбранной цели.\r\n</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1532 AND MD5(`Text`)='2f967f1d56413e9d8534cb15b50d78cb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1532 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1533, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nДИАГРАММА ЗАПАДНОГО ПИЛОНА\r\n</H1>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\11482_crystals_west"/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=1533 AND MD5(`Text`)='b0d71958dca67b3f7b8f892a972698da' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1533 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1551, 'ruRU', 'Привет и поклон вам, искатели приключений!\r\n\r\nМне, Кринкелю Сталлеру, необходима помощь желающих рискнуть своей жизнью ради выполнения некоторых моих трудных поручений. Поскольку у меня множество обязанностей и я загружен взвалившейся на меня работой, я уверяю, что любому, достаточно смелому, чтобы собрать необходимые предметы из данного списка и принести их мне, будет выплачена солидная премия.\r\n\r\nСписок включает в себя следующие страницы...' FROM `page_text` WHERE `ID`=1551 AND MD5(`Text`)='018846f46a71f9a5220766c92725e77f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1551 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1552, 'ruRU', 'Прочная хрустальная нога- \r\n\r\nХрустальные пауки из Выжженной теснины сделаны из невероятного кристаллоподобного материала. Из их ног, в том случае если они не повреждены при убийстве их владельцев, получаются замечательные трубки, необходимые в экспериментах моих компаньонов-инженеров.\r\n\r\nМне понадобится некоторое их количество, чтобы провести тестирование. У пауков есть восемь ног, так что достать их будет не проблемой для крепкого воина или опытного мага.' FROM `page_text` WHERE `ID`=1552 AND MD5(`Text`)='44851d130014349a631407595d269713' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1552 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1553, 'ruRU', 'Задержанная посылка -\r\n\r\nЯ нанял кое-кого с репутацией надежного пилота, чтобы доставить груз из Терамора. Я ошибался. Несмотря на то что пилот выжил и смог рассказать мне эту историю, он бросил и свой дирижабль и весь мой груз, чтобы спасти свою шею.\r\n\r\nВ общем, мне нужно вернуть мой товар. Исходя из того, что рассказал мне Бизиль, он потерпел крушение к западу от берега Пылевых топей. Он начал падать сразу после того, как пересек холмы, окаймляющие море.\r\n\r\nХм-м-м... он никогда не рассказывал мне, что послужило причиной аварии...' FROM `page_text` WHERE `ID`=1553 AND MD5(`Text`)='504afc2b278a0b4a551871f2a95a59c6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1553 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1554, 'ruRU', 'Сбалансированная шпага Сталлера- \r\n\r\nИ последнее: я хочу вернуть одну из моих лучших кузнечных работ. Эта шпага – невероятное оружие, и я подарил его тому, кого я считал весьма благородным и великим воином. В общем, его побил мурлок по имени... как его там, Джаркай? Как-то так.\r\n\r\nОн подвергся атаке этого чудища во время своего путешествия по берегу Болота Печали. Он проиграл сражение и, видимо, обратился в бегство, оставив оружие в лапах мурлока.' FROM `page_text` WHERE `ID`=1554 AND MD5(`Text`)='267b1f7bcd86b58d2f0a0dc16448b53f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1554 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1556, 'ruRU', 'Найдите их для меня и принесите в Прибамбасск вместе с этим гроссбухом, и я награжу вас.' FROM `page_text` WHERE `ID`=1556 AND MD5(`Text`)='64dbab458b5ee6aabcd97e4192112900' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1556 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1591, 'ruRU', 'Эта наковальня является собственностью Джордана Стивелла – Просьба НЕ трогать!\r\n\r\n- Джордан' FROM `page_text` WHERE `ID`=1591 AND MD5(`Text`)='b15286178fdfe06cbb95f58718209649' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1591 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1611, 'ruRU', 'Страницы покрыты древними эльфийскими рунами.\r\n\r\nЭти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня.\r\n\r\nДа не получат наши враги никогда доступ к этим письменам. \r\n\r\nДа доживу я до тех пор, когда бледный свет луны вновь осветит Кель\'Талас.\r\n\r\nДа умру я во имя Кель\'таса.\r\n\r\nДа буду убивать я во славу Иллидана.\r\n\r\n-Мастер Кариэль Винтхалус' FROM `page_text` WHERE `ID`=1611 AND MD5(`Text`)='182ae470bfa7c5d31ec818ad7b2abbf9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1611 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1631, 'ruRU', '*Страницы покрыты древними эльфийскими рунами.*\r\n\r\nЭти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня.\r\n\r\nДа не получат наши враги никогда доступ к этим письменам.\r\n\r\nДа доживу я до тех пор, когда бледный свет луны вновь осветит Кель\'Талас.\r\n\r\nДа умру я во имя Кель\'таса.\r\n\r\nДа буду убивать я во славу Иллидана.\r\n\r\n-Мастер Кариэль Винтхалус' FROM `page_text` WHERE `ID`=1631 AND MD5(`Text`)='20612f4e63b7a2c0e0f028c37088745a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1631 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1632, 'ruRU', 'Страницы покрыты древними эльфийскими рунами.\r\n\r\nЭти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня.\r\n\r\nДа не получат наши враги никогда доступ к этим письменам. \r\n\r\nДа доживу я до тех пор, когда бледный свет луны вновь осветит Кель\'Талас.\r\n\r\nДа умру я во имя Кель\'таса.\r\n\r\nДа буду убивать я во славу Иллидана.\r\n\r\n-Мастер Кариэль Винтхалус' FROM `page_text` WHERE `ID`=1632 AND MD5(`Text`)='7ebb28afc0462130c18fbf536f886b83' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1632 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1633, 'ruRU', 'Страницы покрыты древними эльфийскими рунами.\r\n\r\nЭти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня.\r\n\r\nДа не получат наши враги никогда доступ к этим письменам. \r\n\r\nДа доживу я до тех пор, когда бледный свет луны вновь осветит Кель\'Талас.\r\n\r\nДа умру я во имя Кель\'таса.\r\n\r\nДа буду убивать я во славу Иллидана.\r\n\r\n-Мастер Кариэль Винтхалус' FROM `page_text` WHERE `ID`=1633 AND MD5(`Text`)='089afc7664e86f7e350d4a097d0b5111' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1633 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1634, 'ruRU', 'Страницы покрыты древними эльфийскими рунами.\r\n\r\nЭти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня.\r\n\r\nДа не получат наши враги никогда доступ к этим письменам.\r\n\r\nДа доживу я до тех пор, когда бледный свет луны вновь осветит Кель\'Талас.\r\n\r\nДа умру я во имя Кель\'таса.\r\n\r\nДа буду убивать я во славу Иллидана.\r\n\r\n-Мастер Кариэль Винтхалус' FROM `page_text` WHERE `ID`=1634 AND MD5(`Text`)='20612f4e63b7a2c0e0f028c37088745a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1634 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1691, 'ruRU', 'Привет, Фелнок!\r\n\r\nМои исследования в Пылающих степях продвигаются отлично. Я весьма обязана $N за $gего:ее; помощь! Вот что мне нужно, чтобы продолжать исследования:\r\n\r\nБумбербитцель из рулонной стали\r\nЛедяной гаечный ключ номер 17\r\n12 фунтов утиных перьев\r\nБанку твоего клея\r\n\r\nСпасибо тебе большое, Фелнок, когда мы увидимся снова, напомни, чтобы я не подкладывала уголь в твои ботинки!\r\n\r\n-Тинки' FROM `page_text` WHERE `ID`=1691 AND MD5(`Text`)='be7726c43e8989d181b1859aea32d63b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1691 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1711, 'ruRU', 'Срочное сообщение для дозорного утесов Долгорога\r\n\r\nОгромные силы кентавров из Лагеря Э\'ток напали на один из наших торговых караванов. Все члены каравана были убиты, а весь товар потерян. Это было наглое и беспрецедентное нападение, и, я боюсь, не последнее.' FROM `page_text` WHERE `ID`=1711 AND MD5(`Text`)='540f7e8fd689504e4277fc4b3b60cc13' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1711 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1731, 'ruRU', 'Здесь покоятся останки короля Теренаса Менетила II – Последнего Истинного Короля Лордерона.$b$bВелики были его дела, долгим было его правление, немыслимой была его смерть. $b$b"Да не будет на отце вины за бесстыдные поступки сына. $bДа останется потерянной и забытой окровавленная корона".' FROM `page_text` WHERE `ID`=1731 AND MD5(`Text`)='c96db54e69563efc6f1fd637408cd91d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1731 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1755, 'ruRU', 'Найденное в отдаленных тропических лесах Кратера Ун\'Горо, это яйцо когда-то содержало в себе эмбрион девизавра. Генетический материал этого зверя оказался бесценен для экологов Лиги Исследователей, которые теперь как никогда близки к изобретению сыворотки от лишающего сил яда девизавров.' FROM `page_text` WHERE `ID`=1755 AND MD5(`Text`)='16c90c50556696bc6e5cd019d46b9b24' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1755 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1757, 'ruRU', 'Поднятая из затопленных руин Сурамара, эта все еще работающая астролябия, была создана высокорожденными эльфами около двенадцати тысяч лет назад. Высокорожденные, одержимые магией, оккультными науками и астрономией, создали множество гениальных инструментов. Это приспособление позволяет нам получить неоценимое представление об уровне развития наук у древних ночных эльфов.' FROM `page_text` WHERE `ID`=1757 AND MD5(`Text`)='dafff6e1130fba5b166f899bee67c35a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1757 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1758, 'ruRU', 'Эти образцы древней глиняной посуды были найдены при раскопках Ульдамана. Хотя на них не так много загадочных рун или иероглифов, они позволяют оценить мастерство изготовления этих повседневных предметов древней расы дворфов.' FROM `page_text` WHERE `ID`=1758 AND MD5(`Text`)='ccb5469cbb4fd774bf56920f475eb361' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1758 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1761, 'ruRU', 'Эти следы Второй войны служат грозным напоминанием о том, как опасно близка была орда к завоеванию Железных гор.' FROM `page_text` WHERE `ID`=1761 AND MD5(`Text`)='7b071b69b44525ce1b3cf7ded0ff2463' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1761 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1762, 'ruRU', 'Эти демонические доспехи носил демон, поразивший наш народ проклятием кровожадности. Благодаря геройскому поступку одного храброго орка он был побежден. Нет больше Маннорота Разрушителя. Да послужат эти доспехи напоминанием нам о том, как глубоко мы пали и как отчаянно мы сражались за то, чтобы вновь обрести наше доброе имя.\r\n\r\n- Тралл, Вождь Орды' FROM `page_text` WHERE `ID`=1762 AND MD5(`Text`)='b2a4d7fc35f9710d754f4c94892a7c3f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1762 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1772, 'ruRU', 'Вурмталак!\r\n\r\nТвой господин Нефариан дал мне повеление наказать тебя так, как я посчитаю нужным, если еще хоть кто-нибудь проберется внутрь крепости.\r\n\r\nНе забывай, кому ты подчиняешься, рептилия.\r\n\r\nСыну Чернорука: Мастеру меча и битвы. Единственному истинному Вождю.\r\n\r\n-Ренд' FROM `page_text` WHERE `ID`=1772 AND MD5(`Text`)='e4aefff411268b074cf37cd77992ec5a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1772 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1774, 'ruRU', 'Эредары, коварная раса демонических чародеев, использовала магию своих колдунов, чтобы поработить множество миров. Расы тех миров мутировали под влиянием злых сил эредаров и сами превращались в демонов.' FROM `page_text` WHERE `ID`=1774 AND MD5(`Text`)='904e634d536727d8b648c37135cf9f78' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1774 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1777, 'ruRU', 'Нечестивые, коварные повелители ужаса обращали друг против друга целые народы, манипулируя их бездумной ненавистью и недоверием друг к другу. Саргерас легко победил Натрезим, но их порча глубоко запала в его душу.' FROM `page_text` WHERE `ID`=1777 AND MD5(`Text`)='6e54f9cbdb74737b2f93bdad0c4a6cb4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1777 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1778, 'ruRU', 'Когда сомнения и отчаяние полностью овладели Саргерасом, он потерял веру не только в свою миссию, но отказался от мыслей титанов об упорядоченной вселенной. В конечном счете он пришел к выводу, что сам порядок является глупостью и что хаос и порочность – единственно абсолютные понятия в этой темной, одинокой вселенной.' FROM `page_text` WHERE `ID`=1778 AND MD5(`Text`)='6a0825ccb9c9f901047eba21f97adf6d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1778 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1779, 'ruRU', 'Его друзья-титаны пытались убедить его не совершать ошибки, пытались успокоить его разбушевавшиеся чувства, но он принимал их более чем оптимистичные верования за корыстные заблуждения. Покинув навсегда их ряды, Саргерас отправился на поиски своего собственного места во вселенной. Несмотря на то что Пантеон был опечален его уходом, даже титаны не могли предугадать того, как далеко зайдет их заблудший брат.' FROM `page_text` WHERE `ID`=1779 AND MD5(`Text`)='e2bbcf69193f118c21765cc4b9b6f708' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1779 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1780, 'ruRU', 'К тому времени, как безумие Саргераса поглотило остатки его некогда отважного духа, он уверовал в то, что титаны сами несут ответственность за ошибки своих созданий. Решив, в конечном счете, уничтожить плоды их трудов во всей вселенной, он захотел создать несокрушимую армию, которая огнем и мечом пройдет по вселенной.' FROM `page_text` WHERE `ID`=1780 AND MD5(`Text`)='310b0b5ece521f325e98e87c7ca27a78' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1780 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1781, 'ruRU', 'Даже титаническое тело Саргераса пострадало от порчи, что поразила его когда-то благородное сердце. Его глаза, волосы и борода горели пламенем, а его металлическая бронзовая кожа раскололась, открыв бездонное горнило пылающей ненависти.' FROM `page_text` WHERE `ID`=1781 AND MD5(`Text`)='5d2b6579a9572db9dbe04eb084179755' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1781 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1783, 'ruRU', 'Кил\'джеден Искуситель был выбран для поиска самых темных рас во вселенной и присоединения их к армии Саргераса. Второй, Архимонд Осквернитель, был избран, чтобы вести огромную армию Саргераса в битву против тех, кто мог воспротивиться воле титана.' FROM `page_text` WHERE `ID`=1783 AND MD5(`Text`)='e0039462feaa5bc5cf307637baed71a6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1783 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1784, 'ruRU', 'Первым шагом Кил\'джедена было порабощение вампирических повелителей ужаса своей чудовищной властью. Повелители ужаса служили его личными агентами по всей вселенной, они находили удовольствие в поиске примитивных рас для своего повелителя, совращали их и сбивали с пути истинного. Первым среди повелителей ужаса был Тикондрус Затмеватель. Тикондрус безукоризненно служил Кил\'джедену и согласился распространять пылающую волю Саргераса во всех темных уголках вселенной.' FROM `page_text` WHERE `ID`=1784 AND MD5(`Text`)='df19bd22e54772b2a3cd64ef19a01604' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1784 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1785, 'ruRU', 'Могущественный Архимонд также избрал для себя агентов. Призвав зловредных разрушителей и их жестокого предводителя, Маннорота Разрушителя, Архимонд надеялся создать военную элиту, которая искореняла бы все живое.' FROM `page_text` WHERE `ID`=1785 AND MD5(`Text`)='7cac6bbda5a9f0bb7e6122bb6f7869ae' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1785 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1786, 'ruRU', 'Когда Саргерас убедился, что его армии в сборе и готовы следовать всем его приказам, он выпустил свои необъятные силы на просторы Великой запредельной тьмы. Он назвал свою растущую армию Пылающим Легионом. До сих пор никто не знает, сколько миров они уничтожили, пройда по вселенной огнем и мечом.' FROM `page_text` WHERE `ID`=1786 AND MD5(`Text`)='1a8ca6a091a4e1810bda0adf735a5ad9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1786 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1787, 'ruRU', 'Не знавшие том, что Саргерас намерен уничтожить плоды их бесчисленных трудов, титаны продолжали передвигаться от мира к миру, формируя и приводя в порядок те планеты, что они находили пригодными. В своем путешествии они случайно попали в небольшой мир, который его обитатели позже назвали Азеротом.' FROM `page_text` WHERE `ID`=1787 AND MD5(`Text`)='1f2d41975bbf621cf81b94d65395e5ab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1787 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1788, 'ruRU', 'Путешествуя по этому девственному миру, по первобытной земле, титаны встречали множество агрессивных элементалей. Эти духи, поклонявшиеся расе невероятно злых существ, известных как Древние Боги, поклялись отбросить титанов и сохранить их мир от металлического прикосновения захватчиков.' FROM `page_text` WHERE `ID`=1788 AND MD5(`Text`)='7ba247af09e8afb3f0a55185d1cb7f77' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1788 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1789, 'ruRU', 'Пантеон, обеспокоенный склонностью Древних Богов ко злу, начал войну против элементалей и их темных повелителей. Армии Древних Богов вели в бой наиболее могущественные элементали: Рагнарос Повелитель Огня, Теразан Матерь Камня, Ал\'Акир Владыка Ветра и Нептулон Охотник Прилива.' FROM `page_text` WHERE `ID`=1789 AND MD5(`Text`)='b5897c34ef565a042be5a4fdde8917c1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1789 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1790, 'ruRU', 'Эти силы хаоса бушевали и бились с колоссами-титанами на груди мира. Несмотря на то что элементали были настолько могущественны, что смертным даже представить невозможно, их объединенных сил было недостаточно, чтобы остановить могучих титанов. Один за другим повелители элементалей пали, а их силы отступили.' FROM `page_text` WHERE `ID`=1790 AND MD5(`Text`)='73d87f308606fa7dc849b704c48460d0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1790 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1791, 'ruRU', 'Пантеон разрушил цитадель Древних Богов и заточил пятерых злых богов глубоко в недрах мира. Элементали, которые не могли сдерживать свое буйство без власти Древних богов, были изгнаны в бездну миров, где они остались сражаться друг с другом на веки вечные. С исчезновением элементалей природа смягчилась, и в мире наступила полная гармония. Титаны увидели, что с угрозой покончено, и принялись за работу.' FROM `page_text` WHERE `ID`=1791 AND MD5(`Text`)='87556b5637c43eb773ec31ddf6fe841b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1791 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1792, 'ruRU', 'Титаны наделили силой многие расы, чтобы те смогли помочь им придавать миру форму. Для создания бездонных подземных пещер титаны сотворили дворфоподобных земельников из магического живого камня. Чтобы помочь им осушить моря и поднять землю над уровнем моря, титаны создали огромных, но кротких морских великанов. Многие столетия титаны придавали форму землям, пока не смогли сотворить совершенный континент.' FROM `page_text` WHERE `ID`=1792 AND MD5(`Text`)='6d32a2f72cc8c17bd4b3da9903c22466' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1792 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1793, 'ruRU', 'В центре континента титаны поместили озеро искрящейся энергии. Озеро, которое они назвали Источником Вечности, было источником жизни в мире. Его могущественная энергия питала корни мира и давала возможность жизни пустить побеги в его плодородной почве. Со временем травы, деревья, монстры и создания всех видов появились на первобытном континенте.' FROM `page_text` WHERE `ID`=1793 AND MD5(`Text`)='f8de02eb6fb2eca40c2889b54f35e987' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1793 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1794, 'ruRU', 'В честь сумерек, павших на мир в их последний день работы, титаны назвали этот континент Калимдором – "землей вечного звездного света".' FROM `page_text` WHERE `ID`=1794 AND MD5(`Text`)='1f9ac8201f2976fc0225954853189c2c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1794 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1795, 'ruRU', 'Удовлетворенные упорядочением этого небольшого мира и окончанием трудов, титаны приготовились покинуть Азерот. Однако перед своим уходом они поручили величайшим существам этого мира присматривать за Калимдором, поскольку любое враждебное вмешательство могло поколебать его идеальный баланс. В то время существовало множество родов драконов.' FROM `page_text` WHERE `ID`=1795 AND MD5(`Text`)='40bb84e03c67015add57cf5afd0c7b3d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1795 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1796, 'ruRU', 'Но пять родов главенствовали над своими собратьями. Титаны избрали эти пять стай, чтобы те присматривали за расцветающим миром. Величайшие члены Пантеона отдали часть своей силы каждому из лидеров стай. Эти магические драконы (указанные ниже) стали известны как Великие аспекты или Великие драконы.' FROM `page_text` WHERE `ID`=1796 AND MD5(`Text`)='138f9eb456adf2ef1692e02c0239e8e8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1796 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1797, 'ruRU', 'Аман-Тул, Великий Отец Пантеона, отдал часть своей вселенской силы огромному бронзовому дракону, Ноздорму. Великий Отец велел Ноздорму защищать само время и управлять извечными потоками рока и судьбы. Мужественный и благородный Ноздорму стал известен как Вневременный.' FROM `page_text` WHERE `ID`=1797 AND MD5(`Text`)='2e57b8c82dd66150952820f12a3c08b6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1797 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1798, 'ruRU', 'Эонар, титан-покровительница всего живого, отдала часть своей силы красной огромной Алекстразе. С тех пор Алекстраза зовется Хранительницей Жизни и охраняет всех созданий этого мира. За ее мудрость и безграничное сострадание ко всему живому Алекстраза была избрана Королевой драконов и возглавила свой род.' FROM `page_text` WHERE `ID`=1798 AND MD5(`Text`)='3977abe46faea10dadd7006ceb7cc631' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1798 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1799, 'ruRU', 'Эонар также даровала младшей сестре Алекстразы, изящной зеленой драконице Изере, определенную власть над природой. Изера впала в вечный транс, именуемый "Сном Творения". Известная под именем Дремлющей, она следит за природой мира из царства Изумрудного Сна.' FROM `page_text` WHERE `ID`=1799 AND MD5(`Text`)='3a01870e665d68ea1fcfbd58221e3fa8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1799 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1800, 'ruRU', 'Титан Норганнон, хранитель знаний и владыка магии, даровал синему дракону Малигосу часть своей великой силы. С того времени Малигос, известный как Хранитель Магии, хранит магию и тайные знания.' FROM `page_text` WHERE `ID`=1800 AND MD5(`Text`)='bfdf1c89e41aee740bb0941c04079884' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1800 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1801, 'ruRU', 'Титан Каз\'горот, ваятель и кузнец мира, даровал часть своей огромной силы могучему черному змею Нелтариону. Великодушный Нелтарион, позже известный как Хранитель Земли, получил власть над почвой, камнем и подземными недрами. Воплотив в себе силу мира, он стал самым могущественным сторонником Алекстразы.' FROM `page_text` WHERE `ID`=1801 AND MD5(`Text`)='212f6bcf3bcc2f3928f9b53f32c45014' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1801 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1802, 'ruRU', 'Получив могущество, пять Аспектов были уполномочены охранять мир в отсутствие титанов. Оставив драконов, готовых защищать их творение, титаны покинули Азерот навеки. К сожалению, Саргерас очень быстро узнал о существовании нового мира…' FROM `page_text` WHERE `ID`=1802 AND MD5(`Text`)='70cea25b82b3d90ee3ea04f14fb62057' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1802 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1803, 'ruRU', 'Высокорожденные довольно бездумно обращались с магией, в результате чего из источника Вечности начали расходиться волны, проникающие даже в самые дальние уголки Великой запредельной тьмы и привлекающие внимание тамошних обитателей. Вскоре и Саргерас – Великий враг всего живого и Разрушитель миров – почуял эти волны и устремился к их источнику.' FROM `page_text` WHERE `ID`=1803 AND MD5(`Text`)='6f6a1cb3eb43b2946cb882ff47c183d7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1803 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1804, 'ruRU', 'Когда Саргерас увидел юный мир Азерота и почуял энергию источника Вечности, в нем проснулся неутолимый голод, и великий темный бог Безымянной Бездны решил уничтожить этот мир и завладеть его силой.' FROM `page_text` WHERE `ID`=1804 AND MD5(`Text`)='fea96a4bb51ff9857d01358ec8a0a473' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1804 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1805, 'ruRU', 'Собрав свою армию – великий Пылающий Легион, – Саргерас пошел на мирный Азерот войной. Легион состоял из миллионов кровожадных демонов, слетевшихся со всех концов Вселенной, и этим демонам не терпелось начать вторжение. Ближайшие помощники Саргераса, Архимонд Осквернитель и Маннорот Разрушитель, подготовили своих зловещих воинов к решительному удару.' FROM `page_text` WHERE `ID`=1805 AND MD5(`Text`)='9839a222dffd50821bca67e626bfb34e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1805 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1806, 'ruRU', 'Королева Азшара, которую магия привела в состояние безумной эйфории, подчинилась невероятному могуществу Саргераса и согласилась пропустить его в свой мир. Перед разлагающим действием магии не устояли даже ее служители-высокорожденные, которые начали поклоняться Саргерасу, как богу. Для того чтобы доказать свою верность Легиону, Высокорожденные помогли своей королеве открыть огромный портал в недрах источника Вечности.' FROM `page_text` WHERE `ID`=1806 AND MD5(`Text`)='c961f9ec832126782709979fb6b25cd4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1806 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1807, 'ruRU', 'Как только все было готово, Саргерас начал вторжение в Азерот. Демоны Пылающего Легиона ворвались в мир через источник Вечности и осадили мирно спящие города ночных эльфов. Под предводительством Маннорота и Архимонда Легион промчался по землям Калимдора, оставляя за собой лишь боль и пепел.' FROM `page_text` WHERE `ID`=1807 AND MD5(`Text`)='a12f1bb70dec058c8e1972db52d7c4f1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1807 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1808, 'ruRU', 'Демоны-чернокнижники призвали инферналов, которые обрушились на изящные шпили калимдорских храмов будто адские пылающие метеоры. Армия кровожадных убийц, называемых стражниками ужаса, прошла по калимдорским полям, уничтожая все живое на своем пути. Демонические гончие Скверны наводнили сельскую местность. Разумеется, храбрые воины-калдорай пытались защитить свои родные земли, но они не могли сдержать всю ярость Пылающего Легиона, и им пришлось шаг за шагом отступать.' FROM `page_text` WHERE `ID`=1808 AND MD5(`Text`)='c402ed84c25f83692244e3c7cabf0c40' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1808 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1809, 'ruRU', 'Искать спасения для своего застигнутого врасплох народа пришлось Малфуриону Ярости Бури. Родной брат Малфуриона, Иллидан, практиковал магию высокорожденных, и Малфуриона очень сильно беспокоила его растущая одержимость. Малфурион убедил брата отказаться от свого пагубного пристрастия и вместе с ним отправиться на поиски Кенария. Кроме того, братьям надлежало собрать силы для сопротивления демонам.' FROM `page_text` WHERE `ID`=1809 AND MD5(`Text`)='1ff65be76441761ff4ae394727627f56' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1809 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1810, 'ruRU', 'С братьями отправилась юная жрица Тиранда, служительница Элуны. И Малфурион, и Иллидан были влюблены в нее, однако сердце Тиранды принадлежало лишь Малфуриону. Иллидан ревновал девушку к своему брату и завидовал их любви, однако его душевные страдания не шли ни в какое сравнение с муками от магической зависимости.' FROM `page_text` WHERE `ID`=1810 AND MD5(`Text`)='5fe308a0be7239dd19d0a7ebd745af3f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1810 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1811, 'ruRU', 'Зависимость Иллидана от магической энергии непрестанно мучила его, и он с трудом сдерживался, чтобы не броситься к источнику Вечности. Однако Тиранда все время была рядом и поддерживала его, так что в итоге они все же добрались до полубога-отшельника по имени Кенарий.' FROM `page_text` WHERE `ID`=1811 AND MD5(`Text`)='44fee5647ada1c836052bfbd8c4a5d29' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1811 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1812, 'ruRU', 'Кенарий жил на священных Лунных полянах на горе Хиджал. Он согласился помочь ночным эльфам, найти древних драконов и обратиться к ним за помощью. Драконы, в свою очередь, тоже решили не оставаться в стороне и, ведомые исполинской красной Алекстразой, отправились на войну с демонами и их адскими предводителями.' FROM `page_text` WHERE `ID`=1812 AND MD5(`Text`)='6f1f8fef0ebace519651801811fbe671' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1812 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1813, 'ruRU', 'Кенарий призвал на помощь духов из зачарованного леса и собрал армию древних энтов, которые двинулись на Легион. Когда союзники ночных эльфов встретились возле храма Азшары и источника Вечности, там завязалась ужасная битва. Однако, несмотря на всю помощь своих новых союзников, Малфурион и его соратники поняли, что даже этих сил не хватит на то, чтобы остановить Легион.' FROM `page_text` WHERE `ID`=1813 AND MD5(`Text`)='5d7c47b36b7b698f92d15ed51b050a1e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1813 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1814, 'ruRU', 'Пока в самом сердце Азшары гремела битва, одурманенная королева с нетерпением дожидалась прибытия Саргераса, который готовился пройти сквозь источник Вечности и самолично ступить на землю Азерота. Его исполинская тень медленно приближалась к поверхности Источника, а Азшара тем временем собрала своих самых могущественных служителей, чтобы они объединили свои силы, прочитали одно заклинание и расширили портал настолько, чтобы Саргерас смог пройти через него.' FROM `page_text` WHERE `ID`=1814 AND MD5(`Text`)='e4c3550166f57cd43d30993878ad6c16' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1814 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1815, 'ruRU', 'Во время битвы на полях Калимдора произошло нечто ужасное. Подробности этого происшествия были утеряны, но известно лишь то, что дракон Нелтарион, аспект земли, в пылу битвы с Демонами вдруг сошел с ума. Он начал распадаться на части, по всей его черной шкуре вспыхивали языки пламени, и в итоге это разъяренное горящее чудовище назвало себя Смертокрылом и напало на своих собратьев, из-за чего пятеро драконов были вынуждены покинуть поле боя.' FROM `page_text` WHERE `ID`=1815 AND MD5(`Text`)='4f842dce9236f84557079af4aae95b36' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1815 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1816, 'ruRU', 'Внезапное предательство Смертокрыла повлекло за собой столь губительные последствия, что остальные драконы так никогда и не смогли оправиться от потрясения. Израненная и убитая горем Алекстраза и ее пятеро собратьев покинули поле боя, оставив своих смертных союзников один на один с многократно превосходящей их армией демонов. Малфуриону и его соратникам едва удалось выжить в последовавшем натиске.' FROM `page_text` WHERE `ID`=1816 AND MD5(`Text`)='c9da52c0951379c1304cd27ee65f9b15' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1816 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1817, 'ruRU', 'Малфурион был уверен, что демоны рвутся в этот мир из Источника Вечности, поэтому он стал настаивать на его уничтожении. Но так как именно Источник являлся залогом могущества и бессмертия Ночных эльфов, такое решение привело остальных в ужас. Однако Тиранда поняла весь замысел Малфуриона и убедила Кенария и его соратников напасть на храм Азшары и найти способ закрыть источник раз и навсегда.' FROM `page_text` WHERE `ID`=1817 AND MD5(`Text`)='46ceced601357d86ebe58f737e85a6d2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1817 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1828, 'ruRU', 'Немногие уцелевшие при взрыве эльфы собрались вместе, наспех сколотили несколько плотов и медленно поплыли к далекой земле. Милостью Элуны Великий Раскол пережили и Малфурион с Тирандой, и Кенарий. Измученные герои согласились стать предводителями своих выживших сородичей и обустроить для них новый дом.' FROM `page_text` WHERE `ID`=1828 AND MD5(`Text`)='07a9546af627c7fbddf7a4ee6540b369' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1828 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1829, 'ruRU', 'Они плыли в молчании, глядя на то, что осталось от их народа, и понимая, что в этом виноваты лишь они сами и их страсти. Конечно, после уничтожения Источника Саргерасу и Пылающему Легиону больше не было хода в этот мир, но цена, которую пришлось заплатить за это, была поистине ужасной.' FROM `page_text` WHERE `ID`=1829 AND MD5(`Text`)='fb59f387b75bd04ade455ce8f108b639' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1829 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1830, 'ruRU', 'Многим высокорожденным тоже удалось выжить, и они отправились к берегам новой земли вместе с ночными эльфами. Малфурион до сих пор сомневался в Высокорожденных, но он был рад хотя бы тому, что Источника больше нет, а без его энергии они не представляют собой угрозы.' FROM `page_text` WHERE `ID`=1830 AND MD5(`Text`)='a136e1e9a9db19a34fe944ca1befec70' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1830 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1831, 'ruRU', 'Когда изможденные ночные эльфы высадились на берег, они увидели, что священная гора Хиджал не пострадала при взрыве. В поисках места для нового дома Малфурион и остальные эльфы поднялись на горные склоны и остановились на овеваемой всеми ветрами вершине. Спустившись в поросшую лесом низину между двумя огромными пиками, они обнаружили там маленькое тихое озеро и, к своему ужасу, поняли, что воды его светятся магией.' FROM `page_text` WHERE `ID`=1831 AND MD5(`Text`)='d5b4025615a14a28977af75aebe03c67' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1831 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1832, 'ruRU', 'Иллидан тоже пережил Раскол и добрался до вершины Хиджала намного раньше Малфуриона и ночных эльфов. Он был одержим идеей сохранить в этом мире магию, поэтому вылил в горное озеро драгоценную воду из Источника Жизни, которую хранил в нескольких сосудах.' FROM `page_text` WHERE `ID`=1832 AND MD5(`Text`)='10fc0e52777ff01d583b8afda5c80f13' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1832 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1833, 'ruRU', 'Воды горного озера вмиг напитались энергией Источника Вечности, и оно превратилось в новый источник. Иллидан ликовал: он считал, что это станет настоящим даром для будущих поколений, поэтому был несказанно удивлен, когда на него вдруг набросился его брат. Малфурион объяснил Иллидану, что в основе всей магии лежит хаос и что ее использование неизбежно приведет к одержимости и войнам. Иллидан, однако, не спешил отказываться от своей магической силы.' FROM `page_text` WHERE `ID`=1833 AND MD5(`Text`)='25ee369c170377a415bf1c2e5f23e4a0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1833 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1834, 'ruRU', 'Малфурион знал, что планы его брата, одержимого жаждой могущества, не сулят ничего хорошего, поэтому он решил раз и навсегда избавиться от Иллидана. Вместе с Кенарием они заключили его в тюрьму под холмами, где Иллидану надлежало оставаться до конца его жизни, обессиленным и закованным в цепи. Малфурион поручил юной стражнице по имени Майев Песнь Теней следить за пленником, чтобы тот не сбежал.' FROM `page_text` WHERE `ID`=1834 AND MD5(`Text`)='c5f30afc9ae61d425e8c2901bc5719fb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1834 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1835, 'ruRU', 'Ночные эльфы не стали уничтожать новый Источник Вечности, чтобы не вызвать новой катастрофы. Однако Малфурион объявил, что ночные эльфы больше никогда не будут практиковать магию, после чего они под руководством Кенария стали изучать древнее искусство друидизма, которое помогло бы им исцелить истерзанную землю и вырастить новые леса у подножия горы Хиджал.' FROM `page_text` WHERE `ID`=1835 AND MD5(`Text`)='96c01fe6947c064bbdeb84b206875f00' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1835 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1836, 'ruRU', 'На протяжении многих лет ночные эльфы работали не покладая рук, чтобы восстановить то, что осталось от их древней родины. Они оставили свои разрушенные храмы и дороги зарастать и построили новые дома среди зеленых деревьев и тенистых холмов у подножия горы Хиджал. Мало-помалу из своих укрытий выбрались и драконы, пережившие Великий Раскол.' FROM `page_text` WHERE `ID`=1836 AND MD5(`Text`)='72266ba4c4d3099d169c2e00f05eb414' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1836 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1837, 'ruRU', 'Алекстраза красная, Изера зеленая и Ноздорму бронзовый опустились на тихие поляны ночных эльфов и посмотрели на плоды их трудов. Малфурион, ставший могущественным верховным друидом, поприветствовал драконов и рассказал им о новом Источнике Вечности.' FROM `page_text` WHERE `ID`=1837 AND MD5(`Text`)='2e7e95bb4bc6a8af4dcf41593ac8cd9d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1837 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1838, 'ruRU', 'Эта новость встревожила великих драконов, потому что пока существовал источник, существовала и возможность того, что Пылающий Легион когда-нибудь снова вернется в этот мир. Малфурион и три дракона договорились вечно охранять Источник и решили сделать все возможное для того, чтобы демоны никогда больше не появились в этом мире.' FROM `page_text` WHERE `ID`=1838 AND MD5(`Text`)='3ffd9fbfe9a3b28e342a4c38b215cab3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1838 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1839, 'ruRU', 'Алекстраза Хранительница Жизни опустила в источник зачарованный желудь. Пробужденный могущественными водами, он вырос в огромное дерево, корни которого тянулись в самые недра Источника, а крона, казалось, достигала небес.' FROM `page_text` WHERE `ID`=1839 AND MD5(`Text`)='8185f0788cac2726b2ef042adae01f48' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1839 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1840, 'ruRU', 'Огромное древо стало символом вечного союза ночных эльфов и природы, а его жизнетворная энергия впоследствии исцелила весь мир. Ночные эльфы дали своему Древу Жизни имя Нордрассил, что на их языке означало "корона жизни".' FROM `page_text` WHERE `ID`=1840 AND MD5(`Text`)='36cb4e4b1e1dad872785ad826cd41121' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1840 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1841, 'ruRU', 'Ноздорму Вневременный наложил на Древо Жизни заклятье, которое сделало ночных эльфов бессмертными, вечно молодыми и невосприимчивыми к любым болезням.' FROM `page_text` WHERE `ID`=1841 AND MD5(`Text`)='ceb77262d6e82184e1de6fb9cd886dac' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1841 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1842, 'ruRU', 'Изера Дремлющая тоже зачаровала Древо Жизни, связав его со своим миром, астральным измерением, известным как Изумрудный Сон. Этот огромный мир, населенный духами, не подчинялся законам физического мира. Из своего Сна Изера могла управлять жизнью природы и развитием всего остального мира.' FROM `page_text` WHERE `ID`=1842 AND MD5(`Text`)='d80a11d38f47079d94558358d795627b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1842 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1843, 'ruRU', 'Древо Жизни связывало всех ночных эльфов-друидов, включая Малфуриона, с Изумрудным Сном. Заключая договор с драконами, они согласились периодически засыпать на целые века, чтобы их духи могли блуждать по бесконечным тропам сна Изеры. Конечно, друидов печалило то, что придется потерять столько лет своей жизни, но, тем не менее, они самоотверженно пошли на эту сделку.' FROM `page_text` WHERE `ID`=1843 AND MD5(`Text`)='e841f0a2eb755d3dc7205a590bdbe135' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1843 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1844, 'ruRU', 'Шли века, сообщество ночных эльфов набиралось сил и разрасталось, занимая все новые и новые территории леса, который они назвали Ясеневым. Появились и расплодились многие существа, жившие еще до Великого Раскола, – например, фурболги и иглогривы. Ночные эльфы жили под управлением мудрых друидов и наслаждались эрой небывалого спокойствия и мира под звездами.' FROM `page_text` WHERE `ID`=1844 AND MD5(`Text`)='2cb46311e729c6bcf6f55cbf0b3b052c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1844 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1845, 'ruRU', 'Однако многие из выживших высокорожденных становились все беспокойнее. Как и Иллидан, они пали жертвами магии, и изо дня в день их снедало искушение, безумное желание вновь почувствовать энергию Источника Вечности и насладиться его магией. Дат\'Ремар, вспыльчивый и беззастенчивый предводитель Высокорожденных, начал в открытую насмехаться над друидами и обвинять их в трусости за то, что они отказались от использования магии, которая, как он считал, принадлежала им по праву.' FROM `page_text` WHERE `ID`=1845 AND MD5(`Text`)='ee50b8936ce13ecd3cea03edaf186e80' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1845 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1846, 'ruRU', 'Малфурион и друиды не слушали речей Дат\'Ремара и объявили высокорожденным, что любое использование магии будет караться смертью. Однако Дат\'Ремар и его последователи все же попытались нарушить закон друидов, но попытка эта закончилась крахом, и в результате в Ясеневом лесу разразилась ужасная магическая буря.' FROM `page_text` WHERE `ID`=1846 AND MD5(`Text`)='61e78744b228685146b6856567f062fe' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1846 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1847, 'ruRU', 'Друиды не смогли заставить себя вынести стольким сородичам смертный приговор, поэтому решили просто изгнать безрассудных Высокорожденных из своих земель. Дат\'Ремар и его сородичи были только рады освободиться от традиционного общества друидов, поэтому они быстро погрузились на флотилию судов и пустились в плавание по морям. Никто не знал, что ждет их за исполинским бурлящим Водоворотом, но Высокорожденные хотели найти себе новый дом, где они могли бы безнаказанно практиковать свою любимую магию.' FROM `page_text` WHERE `ID`=1847 AND MD5(`Text`)='ac73816671c8e0b0ec0609c1af549387' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1847 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1848, 'ruRU', 'Высокорожденные, или Кель\'дорай, как их ранее называла Азшара, в конце концов достигли берегов восточных земель, которые люди позднее назовут Лордерон. Они планировали создать свое собственное королевство магов, Кель\'Талас, и отречься от поклонения луне и от ночного образа жизни, свойственных ночным эльфам. С тех пор и вовеки они станут поклоняться солнцу и будут известны как высшие эльфы.' FROM `page_text` WHERE `ID`=1848 AND MD5(`Text`)='1cd8825e5b22f784646afbeae53e2ef5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1848 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1849, 'ruRU', 'С уходом своих своевольных собратьев ночные эльфы вновь стали оберегать свою зачарованную родину. Друиды, чувствуя, что скоро должны уснуть, готовились ко сну и прощались со своими родными и близкими.' FROM `page_text` WHERE `ID`=1849 AND MD5(`Text`)='4c02c5cf549fa218eba179cc34ea2ef7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1849 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1850, 'ruRU', 'Тиранда, ставшая Верховной жрицей Элуны, умоляла своего возлюбленного Малфуриона не уходить в Изумрудный Сон Изеры. Но Малфурион, считавший своим долгом вступить на изменчивые тропы Спящей, попрощался со жрицей и поклялся, что они никогда не разлучатся, до тех пор пока хранят верность своей любви.' FROM `page_text` WHERE `ID`=1850 AND MD5(`Text`)='b49e07d073ee727c7ad9f87709aedfff' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1850 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1851, 'ruRU', 'Оставшись в одиночестве защищать Калимдор от опасностей нового мира, Тиранда собрала мощную армию своих сестер, ночных эльфиек. Бесстрашные, искусные воительницы, поклявшиеся защищать Калимдор, стали известны как Часовые. Хотя они предпочитали самостоятельно патрулировать тенистый Ясеневый лес, у них было множество союзников, которых они призывали во время опасностей.' FROM `page_text` WHERE `ID`=1851 AND MD5(`Text`)='3ce3bdc8f488b53610a5e3706facc8f1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1851 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1852, 'ruRU', 'Полубог Кенарий обитал неподалеку оттуда на Лунных полянах горы Хиджал. Его сыновья, известные как Хранители Рощ, наблюдали за ночными эльфами и регулярно помогали Часовым поддерживать мир на этих землях. Даже скромные дочери Кенария, дриады, стали появляться все чаще и чаще.' FROM `page_text` WHERE `ID`=1852 AND MD5(`Text`)='064299313352e6dd0766d02e50e356e1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1852 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1853, 'ruRU', 'Охрана Ясеневого леса занимала все время Тиранды, но она тосковала без Малфуриона. Шли века, друиды спали, а ее опасения насчет нового вторжения демонов росли. Она не могла избавиться от тревожного ощущения, что, возможно, Пылающий Легион все еще здесь, за пределами Великой тьмы неба, и что он готовится отомстить ночным эльфам и всему Азероту.' FROM `page_text` WHERE `ID`=1853 AND MD5(`Text`)='eed73f04be639fdf7d173b2b844ff173' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1853 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1854, 'ruRU', 'Высшие эльфы, ведомые Дат\'ремаром, покинули Калимдор и миновали Водоворот с его бурями. Их флот много долгих лет плавал среди обломков старого мира, они открыли множество тайн и потерянных королевств. Дат\'ремар, взявший имя Солнечный Скиталец (или "тот, кто ходит весь день"), искал места с большей магической энергией, чтобы построить там новое королевство для своего народа.' FROM `page_text` WHERE `ID`=1854 AND MD5(`Text`)='7e823240bd514ffe896949b9b18bf373' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1854 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1855, 'ruRU', 'В конце концов они ступили на берега королевства, которое люди позднее назовут Лордерон. Продвигаясь в глубь континента, высшие эльфы основали поселение на спокойных Тирисфальских лесах. Но через несколько лет многие из них начали сходить с ума. Возникло предположение, что что-то злое спало в недрах тех земель, но эти слухи так и не оправдались. Высшие эльфы собрали все свое добро и двинулись на север, к землям, богатым энергетическими линиями.' FROM `page_text` WHERE `ID`=1855 AND MD5(`Text`)='f2e2d9dc2a8a391d5c1b9e892bb985c6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1855 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1856, 'ruRU', 'В то время как высшие эльфы шли по гористым землям Лордерона, их путешествие становилось все более опасным. Поскольку они были отрезаны от животворных энергий Источника Вечности, многие из них начали болеть из-за холодного климата или умирать от голода. Но ужаснее всего было то, что теперь они были не бессмертны и не могли противостоять стихиям.' FROM `page_text` WHERE `ID`=1856 AND MD5(`Text`)='6dd877bb4c98d3314b3ff851e47a5b81' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1856 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1857, 'ruRU', 'Кроме того, они стали ниже ростом, а их кожа потеряла характерный фиолетовый оттенок. Несмотря на трудности, они смогли противостоять многим неведомым существам, каких в Калимдоре и не видывали. Они нашли племена диких людей, которые охотились в древних чащах. Но самую большую угрозу представляли собой алчные и хитрые лесные тролли Зул\'Амана.' FROM `page_text` WHERE `ID`=1857 AND MD5(`Text`)='ef4d8fd4454688d13cb4ccb3000682d0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1857 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1858, 'ruRU', 'Эти тролли, с кожей цвета мха, умели восстанавливать утраченные конечности и залечивать самые ужасные раны. Но это был варварский, злой народ. Империя Амани растянулась по большей части северного Лордерона, и тролли яростно боролись за свои земли, стараясь держать незваных гостей подальше от своих границ. Эльфы всей душой ненавидели злобных троллей и убивали их при любом удобной случае.' FROM `page_text` WHERE `ID`=1858 AND MD5(`Text`)='fec89a7c8bfecd3310841501ca7a941a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1858 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1859, 'ruRU', 'После долгих лет странствий высшие эльфы, наконец, нашли земли, напоминавшие Калимдор. В глуши северных лесов они основали королевство Кель\'Талас и поклялись создать могущественную империю, которая будет во всем превосходить цивилизацию их собратьев, калдорай. К сожалению, эльфы вскоре узнали, что основали Кель\'Талас на развалинах древнего города троллей, который те до сих пор считали священным. Тролли почти сразу же начали атаковать эльфийские поселения.' FROM `page_text` WHERE `ID`=1859 AND MD5(`Text`)='c98aa4996fe6abdea38eb892c0115653' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1859 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1860, 'ruRU', 'Упрямые эльфы, не желавшие отдавать свои новые владения, использовали магию, оставшуюся от Источника Вечности, и заставили свирепых троллей отступить. Под командой Дат\'Ремара они сумели победить отряды Амани, которые десятикратно превосходили их числом. Некоторые эльфы, помнившие древние предупреждения калдорай, почувствовали, что использование магии может привлечь внимание изгнанного Пылающего Легиона.' FROM `page_text` WHERE `ID`=1860 AND MD5(`Text`)='4a70680e31f8c1b751b16902d7c9def1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1860 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1861, 'ruRU', 'Поэтому они решили скрыть свои земли защитным барьером, который позволял бы им спокойно заниматься магией. Они установили в разных точках Кель\'Таласа, на границах магического барьера, цепь Рунических камней. Рунические камни не только скрывали магию эльфов от внеземных угроз, но и помогали отпугивать суеверных троллей.' FROM `page_text` WHERE `ID`=1861 AND MD5(`Text`)='7387fe79d6cc613cd66eae3bb68cedb3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1861 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1862, 'ruRU', 'С течением времени Кель\'Талас сделался сияющим памятником трудам и магическому мастерству высших эльфов. Его прекрасные дворцы были созданы в том же архитектурном стиле, что и древние чертоги Калимдора, однако они великолепно вписывались в естественный ландшафт тех мест. Кель\'Талас стал сияющим самоцветом, который так хотели создать эльфы.' FROM `page_text` WHERE `ID`=1862 AND MD5(`Text`)='4ffda00a79df2d38e85840bd2ac53d2b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1862 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1863, 'ruRU', 'Правительством Кель\'Таласа стал совет Луносвета, хотя династия Солнечных Скитальцев также отчасти сохраняла политическую власть. Включавший в себя семерых величайших эльфийских лордов совет заботился о безопасности эльфов и эльфийских земель. Под защитой барьера высшие эльфы отвергли былые предупреждения калдорай и с преступной беспечностью продолжали использовать магию практически во всех аспектах своей жизни.' FROM `page_text` WHERE `ID`=1863 AND MD5(`Text`)='0fcae71d000349a169a59de273e40a2c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1863 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1864, 'ruRU', 'Почти четыре тысячи лет высшие эльфы спокойно жили в своем укромном королевстве. Тем не менее мстительные тролли сдаваться не собирались. В глуши лесов они строили планы и копили силы. В конце концов могучая армия троллей вышла из тени лесов и вновь осадила сияющие башни Кель\'Таласа.' FROM `page_text` WHERE `ID`=1864 AND MD5(`Text`)='fba7713b4ea7ffcc241ef80b4474c3eb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1864 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1865, 'ruRU', 'В то время как высшие эльфы сражались не на жизнь, а на смерть против яростного натиска троллей, разрозненные, ведущие кочевой образ жизни люди Лордерона боролись за объединение своих земель. Изначально племена людей постоянно совершали набеги на другие людские поселения, пренебрегая честью и не заботясь об объединении расы.' FROM `page_text` WHERE `ID`=1865 AND MD5(`Text`)='f47ddda22077f54f4635b88ab6a35ca1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1865 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1866, 'ruRU', 'Но одно племя, известное как Арати, поняло, что тролли сделались слишком серьезной угрозой, чтобы продолжать их игнорировать. Арати хотели подчинить себе все племена, чтобы выступить единым фронтом против троллей.' FROM `page_text` WHERE `ID`=1866 AND MD5(`Text`)='c8cb54367ed7bf933cc744bfa0b36fa6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1866 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1867, 'ruRU', 'За шесть лет хитрые Арати победили и перехитрили все вражеские племена. После каждой победы Арати предлагали завоеванным людям мир и равноправие, таким образом получая верность побежденных. В конце концов племя Арати включило в себя много других племен, а мощь их армии росла с огромной скоростью.' FROM `page_text` WHERE `ID`=1867 AND MD5(`Text`)='eb204880737baffac5a80e67ae0aae0c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1867 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1868, 'ruRU', 'Убежденные в том, что они могут самостоятельно противостоять троллям или даже эльфам, военачальники Арати решили построить могучий город-крепость в южных регионах Лордерона. Город, названный Cтром, стал столицей государства Арати, Аратора. В то время как Аратор процветал, люди со всего огромного континента шли на юг, дабы жить под защитой Cтрома.' FROM `page_text` WHERE `ID`=1868 AND MD5(`Text`)='8fefb58493ceae9225bb7413545d7ca8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1868 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1869, 'ruRU', 'Объединенные под одним знаменем, людские племена создали сильную, жизнерадостную культуру. Торадин, король Аратора, знал, что таинственные эльфы на севере постоянно сражались с троллями, но отказался рисковать безопасностью своих людей ради скрытных незнакомцев. Много месяцев прошло, прежде чем слухи о близком поражении эльфов распространились с севера. Только тогда, когда измученные послы Кель\'Таласа добрались до Cтрома, Торадин осознал истинную угрозу, идущую от троллей.' FROM `page_text` WHERE `ID`=1869 AND MD5(`Text`)='1691eb7069b0a84122c0a332f68be890' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1869 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1870, 'ruRU', 'Эльфы сказали Торадину, что армия троллей неисчислима, что, уничтожив Кель\'Талас, они двинутся на юг. Будучи в отчаянии, эльфы, нуждавшиеся в военной помощи, быстро согласились обучить некоторых избранных людей искусству магии в обмен на помощь.' FROM `page_text` WHERE `ID`=1870 AND MD5(`Text`)='e902bf26559788bfd6a6ad737459dda6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1870 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1871, 'ruRU', 'Торадин, не доверявший любой магии, согласился помочь эльфам исключительно по необходимости. Практически немедленно эльфийские волшебники прибыли в Аратор и начали обучать группу людей магии.' FROM `page_text` WHERE `ID`=1871 AND MD5(`Text`)='1ae81e3f94de964d115bb9dc7fe17625' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1871 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1872, 'ruRU', 'Эльфы обнаружили, что хотя люди были неловки в обращении с магией, у них была потрясающая природная связь с ней. Эльфы обучили сотню людей самым азам своих магических тайн: не больше, чем было нужно для битвы с троллями. Убежденные в том, что их ученики-люди готовы вступить в бой, эльфы покинули Cтром и пошли на север вместе с могучей армией короля Торадина.' FROM `page_text` WHERE `ID`=1872 AND MD5(`Text`)='f3d51757a953a4e5fdd468a37b43e46f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1872 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1873, 'ruRU', 'Объединившиеся эльфийские и человеческие армии вступили в схватку с огромной армией троллей у подножья Альтеракских гор. Битва продолжалась много дней, но неослабевавшая армия Аратора не уставала и не отступала под натиском троллей. Эльфийские властители решили, что пришло время ниспослать силы магии на врага.' FROM `page_text` WHERE `ID`=1873 AND MD5(`Text`)='1aaf272c4b91b6b2a43fe6d88d842900' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1873 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1874, 'ruRU', 'Сотня людских магов и множество эльфийских волшебников вызвали ярость небес и напустили пламя на армию троллей. Огонь стихий лишал троллей возможности исцеления ран, сжигая их изнутри и снаружи.' FROM `page_text` WHERE `ID`=1874 AND MD5(`Text`)='58c54ff45aae0f4acc895d0d7fcb79be' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1874 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1876, 'ruRU', 'Когда тролли были изгнаны из северных земель, эльфы Кель\'Таласа направили все свои усилия на воссоздание своего великолепного царства. Армия Аратора с победой вернулась домой, в южные земли Cтрома.' FROM `page_text` WHERE `ID`=1876 AND MD5(`Text`)='adbae508ee8b0b7c285c9ce2177cd3f8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1876 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1878, 'ruRU', 'Первая сотня магов, обученная эльфами использовать магию, развила свое могущество и начали глубже изучать тайны плетения заклинаний. Эти маги, изначально выбранные из-за их сильной воли и доблести, всегда очень осторожно практиковали свою магию; но они передали свою силу и тайны магии новому поколению, не имевшему никакого представления об ужасах войны или необходимости самоконтроля.' FROM `page_text` WHERE `ID`=1878 AND MD5(`Text`)='dae92a5fd46ecc6676b11691b872bd8e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1878 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1879, 'ruRU', 'Эти юные маги начали практиковать магию для собственной пользы, а не ради исполнения долга перед своими сородичами.' FROM `page_text` WHERE `ID`=1879 AND MD5(`Text`)='89d7be6d09a4d5d9eabb4c2c6bf5f80b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1879 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1881, 'ruRU', 'Второй город-государство Аратора, Даларан, был построен севернее Cтрома. Многие юные волшебники покинули ограничивавшие их границы Cтрома и отправились в Даларан, где они надеялись получить свободу в использовании заклинаний. Эти маги использовали свои силы, чтобы создать зачарованные башни Даларана, и с головой погрузились в исследования.' FROM `page_text` WHERE `ID`=1881 AND MD5(`Text`)='63a62b406d792a7b0cacde5eea24eeb6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1881 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1883, 'ruRU', 'Зловещие шпионы Пылающего Легиона, которые были изгнаны во время обрушения Источника Вечности, были привлечены обратно в мир неосторожными заклинаниями магов Даларана. Хотя эти относительно слабые демоны не проявляли себя в полной мере, они создавали довольно большую неразбериху и хаос на улицах Даларана.' FROM `page_text` WHERE `ID`=1883 AND MD5(`Text`)='9764a1a587377733bd662ca19b59a51d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1883 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1886, 'ruRU', 'Услыхав от магократов вести о действиях демонов в Даларане, эльфы немедленно послали своих самых могущественных волшебников к людям. Эльфийские волшебники изучили течение энергии в Даларане и составили детальные отчеты о действиях демонов. Они заключили, что, хотя в мире пока не так много демонов, сам Легион будет по-прежнему представлять огромную угрозу, пока люди используют магию.' FROM `page_text` WHERE `ID`=1886 AND MD5(`Text`)='8200bc15e05a0935d784c54fce98c723' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1886 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1887, 'ruRU', 'Совет Луносвета, правивший эльфами Кель\'Таласа, заключил секретный пакт с магократами, владыками Даларана. Эльфы рассказали лордам-магам об истории древнего Калимдора и Пылающем Легионе, который все еще угрожал миру. Они сообщили людям, что, пока те используют магию, им придется защищать своих граждан от коварных посланцев Легиона.' FROM `page_text` WHERE `ID`=1887 AND MD5(`Text`)='c1a790345e7acbd5954153305793a702' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1887 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1889, 'ruRU', 'Сообщество собиралось на тенистых Тирисфальских лесах, где высшие эльфы впервые поселились в Лордероне. Поэтому секта была названа "Хранители Тирисфаля". Смертные поборники, избранные быть Хранителями, получали огромную силу эльфийской и людской магии. Хотя одновременно мог существовать только один такой поборник, Хранители были настолько могущественны, что могли и в одиночку расправиться со шпионами Легиона, где бы они их ни находили.' FROM `page_text` WHERE `ID`=1889 AND MD5(`Text`)='df1c3d02169030c11bd66ee84b40fcbe' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1889 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1891, 'ruRU', 'Проходили века, Хранители защищали людей от невидимой угрозы Пылающего Легиона по всему Аратору и Кель\'Таласу. Аратор рос и процветал, а использование магии распространилось по всей империи. Тем временем Хранители пристально наблюдали: не появится ли признаков активности демонов.' FROM `page_text` WHERE `ID`=1891 AND MD5(`Text`)='858bdeebe368138d95a36cf153ce0e55' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1891 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1892, 'ruRU', 'В древние времена, после того как титаны покинули Азерот, их дети, известные как земельники, продолжали охранять и обустраивать глубины мира. Земельникам не было дела до наземных рас, они желали лишь проникать все глубже и глубже в землю.' FROM `page_text` WHERE `ID`=1892 AND MD5(`Text`)='6b755fb6db29088b4c849b273dc15d1d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1892 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1893, 'ruRU', 'Когда мир раскололся после взрыва Источника Вечности, это очень сильно задело земельников. Ошеломленные болью самой земли, земельники сделались непохожи на самих себя и закрылись в каменных чертогах, где некогда были созданы. Ульдаман, Ульдум, Ульдуар… это имена древних городов титанов, где земельники впервые обрели свой облик. Погребенные в недрах мира, земельники спокойно отдыхали почти восемь тысяч лет.' FROM `page_text` WHERE `ID`=1893 AND MD5(`Text`)='d234ce1e26f0e13f1791646d359e0587' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1893 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1894, 'ruRU', 'Неизвестно, что именно разбудило земельников, закрывшихся в Ульдамане, но в конце концов они очнулись от сна. Земельники обнаружили, что за время своего забытья сильно изменились. Их каменные шкуры разгладились и сделались мягкой кожей, а их власть над камнем и землей ослабла. Они стали смертными существами.' FROM `page_text` WHERE `ID`=1894 AND MD5(`Text`)='7240067006b3d99b0a1fb3bca19cee7b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1894 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1895, 'ruRU', 'Назвав себя дворфами, последние земельники покинули Ульдаман и отправились исследовать мир. Их по-прежнему влекли уютные и безопасные подземелья, а потому они основали огромное королевство под самой высокой горой.' FROM `page_text` WHERE `ID`=1895 AND MD5(`Text`)='e469c756415ff7016cb6c8f75067a79e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1895 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1896, 'ruRU', 'Они назвали свои земли Каз Модан, или "Гора Каза", в честь титана-кузнеца Каз\'горота. Соорудив алтарь своему отцу-титану, дворфы создали огромную кузницу в самом сердце горы. И город, росший вокруг кузницы, стал называться Стальгорн.' FROM `page_text` WHERE `ID`=1896 AND MD5(`Text`)='047ba8aa2092d905c7a559b5d08cec73' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1896 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1897, 'ruRU', 'Дворфы, от природы любившие придавать формы самоцветам и камню, начали добывать в близлежащих горах драгоценные минералы. Довольные своими подземными трудами, дворфы не стремились общаться с наземными соседями.' FROM `page_text` WHERE `ID`=1897 AND MD5(`Text`)='d1fecec55a454d4ba22d5238b554b95e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1897 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1898, 'ruRU', 'Cтром по-прежнему оставался центром Аратора, но на континенте Лордерон возникло множество новых городов-государств. Гильнеас, Альтерак и Кул-Тирас были первыми среди этих городов-государств, и хотя во всех этих городах были свои обычаи и своя экономика, все они подчинялись Cтрому.' FROM `page_text` WHERE `ID`=1898 AND MD5(`Text`)='646194b30bccb8c80e42927cd0f2ac0f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1898 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1899, 'ruRU', 'Под бдительным присмотром Тирисфальского ордена Даларан стал центром обучения для всех волшебников. Магократы, правившие Далараном, основали Кирин-Тор, особое тайное общество, регистрировавшее и изучавшее каждое заклинание, артефакт или магический предмет, известный в то время.' FROM `page_text` WHERE `ID`=1899 AND MD5(`Text`)='45c0d1302c240cc3b0ee0b3128f8456e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1899 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1900, 'ruRU', 'Гильнеас и Альтерак были надежными союзниками Cтрома. Они отправили свои могучие армии изучать гористые южные земли Каз Модана. Именно тогда люди впервые столкнулись с древней расой дворфов и пришли в их подземный город Стальгорн. Люди и дворфы делились друг с другом секретами обработки металлов и инженерного дела. К тому же оба народа одинаково любили битвы и древние предания.' FROM `page_text` WHERE `ID`=1900 AND MD5(`Text`)='417be3f9299d7e0a69ba20d5be580c34' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1900 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1901, 'ruRU', 'Город-государство Кул-Тирас, основанный на большом острове к югу от Лордерона, имел процветающую экономику, основанную на рыболовстве и мореплавании. Со временем у Кул-Тираса появился могучий флот торговых судов, плававших по всему известному миру в поисках экзотических товаров. Но в то время как экономика Аратора процветала, наиболее мощные ее элементы начали рушиться.' FROM `page_text` WHERE `ID`=1901 AND MD5(`Text`)='cb382969bb71030ef1f234d61347b692' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1901 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1902, 'ruRU', 'Город-государство Кул-Тирас, основанный на большом острове к югу от Лордерона, имел процветающую экономику, основанную на рыболовстве и мореплавании. Со временем у Кул-Тираса появился могучий флот торговых судов, плававших по всему известному миру в поисках экзотических товаров. Но в то время как экономика Аратора процветала, наиболее мощные ее элементы начали рушиться.' FROM `page_text` WHERE `ID`=1902 AND MD5(`Text`)='84150f50b09287dc3482bf4569cf6640' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1902 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1903, 'ruRU', 'Лорды Cтрома, ища на диком севере чистоту и свет, решили оставить свой древний город. Далеко к северу от Даларана лорды Cтрома построили новый город-государство, названный Лордерон. Весь континент был назван в честь этого города. Лордерон стал местом религиозного паломничества и укрытием для тех, кто искал спокойствия и безопасности.' FROM `page_text` WHERE `ID`=1903 AND MD5(`Text`)='0b4f15e937b78cd6be6c5511e276987f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1903 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1904, 'ruRU', 'Наследники Арати, оставшиеся в ветшающих стенах древнего Cтрома, решили отправиться на юг, за каменистые горы Каз Модана. Их странствия длились не один год, но наконец путешествие окончилось, и они поселились в северном регионе континента, который позднее назовут Азерот. В плодородной долине они основали королевство Штормград, быстро ставшее независимой силой.' FROM `page_text` WHERE `ID`=1904 AND MD5(`Text`)='96322e986870e29d30d746d2d52e15fe' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1904 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1905, 'ruRU', 'Несколько воинов, оставшихся в Строме, решили и дальше защищать древние стены. Стром более не был центром империи, но он превратился в новое государство – Стромгард. Хотя каждый город-государство сам по себе процветал, империя Аратор практически распалась. Каждое государство завело свои собственные обычаи и верования, и они начали все больше отдаляться друг от друга. Мечта короля Торадина об объединении человечества развеялась.' FROM `page_text` WHERE `ID`=1905 AND MD5(`Text`)='d7e2405dd87ea701d45cea9c398e6229' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1905 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1906, 'ruRU', 'Пока политические споры и соперничество семи людских государств разгорались и утихали, Хранители постоянно оставались на страже в своей войне против хаоса. За годы сменилось немало Хранителей. Одна из последних Хранителей того времени прославилась как могучая воительница, отважно противостоявшая тьме.' FROM `page_text` WHERE `ID`=1906 AND MD5(`Text`)='00048c914cc71dc3a78531de33ca2136' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1906 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1907, 'ruRU', 'Эгвин, девушка из народа людей, заслужила одобрение Ордена и получила титул Хранителя. Эгвин эффективно выслеживала и уничтожала демонов, но она очень часто подвергала сомнениям действия патриархального совета Тирисфаля.' FROM `page_text` WHERE `ID`=1907 AND MD5(`Text`)='6ac9abbc194b488171b0d71893e2d540' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1907 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1908, 'ruRU', 'Она верила, что древние эльфы и люди-старейшины, возглавлявшие совет, были слишком непреклонны в своих решениях и не смотрели в будущее достаточно далеко, чтобы положить конец войне против хаоса. Раздраженная слишком долгим обсуждением и дебатами, она жаждала показать своим завистникам и старшим по званию, на что она способна, и предпочла храбрость мудрости.' FROM `page_text` WHERE `ID`=1908 AND MD5(`Text`)='4fd3ba421ad0a93666c6c2b327c77b76' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1908 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1909, 'ruRU', 'Власть Эгвин над космическими силами Тирисфаля росла, и однажды она узнала, что на ледяном северном континенте Нордскол обитает несколько могущественных демонов. Отправившись на дальний север, Эгвин выследила демонов в горах. Там она обнаружила, что демоны охотились на последних драконов и вытягивали из древних существ их магическую силу.' FROM `page_text` WHERE `ID`=1909 AND MD5(`Text`)='081b837b4bdcc682810f9df9e6f54137' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1909 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1910, 'ruRU', 'Могучие драконы, бежавшие от быстро распространявшихся по миру людей, обнаружили, что они не могут противостоять могуществу темной магии Легиона. Эгвин сразилась с демонами и с помощью благородных драконов победила их. Но как только последний демон был изгнан из мира, ужасная буря разразилась на севере.' FROM `page_text` WHERE `ID`=1910 AND MD5(`Text`)='b7a4729241ed0b963a510f5bf898c74f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1910 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1911, 'ruRU', 'Огромная тень появилась в небе Нордскола. Саргерас, король демонов и повелитель Пылающего Легиона, явился перед Эгвин, горя адским пламенем. Он сказал юной Хранительнице, что время Тирисфаля истекло и мир скоро падет перед натиском Легиона.' FROM `page_text` WHERE `ID`=1911 AND MD5(`Text`)='c427f8aa9c13d7b61d4accdb5e78b235' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1911 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1912, 'ruRU', 'Гордая Эгвин, веря, что она сможет противостоять грозному богу, использовала свои силы против аватары Саргераса. С необыкновенной легкостью Эгвин одолела лорда демонов и убила его физическую оболочку. Опасаясь, что дух Саргераса выжил, наивная Эгвин сокрыла изуродованные останки в одном из древних дворцов Калимдора, утонувшего в море во время разрушения Источника Вечности.' FROM `page_text` WHERE `ID`=1912 AND MD5(`Text`)='b25c00859b8b3397511f7b4e387cac29' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1912 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1913, 'ruRU', 'Эгвин никогда так и не узнала, что она поступила именно так, как хотел Саргерас. Она неосознанно подписала приговор смертному миру, так как Саргерас во время своей физической смерти вселился духом в ослабленное тело Эгвин. Без ведома юной Хранительницы Саргерас оставался скрытым в темных уголках ее души многие годы.' FROM `page_text` WHERE `ID`=1913 AND MD5(`Text`)='db2c687ca0d2cc920ba9c32325bbbc7e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1913 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1914, 'ruRU', 'Дворфы Стальгорна многие века жили в спокойствии. Но их стало слишком много, им перестало хватать места в подземных городах. И хотя могучий король Модимус Старая Наковальня правил всеми дворфами мудро и справедливо, три мощные фракции появились в обществе дворфов.' FROM `page_text` WHERE `ID`=1914 AND MD5(`Text`)='d64888dcead589850497ca20355618a5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1914 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1915, 'ruRU', 'Клан Бронзобородов под управлением тана Мадорана Бронзоборода имел хорошие связи с королем и был защитником Стальгорна. Клан Громового Молота, управляемый таном Кардросом Громовым Молотом, населял холмы и утесы у подножья горы и пытался добиться большей власти в городе.' FROM `page_text` WHERE `ID`=1915 AND MD5(`Text`)='fe4580077e6cf6401e5a749e08084101' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1915 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1916, 'ruRU', 'Третья фракция, клан Черного Железа, была под командованием тана-чародея Тауриссана. Дворфы Черного Железа таились в самых глубоких тенях под горой и замышляли заговор против своих собратьев из клана Бронзобородов и клана Громового Молота.' FROM `page_text` WHERE `ID`=1916 AND MD5(`Text`)='21f45230f7adcb6003ede4a631a1be78' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1916 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1917, 'ruRU', 'Некоторое время три фракции поддерживали хрупкий мир, однако напряжение возросло, когда король Старая Наковальня скончался от старости. Три правящих клана вступили в войну за контроль над Стальгорном. Гражданская война дворфов многие годы пылала под землей. В конце концов клан Бронзобородов, имевший самую большую армию, изгнал кланы Черного Железа и Громового Молота из-под горы.' FROM `page_text` WHERE `ID`=1917 AND MD5(`Text`)='7663d72df6c52f03e70fe4202a076d6b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1917 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1918, 'ruRU', 'Кардрос и воины Громового Молота отправились на север через пограничные ворота Дун Альгаз и основали свое собственное королевство под далекой горой Грим Батол. Там Громовые Молоты разбогатели и построили новые сокровищницы. Тауриссан и другие члены клана Черного Железа не были столь же удачливы. Униженные и разгневанные своим поражением, они поклялись отомстить Стальгорну. Уведя своих сородичей далеко на юг, Тауриссан основал город (названный в свою честь) под прекрасным Красногорьем.' FROM `page_text` WHERE `ID`=1918 AND MD5(`Text`)='8fbb7ed10338339a85819af0e4792f60' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1918 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1919, 'ruRU', 'Процветание и прошедшие годы не уменьшили ненависти клана Черного Железа к своим собратьям. Тауриссан и его жена-волшебница Модгуд начали войну на два фронта против Стальгорна и Грим Батола. Клан Черного Железа хотел заполучить весь Каз Модан для себя.' FROM `page_text` WHERE `ID`=1919 AND MD5(`Text`)='3f474de256f5e8825eb19265aab06d71' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1919 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1920, 'ruRU', 'Армии Черного Железа атаковали крепости своих собратьев и практически захватили оба королевства. Но Мадоран Бронзобород в конце концов привел свой клан к окончательной победе над колдовской армией Тауриссана. Тауриссан и его слуги бежали в свой безопасный город, не зная о том, что происходило в Грим Батоле, где армия Модгуд тоже не особо успешно сражалась с Кардросом и его воинами из клана Громового Молота.' FROM `page_text` WHERE `ID`=1920 AND MD5(`Text`)='c52ba43d22fc66b6ffdfadf93445852e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1920 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1921, 'ruRU', 'Столкнувшись с вражескими воинами, Модгуд использовала свои силы, чтобы вселить страх в их сердца. Тени двигались по ее команде, и темные существа вылезали из глубин земли, нападая на Громовых Молотов в их собственных дворцах. В конце концов Модгуд прорвалась через ворота и осадила саму крепость. Громовые Молоты сражались отчаянно, сам Кардрос был среди воинов, желая убить королеву-колдунью.' FROM `page_text` WHERE `ID`=1921 AND MD5(`Text`)='38ecd72af85c7acfae1b025e52446812' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1921 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1922, 'ruRU', 'Потеряв свою королеву, воины клана Черного Железа бежали от ярости Громовых Молотов. Они бежали на юг, к крепости своего короля, но столкнулись с армией Стальгорна, пришедшей помочь Грим Батолу. Зажатые между двух армий, силы Черного Железа были полностью уничтожены.' FROM `page_text` WHERE `ID`=1922 AND MD5(`Text`)='919a249e4a96b36b7d5114b094fe8bab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1922 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1923, 'ruRU', 'Объединенные армии Стальгорна и Грим Батола отправились на юг с целью уничтожить Тауриссана и клан Черного Железа раз и навсегда. Они не успели далеко уйти, когда гнев Тауриссана вызвал заклинание, приведшее к катаклизму. Желая призвать сверхъестественное существо, которое поможет ему победить, Тауриссан призвал древние силы, спавшие в глубинах мира, и к своему ужасу он обнаружил, что появившееся существо было ужаснее самых страшных ночных кошмаров.' FROM `page_text` WHERE `ID`=1923 AND MD5(`Text`)='c728aec42543123449e2a352b775718a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1923 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1924, 'ruRU', 'Это был Рагнарос – Повелитель Огня, бессмертный повелитель всех элементалей огня, изгнанный титанами, когда мир еще был юн. Теперь, освобожденный призывом Тауриссана, Рагнарос явился вновь. Возрождение Рагнароса в Азероте сотрясло Красногорье, и посреди руин воздвигся огромный вулкан.' FROM `page_text` WHERE `ID`=1924 AND MD5(`Text`)='43744557cee89e42db040a2126a15049' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1924 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1925, 'ruRU', 'Вулкан, известный как Черная гора, был окружен Выжженной тесниной с севера и Пылающими степями с юга. И хотя Тауриссан был убит силами, которые он призвал, его выжившие собратья были полностью порабощены Рагнаросом и его элементалями. До сих пор они остаются в глубинах Черной горы.' FROM `page_text` WHERE `ID`=1925 AND MD5(`Text`)='0d27066dd5955f8843c339ebec503995' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1925 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1926, 'ruRU', 'Увидев ужасное разрушение и огонь, распространившийся по южным горам, король Мадоран и король Кардрос остановили свои армии и спешно вернулись назад в свои королевства, не желая пасть жертвами ужасного гнева Рагнароса.' FROM `page_text` WHERE `ID`=1926 AND MD5(`Text`)='c00d43cd4c921f1866311e32fde57bd2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1926 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1927, 'ruRU', 'Клан Бронзобородов вернулся в Стальгорн и восстановил свой славный город. Громовой Молот также вернулся домой, в Грим Батол. Но смерть Модгуд осквернила крепость, и дворфы Громового Молота не могли уже там жить.' FROM `page_text` WHERE `ID`=1927 AND MD5(`Text`)='fa69bbaa8589b0c9e8d43f398b8a87c0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1927 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1928, 'ruRU', 'Горечь потери своего дома ожесточила их сердца. Король Бронзобород предложил дворфам Громового Молота место, где они бы могли жить в границах Стальгорна, но они отказались. Кардрос повел свой народ на север к землям Лордерона. Поселившись в буйно зеленеющих лесах Внутренних земель, клан Громового Молота построил город Заоблачный пик, где дворфы стали ближе к природе и даже приручили могучих грифонов, живших там.' FROM `page_text` WHERE `ID`=1928 AND MD5(`Text`)='946fbc22b01e4215609c4a4ac35700b9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1928 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1929, 'ruRU', 'Желая восстановить отношения и торговлю со своими собратьями, дворфы Стальгорна построили две огромные арки, называемые Мост Тандола, между Каз Моданом и Лордероном. Поддерживаемые обоюдной торговлей, два королевства процветали. После смерти Мадорана и Кардроса их сыновья вместе построили две большие статуи в честь своих отцов.' FROM `page_text` WHERE `ID`=1929 AND MD5(`Text`)='8cdd220e299e7798df47a3bfd84a51ca' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1929 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1930, 'ruRU', 'Две статуи должны были стоять на страже прохода в южные земли, покрытого застывшей лавой из-за близости всесжигающего Рагнароса. Они служили не только грозным предупреждением всем тем, кто решится напасть на дворфийские королевства, но также и напоминанием о цене, которую клан Черного Железа заплатил за свои преступления.' FROM `page_text` WHERE `ID`=1930 AND MD5(`Text`)='53cc24c373344763d97862e3527aafb0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1930 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1931, 'ruRU', 'Два королевства некоторое время поддерживали довольно тесную связь, но на клан Громового Молота слишком сильно повлияли ужасы, свидетелями которых дворфы стали у Грим Батола. Вместо того чтобы создать огромное подземное царство, они обжили склоны Заоблачного пика. Идеологические различия между двумя оставшимися кланами дворфов в конце концов привели к отчуждению.' FROM `page_text` WHERE `ID`=1931 AND MD5(`Text`)='d987aea2702492778251467798e94af1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1931 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1932, 'ruRU', 'Хранительница Эгвин с течением времени становилась все могущественнее, используя энергии Тирисфаля, чтобы продлить свою жизнь. Самоуверенно надеясь, что она победила Саргераса, она продолжала охранять мир от приспешников короля демонов почти девятьсот лет. Но в конце концов Совет Тирисфаля объявил, что время ее службы подошло к концу.' FROM `page_text` WHERE `ID`=1932 AND MD5(`Text`)='12abc3c596ff6919283311acca547011' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1932 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1934, 'ruRU', 'Гордая Эгвин хотела родить сына, которому она передаст свою силу. Она не хотела, чтобы Тирисфальский орден манипулировал ее преемником так же, как они пытались манипулировать ей. Отправившись в южное государство Азерот, Эгвин нашла идеального мужчину, который мог бы стать отцом ее сына – искусного человека-мага по имени Ниелас Аран.' FROM `page_text` WHERE `ID`=1934 AND MD5(`Text`)='ed09ef810b26ef6e2a9266aaad69dec8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1934 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1940, 'ruRU', 'Вернувшись к жизни, он обнаружил, что уже повзрослел, а его друзья Ллейн и Андуин стали правителями Азерота. Он желал использовать обретенные силы на благо своей родной земли, но злой дух Саргераса овладел его разумом и направил его на путь злодеяний.' FROM `page_text` WHERE `ID`=1940 AND MD5(`Text`)='8dee8c9b8779f3b31f6a40c4a01d8dc9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1940 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1941, 'ruRU', 'Сердце Медива заполняла тьма, и Саргерас был доволен: почти все было готово для его повторного вторжения в этот мир, а последний Страж должен был помочь ему с легкостью осуществить все свои планы.' FROM `page_text` WHERE `ID`=1941 AND MD5(`Text`)='b4aecdbffeb8e9e5a62272e0f2a10c63' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1941 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1942, 'ruRU', 'Когда на Азероте родился Медив, Кил\'джеден Искуситель и его последователи из Круговерти Пустоты погрузились в размышления. По приказу своего хозяина Саргераса, коварный великий демон готовил зловещие планы по захвату Пылающим Легионом Азерота.' FROM `page_text` WHERE `ID`=1942 AND MD5(`Text`)='5848383fbe7a2b43cda430a229fcd62d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1942 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1943, 'ruRU', 'На этот раз не должно было быть никаких ошибок. Кил\'джеден решил, что нужно ослабить оборону Азерота еще до того, как Легион ступит на его земли. Расы смертных, такие как ночные эльфы и драконы, занятые борьбой с новым врагом, были бы уже неспособны противостоять нашествию Легиона.' FROM `page_text` WHERE `ID`=1943 AND MD5(`Text`)='163225880c2b08726fca22ad7996dc2e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1943 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1944, 'ruRU', 'Именно тогда Кил\'джеден обнаружил покрытый густыми зарослями мир Дренора, который мирно парил по бескрайним просторам Великой запредельной тьмы. Дренор, родина поклонявшихся духам орков и миролюбивых дренеев, был миром настолько же безмятежным и тихим, насколько бескрайним.' FROM `page_text` WHERE `ID`=1944 AND MD5(`Text`)='84cdc9b6daea69834993159fa3e06c88' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1944 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1945, 'ruRU', 'Благородные кланы орков странствовали по необъятным степям и охотились – больше ради развлечения, а дренеи начинали возводить города среди скал и горных вершин. Кил\'джеден решил, что, приложив немного усилий, из жителей Дренора можно сделать превосходных солдат для Пылающего Легиона.' FROM `page_text` WHERE `ID`=1945 AND MD5(`Text`)='7cf94c2a22b5c159e15e1e4c3a7a764f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1945 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1946, 'ruRU', 'Из двух рас Кил\'джеден выбрал воинственных орков: их было легче привлечь под знамена Легиона. Он околдовал главного шамана орков Нер\'зула точно так же, как много лет назад Саргерас подчинил своей воле королеву Азшару. Коварный шаман стал исполнителем воли демона, пробуждая в орках жестокость и жажду сражения.' FROM `page_text` WHERE `ID`=1946 AND MD5(`Text`)='4617876508581cc2130a45669016e359' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1946 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1947, 'ruRU', 'Вскоре он превратил эту миролюбивую расу в жестоких, кровожадных воинов. Нер\'зулу и его народу оставалось сделать последний роковой шаг: стать вестниками смерти, полностью посвятив себя войне. Но старый шаман понял, что для орков это означало вечное рабство, и ему удалось не поддаться воле демона.' FROM `page_text` WHERE `ID`=1947 AND MD5(`Text`)='65fe03c01aae03d4865701ed773b3c21' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1947 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1948, 'ruRU', 'Кил\'джедена разозлила непокорность Нер\'зула, и он стал искать другого орка, который смог бы заставить свой народ присоединиться к Легиону. Хитрому великому демону удалось-таки найти достойного кандидата – им стал тщеславный ученик Нер\'зула, Гул\'дан. Кил\'джеден пообещал ему невиданную силу в обмен на полное повиновение.' FROM `page_text` WHERE `ID`=1948 AND MD5(`Text`)='a18872690cfc0088fe125e250f1df5d0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1948 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1949, 'ruRU', 'Юный орк охотно согласился быть учеником демона и вскоре стал одним из самых могущественных смертных волшебников в истории. Он учил других орков темным искусствам и пытался искоренить их древние ритуалы. Гул\'дан показал своим братьям волшебство, которое никто из них никогда не видел, ужасающую мощь, способную повсюду сеять смерть.' FROM `page_text` WHERE `ID`=1949 AND MD5(`Text`)='7ffaf8b412fd4254f55d2181a37cc327' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1949 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1950, 'ruRU', 'Стремясь укрепить свою власть над орками, Кил\'джеден помог Гул\'дану основать тайную секту под названием Совет Теней, чтобы манипулировать кланами и разносить по Дренору слухи о новой колдовской силе. Все больше орков овладевали искусством наложения чар, и безмятежные просторы Дренора окутывал мрак. Со временем бескрайние степи, служившие домом для орков не одно поколение, поблекли и превратились в безжизненные пустоши. Энергия демона медленно убивала этот мир.' FROM `page_text` WHERE `ID`=1950 AND MD5(`Text`)='f2b51ce8c670f231a4c157cd60836356' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1950 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1951, 'ruRU', 'Под контролем Гул\'дана и Совета Теней орки стали грубыми и жестокими. Они построили огромные арены, где соревновались друг с другом в умении сражаться и убивать. В это время вожди некоторых кланов решили высказать свое негодование по поводу упадка их расы.' FROM `page_text` WHERE `ID`=1951 AND MD5(`Text`)='c98cfe41f635c370ceb7deb8df4d48df' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1951 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1952, 'ruRU', 'Одним из таких вождей был Дуротан из клана Северного Волка; он указал оркам на то, что они начали терять контроль над собой и поддаваться гневу и ненависти. Но они были глухи к его предостережениям, да и многие более могущественные вожди, среди которых был Гром Адский Крик из клана Песни Войны, выступили в поддержку новой эры войны и господства.' FROM `page_text` WHERE `ID`=1952 AND MD5(`Text`)='2122edcd6e88e77d03fff0417a79f0df' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1952 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1954, 'ruRU', 'Во главе с Громом Адским Криком все вожди, кроме Дуротана, повиновались и тем самым обрекли себя на вечную службу Пылающему Легиону. Те, кого коснулась ярость Маннорота, пусть не желая того, превратили своих ничего не подозревающих собратьев в таких же рабов, какими стали сами.' FROM `page_text` WHERE `ID`=1954 AND MD5(`Text`)='69786ec597d13ad8cd41da07cb3aadc2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1954 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1955, 'ruRU', 'Орки были обречены на вечную неутолимую жажду крови и обрушивали свою ярость на любого, кто стоял у них на пути. Гул\'дан почувствовал, что время пришло, и объединил воюющие кланы в одну неудержимую Орду.' FROM `page_text` WHERE `ID`=1955 AND MD5(`Text`)='91fb77f8abbc3fac8838c0b35cc69238' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1955 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1956, 'ruRU', 'Но зная, что все вожди, в первую очередь Адский Крик и Оргрим Молот Рока, начнут борьбу за превосходство, Гул\'дан поставил во главу Орды своего вождя-марионетку. На эту роль он выбрал Чернорука Разрушителя, злобного и жестокого орка. Под командованием Чернорука Орда выдвинулась в первый пробный бой против дренеев.' FROM `page_text` WHERE `ID`=1956 AND MD5(`Text`)='66e311902e3f6736718e3500c7325a2a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1956 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1957, 'ruRU', 'Через несколько месяцев Орда истребила почти всех дренеев, живших на Дреноре. Лишь немногие сумели избежать гнева орков. Гул\'дан был доволен: его Орда была непобедима. Но он знал, что если им будет не с кем сражаться, непреодолимая жажда крови заставит их убивать друг друга и войско уничтожит само себя.' FROM `page_text` WHERE `ID`=1957 AND MD5(`Text`)='f00a823ba894cb577d4046f8c6ca79a0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1957 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1958, 'ruRU', 'Кил\'джеден знал, что Орда, наконец, готова. Орки стали мощнейшей силой Пылающего Легиона. Коварный демон рассказал обо всем своему повелителю, и Саргерас согласился, что час расплаты настал.' FROM `page_text` WHERE `ID`=1958 AND MD5(`Text`)='48d0aebe86fae7fbb1d0c923c9e3138c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1958 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1959, 'ruRU', 'Кил\'джеден подготавливал Орду к нападению на Азерот, а Медив в это время продолжал сражаться с Саргерасом за свою душу. Король Ллейн, благородный правитель Штормграда, узнал о том, что тьма завладела душой его бывшего друга.' FROM `page_text` WHERE `ID`=1959 AND MD5(`Text`)='2145fabd2aaa29bd7ebf6bd458cdf4a4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1959 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1960, 'ruRU', 'Король Ллейн рассказал об этом Андуину Лотару, последнему потомку рода Арати, которого он сделал своим военачальником. Но никто из них не мог предположить, что беда, случившаяся с Медивом, станет причиной столь ужасных событий.' FROM `page_text` WHERE `ID`=1960 AND MD5(`Text`)='c90d4946edb53ebeee641bc225ff4b64' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1960 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1961, 'ruRU', 'В качестве последней награды Саргерас пообещал Гул\'дану огромную силу в обмен на его согласие повести Орду на Азерот. Через Медива Саргерас сказал чернокнижнику, что может сделать его богом во плоти, если тот найдет подводную могилу, в которой Страж Эгвин тысячу лет назад укрыла останки Саргераса.' FROM `page_text` WHERE `ID`=1961 AND MD5(`Text`)='8c89d36971d80e25fd173b870a3a2941' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1961 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1962, 'ruRU', 'Гул\'дан согласился сделать это и решил, что, как только Азерот будет повержен, он направится на поиски легендарной могилы и получит свою награду. Саргерас, уверенный в том, что Орда будет покорно служить ему, приказал начать вторжение.' FROM `page_text` WHERE `ID`=1962 AND MD5(`Text`)='03ea63db4b4d5606ae6a7895df895bc3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1962 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1963, 'ruRU', 'Общими усилиями Медив и волшебники Совета Теней открыли портал межу измерениями – Темный портал. Этот портал позволил армии Дренора попасть на Азерот. Гул\'дан послал через портал разведчиков, чтобы они исследовали земли, которые им предстояло завоевать. Вернувшись, они доложили Совету Теней, что можно начать вторжение.' FROM `page_text` WHERE `ID`=1963 AND MD5(`Text`)='c144473d5b308a68a5721dbf84c6a3d0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1963 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1964, 'ruRU', 'Дуротан, по-прежнему уверенный в том, что Гул\'дан приведет их народ к гибели, снова высказался против действий волшебников. Храбрый воин сказал, что они уничтожили чистый дух орков и что это безрассудное нападение на Азерот погубит их всех. Гул\'дан не мог пойти на риск, убив любимого всеми героя, и был вынужден отправить Дуротана вместе с его кланом Северного Волка в самые отдаленные области нового мира.' FROM `page_text` WHERE `ID`=1964 AND MD5(`Text`)='36390156e35d97b96649be8c551a6e2f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1964 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1966, 'ruRU', 'Хотя битвы с людьми заканчивались довольно быстро, обе расы успели выяснить сильные и слабые стороны соперников. Ллейну и Лотару не удавалось получить точные сведения о численности орков, и они могли лишь догадываться о том, насколько могуч был их противник.' FROM `page_text` WHERE `ID`=1966 AND MD5(`Text`)='890ed052268d8d6959caadaf024a1045' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1966 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1967, 'ruRU', 'Через несколько лет большая часть Орды перебралась на Азерот, и Гул\'дан решил, что настало время нанести сокрушительный удар по человечеству. Орда обрушила всю свою мощь на ничего не подозревающих жителей королевства Штормград.' FROM `page_text` WHERE `ID`=1967 AND MD5(`Text`)='7d7212981ce2d9629c8ddf1e58de77ab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1967 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1968, 'ruRU', 'В то время как жители Азерота и Орда бились друг с другом по всему королевству, внутри обеих армий разгорались конфликты. Король Ллейн, убежденный в том, что звероподобные орки не в состоянии завоевать Азерот, упрямо отказывался покидать столицу Штормграда; Лотар же был уверен, что бой следует перенести на территорию, занятую противником, так что ему пришлось выбирать между своими убеждениями и верностью королю.' FROM `page_text` WHERE `ID`=1968 AND MD5(`Text`)='c8775b78d35f16a4b79e9b4b39b26361' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1968 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1969, 'ruRU', 'Лотар решил последовать своим инстинктам и, заручившись поддержкой ученика Медива – Кадгара, – пошел на штурм крепости волшебника – Каражана. Кадгару и Лотару удалось победить Стражника, которого они считали причиной всей войны.' FROM `page_text` WHERE `ID`=1969 AND MD5(`Text`)='31912ca8f8e5bd6e42565c0ac7d7d08b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1969 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1970, 'ruRU', 'Убив тело Медива, Лотар и юный Кадгар, сами того не зная, изгнали дух Саргераса в бездну. А праведный дух Медива остался жив… и долгие годы скитался по астральному миру.' FROM `page_text` WHERE `ID`=1970 AND MD5(`Text`)='f9ad5aeccbd37c0b19a48b3d652f15e3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1970 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1971, 'ruRU', 'Хотя Медив был повержен, Орда по-прежнему брала верх над защитниками Штормграда. Но когда победа была уже у Орды в руках, один из самых могучих вождей орков, Оргрим Молот Рока, стал понимать, насколько изменились некогда миролюбивые кланы, жившие на Дреноре.' FROM `page_text` WHERE `ID`=1971 AND MD5(`Text`)='aed2a9f272fea1a633f56c00bb224afd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1971 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1973, 'ruRU', 'Оргрим, разгневанный убийством Дуротана, решил освободить Орду от ужасного проклятья и, чтобы стать новым вождем Орды, убил Чернорука, марионетку Гул\'дана. Под его твердым руководством безжалостная Орда наконец окружила Крепость Штормграда.' FROM `page_text` WHERE `ID`=1973 AND MD5(`Text`)='3a8e695b8b6f72960a6c5a247f06e955' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1973 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1974, 'ruRU', 'Король Ллейн сильно недооценил мощь Орды и мог лишь беспомощно смотреть на то, как его королевство рассыпалось под натиском зеленокожих захватчиков. Вскоре и сам король был убит одним из лучших наемных убийц Совета Теней, полуорком Гароной.' FROM `page_text` WHERE `ID`=1974 AND MD5(`Text`)='64aec0231ee43800b3efdc14b0c0b95d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1974 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1975, 'ruRU', 'Лотар и его войны, возвращавшиеся из Каражана, надеялись остановить кровопролитие и спасти свою некогда славную родину. Но было слишком поздно: когда они вернулись, их королевство лежало в руинах. Орда опустошала деревни и захватывала близлежащие земли. Лотар и его войско, вынужденные скрываться от врагов, поклялись вернуть свою родину любой ценой.' FROM `page_text` WHERE `ID`=1975 AND MD5(`Text`)='2189706a38890e4c5233c371551b0114' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1975 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1976, 'ruRU', 'После битвы в Крепости Штормграда лорд Лотар собрал остатки армий Азерота и организовал отступление к берегам северного королевства Лордерона. Главы семи человеческих народов решили, что если Орду не остановить, то она уничтожит все человечество, и создали союз, позже получивший название Лордеронский Альянс.' FROM `page_text` WHERE `ID`=1976 AND MD5(`Text`)='c989e9f6cedc85a95333a69822484312' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1976 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1977, 'ruRU', 'В первый раз за почти три тысячи лет разрозненные народы Аратора объединились под одним знаменем. Лорд Лотар был назначен главнокомандующим войск Альянса и начал подготовку своих воинов к нашествию Орды.' FROM `page_text` WHERE `ID`=1977 AND MD5(`Text`)='4abc9655aec7812428418351cbd4cccd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1977 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1978, 'ruRU', 'При поддержке своих помощников Утера Светоносного, адмирала Даэлина Праудмура и Туралиона, Лотар убедил получеловеческие народы Лордерона в необходимости противостоять надвигающемуся вторжению. Альянс также смог заручиться поддержкой дворфов из Стальгорна и некоторых высших эльфов из Кель\'Таласа.' FROM `page_text` WHERE `ID`=1978 AND MD5(`Text`)='5f913ee5629a86a76facca4f0fc69bc9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1978 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1979, 'ruRU', 'Эльфы под предводительством Анастериана Солнечного Скитальца не хотели вмешиваться в предстоящий конфликт. Но они не могли отказать Лотару – последнему из рода Арати, который поддерживал их в прошлом.' FROM `page_text` WHERE `ID`=1979 AND MD5(`Text`)='2ae0380b3dec82bebbf87830706d12d1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1979 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1980, 'ruRU', 'Орда под предводительством вождя Молота Рока привела под свои знамена огров из родного Дренора и лесных троллей Амани. Продолжая свое наступление, Орда легко подавила сопротивление дворфов из королевства Каз Модан и южных областей Лордерона.' FROM `page_text` WHERE `ID`=1980 AND MD5(`Text`)='1537d94eb219e0bbf67427d448681f8f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1980 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1981, 'ruRU', 'Грандиозные битвы Второй войны сотрясали море и воздух. Каким-то образом Орде удалось завладеть могущественным артефактом – Душой Демона – и с его помощью подчинить себе Алекстразу, древнюю королеву драконов. Угрожая уничтожить отложенные ею яйца, Орда заставила Алекстразу отправить своих детей на войну. Благородные красные драконы были вынуждены сражаться на стороне Орды, и сражались они превосходно.' FROM `page_text` WHERE `ID`=1981 AND MD5(`Text`)='7e767eab3c9fd3f49a09b1aa13a8689e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1981 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1982, 'ruRU', 'Война бушевала на просторах Каз Модана, Лордерона и самого Азерота. Свирепая Орда сожгла дотла пограничные земли Кель\'Таласа, после чего эльфы наконец-таки присоединились к Альянсу. Война разрушила и разорила некогда процветавшие города Лордерона. Несмотря на превосходящие силы врага, Лотар и его союзники сумели сдержать наступление Орды.' FROM `page_text` WHERE `ID`=1982 AND MD5(`Text`)='5df0733a2092dd9f6acd3292df7ff119' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1982 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1983, 'ruRU', 'Но в последние дни Второй войны, когда победа Орды казалась уже неизбежной, между двумя самыми могучими орками Азерота возникли небывалые раздоры. Когда Молот Рока готовился к решающей атаке на столицу Лордерона, которая должна была сокрушить последние силы Альянса, Гул\'дан и его сторонники покинули остальное войско и отправились в море.' FROM `page_text` WHERE `ID`=1983 AND MD5(`Text`)='fe21dc4edf2721084bd6120e45780b5d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1983 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1984, 'ruRU', 'Из-за предательства Гул\'дана Молот Рока потерял почти половину своих воинов и был вынужден отступить, выпустив из рук столь близкую победу.' FROM `page_text` WHERE `ID`=1984 AND MD5(`Text`)='a6967536aa6d8f6ad95cc9bdfd71eaa5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1984 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1985, 'ruRU', 'Жаждавший могущества, Гул\'дан отправился на поиски подводной Гробницы Саргераса, где он надеялся раскрыть тайну абсолютной силы. Гул\'дан уже обрек своих воинов на вечное рабство в Пылающем Легионе и о своем долге перед Молотом Рока он беспокоился меньше всего.' FROM `page_text` WHERE `ID`=1985 AND MD5(`Text`)='1618cc73e0f031f4b94aba78d35452a8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1985 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1986, 'ruRU', 'С помощью кланов Бушующего Шторма и Сумеречного Молота Гул\'дану удалось поднять Гробницу Саргераса с морского дна. Но когда он открыл древний склеп, его встретили полчища обезумевших демонов.' FROM `page_text` WHERE `ID`=1986 AND MD5(`Text`)='1787788bba9860c7ed19928731f4dfed' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1986 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1987, 'ruRU', 'Молот Рока желал наказать своенравных орков за столь дерзкое предательство и послал своих воинов убить Гул\'дана и вернуть остальных изменников. Обезумевшие демоны, которых столь опрометчиво освободил Гул\'дан, разорвали его на клочки. Потеряв своего командира, воины тотчас сдались на милость войска Молота Рока.' FROM `page_text` WHERE `ID`=1987 AND MD5(`Text`)='c7807cf602c83f2e920ba628df8c2c58' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1987 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1988, 'ruRU', 'Несмотря на то что восстание было подавлено, Орде не удалось оправиться от ужасных потерь. Предательство Гул\'дана не только придало Альянсу уверенности, но и обеспечило им время на перегруппировку и подготовку к ответной атаке.' FROM `page_text` WHERE `ID`=1988 AND MD5(`Text`)='407b7ee9c38441d0e51c6f15ad7b7c47' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1988 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1989, 'ruRU', 'Видя, что Орда раскалывается изнутри, лорд Лотар собрал последние силы и отбросил Молота Рока на юг, к центру Штормграда. Там войска Альянса окружили Орду в вулканической крепости пика Черной горы. Лотар пал в этой битве, но один из его командиров, Туралион, в последний момент взял на себя командование войском и заставил Орду отступить к бескрайнему Болоту Печали.' FROM `page_text` WHERE `ID`=1989 AND MD5(`Text`)='65c9f85d58e61650b0d88333c6d63fd9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1989 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1990, 'ruRU', 'Войскам Туралиона удалось уничтожить Темный портал – волшебный портал в родной мир орков, Дренор. Орда, лишенная подкрепления и разрываемая на части внутренней враждой, наконец, пала перед мощью Альянса.' FROM `page_text` WHERE `ID`=1990 AND MD5(`Text`)='4623811b4e00cce91650bfdcd05e2df0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1990 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1991, 'ruRU', 'Орки со всего мира были собраны вместе и помещены в лагеря для военнопленных. Но, хотя с Ордой было покончено, многие сомневались, что мир удастся сохранить надолго. Кадгар, ставший верховным магом, убедил глав Альянса построить Крепость Стражей Пустоты, чтобы охранять руины Темного портала и не допустить повторного вторжения из Дренора.' FROM `page_text` WHERE `ID`=1991 AND MD5(`Text`)='37151d6493fd343fca2124925db894a0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1991 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1992, 'ruRU', 'Когда последние очаги войны были ликвидированы, Альянс предпринял жесткие меры для предотвращения угрозы со стороны орков. На юге Лордерона были построены несколько лагерей специально для пленных орков. Лагеря, охраняемые паладинами и опытными воинами Альянса, успешно справились со своей задачей.' FROM `page_text` WHERE `ID`=1992 AND MD5(`Text`)='5b3595e3ab4cfc75032fbee67aa831f7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1992 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1993, 'ruRU', 'Пленные орки жаждали сражений, но начальники лагерей, обосновавшиеся в крепости-тюрьме Дарнхольде, поддерживали среди них видимость порядка и спокойствия.' FROM `page_text` WHERE `ID`=1993 AND MD5(`Text`)='ba19ba3c229c52c2cd0cdd286e20d54e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1993 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1994, 'ruRU', 'Тем временем в дьявольском мире Дренора новая армия орков готовилась к нападению на ничего не подозревающий Альянс. Бывший наставник Гул\'дана Нер\'зул собирал оставшиеся кланы орков под своими знаменами. С помощью клана Призрачной Луны он намеревался открыть на Дреноре несколько порталов, позволяющих Орде проникнуть в новые нетронутые миры.' FROM `page_text` WHERE `ID`=1994 AND MD5(`Text`)='7464f2007f32c9fec9fdfcf7dccb901b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1994 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1995, 'ruRU', 'Чтобы добыть энергию, необходимую для порталов, ему нужно было несколько мощных артефактов с Азерота. Нер\'зул снова открыл Темный портал и послал туда своих верных слуг, чтобы они нашли эти артефакты.' FROM `page_text` WHERE `ID`=1995 AND MD5(`Text`)='3612580e810bb6aba9fd6ae86597e7c4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1995 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1996, 'ruRU', 'Новая Орда, возглавляемая такими опытными вождями, как Гром Адский Крик и Килрогг Мертвый Глаз (из клана Кровавой Глазницы), застала врасплох войска Альянса и напала на близлежащие деревни. Под командованием Нер\'зула орки быстро добыли нужные артефакты и вернулись обратно на Дренор.' FROM `page_text` WHERE `ID`=1996 AND MD5(`Text`)='88bc8dbec3bd6b89e731c923e61c5c43' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1996 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1997, 'ruRU', 'Король Лордерона Теренас, уверенный в том, что орки готовят новое нашествие, созвал к себе своих самых преданных военачальников. Он приказал генералу Туралиону и верховному магу Кадгару, возглавить поход сквозь Темный портал, чтобы раз и навсегда разделаться с орками. Силы Туралиона и Кадгара вторглись в Дренор и вступили в сражение с войсками Нер\'зула на Полуострове Адского Пламени.' FROM `page_text` WHERE `ID`=1997 AND MD5(`Text`)='a4a27cbbd21a0666424b6659fae45818' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1997 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1998, 'ruRU', 'Но даже при поддержке высшего эльфа Аллерии Ветрокрылой, дворфа Курдрана Громового Молота и опытного воина Даната Троллебоя Кадгар не смог помешать Нер\'зулу открыть порталы в другие миры.' FROM `page_text` WHERE `ID`=1998 AND MD5(`Text`)='4303e433de69a0245b28521aeb0e4bfa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1998 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 1999, 'ruRU', 'Нер\'зулу, наконец, удалось открыть порталы, но он даже не предполагал, какую цену придется за это заплатить. Колоссальная энергия порталов начала буквально разрывать Дренор на части. Мир орков рушился, и войска Туралиона отчаянно пытались добраться до портала, чтобы вернуться домой. Гром Адский Крик и Килрогг Мертвый Глаз поняли, что безумные планы Нер\'зула вот-вот погубят весь их народ, и, собрав всех оставшихся орков, отправились искать спасение на Азероте.' FROM `page_text` WHERE `ID`=1999 AND MD5(`Text`)='2f5ed754f80a1352e9fa22899b52a28a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=1999 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2000, 'ruRU', 'Туралион и Кадгар решили героически принести себя в жертву, разрушив Темный портал со стороны Дренора. Их жизни и жизни их воинов – немалая цена за разрушение портала, но они понимали, что это единственный шанс спасти Азерот. Адский Крик и Мертвый Глаз успели пройти через Темный портал навстречу своей свободе, и через мгновение он взорвался за их спинами. Для них и остальных орков на Азероте пути назад больше не было.' FROM `page_text` WHERE `ID`=2000 AND MD5(`Text`)='69f3522a2ab2f6f0fe868895eece079f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2000 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2001, 'ruRU', 'Нер\'зул и верный ему клан Призрачной Луны прошли через самый большой из открытых ими порталов, в то время как извержения вулканов начали разрывать континенты Дренора на части. Кипящие моря вознеслись к небу и обрушились на землю: мир орков исчез во всепоглощающем пламени гигантского взрыва.' FROM `page_text` WHERE `ID`=2001 AND MD5(`Text`)='520334059d1c9c95e4024df0d1e9a4f8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2001 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2002, 'ruRU', 'Нер\'зул и его последователи оказались в Круговерти Пустоты, астральной среде между мирами, разбросанными по Великой запредельной тьме. К несчастью, там его поджидал Кил\'джеден со своими воинами-демонами. Кил\'джеден, поклявшийся отомстить Нер\'зулу за его неповиновение, медленно терзал старого шамана, разрывая на части его тело.' FROM `page_text` WHERE `ID`=2002 AND MD5(`Text`)='eff0023861c7a1a3e8779fa3dd56af4b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2002 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2003, 'ruRU', 'Кил\'джеден не давал духу шамана умереть, заставляя его в полной мере чувствовать ужасную боль, которую ему причинял. Нер\'зул умолял демона послать ему смерть, но тот был непреклонен: он сказал, что Кровавый договор, который они очень давно заключили, все еще в силе, и Нер\'зул еще должен был сослужить демону службу.' FROM `page_text` WHERE `ID`=2003 AND MD5(`Text`)='6014852b57f037525567fad5e1e894af' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2003 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2005, 'ruRU', 'Кил\'джеден поставил беспомощный дух Нер\'зула перед последним выбором между службой Легиону и вечными муками. И вновь Нер\'зул принял условия демона. Кил\'джеден заточил его душу в глыбу прочного как алмаз льда, собранного в самых дальних пределах Круговерти Пустоты.' FROM `page_text` WHERE `ID`=2005 AND MD5(`Text`)='96d2aad3074c2661b7bc9988097ab865' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2005 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2006, 'ruRU', 'Заточенный в ледяной тюрьме Нер\'зул почувствовал, что возможности его разума возросли тысячекратно. Наделенный огромной силой демона, он стал невероятно могущественным духом. В этот момент орк по имени Нер\'зул перестал существовать, и на свет явился Король-лич.' FROM `page_text` WHERE `ID`=2006 AND MD5(`Text`)='dba030f6dae82d5b6cc49ed9432a39c7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2006 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2007, 'ruRU', 'Рыцари смерти и последователи клана Призрачной Луны, верные Нер\'зулу, также подверглись трансформации: их разорвали на части, а затем превратили в костяных Королей Мертвых. Демоны позаботились о том, чтобы даже после смерти последователи Нер\'зула беспрекословно служили ему.' FROM `page_text` WHERE `ID`=2007 AND MD5(`Text`)='9308e49b22507d8d5f16d8a4fca2339e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2007 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2008, 'ruRU', 'Когда пришло время, Кил\'джеден объяснил Королю-личу, зачем тот был создан. Нер\'зул должен был распространить в Азероте смертоносную чуму, которая истребила бы расу людей. Заразившиеся этой чумой умирали и превращались в нежить, отдавая свои души во власть железной воли Нер\'зула.' FROM `page_text` WHERE `ID`=2008 AND MD5(`Text`)='7915c751112d9e6d67127dd7f444626e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2008 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2009, 'ruRU', 'В случае успеха миссии по истреблению людей Кил\'джеден пообещал Нер\'зулу свободу от проклятия и новое здоровое тело.' FROM `page_text` WHERE `ID`=2009 AND MD5(`Text`)='7042995bf279089afa597a1ff649f8bc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2009 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2010, 'ruRU', 'Несмотря на то что Нер\'Зул согласился сыграть свою роль, Кил\'джеден не был уверен в его преданности. Удерживая дух Короля-лича в заточении, демон мог не беспокоиться о его покорности, но, тем не менее, он предпочел не оставлять его без присмотра. Для этого Кил\'джеден приставил к Нер\'Зулу своих лучших демонов-стражников, повелителей ужаса, чтобы те охраняли его и следили за тем, чтобы он выполнил свою жуткую миссию.' FROM `page_text` WHERE `ID`=2010 AND MD5(`Text`)='7f871d6c9ab99d12d37154c7966928af' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2010 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2011, 'ruRU', 'Самому могучему и коварному из повелителю ужаса, Тикондрусу, это задание пришлось по душе: его завораживала смертоносная сила чумы и небывалая мощь Короля-лича.' FROM `page_text` WHERE `ID`=2011 AND MD5(`Text`)='e65bb4d7ede091c22b5e0fd602462895' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2011 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2012, 'ruRU', 'Кил\'джеден отправил Нер\'зула обратно на Азерот. Его ледяная тюрьма пронеслась по ночному небу и упала на заснеженный северный континент Нордскол, погрузившись глубоко в ледник Ледяной Короны. После падения кристалл принял форму трона, а дух Нер\'зула, заключенный в нем, вскоре пробудился.' FROM `page_text` WHERE `ID`=2012 AND MD5(`Text`)='1161e045469e24892686f5d5610a07f2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2012 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2013, 'ruRU', 'Из глубин Ледяного Трона Нер\'зул направил свой могучий разум ко всем обитателям Нордскола. Без особых усилий он подчинил своей воле многих существ, включая ледяных троллей и свирепых вендиго. Силы его духа были практически безграничны, и с их помощью он создал небольшую армию, которую собрал в бесконечных лабиринтах Ледяной Короны.' FROM `page_text` WHERE `ID`=2013 AND MD5(`Text`)='b987bc6d3e397ea563ee19b502a46c43' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2013 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2014, 'ruRU', 'Совершенствуя свои навыки под неусыпным надзором повелителей ужаса, Король-лич вскоре сумел дотянуться до небольшого поселения людей на самом краю Драконьего Погоста. На нем Нер\'зул и решил испытать свои силы.' FROM `page_text` WHERE `ID`=2014 AND MD5(`Text`)='db06ff147acc8e879b1be2ad9fc7fcbe' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2014 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2015, 'ruRU', 'Нер\'зул выпустил на просторы ледяной пустыни чуму нежити, зародившуюся глубоко внутри Ледяного Трона. Направляя ее силами одного лишь разума, он привел ее в поселение людей. Спустя три дня все его жители погибли, но вскоре восстали, превратившись в ужасных зомби. Нер\'зул чувствовал их мысли и настроения так же ясно, как свои.' FROM `page_text` WHERE `ID`=2015 AND MD5(`Text`)='bc4a2dc0d70686a6ef2e25685bf85da4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2015 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2016, 'ruRU', 'Яростный диссонанс чужих душ, наполнивший разум бывшего шамана, еще более увеличил его силу. Нер\'зул буквально пожирал души умерших. Но вскоре контроль над зомби наскучил Нер\'зулу – слишком уж это было просто.' FROM `page_text` WHERE `ID`=2016 AND MD5(`Text`)='1f2420e88f2f79f8a408f1a2e3b7cca0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2016 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2017, 'ruRU', 'Следующие месяцы он провел, испытывая чуму нежити на оставшихся людях Нордскола, пока не поработил их всех. Армия нежити росла с каждым днем, и он понял, что пришло время для настоящего испытания.' FROM `page_text` WHERE `ID`=2017 AND MD5(`Text`)='51077c1996a47402061be82700c92a90' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2017 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2018, 'ruRU', 'Тем временем остатки Орды боролись за выживание в истерзанных войной южных землях. Гром Адский Крик со своим кланом Песни Войны сумел избежать плена, а вот клан Кровавой Глазницы в полном составе, вместе с вождем Мертвым Глазом, был заключен в лордеронские лагеря для военнопленных. Последовала череда бунтов, но начальникам лагерей вскоре удалось восстановить порядок среди заключенных.' FROM `page_text` WHERE `ID`=2018 AND MD5(`Text`)='dea05457b4854f587122245fc72be641' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2018 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2019, 'ruRU', 'Но втайне от Альянса, большая группа орков продолжала странствовать по пустошам Каз Модана. Клан Драконьей Пасти, возглавляемый коварным чернокнижником Некросом, с помощью могущественного артефакта под названием "Душа Демона" подчинил себе королеву драконов Алекстразу и ее подданных. Удерживая королеву в заложниках, Некрос собрал тайную армию в заброшенной цитадели Громового Молота, которую многие считали проклятой.' FROM `page_text` WHERE `ID`=2019 AND MD5(`Text`)='3a2c837345dce873583f9312edcfa992' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2019 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2020, 'ruRU', 'Планируя нанести удар Альянсу силами своей армии и могучих красных драконов, Некрос надеялся вновь объединить Орду и продолжить завоевание Азерота. Но его надеждам не суждено было сбыться: небольшая группа бойцов сопротивления, возглавляемая магом Ронином, смогла уничтожить Душу Демона и освободить королеву драконов.' FROM `page_text` WHERE `ID`=2020 AND MD5(`Text`)='9060d75fb1a075ca704ba00a979476e0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2020 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2021, 'ruRU', 'Разъяренные драконы Алекстразы разрушили Грим Батол и сожгли большую часть орков Драконьей Пасти. Грандиозные планы Некроса рухнули; войска Альянса окружили уцелевших орков и заключили их в лагерь для военнопленных. Поражение Драконьей Пасти ознаменовало конец Орды и кровожадности орков.' FROM `page_text` WHERE `ID`=2021 AND MD5(`Text`)='c21c1a944b2d55f0cff665ed7b2e2691' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2021 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2022, 'ruRU', 'Шли месяцы, и все больше орков попадали в лагеря для военнопленных. В них стало не хватать места, и Альянс был вынужден строить новые лагеря на равнинах к югу от Альтеракских гор. Чтобы содержать их, королю Теренасу пришлось ввести новые налоги.' FROM `page_text` WHERE `ID`=2022 AND MD5(`Text`)='2af013dca0f2905456f228115b40dfda' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2022 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2023, 'ruRU', 'Эти налоги и постоянные споры по поводу границ вызвали недовольство среди населения. Казалось, что хрупкий союз, который люди заключили в тяжелый час, может развалиться в любой момент.' FROM `page_text` WHERE `ID`=2023 AND MD5(`Text`)='a658b74c99add5b600ece9e06a28055c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2023 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2024, 'ruRU', 'Среди политической неразберихи многие начальники лагерей стали замечать изменения в поведении пленных орков. Число попыток побега и даже драк между заключенными резко уменьшилось. Орки стали спокойными и безразличными.' FROM `page_text` WHERE `ID`=2024 AND MD5(`Text`)='993dc37fd5ff9bcf2082f1670e06f067' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2024 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2025, 'ruRU', 'Это было невероятно, но орки, некогда считавшиеся самой воинственной расой, ступавшей на земли Азерота, потеряли желание сражаться. Они становились все более вялыми, чем совершенно сбили с толку предводителей Альянса.' FROM `page_text` WHERE `ID`=2025 AND MD5(`Text`)='05bbc57743058041a3852ad4b49fd944' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2025 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2026, 'ruRU', 'Некоторые считали, что виной этому какое-то заболевание, которому подвержены только орки. Но верховный маг Антонидас из Даларана предложил другое объяснение. Изучив те немногие материалы по истории орков, которые ему удалось найти, Антонидас узнал, что несколько поколений этого народа находилось под влиянием демонов.' FROM `page_text` WHERE `ID`=2026 AND MD5(`Text`)='1e3a0d3d044e64fac8d957ed64020d2f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2026 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2027, 'ruRU', 'Он полагал, что орки подверглись пагубному влиянию еще до первого вторжения на Азерот. Демоны ввели что-то в их кровь, и те стали невероятно сильны, выносливы и агрессивны.' FROM `page_text` WHERE `ID`=2027 AND MD5(`Text`)='3df21fd742a0c02325bdbe07019ed788' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2027 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2028, 'ruRU', 'Антонидас предположил, что спокойствие орков вызвано не болезнью, а отсутствием черной магии, которая превращала их в грозных и безжалостных воинов.' FROM `page_text` WHERE `ID`=2028 AND MD5(`Text`)='5166abc10f32236a96c8ebe3e734ac81' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2028 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2029, 'ruRU', 'Несмотря на то что причина стала ясна, Антонидасу не удалось найти лекарства, чтобы вывести орков из этого состояния. Кроме того, многие маги и некоторые лидеры Альянса полагали, что пытаться излечить орков – не самая благоразумная идея. Размышляя над проблемой, Антонидас пришел к выводу, что лекарство для орков, каким бы оно ни было, должно врачевать душу, а не тело.' FROM `page_text` WHERE `ID`=2029 AND MD5(`Text`)='e9c46fe86869de0ccf0a667e2aa16568' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2029 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2030, 'ruRU', 'Адэлас Блэкмур, руководитель всех лагерей для военнопленных, наблюдал за орками из своей крепости Дарнхольд. Один из орков пользовался его особым вниманием: молодой сирота, пойманный почти восемнадцать лет назад. Блэкмур воспитал орчонка как своего раба, назвал его Траллом и обучил тактике, философии и фехтованию. Тралл даже пробовал себя в качестве гладиатора. Блэкмур пытался сделать из юного орка орудие убийства.' FROM `page_text` WHERE `ID`=2030 AND MD5(`Text`)='bbf4f158db02bf9c7ca1190c982437b7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2030 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2031, 'ruRU', 'Несмотря на тяжелое детство, Тралл вырос сильным и умным орком; он осознавал, что участь раба – не для него. Повзрослев, он узнал многое об истории своего народа, представителей которого он почти не видел: после поражения в войне практически все орки попали в лагеря для военнопленных. Ходили слухи, что вождю Молоту Рока удалось бежать из Лордерона. И лишь один клан орков все еще оставался на свободе, скрываясь от бдительных глаз Альянса.' FROM `page_text` WHERE `ID`=2031 AND MD5(`Text`)='ec6648bffc97f40d5671dbba8daf1621' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2031 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2032, 'ruRU', 'Находчивый, но неопытный Тралл решил бежать от Блэкмура и отправиться на поиски своих собратьев. Путешествуя от одного лагеря к другому, Тралл обнаружил, что некогда могучие и воинственные орки превратились в совершенно безжизненных существ. Не сумев найти среди них могучих воинов, о которых он так много слышал, Тралл отправился искать последнего непобежденного вождя Грома Адского Крика.' FROM `page_text` WHERE `ID`=2032 AND MD5(`Text`)='6349aaed20806fada52bfca7a71921e9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2032 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2033, 'ruRU', 'Несмотря на постоянные преследования со стороны людей, душа Адского Крика была по-прежнему полна неутолимой жажды боя. Вместе со своим верным кланом Песни Войны он продолжал партизанскую войну против поработителей своего народа. К несчастью, он так и не нашел способ вернуть пленным оркам их жизненную энергию. Юного Тралла завораживал идеализм Адского Крика и воинские традиции Орды.' FROM `page_text` WHERE `ID`=2033 AND MD5(`Text`)='c8efc199102bf5b90dc1a0b1ef825a9b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2033 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2034, 'ruRU', 'В поисках правды о своих предках Тралл отправился на север, где обнаружил легендарный клан Северного Волка. Там ему рассказали, как Гул\'дан отправил Северного Волка в изгнание в самом начале Первой войны. Тралл также узнал, что он – сын и наследник храброго орка Дуротана, вождя Северного Волка, погибшего на этих пустынных просторах почти двадцать лет назад.' FROM `page_text` WHERE `ID`=2034 AND MD5(`Text`)='9abc048eecfe9cf79651708399926e80' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2034 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2035, 'ruRU', 'Под руководством мудрого шамана Дрек\'Тара Тралл изучил древнюю культуру своего народа, которая была почти полностью забыта при правлении коварного Гул\'дана. Со временем Тралл сам стал могучим шаманом и занял свое законное место вождя клана. Исполненный силы самих стихий, Тралл отправился в путь, чтобы освободить свой народ и снять с него демоническое проклятие.' FROM `page_text` WHERE `ID`=2035 AND MD5(`Text`)='6a995767189ebef462b0213a772a0a0a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2035 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2036, 'ruRU', 'В ходе своих путешествий Тралл встретил старого вождя Оргрима Молота Рока, который долгие годы жил отшельником. Молот Рока был близким другом отца Тралла. Он решил помочь юному орку освободить плененные кланы. При поддержке опытных воинов Траллу удалось вернуть Орду к жизни и стать ее духовным учителем.' FROM `page_text` WHERE `ID`=2036 AND MD5(`Text`)='365aa9289aec7d3f9aee3503479b45a3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2036 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2037, 'ruRU', 'Символом перерождения орков стал поход Тралла на крепость Дарнхольд и освобождение из лагерей всех пленных; зловещим планам Блэкмура не суждено было сбыться. Но эта победа далась дорогой ценой: во время осады одного из лагерей в бою погиб Молот Рока.' FROM `page_text` WHERE `ID`=2037 AND MD5(`Text`)='8fc32f3fe68ed20115860c587c5c3e33' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2037 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2038, 'ruRU', 'Тралл взял легендарный боевой молот Молота Рока и надел свои черные доспехи; теперь он стал новым предводителем Орды. Следующие несколько месяцев его маленькое неуловимое войско совершало набеги на лагеря военнопленных Альянса; войско Альянса было бессильно против него. Под руководством своего лучшего друга и наставника, Грома Адского Крика, Тралл делал все возможное, чтобы его народ никогда больше не испытал на себе гнета рабства.' FROM `page_text` WHERE `ID`=2038 AND MD5(`Text`)='077be0a5d1ca8fc40fe08a1bb5daae55' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2038 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2039, 'ruRU', 'Пока Тралл был занят освобождением своих собратьев в Лордероне, Нер\'зул продолжал строить базу в Нордсколе. Над Ледяной Короной он возвел огромную крепость, в которой трудились легионы мертвецов. Но нашлась одна империя, готовая противостоять растущему могуществу Короля-лича.' FROM `page_text` WHERE `ID`=2039 AND MD5(`Text`)='fb9f06ba0c9f426dbb0c33f9db184001' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2039 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2040, 'ruRU', 'Из древнего подземного королевства Азол-Неруб, основанного расой зловещих пауков-гуманоидов, был послан элитный отряд воинов. Они должны были напасть на Ледяную Корону и остановить помешанного на абсолютном господстве Короля-лича. К своему разочарованию, Нер\'зул обнаружил, что воины Неруба невосприимчивы не только к чуме, но и к его телепатии.' FROM `page_text` WHERE `ID`=2040 AND MD5(`Text`)='899ceb4713d5de02641381f2d9ac6fc5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2040 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2041, 'ruRU', 'В распоряжении пауков-повелителей Неруба имелось немалое войско и сеть подземных тоннелей, простирающихся почти на половину территории Нордскола. Они нападали небольшими отрядами, и это не позволяло Королю-личу разделаться с ними раз и навсегда. В конце концов Нер\'зулу удалось победить в этой войне, нанеся сокрушительный удар по воинам Неруба. Вместе со зловещими повелителями ужаса и огромной армией нежити Король-лич напал на Азол-Неруб и обрушил их подземные храмы на головы пауков-повелителей.' FROM `page_text` WHERE `ID`=2041 AND MD5(`Text`)='d9e09e05a95595620838907b703d4bea' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2041 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2042, 'ruRU', 'Несмотря на невосприимчивость воинов Неруба к чуме, Нер\'зулу удалось воскресить пауков-воинов и подчинить их своей воле. Нер\'зул отдал дань уважения их силе и храбрости, позаимствовав их необычный архитектурный стиль для строительства своих крепостей и сооружений.' FROM `page_text` WHERE `ID`=2042 AND MD5(`Text`)='1403f1639c670716722661e467cc31d5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2042 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2043, 'ruRU', 'Избавившись от всех противников, Король-лич мог, наконец, приступить к выполнению своей истинной миссии в этом мире. Он устремил свои помыслы к землям людей, выискивая тех, в чьих душах скрывалась тьма, тех, кто слышал его зловещий зов…' FROM `page_text` WHERE `ID`=2043 AND MD5(`Text`)='bb4af05e9c6e44e37a26983cfe826adb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2043 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2044, 'ruRU', 'Немало могущественных людей услышали зов Короля-лича из Нордскола. Среди них оказался Кел\'Тузад, верховный даларанский маг, один из старейшин Кирин-Тора, совета Даларана. В течение многих лет его считали отступником за желание изучать запретные искусства некромантии.' FROM `page_text` WHERE `ID`=2044 AND MD5(`Text`)='82b5ab28a58daf721e8e055c03dba150' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2044 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2045, 'ruRU', 'Он хотел знать как можно больше о мире магии и темных чудес, но ограниченность и старомодность взглядов коллег разочаровывала его. Когда верховный маг услышал таинственный голос из Нордскола, он приложил все свои силы, чтобы ответить на этот зов. Кел\'Тузад был убежден, что Кирин-Тор слишком слаб, чтобы овладеть силой и знаниями, заключенными в темных искусствах, и поэтому сам решил стать учеником могущественного Короля-лича.' FROM `page_text` WHERE `ID`=2045 AND MD5(`Text`)='a83fb89424426bfe7398b837c45c5ae0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2045 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2046, 'ruRU', 'Кел\'Тузад оставил учение Кирин-Тора и навсегда покинул Даларан, отказавшись от всех своих богатств и высокого положения в обществе. Повинуясь голосу Короля-лича, звучащему в его мыслях, он продал все, что у него было, и спрятал свои богатства. Он проделал долгий путь по суше и морю – и наконец достиг ледяных берегов Нордскола.' FROM `page_text` WHERE `ID`=2046 AND MD5(`Text`)='cc135af8f7c28d5ac216f09c56d21d72' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2046 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2047, 'ruRU', 'В намерении добраться до Ледяной Короны и предложить свою службу Королю-личу, верховный маг миновал опустошенные войной земли Азол-Неруба. Кел\'Тузад своими глазами увидел, насколько могучим и яростным был Нер\'зул. Он начал осознавать, сколь мудрым было его решение вступить в союз с загадочным Королем-личом и какие плоды этот союз мог принести.' FROM `page_text` WHERE `ID`=2047 AND MD5(`Text`)='267a62e46041cbb7d6e8829b66770411' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2047 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2048, 'ruRU', 'После долгих месяцев блуждания по суровым снежным пустошам Кел\'Тузад, наконец, добрался до Ледяной Короны. Он смело подошел к темной крепости Нер\'зула, и, к его удивлению, стражники-нежить молча расступились – так, словно мага здесь ждали.' FROM `page_text` WHERE `ID`=2048 AND MD5(`Text`)='9b11e2d18407c32414b0ac8e4d72322c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2048 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2049, 'ruRU', 'Кел\'Тузад спустился глубоко под замерзшую землю и добрался до сердца ледника. Там, в бесконечных ледяных пещерах, он преклонился перед Ледяным Троном и преподнес свою душу темному повелителю нежити.' FROM `page_text` WHERE `ID`=2049 AND MD5(`Text`)='9d0369d6b4b97f12ada26165431ffa48' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2049 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2050, 'ruRU', 'Король-лич был доволен новобранцем. Он пообещал Кел\'Тузаду бессмертие и невиданную силу в обмен на преданность и покорность. Кел\'Тузад жаждал получить эту силу и знание темных искусств и с радостью принял свою первую великую миссию – отправиться в мир людей и основать новую религию, последователи которой должны поклоняться Королю-личу как богу.' FROM `page_text` WHERE `ID`=2050 AND MD5(`Text`)='be5ed24e926cfaff572d755aa8bf1293' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2050 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2051, 'ruRU', 'Чтобы Кел\'Тузаду было легче справиться со своим заданием, Нер\'зул оставил ему человеческую внешность. Престарелому, но тем не менее умевшему привлечь к себе сторонников магу предстояло использовать свой дар убеждения и иллюзии, чтобы внушить угнетенным жителям Лордерона веру и надежду. После этого он должен был показать им, насколько лучше они могли бы жить под властью нового короля.' FROM `page_text` WHERE `ID`=2051 AND MD5(`Text`)='077470b386e1ffd0a7d148c6fc7325ed' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2051 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2052, 'ruRU', 'Кел\'Тузад вернулся в Лордерон в новом обличии и через три года, благодаря богатству и уму, собрал вокруг себя тайное братство. Это братство, которое он назвал Культом Проклятых, обещало всем своим служителям абсолютное равенство и вечную жизнь в Азероте в обмен на службу и покорность Нер\'зулу.' FROM `page_text` WHERE `ID`=2052 AND MD5(`Text`)='678b387a3e7e742b63ea78dc4bb22df3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2052 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2053, 'ruRU', 'Шли месяцы; к Кел\'Тузаду приходили все новые и новые приверженцы Культа Проклятых. Кел\'Тузад на удивление легко добился своей цели: многие потеряли веру в Священный Свет и стали поклоняться темному владыке Нер\'зулу. Культ Проклятых становился все более влиятельным, но благодаря Кел\'Тузаду власти Лордерона все еще не замечали перемен…' FROM `page_text` WHERE `ID`=2053 AND MD5(`Text`)='38e6944cb27b6cafe3c605bd5ba3f001' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2053 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2054, 'ruRU', 'Довольный успехами Кел\'Тузада в Лордероне, Король-лич готовился к нападению на людскую цивилизацию. Нер\'зул поместил сгустки энергии чумы в передвижные артефакты, именовавшиеся котлами чумы, и приказал Кел\'Тузаду перенести их в Лордерон, где их нужно было спрятать в селениях последователей Культа.' FROM `page_text` WHERE `ID`=2054 AND MD5(`Text`)='3e8580e8a3d528a4b59d1c9d13157c74' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2054 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2055, 'ruRU', 'Котлы должны были находиться под охраной служителей Культа, а впоследствии использоваться в качестве источников чумы, разносящих по всем деревням и городам на севере Лордерона.' FROM `page_text` WHERE `ID`=2055 AND MD5(`Text`)='1a4c8b64ddc6884d54a397f535b9523a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2055 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2056, 'ruRU', 'План Короля-лича сработал идеально. Многие северные деревни чума поразила почти мгновенно. Как и в Нордсколе, жители, заразившиеся чумой, умирали и восставали из мертвых верными рабами Короля-лича.' FROM `page_text` WHERE `ID`=2056 AND MD5(`Text`)='62c2bcd2784c0278a397b4535a5538cc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2056 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2057, 'ruRU', 'Члены Культа, созданного Кел\'Тузадом, добровольно желали умереть и стать слугами своего темного повелителя. Они жаждали получить бессмертие через нежизнь. По мере распространения чумы северные земли наводняли полчища беспощадных зомби. Кел\'Тузад назвал новую армию Плетью Короля-лича. Этой армии предстояло покорить Лордерон и стереть человечество с лица земли.' FROM `page_text` WHERE `ID`=2057 AND MD5(`Text`)='a9172598d6a446c5eb1f81f4e642fd40' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2057 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2064, 'ruRU', 'После долгих месяцев приготовлений Культ Проклятых под предводительством Кел\'Тузада нанес первый удар, выпустив чуму на земли Лордерона. Утер и его паладины обследовали зараженные территории в надежде найти способ остановить чуму; но, несмотря на все их старания, болезнь продолжала распространяться, угрожая полностью уничтожить Альянс.' FROM `page_text` WHERE `ID`=2064 AND MD5(`Text`)='f468e21813eccb4fb3afc5a7aa7b4bfa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2064 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2065, 'ruRU', 'Полчища нежити продолжали свое шествие по землям Лордерона, и принц Артас, единственный сын Теренаса, решил выступить против них. Артасу удалось убить Кел\'Тузада, но ряды нежити пополнялись с каждым павшим солдатом, защищавшим свои земли. Враги казались непобедимыми, и Артас впал в отчаяние; ему пришлось идти на крайние меры. В конце концов он узнал от солдат, что начал терять свои человеческие качества.' FROM `page_text` WHERE `ID`=2065 AND MD5(`Text`)='08e10ab55daaf4fd9464e6cde58e911e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2065 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2066, 'ruRU', 'Страх и решимость Артаса привели его к погибели. Он желал уничтожить угрозу своей земле и ради этого добрался до источника чумы в Нордсколе, но сам пал жертвой могущества Короля-лича. Надеясь спасти свой народ, Артас взял в руки проклятый рунический клинок, Ледяную Скорбь.' FROM `page_text` WHERE `ID`=2066 AND MD5(`Text`)='127b040513782a5c68e6640f0bf9a699' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2066 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2067, 'ruRU', 'Меч дал Артасу невиданную силу, но забрал его душу, превратив принца в одного из самых могущественных рыцарей смерти, подданных Короля-лича. Потеряв душу и рассудок, Артас возглавил Плеть и повел армию против своего собственного королевства. Артас убил своего отца, короля Теренаса, и бросил поверженное королевство Лордерон к ногам Короля-лича.' FROM `page_text` WHERE `ID`=2067 AND MD5(`Text`)='3f826dd9c184f2e27fc824a4165694dd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2067 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2068, 'ruRU', 'Хотя Артас сокрушил всех, кого теперь считал своими врагами, его не переставал преследовать дух Кел\'Тузада. Призрак сказал, что Артас должен помочь вернуть его к жизни, чтобы продолжить выполнение плана Короля-лича. Для этого Артас должен был принести останки Кел\'Тузада к волшебному Солнечному Колодцу, сокрытому в королевстве высших эльфов Кель\'Таласе.' FROM `page_text` WHERE `ID`=2068 AND MD5(`Text`)='571a5f03ff6efa66c480674c0e1e3ff8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2068 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2069, 'ruRU', 'Войско Плети под предводительством Артаса вторглось в Кель\'Талас и окружило немногочисленную армию эльфов. Сильвана Ветрокрылая, предводительница следопытов Луносвета, храбро вступила в неравный бой с врагом, но Артас истребил всю армию высших эльфов и добрался до Солнечного Колодца. В подтверждение своего превосходства безжалостный Артас воскресил Сильвану как банши, чтобы она вечно служила поработителю Кель\'Таласа.' FROM `page_text` WHERE `ID`=2069 AND MD5(`Text`)='8b62739a06ee4a58e752d044b32abc35' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2069 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2070, 'ruRU', 'Затем Артас погрузил останки Кел\'Тузада в священные воды Солнечного Колодца. Могучие воды Вечности были осквернены этим злодеянием, но Кел\'Тузад воскрес и вернулся в этот мир могущественным личом. Кел\'Тузад, чьи силы теперь многократно возросли, объяснил, в чем состоял следующий этап плана Короля-лича.' FROM `page_text` WHERE `ID`=2070 AND MD5(`Text`)='81ae36a9b80777a6e215036090eea7ab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2070 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2071, 'ruRU', 'Когда Артас со своей армией нежити повернул на юг, в землях Кель\'Таласа уже не осталось ни одного живого эльфа. Славного королевства высших эльфов, просуществовавшего более девяти тысяч лет, больше не существовало.' FROM `page_text` WHERE `ID`=2071 AND MD5(`Text`)='c99d903a370fcc9c7edab7fc0203354c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2071 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2072, 'ruRU', 'Как только Кел\'Тузад вернулся к жизни, Артас повел Плеть на юг, к Даларану. Там лич должен был найти книгу заклинаний Медива и с ее помощью вернуть в этот мир Архимонда. После этого Архимонд должен был возглавить Легион и повести его в решающий бой. Даже волшебники Кирин-Тора не смогли помешать Артасу завладеть книгой Медива, и Кел\'Тузаду оставалось лишь прочесть заклинание.' FROM `page_text` WHERE `ID`=2072 AND MD5(`Text`)='576d73695c72d2dd79319d1421662d8e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2072 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2073, 'ruRU', 'Спустя десять тысяч лет могучий демон Архимонд вновь ступил на Азерот. Но в Даларане их путешествие не закончилось. По приказу самого Кил\'джедена Архимонд и его демоны последовали за Плетью в Калимдор, чтобы уничтожить Нордрассил, Древо Жизни.' FROM `page_text` WHERE `ID`=2073 AND MD5(`Text`)='e95f8f6b5d0e37de17312b35abcaf8a4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2073 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2074, 'ruRU', 'Среди всего этого хаоса появился таинственный пророк, который стал для смертных спасителем и наставником. Этим пророком оказался не кто иной, как сам Медив, последний Страж, чудесным образом вернувшийся из Бездны, чтобы искупить все свои грехи. Медив поведал Орде и Альянсу о смертельной опасности, которая им грозит, и убеждал их объединить свои силы.' FROM `page_text` WHERE `ID`=2074 AND MD5(`Text`)='3b7c02b9efbc2a5279253df4f043cf22' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2074 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2075, 'ruRU', 'Орки и люди, враждовавшие не одно поколение, не хотели и слушать его. Медиву пришлось общаться с каждой расой по отдельности, обманом заставить их пересечь море и ступить на легендарную землю Калимдора. Вскоре орки и люди обнаружили скрывавшуюся долгое время цивилизацию калдорай.' FROM `page_text` WHERE `ID`=2075 AND MD5(`Text`)='e750e5f5d2f8beff0f4442ea59b0f5f2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2075 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2076, 'ruRU', 'Орков, отправившихся в путь через Степи Калимдора под предводительством Тралла, преследовали неудачи. Они заключили союз с Кэрном Кровавым Копытом и его могучими тауренами-воинами, но при этом многих орков стала одолевать жажда крови, мучившая их на протяжении многих лет. Гром Адский Крик, лучший лейтенант Тралла, предал Орду и позволил своим самым низменным инстинктам взять верх над собой.' FROM `page_text` WHERE `ID`=2076 AND MD5(`Text`)='8aa0a68ae02c7f59a355fed0156cda61' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2076 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2077, 'ruRU', 'Пробираясь через Ясеневый лес, Адский Крик и его верные воины Песни Войны наткнулись на древних ночных эльфов-Часовых. Полубог Кенарий решил, что орки вновь возжаждали войны, и хотел прогнать их из своих земель. Но Адский Крик со своими воинами, преисполненные сверхъестественной ярости и злобы, убили Кенария и осквернили древние леса.' FROM `page_text` WHERE `ID`=2077 AND MD5(`Text`)='b957728457d6a73fa425f66ebf03b838' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2077 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2078, 'ruRU', 'В конечном итоге Адский Крик сумел восстановить свою честь, победив вместе с Траллом Маннорота – демона, обрекшего орков на вечную жажду крови. Смерть Маннорота положила конец ужасному проклятию орков.' FROM `page_text` WHERE `ID`=2078 AND MD5(`Text`)='b226f6dc48ff7029561691aaeeea94e3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2078 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2079, 'ruRU', 'В то время как Медив пытался убедить орков и людей в необходимости объединить силы, ночные эльфы сами боролись с Легионом. Тиранда Шелест Ветра, бессмертная верховная жрица ночных эльфов-Стражей, отчаянно сражалась с демонами и мертвецами, чтобы не дать им захватить Ясеневый лес. Тиранда поняла, что одной ей не справиться, и велела пробудить друидов ночных эльфов от многовекового сна, чтобы просить их о помощи.' FROM `page_text` WHERE `ID`=2079 AND MD5(`Text`)='ce509271e55f3a0a7d9eefa11dc1b199' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2079 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2080, 'ruRU', 'Призвав на помощь Малфуриона Ярость Бури, свою давнюю любовь, Тиранда укрепила оборону и вынудила Легион отступить. Малфурион заставил саму природу восстать против армий Легиона и Плети.' FROM `page_text` WHERE `ID`=2080 AND MD5(`Text`)='3b01fe5eb93ce74f3048710affbae1c6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2080 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2081, 'ruRU', 'В поисках друидов, которых еще не удалось пробудить, Малфурион наткнулся на древнюю тюрьму, в которой он заточил своего брата Иллидана. Тиранда освободила его в надежде, что он присоединится к ним в битве с Легионом. Некоторое время Иллидан помогал им, но затем бежал, решив, что личные цели для него важнее.' FROM `page_text` WHERE `ID`=2081 AND MD5(`Text`)='2276acefabe5f3890449ba6d44333aab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2081 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2082, 'ruRU', 'Ночные эльфы собрались с силами и, полные решимости, вступили в сражение с Пылающим Легионом. Легион всегда желал завладеть Источником Вечности, который питал Древо Жизни и был сердцем королевства ночных эльфов. Если бы Легиону удалось захватить Древо, демоны могли бы в буквальном смысле разорвать мир на части.' FROM `page_text` WHERE `ID`=2082 AND MD5(`Text`)='5415850b1e076877d36b81249c90c73e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2082 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2083, 'ruRU', 'Во время атаки Легиона на Ясеневый лес Иллидан был освобожден из своей тюрьмы, где он провел в заточении десять тысяч лет. Сначала Иллидан пытался помочь своим товарищам, но вскоре он принял свое истинное обличие и поглотил энергию могущественного волшебного артефакта под названием Череп Гул\'дана.' FROM `page_text` WHERE `ID`=2083 AND MD5(`Text`)='bef27dabdfec7ccba5b9c619cf7b571f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2083 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2084, 'ruRU', 'Череп Гул\'дана дал Иллидану демонический облик и огромную силу. Кроме того, он получил часть воспоминаний Гул\'дана, главным образом о Гробнице Саргераса – подземелье на острове, где, по слухам, находились останки Титана Мрака Саргераса.' FROM `page_text` WHERE `ID`=2084 AND MD5(`Text`)='7b3ec4db885a8ffd91337875175e185a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2084 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2085, 'ruRU', 'Вновь получив силу и возможность свободно странствовать по миру, Иллидан отправился на поиски своей судьбы; но на этом пути он столкнулся с Кил\'джеденом, который сделал Иллидану предложение, от которого тот не мог отказаться. Кил\'джеден был разгневан поражением Архимонда у горы Хиджал, но ему предстояли более важные дела, чем отмщение.' FROM `page_text` WHERE `ID`=2085 AND MD5(`Text`)='5281972f157b40519ccda35b13a0d2be' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2085 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2086, 'ruRU', 'Кил\'джеден понимал, что Король-лич, его собственное творение, достиг слишком большого могущества, и управлять им уже невозможно, а потому он приказал Иллидану убить Нер\'зула, уничтожив Плеть раз и навсегда. Взамен он пообещал Иллидану невиданную силу и почетное место среди повелителей Пылающего Легиона.' FROM `page_text` WHERE `ID`=2086 AND MD5(`Text`)='a0eeaf856c9940f8b2e21b17bf55b925' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2086 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2087, 'ruRU', 'Иллидан согласился и тотчас отправился на поиски Ледяного Трона, чтобы уничтожить этот ледяной сосуд, в котором хранилась душа Короля-лича. Иллидан знал, что для этого ему понадобится могущественный артефакт. Использовав знания, перешедшие к нему с воспоминаниями Гул\'дана, Иллидан отправился к Гробнице Саргераса за останками Титана Мрака.' FROM `page_text` WHERE `ID`=2087 AND MD5(`Text`)='cb543af39d2c195ac626afe1d284f20e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2087 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2088, 'ruRU', 'Иллидан потревожил своих старых должников высокорожденных и выманил из подводных убежищ змееподобных существ – наг. Наги во главе с леди Вайш помогли Иллидану добраться до Таинственных островов, где, по слухам, находилась Гробница Саргераса.' FROM `page_text` WHERE `ID`=2088 AND MD5(`Text`)='cdb16ae967c72ba2327a0bcb21bbdaff' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2088 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2089, 'ruRU', 'Когда Иллидан, сопровождаемый нагами, отправился в путь, его начала преследовать Майев Песнь Теней. Майев была тюремным стражником Иллидана десять тысяч лет и страстно желала вернуть его в заточение. Но Иллидан, перехитрив Майев и ее Смотрящих, сумел завладеть Оком Саргераса. Найдя могущественное Око, Иллидан отправился в бывший город волшебников – Даларан.' FROM `page_text` WHERE `ID`=2089 AND MD5(`Text`)='c146cbe0b2754fc3d5cc9c4aeab28c47' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2089 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2090, 'ruRU', 'Забрав энергию силовых линий города, Иллидан воспользовался Оком, чтобы нанести магический удар по цитадели Ледяной Короны в далеком Нордсколе. Этот удар сокрушил защиту Короля-лича и поставил под угрозу саму крышу мироздания. В последний момент разрушительное заклятие Иллидана было остановлено, когда его брат Малфурион и жрица Тиранда пришли на помощь Майев.' FROM `page_text` WHERE `ID`=2090 AND MD5(`Text`)='d23aa6e0a35dffba16025359ac3a93fa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2090 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2091, 'ruRU', 'Зная, что Кил\'джеден будет недоволен его неудавшейся попыткой разрушить Ледяной Трон, Иллидан бежал в безжизненный мир, называемый Запределье: последние остатки Дренора, бывшей родины орков. Там он хотел укрыться от гнева Кил\'джедена и обдумать свои дальнейшие планы.' FROM `page_text` WHERE `ID`=2091 AND MD5(`Text`)='295fdc0e047e4ee336387f245f81dc62' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2091 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2092, 'ruRU', 'Остановив Иллидана, Малфурион и Тиранда вернулись на родину, в Ясеневый лес, дабы охранять свой народ. Однако Майев не согласилась отступить так просто – она последовала за Иллиданам в Запределье, чтобы покарать его.' FROM `page_text` WHERE `ID`=2092 AND MD5(`Text`)='d1e162cdaca530dcb1b06a8fe8563bdd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2092 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2093, 'ruRU', 'На этот раз Плеть превратила практически весь Лордерон и Кель\'Талас в ядовитые Чумные земли. Там осталось лишь несколько очагов сопротивления Альянса. Один из них, состоявший в основном из высших эльфов, возглавлял последний представитель династии Солнечного Скитальца – принц Кель\'тас.' FROM `page_text` WHERE `ID`=2093 AND MD5(`Text`)='52ab27da62d5839fb13f6df1dc62c17e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2093 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2094, 'ruRU', 'Кель, опытный маг, был обеспокоен слабостью Альянса. Его подданные, высшие эльфы, огорченные потерей своей родины, назвали себя эльфами крови – в память о своем погибшем народе. Лишенные энергии Солнечного Колодца, они ценой огромных страданий сдерживали дальнейшее наступление Плети.' FROM `page_text` WHERE `ID`=2094 AND MD5(`Text`)='a7d14f9e05f7e18b280102d849a01153' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2094 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2095, 'ruRU', 'Когда Кель понял, что не сможет найти средство от магической зависимости своего народа, он совершил непоправимое. Вспомнив об общих предках-высокорожденных, он встал на сторону Иллидана и его спутников-наг. Остальные предводители Альянса объявили эльфов крови предателями и изгнали их навсегда.' FROM `page_text` WHERE `ID`=2095 AND MD5(`Text`)='132e14e309976592fe868db7e65c8a21' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2095 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2096, 'ruRU', 'Келю и его подданным не оставалось ничего, кроме как отправиться в Запределье вслед за леди Вайш и сразиться с Майев, которой удалось снова поймать Иллидана. Объединив силы, наги и эльфы крови справились с Майев и освободили его. Обосновавшись в Запределье, Иллидан начал копить силы для следующего удара по Королю-личу и его цитадели Ледяной Короны.' FROM `page_text` WHERE `ID`=2096 AND MD5(`Text`)='bf44ccce449217cb6555a2294588c64e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2096 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2097, 'ruRU', 'Король-лич Нер\'зул знал, что времени у него мало. Заключенный в Ледяном Троне, он подозревал что Кил\'джеден попытается уничтожить его. Заклятие Иллидана необратимо повредило Трон, и с каждым днем Король-лич становился все слабее. В надежде на спасение он призвал к себе своего величайшего смертного слугу – рыцаря смерти Артаса.' FROM `page_text` WHERE `ID`=2097 AND MD5(`Text`)='fd45a2f8c41ddf37921aac7330def65a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2097 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2098, 'ruRU', 'Несмотря на нехватку сил, вызванную слабостью повелителя, Артас все же ввязался в братоубийственную войну в Лордероне. Тогда половина его уцелевших войск во главе с банши Сильваной Ветрокрылой вышла из-под его контроля и взяла власть в свои руки. Призванный своим господином, Артас был вынужден передать командование Плетью своему заместителю Кел\'Тузаду, а война тем временем охватывала все новые области Чумных земель.' FROM `page_text` WHERE `ID`=2098 AND MD5(`Text`)='0352766f264bf775f166aaed9b2e94bd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2098 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2099, 'ruRU', 'В конечном итоге Сильвана и ее мятежники, назвавшие себя Отрекшимися, объявили руины столицы Лордерона своей собственностью. В подземельях под этими руинами они обустроили собственную крепость, поклявшись победить Плеть и изгнать из своих земель Кел\'Тузада.' FROM `page_text` WHERE `ID`=2099 AND MD5(`Text`)='d1f383dc304cb1f5d31da99731a5f3f1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2099 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2100, 'ruRU', 'Ослабевший, но исполненный решимости спасти своего господина, Артас добрался в Нордскол – и обнаружил там наг Иллидана с эльфами крови. Стремясь опередить обнаруженные силы врага, Артас со своими союзниками из Неруба направился к Ледяному Трону.' FROM `page_text` WHERE `ID`=2100 AND MD5(`Text`)='903487ef07bd895946e6296e2b52ab75' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2100 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2101, 'ruRU', 'Даже практически оставшись без сил, Артас сумел опередить Иллидана и первым добраться до Ледяного Трона. Своим руническим мечом, Ледяной Скорбью, Артас разрушил ледяную тюрьму, а потом забрал из нее зачарованный шлем и доспехи Нер\'зула.' FROM `page_text` WHERE `ID`=2101 AND MD5(`Text`)='4481f53143539d2f7915e54db190f61b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2101 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2102, 'ruRU', 'Водрузив на свою голову шлем, Артас стал новым Королем-личом. Души Нер\'зула и Артаса слились воедино, обретя небывалое могущество. Увидев, что Артас стал самым грозным существом в истории этого мира, Иллидан со своими войсками был вынужден бежать обратно в Запределье.' FROM `page_text` WHERE `ID`=2102 AND MD5(`Text`)='8958f126ec7a271147257bbad3e9a687' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2102 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2103, 'ruRU', 'Сейчас Король-лич Артас пребывает в Нордсколе. Говорят, что он собирается восстановить Ледяную Корону. Его верный помощник Кел\'Тузад командует силами Плети в Чумных землях. Сильвана же со своими Отрекшимися удерживает лишь Тирисфальские леса – небольшую часть растерзанного войной королевства.' FROM `page_text` WHERE `ID`=2103 AND MD5(`Text`)='b8e8c2556bc83da24f0a036c86f099bf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2103 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2104, 'ruRU', 'Хотя смертные расы и одержали победу, их мир был растерзан войной. Плеть и Пылающий Легион практически уничтожили все народы Лордерона и почти закончили свою работу в Калимдоре. Леса нуждались в восстановлении, обиды – в забвении, а разоренные земли – в новых жителях. Война нанесла тяжелые раны каждой из рас, но все они нашли силы объединиться и начать новую жизнь. Первым шагом к ней было перемирие между Альянсом и Ордой.' FROM `page_text` WHERE `ID`=2104 AND MD5(`Text`)='1a0bc0bbf74b999c2f92a3f197f280b6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2104 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2105, 'ruRU', 'Тралл привел орков на материк Калимдор, где они обрели новую родину с помощью своих братьев-тауренов. Стремясь вернуть былое величие, орки назвали свой дом Дуротаром в честь убитого отца Тралла.' FROM `page_text` WHERE `ID`=2105 AND MD5(`Text`)='e4a7fbbf5bcc08f1a6578f6f958870a5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2105 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2106, 'ruRU', 'Когда проклятие демонов было снято, Орда превратилась из безжалостной военной машины в относительно свободный союз, направленный не столько на захват новых земель, сколько на жизнь и процветание. Тралл и его орки предвкушали начало новой мирной эры, получая помощь от благородных тауренов и хитрых троллей из племени Черного Копья.' FROM `page_text` WHERE `ID`=2106 AND MD5(`Text`)='fcc838fdb99cbd186098785d3340ca4d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2106 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2107, 'ruRU', 'Уцелевшие войска Альянса под командованием Джайны Праудмур осели в южном Калимдоре. На восточном краю Пылевых топей они построили укрепленный портовый город Терамор, в котором люди и дворфы объединили усилия ради выживания в этой негостеприимной земле. Хотя жители Дуротара и Терамора и сохраняли непрочное перемирие, оно не могло длиться вечно.' FROM `page_text` WHERE `ID`=2107 AND MD5(`Text`)='7a56ff56a7cd0a5a9c9dc37128c9728b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2107 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2108, 'ruRU', 'Мир между орками и людьми был нарушен с прибытием огромного флота Альянса под командованием отца Джайны, Великого адмирала Даэлина Праудмура. Этот флот покинул Лордерон перед самым падением королевства. В течение долгих месяцев плавания адмирал Праудмур искал любых уцелевших союзников по Альянсу.' FROM `page_text` WHERE `ID`=2108 AND MD5(`Text`)='a5b9f2c5d70fb0b6459796750651350f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2108 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2109, 'ruRU', 'Флот Праудмура представлял серьезную угрозу стабильности в регионе. Будучи знаменитым героем Второй войны, отец Джайны всей душой ненавидел Орду. Он твердо решил уничтожить Дуротар прежде, чем орки закрепятся на этой земле.' FROM `page_text` WHERE `ID`=2109 AND MD5(`Text`)='266aa3484f7e15295f90e58d94993297' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2109 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2110, 'ruRU', 'Адмирал поставил Джайну перед страшным выбором: выступить против новообретенных союзников-орков или сразиться с собственным отцом в надежде сохранить хрупкий мир между Альянсом и Ордой. После сильных душевных метаний Джайна выбрала последнее и встала на сторону Тралла.' FROM `page_text` WHERE `ID`=2110 AND MD5(`Text`)='affb9ca17ea5fb6c11816393ca33c00c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2110 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2111, 'ruRU', 'К сожалению, адмирал Праудмур умер в бою, не успев помириться с Джайной и узнать, что орки перестали быть кровожадными чудовищами. В награду за помощь орки позволили Джайне и ее подданным беспрепятственно вернуться в Терамор.' FROM `page_text` WHERE `ID`=2111 AND MD5(`Text`)='ffb2994a6e176ce0cb89b60a681393af' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2111 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2131, 'ruRU', 'Тром-ка, воин. Меня не интересуют твои подвиги – это все дела прошлого. Когда ты последний раз $gубивал:убивала; человека? Наверняка давно. Ты теряешь хватку без дела.$b$bМне $gнужен напарник:нужна напарница;. А взамен я дам тебе то, что тебе нужно, – полезную тренировку. Когда до тебя дойдет, что я дело говорю, – приходи. Я буду ждать тебя под навесом прямо возле Логова.$b$b-Франг, наставник воинов' FROM `page_text` WHERE `ID`=2131 AND MD5(`Text`)='fba0c09808d632913aa385e74a66ba9a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2131 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2152, 'ruRU', 'Адмирал Бареан Вествинд\r\nКомандующий флотом Алого марша\r\nГражданин Кул-Тираса\r\nПропал без вести у берегов Нордскола' FROM `page_text` WHERE `ID`=2152 AND MD5(`Text`)='1f8bd0ef6920d0b072400bf3d4a9a96e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2152 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2153, 'ruRU', 'Доргар Камнелоб\r\nВоин Алого ордена\r\nВластитель Красных пещер\r\nПоследний раз был замечен в горах Альтерака' FROM `page_text` WHERE `ID`=2153 AND MD5(`Text`)='71c6c697073209de73838ccdbe070aa2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2153 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2171, 'ruRU', 'Феллари Быстрая Стрела\r\nКапитан следопытов Алого ордена\r\nЖительница Кель\'Таласа\r\nПропала без вести в Серебряном бору' FROM `page_text` WHERE `ID`=2171 AND MD5(`Text`)='d48e18d932391634218f997c1225ab90' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2171 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2172, 'ruRU', 'Феррен Маркус\r\nАббат Монастыря Алого ордена\r\nГражданин Стратхольма\r\nПогиб при обороне монастыря во время Первого летнего штурма' FROM `page_text` WHERE `ID`=2172 AND MD5(`Text`)='e93afa65b62c8409fb895f15ba4e1a78' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2172 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2173, 'ruRU', 'Хартал Проницательный\r\nПредводитель паладинов Алого ордена\r\nГражданин Азерота – рыцарь Серебряной Длани\r\nПоследний раз был замечен входящим в проклятый город Стратхольм' FROM `page_text` WHERE `ID`=2173 AND MD5(`Text`)='d3bb64ed3f5273c6134234d2a373484e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2173 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2176, 'ruRU', 'Орман из Стромгарда\r\nПервый капитан-генерал Алого ордена\r\nГражданин Стромгарда\r\nПропал без вести на леднике Ледяной Короны' FROM `page_text` WHERE `ID`=2176 AND MD5(`Text`)='c313f62e76e93b2941ec7129dd494928' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2176 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2177, 'ruRU', 'Валея Два Клинка\r\nВоительница Алого ордена\r\nЖительница Альтерака\r\nПоследний раз была замечена в Восточных Чумных землях.' FROM `page_text` WHERE `ID`=2177 AND MD5(`Text`)='72ffc34e625a9fcc2e0ac9928855a3c9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2177 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2178, 'ruRU', 'Яна Кровавое Копье\nВторой предводитель убийц Алого ордена\nЖительница Даларана \nПропала без вести в Тирисфальских лесах' FROM `page_text` WHERE `ID`=2178 AND MD5(`Text`)='c6d17e87e8ffc8550fa1a269528ccb45' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2178 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2191, 'ruRU', 'Около 16 000 лет назад, задолго до того как ночные эльфы навлекли на себя гнев Пылающего Легиона, большая часть Калимдора принадлежала троллям. Они основали две империи: Гурубаши в юго-восточных джунглях и Амани в центре материка.' FROM `page_text` WHERE `ID`=2191 AND MD5(`Text`)='8cd836bf0e276157e95d5a50ae13d871' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2191 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2192, 'ruRU', 'Далеко на севере, в области, сейчас известной под названием Нордскол, жили малочисленные племена, образовавшие государство Гундрак, но так и не сравнившиеся со своими южными сородичами.' FROM `page_text` WHERE `ID`=2192 AND MD5(`Text`)='725ed009e35056ce0cc32f65fc373e55' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2192 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2193, 'ruRU', 'Хотя империи Гурубаши и Амани недолюбливали друг друга, конфликты между ними были редкостью. Их общим врагом был Аз\'Акир – цивилизация насекомоподобных существ с дальнего запада. Разумные насекомые отличались невероятной агрессивностью и стремились искоренить все остальные формы жизни Калимдора.' FROM `page_text` WHERE `ID`=2193 AND MD5(`Text`)='7c26639856e1d38ba9c01f01374bf89a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2193 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2194, 'ruRU', 'Тролли долгие годы воевали с акири, но так и не смогли одержать над ними настоящую победу. Все, что им удалось, – это расколоть вражеское королевство на части и изгнать насекомых в далекие земли севера и юга.' FROM `page_text` WHERE `ID`=2194 AND MD5(`Text`)='76e661e2c1c179f3f9be13582d809ef9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2194 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2195, 'ruRU', 'Акири основали две крупнейших колонии – Азол-Неруб на севере и Ан\'Кираж на юге. Тролли предполагали, что существуют и другие колонии под поверхностью Калимдора, но эти подозрения не оправдались.' FROM `page_text` WHERE `ID`=2195 AND MD5(`Text`)='8ce3555a1e1f406875fc709084f308ce' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2195 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2196, 'ruRU', 'После изгнания коварных насекомых две империи вернулись к обычной жизни. Победа в войне практически не изменила их границ. Впрочем, в древних рукописях упоминается некое племя, покинувшее в те годы империю Амани и основавшее собственное поселение в самом сердце темного континента.' FROM `page_text` WHERE `ID`=2196 AND MD5(`Text`)='e8ff5d3d10e1c6e5e447a0b0a7bf62ad' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2196 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2197, 'ruRU', 'Легенда гласит, что эти храбрые первопроходцы обнаружили источник Вечности, наделивший их невероятной силой. Есть предположение, что именно от них произошли ночные эльфы, но точно это не известно.' FROM `page_text` WHERE `ID`=2197 AND MD5(`Text`)='73c4d43d854d5fa639620005406e7f24' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2197 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2198, 'ruRU', 'С другой стороны, достоверно установлено, что раса ночных эльфов обрела могущество именно после обнаружения источника Вечности. Несмотря на все попытки троллей защитить свои владения, эта раса стремительно захватывала первобытный Калимдор. Сильная магия, недостижимая для суеверных троллей, позволила ночным эльфам добиться того, что не смогли сделать акири, – разрушить две великие империи.' FROM `page_text` WHERE `ID`=2198 AND MD5(`Text`)='95164505ba0dbd3c39732f5d9cf616e8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2198 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2200, 'ruRU', 'В конце концов ночные эльфы обожглись именно на том чародейском огне, который стремились подчинить. Их безрассудное злоупотребление магией привлекло в мир демонов Пылающего Легиона, которые нанесли существенный урон эльфийской цивилизации. Насчет войн демонов с троллями ничего не известно, но можно предположить, что нашествие не обошло их стороной.' FROM `page_text` WHERE `ID`=2200 AND MD5(`Text`)='7c68b29f2d8888bc343640def83a935d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2200 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2201, 'ruRU', 'В конце страшного противостояния, известного под названием Войны Древних, Источник Вечности взорвался. Мощная волна разорвала Калимдор на части, превратив его в несколько менее крупных континентов и островов.' FROM `page_text` WHERE `ID`=2201 AND MD5(`Text`)='4e6290cabc48c17c59a033af29675d90' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2201 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2203, 'ruRU', 'Годы после Великого Раскола были для троллей самыми тяжелыми. Их разрозненные королевства были охвачены голодом и страхом. Тролли Гурубаши в отчаянии искали помощи у древних мистических сил. Все тролли имели общих многочисленных богов, но на призывы Гурубаши откликнулся самый темный и мрачный из них.' FROM `page_text` WHERE `ID`=2203 AND MD5(`Text`)='cdfcc9f5c321cd3d36b09f6831318409' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2203 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2204, 'ruRU', 'Хаккар Свежеватель Душ – жестокий и кровожадный дух – решил прийти на помощь троллям. Открыв Гурубаши секреты крови, он помог им захватить большую часть Тернистой долины и несколько островов Южных морей. Но за свою помощь Хаккар потребовал очень дорогую цену.' FROM `page_text` WHERE `ID`=2204 AND MD5(`Text`)='cc75bacb5a19baa9a2e1555157bff5a2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2204 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2205, 'ruRU', 'Кровожадный бог требовал ежедневного приношения множества жертв. Он мечтал явиться в реальный мир и выпить кровь всех живых существ. Но в конце концов Гурубаши поняли, что за создание им помогает, и восстали против него. Самые сильные племена пошли войной на Хаккара и его верных жрецов Атал\'ай.' FROM `page_text` WHERE `ID`=2205 AND MD5(`Text`)='799643039cdf2c1d15a003e2451799bd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2205 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2206, 'ruRU', 'О страшной войне между слугами Хаккара и остальными троллями Гурубаши говорят только шепотом. От магии, которую обрушивали друг на друга злой бог и его мятежные дети, содрогалась земля. В самый последний момент троллям удалось изгнать Хаккара из мира, убив его аватару.' FROM `page_text` WHERE `ID`=2206 AND MD5(`Text`)='1213fc9cb0015a2c9f739432b5f335a5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2206 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2207, 'ruRU', 'Даже его жрецы из племени Атал\'ай, были изгнаны из столицы Зул\'Гуруба в северные топи. Там, посреди болот, они воздвигли огромный Храм Атал\'Хаккара и продолжили дело своего павшего хозяина…' FROM `page_text` WHERE `ID`=2207 AND MD5(`Text`)='454a81a68f79ebdbc6de0860b34e07cc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2207 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2212, 'ruRU', 'О, я проклят! Когда-то я был великим магом огров Черной Вершины. Но я бросил вызов Арроку Роковому Смертному Воплю – и он украл мою магию, а потом наслал на меня проклятье. Теперь мне приходится скитаться по залам Ордамара, подобно жалкой твари!\r\n\r\nПомоги мне! Найди Аррока и укради у него мою магию! Это будет нелегко, потому что Аррок прячется. Чтобы выманить его, нужно очень важное событие.\r\n\r\nТаким событием могла бы быть смерть его ближайшего помощника, вождя Омокка.\r\n\r\nПрочти, и ты поймешь.' FROM `page_text` WHERE `ID`=2212 AND MD5(`Text`)='fde434bf6193a8f60f02daafbea8e997' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2212 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2213, 'ruRU', 'Вождь Омокк правит Черной Вершиной с помощью магии Аррока. Аррок наложил на Омокка заклятие, которое убивает любого огра, бросившего ему вызов. Омокк применял это заклятье много раз, а черепа его жертв складывал на месте силы над своим жилищем.\r\n\r\nВот куда ты должен идти, чтобы встретится с Арроком.' FROM `page_text` WHERE `ID`=2213 AND MD5(`Text`)='ecca6c4e85ce20a709e05f153a16b772' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2213 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2214, 'ruRU', 'Найди наконечник Грубой силы в лагере Изрубленного Щита. Эти глупцы часто прячут их под свои лежанки возле входа во владения Черной Вершины.\r\n\r\nКогда у тебя будет наконечник, иди к вождю Омокку, убей его, а потом насади на наконечник его голову.\r\n\r\nТогда ты будешь готов к настоящему делу.' FROM `page_text` WHERE `ID`=2214 AND MD5(`Text`)='a34150904526d77ee553129aa6f71899' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2214 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2215, 'ruRU', 'Найди место силы над владениями Черной Вершины, за Паучим лабиринтом. Там навалены черепа врагов и соперников Аррока. Вот туда-то ты и должен воткнуть наконечник с головой Омокка!\r\n\r\nКогда голова будет на месте, Аррок точно придет… но сначала он пришлет своих приспешников. Убей их – и он придет сам.\r\n\r\nУбей Аррока и возьми мою магию обратно. Когда я вновь обрету ее, я тебя вознагражу.' FROM `page_text` WHERE `ID`=2215 AND MD5(`Text`)='c7dba283cc5e90c4d825e16fa2cb7bbb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2215 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2216, 'ruRU', 'Удачи тебе. Вот тебе подсказка, как справится с приспешниками Аррока:\r\n\r\nЗаклятие Омокка, убивающее огров, останется в силе даже после гибели самого Омокка. В бою с приспешниками Аррока пробуди силу в голове Омокка – и она, может быть, убьет твоих врагов!\r\n\r\nСпособ что надо.' FROM `page_text` WHERE `ID`=2216 AND MD5(`Text`)='87f2b54d5abf0f763fb948deb375a438' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2216 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2217, 'ruRU', 'На добрую память о Джесс Моралес' FROM `page_text` WHERE `ID`=2217 AND MD5(`Text`)='77922e02023b94fc7f589dd23563a6d4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2217 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2232, 'ruRU', 'Агашам!$b$bНаши планы должны оставаться тайной при любых обстоятельствах! Нельзя допустить, чтобы остальные племена узнали о них.$b$bПодпись:$b$bВестник Эльм' FROM `page_text` WHERE `ID`=2232 AND MD5(`Text`)='a2245a473daa813a739e78f743aa3457' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2232 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2233, 'ruRU', 'Агашам!$b$bВместе мы будем гораздо сильнее, чем все племена тауренов вместе взятые! Все же мы настаиваем на вашем полном подчинении. Помните, ваш народ получит вознаграждение только после воплощения наших замыслов!$b$bПодпись:$b$bВестник Рекс' FROM `page_text` WHERE `ID`=2233 AND MD5(`Text`)='dc26910aebab2322cff46f814e867386' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2233 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2234, 'ruRU', 'Агашам!$b$bСкоро наши агенты из Лордерона встретятся с вашими посланниками. Мы сообщим вам, как только найдем подходящее место для встречи.$b$bПодпись:$b$bВестник Гракус' FROM `page_text` WHERE `ID`=2234 AND MD5(`Text`)='aa40fa03cd197f7340d098222bb38c34' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2234 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2251, 'ruRU', 'Враги… со всех сторон.$B$BПо глазам вижу. Древобрюхи – зло. Враг.$B$BНужно защитить племя. Защитить клан Зимней Спячки. Выгнать врагов с нашей земли.' FROM `page_text` WHERE `ID`=2251 AND MD5(`Text`)='8c977f1874f92dac836eadf626b4ee94' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2251 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2271, 'ruRU', 'Натака, в Тысяче Игл все хорошо. Кентавры вот только иногда нападают, но это нельзя назвать реальной угрозой. Впрочем, говорят, что в последнее время кланы кентавров объединяются.\r\n\r\nМы все понимаем, к чему может привести объединение такого безжалостного народа, как кентавры… Я стараюсь не думать об этом, ты же знаешь… их ненависть вечна… даже друг к другу.\r\n\r\n-Дозорный утесов Долгорог' FROM `page_text` WHERE `ID`=2271 AND MD5(`Text`)='15f2fad024407d04ca8f652dba05c22e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2271 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2291, 'ruRU', 'Архиепископ Алонсус Фаол\r\n\r\nБлагосклонный покровитель Храма Света.\r\n\r\nНесмотря на то что архиепископ Фаол начал свой светлый путь в лордеронском Стратхольме, он всегда был другом Штормграда. В темные времена после Второй войны он помогал монастырю в Североземье и жертвовал значительные средства на восстановление самого города.\r\n\r\nСей храм стоит не только как бастион Света, но и как памятник благородному духу и щедрости этого человека.' FROM `page_text` WHERE `ID`=2291 AND MD5(`Text`)='0c7ad60445075f1947fbe601309c257e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2291 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2292, 'ruRU', 'Король Ллейн I из дома Ринн\r\n\r\nВластительный лорд Штормграда\r\n\r\nЗащитник Азерота' FROM `page_text` WHERE `ID`=2292 AND MD5(`Text`)='90e4ea3a2bc907eed7ded2bbdefb4a93' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2292 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2293, 'ruRU', 'Командующий флотами Альянса\r\n\r\nДруг Штормграда' FROM `page_text` WHERE `ID`=2293 AND MD5(`Text`)='a4306cd041bea158797398c7febcb315' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2293 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2294, 'ruRU', 'Леди Мара Фордрагон\r\n\r\nВысший клирик Штормграда\r\n\r\nПокровительница беженцев, наводнивших Лордерон после Первой войны.\r\n\r\nОна была светлой матерью нашего будущего. Да упокоится она в Свете.' FROM `page_text` WHERE `ID`=2294 AND MD5(`Text`)='0495cb35ce6bab051e160fad91ac8b87' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2294 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2295, 'ruRU', 'Еще до дней, которые мы помним, Мать-Земля своим дыханием создала золотые туманы рассвета. Там где эти янтарные облака коснулись земли, появились бесконечные пшеничные и ячменные поля. Это была чаша ее творений – великая чаша жизни и надежды.' FROM `page_text` WHERE `ID`=2295 AND MD5(`Text`)='78875093866a12021816a23c04cbfc4b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2295 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2296, 'ruRU', 'Очи Матери-Земли взирали сверху на созданные ею земли. Ее правое око, Ан\'ше – солнце, дарило тепло и свет всей земле, а левое, Му\'ша – луна, приносило покой и сон детям рассвета. Сила ее взгляда была такова, что пока одно ее око дремало, небо поворачивалось другой стороной. Ее любящий взгляд превращал день в ночь, и наоборот.' FROM `page_text` WHERE `ID`=2296 AND MD5(`Text`)='60473d12787e86422fa03904b2c3cca8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2296 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2297, 'ruRU', 'Глядя правым оком на золотой рассвет, Мать-Земля распростерла свои нежные руки над золотыми равнинами. Там, где легла тень от ее рук, из земли восстал благородный народ. Это Шу\'хало, нареченные тауренами, вышли вознести благодарность и молитвы своей любящей матери. Там, в бескрайних полях рассвета, дети земли поклялись восхвалять ее имя до скончания времен.' FROM `page_text` WHERE `ID`=2297 AND MD5(`Text`)='99aeaa8e5cbc3cedc387b1549b12092a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2297 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2298, 'ruRU', 'Странствуя по полям рассвета, дети земли слышали мрачный шепот из подземных недр. Этот шепот рассказывал им про войну и обман. Многие Шу\'хало попали под его чары и впустили зло в свои души. Они отвернулись от своих добрых братьев и утратили первозданную чистоту.' FROM `page_text` WHERE `ID`=2298 AND MD5(`Text`)='b53121526301bbaa02eba63820a78161' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2298 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2299, 'ruRU', 'Увидев падение своих детей, Мать-Земля не выдержала такого горя. Она вырвала свои глаза и бросила их на бескрайний небосвод. С тех пор Ан\'ше и Му\'ша, словно бы желая утешить друг друга, гоняются друг за другом по небу. Поэтому день и сменяет ночь.' FROM `page_text` WHERE `ID`=2299 AND MD5(`Text`)='0820d74cadf857e6bf70991c02bfd06c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2299 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2300, 'ruRU', 'Но даже ослепнув, Мать-Земля не могла оставаться безучастной. Ветер доносил до ее ушей вести обо всем, что происходило на рассветных равнинах. Ее любящее сердце всегда пребывало с ее детьми, как и ее великая мудрость.' FROM `page_text` WHERE `ID`=2300 AND MD5(`Text`)='0e8dc9d583f0e7015d6b8cc4c54eaf74' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2300 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2301, 'ruRU', 'В сердца своих светлых детей Мать-Земля вложила любовь к охоте, ибо создания первого рассвета были злобными и жестокими. Они прятались от Матери-Земли в темных и глухих уголках мира. Шу\'хало охотились на них везде, где находили, и укрощали их нрав с благословения Матери Земли.' FROM `page_text` WHERE `ID`=2301 AND MD5(`Text`)='985f0f79290fe03138606278733f6975' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2301 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2302, 'ruRU', 'Но один великий дух ускользнул от них. Это был Апа\'ро, которого ночные эльфы называли Малорном, гордый белоснежный олень. Его рога упирались в небеса, а его сильные копыта оставляли глубокие следы по всей земле. Шу\'хало долго охотились за Апа\'ро, но в конце концов сумели окружить гордого оленя.' FROM `page_text` WHERE `ID`=2302 AND MD5(`Text`)='46f9c5562b83af831886d0f22af30842' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2302 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2303, 'ruRU', 'Пытаясь спастись, великий олень прыгнул на небо, но зацепился могучими рогами за звезды. Как ни старался Апа\'ро вырваться, ничего у него не вышло. И тогда его нашла Му\'ша, которая гналась за свои братом Ан\'ше. Она увидела, как могучий олень борется за свою свободу, и тотчас же влюбилась в него.' FROM `page_text` WHERE `ID`=2303 AND MD5(`Text`)='2b8423afd01113c7cbc7464f9daac346' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2303 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2304, 'ruRU', 'Умница луна договорилась с великим оленем, что освободит его в обмен на его любовь.$b$bЖелание Му\'ша исполнилось, и она зачала от Апа\'ро ребенка, который родился темной ночью. Он получил имя Ценарион и бродил по звездной тропе между пробуждающимся миром и небесным царством.' FROM `page_text` WHERE `ID`=2304 AND MD5(`Text`)='b165a5c1315591c6bc6b3029da5a0eac' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2304 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2305, 'ruRU', 'Прошло время, и Ценарион стал сильным, как его великий отец. Брат деревьев и звезд, этот великий охотник странствовал по миру, напевая умиротворяющую песню рассвета. Все живое склонялось перед его грацией и красотой. Никого на свете не было мудрее сына луны и белого оленя.' FROM `page_text` WHERE `ID`=2305 AND MD5(`Text`)='e682b545ed5a1cdf07d661616b138a1a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2305 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2306, 'ruRU', 'Со временем Ценарион стал другом Шу\'хало и рассказывал им о мире. Дети земли назвали его своим братом и поклялись помогать ему в заботе о полях жизни и любимых созданиях Матери-Земли.' FROM `page_text` WHERE `ID`=2306 AND MD5(`Text`)='5e6a7f0ddfabfc47e247549fe5cc6dba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2306 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2307, 'ruRU', 'Ценарион научил детей земли разговаривать с деревьями и травами. Шу\'хало стали друидами и совершили множество чудес, приносящих земле здоровье. Многие поколения Шу\'хало охотились вместе с Ценарионом и хранили землю от темных сил.' FROM `page_text` WHERE `ID`=2307 AND MD5(`Text`)='4dbceea2a442c1aa29e0952e5a729471' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2307 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2308, 'ruRU', 'Когда рассветные туманы рассеялись, наступили дни, которые мы помним. Ценарион ушел по своим неизбывным путям. Из за его ухода Шу\'хало, нареченные тауренами, впали в отчаянье и забыли многое из того, чему он учил. Сменилось поколение, и они разучились говорить с деревьями и травами. И тогда их ушей вновь начали достигать темные голоса из недр земли.' FROM `page_text` WHERE `ID`=2308 AND MD5(`Text`)='b2d9860235d48959f76feb634e3afb7a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2308 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2309, 'ruRU', 'Дети земли не слушали темных голосов, но их постигло страшное проклятье. Из темных западных земель пришли орды кровожадных существ – кентавров. Каннибалы и разрушители, кентавры набросились на Шу\'хало, как саранча. Даже благословение Матери-Земли не помогло смелым охотника одолеть эту напасть.' FROM `page_text` WHERE `ID`=2309 AND MD5(`Text`)='ab7f136cbe697d5f9905794d4798e5ca' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2309 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2310, 'ruRU', 'Шу\'хало навсегда покинули родные земли и стали кочевать по бескрайним равнинам. Но они хранят надежду, что их племена найдут новое пристанище под сенью любящих рук Матери-Земли.' FROM `page_text` WHERE `ID`=2310 AND MD5(`Text`)='cd122ead513218887e606c863cc796a8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2310 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2371, 'ruRU', 'Анналы Дарроушира\r\n\r\nПоселение Дарроушир, названное в честь озера Дарроумир, находится к западу от этого озера на южной границе Лордерона. Известное своими скромными, но трудолюбивыми обитателями, это поселение было ничем не примечательно, пока не началась Вторая война.\r\n\r\nГерои появляются во время войны, а после нее их забывают.' FROM `page_text` WHERE `ID`=2371 AND MD5(`Text`)='6121776fcfc92e1eef342c8540709583' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2371 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2372, 'ruRU', 'Битва за Дарроушир\r\n\r\nБитва за Дарроушир произошла в середине Второй войны, когда силы Плети бесчинствовали по всему Лордерону. Хотя поселение Дарроушир было отрезано от основных сил Альянса, в нем был отряд собственных войск, подразделение паладинов Серебряной Длани, а также местное ополчение, которое возглавлял капитан Джозеф Редпат.' FROM `page_text` WHERE `ID`=2372 AND MD5(`Text`)='4b20519a5517acaab63dfdbe551dc109' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2372 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2373, 'ruRU', 'Первые удары Плети по Дарроуширу были сравнительно редкими и слабыми. Отдельные группы скелетов и ходячих трупов, нападавшие на окрестности деревни, легко отгонялись ее защитниками.\r\n\r\nНо Плеть не собиралась отступать, и вскоре на поселение обрушилась вторая волна атак. Отборные вурдалаки под предводительством лорда Хоргуса спустились с холмов и вступили в бой с защитниками Дарроушира.' FROM `page_text` WHERE `ID`=2373 AND MD5(`Text`)='9f93f6616da96368bea0003560288242' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2373 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2374, 'ruRU', 'Силы защитников были на исходе, когда им на помощь пришли паладины Серебряной Длани. Их предводитель Дейвил Крокфорд сам был родом из Дарроушира. Услышав о нападении, он привел на помощь своих соратников. Совместными усилиями они остановили слуг Хоргуса.\r\n\r\nКогда на поле битвы появился сам Хоргус, Дейвил вышел ему навстречу. Их поединок длился очень долго, но Дейвил сумел одержать верх. Однако смертельная рана, полученная им, не позволила ему намного пережить своего врага.' FROM `page_text` WHERE `ID`=2374 AND MD5(`Text`)='0ff245d163ac38546335d3536ed47a78' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2374 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2375, 'ruRU', 'Битва продолжалась, и капитан Редпат со своим ополчением твердо держал оборону. Они бы победили, если бы не магия рыцаря смерти Мардука Черного.\r\n\r\nВ самом разгаре битвы Мардук приблизился к Редпату и своей черной магией растерзал его душу, обратив отважного капитана в злобную тень.' FROM `page_text` WHERE `ID`=2375 AND MD5(`Text`)='da7f5498098b6e6bc2aaf49fbf9cfb67' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2375 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2376, 'ruRU', 'От капитана Крассена порча перекинулась и на других защитников Дарроушира, которые после этого предавали и убивали своих бывших союзников. Потом они вошли в поселение и перерезали всех, кто укрылся в домах.\r\n\r\nОстатки армии Плети вместе с черной тенью Редпата покинули разоренное поселение и ворвались в Лордерон, неся с собой боль и смерть Второй войны.' FROM `page_text` WHERE `ID`=2376 AND MD5(`Text`)='1f6550d8499acf8781697d368bc8d048' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2376 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2377, 'ruRU', 'Анналы Дарроушира\r\n\r\nПоселение Дарроушир, названное в честь озера Дарроумир, находится к западу от этого озера на южной границе Лордерона. Известное своими скромными, но трудолюбивыми обитателями, это поселение было ничем не примечательно, пока не началась Вторая война.\r\n\r\nВ ту войну появилось множество героев. И потеряно было немало.' FROM `page_text` WHERE `ID`=2377 AND MD5(`Text`)='ba9323167a8d2037f0f2fdceaf7fedfe' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2377 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2378, 'ruRU', 'Битва за Дарроушир\r\n\r\nБитва за Дарроушир произошла в середине Второй войны, когда силы Плети бесчинствовали по всему Лордерону. Хотя поселение Дарроушир было отрезано от основных сил Альянса, в нем был отряд собственных войск, подразделение паладинов Серебряной Длани, а также местное ополчение, которое возглавлял капитан Джозеф Редпат.' FROM `page_text` WHERE `ID`=2378 AND MD5(`Text`)='4b20519a5517acaab63dfdbe551dc109' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2378 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2379, 'ruRU', 'Первые удары Плети по Дарроуширу были сравнительно редкими и слабыми. Отдельные группы скелетов и ходячих трупов, нападавшие на окрестности деревни, легко отгонялись ее защитниками.\r\n\r\nНо Плеть не собиралась отступать, и вскоре на поселение обрушилась вторая волна атак. Отборные вурдалаки под предводительством лорда Хоргуса спустились с холмов и вступили в бой с защитниками Дарроушира.' FROM `page_text` WHERE `ID`=2379 AND MD5(`Text`)='cdd2c7546ac2186df624225f4df88d1e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2379 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2380, 'ruRU', 'Силы защитников были на исходе, когда им на помощь пришли паладины Серебряной Длани. Их предводитель Дейвил Крокфорд сам был родом из Дарроушира. Услышав о нападении, он привел на помощь своих соратников. Совместными усилиями они остановили слуг Хоргуса.\r\n\r\nКогда на поле битвы появился сам Хоргус, Дейвил вышел ему навстречу. Их поединок длился очень долго, но Дейвил сумел одержать верх. Однако смертельная рана, полученная им, не позволила ему намного пережить своего врага.' FROM `page_text` WHERE `ID`=2380 AND MD5(`Text`)='0ff245d163ac38546335d3536ed47a78' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2380 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2381, 'ruRU', 'Битва продолжалась, и капитан Редпат со своим ополчением твердо держал оборону. Они бы победили, если бы не магия рыцаря смерти Мардука Черного.\r\n\r\n В самом разгаре битвы Мардук приблизился к Редпату и своей черной магией растерзал его душу, обратив отважного капитана в злобную тень.' FROM `page_text` WHERE `ID`=2381 AND MD5(`Text`)='da7f5498098b6e6bc2aaf49fbf9cfb67' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2381 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2382, 'ruRU', 'От капитана Редпата порча перекинулась и на других защитников Дарроушира, которые после этого предавали и убивали своих бывших союзников. Потом они вошли в поселение и перерезали всех, кто укрылся в домах.\r\n\r\nОстатки армии Плети вместе с черной тенью Редпата покинули разоренное поселение и ворвались в Лордерон, неся с собой боль и смерть Второй войны.' FROM `page_text` WHERE `ID`=2382 AND MD5(`Text`)='1f6550d8499acf8781697d368bc8d048' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2382 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2383, 'ruRU', 'Судьба Хоргуса Опустошителя\r\n\r\nХоргус Опустошитель погиб в битве за Дарроушир. Но зло, которое он нес в себе, не умерло вместе с ним. Победившие воины Плети отрезали его голову и забрали ее с собой, чтобы наводить ужас на все живое.\r\n\r\nЧерез несколько дней отряд Плети, у которого была голова Хоргуса, был уничтожен паладинами Серебряной Длани, а саму голову утопили в озере Чернолесья.' FROM `page_text` WHERE `ID`=2383 AND MD5(`Text`)='aadf55c02f77ba377353b7437e5acc52' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2383 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2384, 'ruRU', 'Судьба Мардука Черного\r\n\r\nМардук пережил Вторую войну, сея смерть и страдания своим руническим мечом. Хотя Мардук жив и сейчас, его меч был утерян в битве при Перекрестке Корина. Храбрый капитан дворфов разбил его своим зачарованным щитом, обратив Мардука в бегство и обеспечив победу Альянсу.\r\n\r\nСломанный меч погрузился в землю и осквернил ее, образовав впадину, которую в наши дни называют Чумным Шрамом.' FROM `page_text` WHERE `ID`=2384 AND MD5(`Text`)='cb1d3eb33081b4c136c8c57eb2245162' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2384 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2386, 'ruRU', 'Судьба Джозефа Редпат\r\n\r\nДжозеф Редпат погиб во время битвы при Дарроушире. Его искалеченная душа стала совершенно новым существом, несущим великое зло всему Лордерону.\r\n\r\nСилы Альянса в конечном счете победили Редпата на пустоши Гаррона в восточной части Андорала. Его щит до сих пор лежит возле амбара на чумной ферме, и приспешники Плети помнят об этом.' FROM `page_text` WHERE `ID`=2386 AND MD5(`Text`)='c6e294f8f2f93c1fa85657295236c14b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2386 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2391, 'ruRU', 'Судьба Карлина Редпата\r\n\r\nКарлин, брат капитана Джозефа Редпата, был тяжело ранен в битве за Дарроушир, однако ему удалось выжить.\r\n\r\nЧерез несколько дней измученного жаждой и сильным жаром Карлина, неизвестно как оказавшегося возле Перекрестка Корина, подобрали агенты Серебряного Рассвета. Они залечили его раны и доставили в часовню Последней Надежды.\r\n\r\nБлагодарный Карлин вступил в ряды Серебряного Рассвета. И в наши дни он сражается с Плетью, стремясь отомстить тем, кто погубил его дом и его брата.' FROM `page_text` WHERE `ID`=2391 AND MD5(`Text`)='426f1db81ecb975074dbff7076ad6711' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2391 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2413, 'ruRU', 'Снег ослепляет…$B$BПлемя нужно защитить. Дать им силу. Быть сильным.$B$BНе знаю…' FROM `page_text` WHERE `ID`=2413 AND MD5(`Text`)='251746e916d7e8d8827e20b64be7a4e5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2413 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2414, 'ruRU', 'Огненная вода.$B$BСделай еще. Еще огненной воды.$B$BОгненная вода дает силу. Помогает побеждать врагов.$B$BУ Зимней Спячки нет союзников. Но есть сила.' FROM `page_text` WHERE `ID`=2414 AND MD5(`Text`)='41b96bf1315679a6d88aa606b5e07aa9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2414 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2415, 'ruRU', 'Больше. Еще больше… $B$BКлан Зимней Спячки… не… слабый…' FROM `page_text` WHERE `ID`=2415 AND MD5(`Text`)='2fbbe3929d2f0d1bf29d035a832fe09d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2415 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2431, 'ruRU', 'Дата занесения: нет данных\r\n\r\nИмя: Натанос Маррис, человек, предводитель следопытов Лордерона.\r\n\r\nТема:\r\n\r\nХочу отметить несогласие Кель\'таса Солнечного Скитальца с моим решением принять Натаноса Марриса в наши ряды. Следует отметить, что Натанос, несмотря на свое человеческое происхождение, является одним из самых талантливых следопытов, которых мне доводилось обучать.\r\n\r\n(продолжение следует)' FROM `page_text` WHERE `ID`=2431 AND MD5(`Text`)='92e247f1e43693700713618938e69f33' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2431 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2432, 'ruRU', 'Я никогда так не гордился своим ремеслом, как в последние несколько лет. Спрос на услуги убийц, шпионов и разведчиков высок как никогда. На первый взгляд может показаться, что нас кормит война. Но ни в одну войну мы не процветали так, как процветаем сейчас, когда мирное время подходит к концу.$B$BМне передали, что ты $gпоявился:появилась; в наших краях и хочешь кое-чему научиться. Когда будет время, приходи к стойлам позади аббатства.$B$B-Джорик Керридан, наставник разбойников' FROM `page_text` WHERE `ID`=2432 AND MD5(`Text`)='cc0110424408eec5d43262d6b4015ccf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2432 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2433, 'ruRU', 'Готов спорить, что ты сначала $gрешил:решила;, будто это настоящее письмо от короля или кого-то там еще. Видишь ли, я знаю толк в фальшивых письмах. Мне надо было убедиться, что ты точно прочтешь это послание, а как еще этого добиться?$B$BЯ нахожусь в Старой Наковальне, рядом с огненной ямой. Как будешь $gготов:готова;, приходи, поговорим. Было бы любопытно с тобой познакомиться.$B$B-Сольм Харгрин, наставник разбойников' FROM `page_text` WHERE `ID`=2433 AND MD5(`Text`)='afe59023cc5da2c5b866eb306a410f4e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2433 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2434, 'ruRU', 'Приветствую тебя, $N. Я был погружен в размышления, когда мне в голову пришла мысль тебе написать.$B$BМногие наши соплеменники считают духовными лидерами шаманов, подобных нашему Вождю. Другие предпочитают поклоняться мечу и топору. Но не стоит забывать, что на исход битв и даже целых войн влияют совсем другие силы. Вот об этом я и хочу поговорить с тобой, $N. Ты можешь найти меня в Логове, что в Долине Испытаний.$B$B-Руаг, наставник разбойников.' FROM `page_text` WHERE `ID`=2434 AND MD5(`Text`)='7a78c0be6fbff2f83efdee3f96957c3b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2434 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2436, 'ruRU', 'Постарайся принять мои слова во внимание, $N. В наше время хитрость и обман распространены везде… даже в нашем славном Подгороде. Каждый, кто сохраняет верен Сильване, вносит свой вклад в славное будущее Отрекшихся. Мы не владеем магией и не охраняем границы – наше ремесло иного рода. $B$BНайди меня в таверне в Могильнике. Там и поговорим.$B$B-Давид Триас, наставник разбойников' FROM `page_text` WHERE `ID`=2436 AND MD5(`Text`)='1ee35e703921551edc3ebd19cfd7f4d0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2436 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2437, 'ruRU', 'Сал\'ах, друг мой. Я надеюсь, ты $gполучил:получила; мой знак. Меня попросили помочь тебе. Я нахожусь в Тенистой долине, среди ветвей великого Альдрассила. Если тебе нужны знания, обращайся ко мне.\r\n\r\nВ наше неспокойное время все благоразумные мастера тонких искусств должны держаться друг друга. По-другому мы не сможем сохранить Тельдрассил и наше ремесло. \r\n\r\nПриходи, когда сможешь.\r\n\r\n-Фрагун Шепот Тени, наставник разбойников' FROM `page_text` WHERE `ID`=2437 AND MD5(`Text`)='30e41fb328dba852ed9b9b9469ace317' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2437 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2438, 'ruRU', 'Приветствую тебя, $gбрат:сестра;. Изувеченная Длань выражает тебе свое почтение и надеется, что в нашей долине ты найдешь, где применить свое ремесло. Учти: мы пристально следим за твоими успехами и неудачами.$B$BМне поручено оценить твое мастерство и сообщить, когда ты будешь $gготов:готова; к серьезным делам.$B$BКак будет время, навести меня в глубинах Логова.$B$B-Руаг, наставник разбойников.' FROM `page_text` WHERE `ID`=2438 AND MD5(`Text`)='7c56b28d5712ff874ccf8a84396ab70b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2438 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2439, 'ruRU', 'Скажи-ка мне, |3-6($c), ты когда-нибудь $gслышал:слышала; боевой клич орков? А может быть, ты $gзащищал:защищала; свой дом от гноллов, желающих перегрызть глотку тебе и твоим близким? Жутковато звучит, не правда ли?$B$BЧто ж, тебе пригодится моя помощь. Меня можно найти в североземском аббатстве. Мои знания стоят недешево, но если ты достаточно $gопытен:опытна;, я могу научить тебя приемам и хитростям, которые помогут тебе защищать Штормград и наши земли.$B$BЛлан Бишер, наставник воинов' FROM `page_text` WHERE `ID`=2439 AND MD5(`Text`)='e37be7aa2609a3694963472929c98982' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2439 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2440, 'ruRU', 'ВНИМАНИЕ:$BНемедленно свяжись с Траном Корманом. Он находится на объекте А3, известном местному населению как "Старая Наковальня". После успешного контакта с Корманом продолжай подготовку к войне за возвращение нашего Гномрегана!$B$BВсе твои действия и усилия должны быть направлены на выполнение этих указаний. Сделав все, что нужно, ты получишь новое задание.' FROM `page_text` WHERE `ID`=2440 AND MD5(`Text`)='3caea5c835502391a16f35a5a104f5cf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2440 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2442, 'ruRU', 'Клянусь бородой Магни, $N, нам нужно многое обсудить, а времени очень мало. Как можно скорее найди меня в Старой Наковальне, что в Холодной долине. Там и начнем обучение.$B$BЯ мог бы открыть тебе секреты быстроты движений… но об этом говорить еще рано. Сначала тебе нужно научиться правильно держать топор, привыкнуть к весу доспехов и запаху пота, заливающему лицо в тяжелом бою… Для начала этого будет достаточно.$B$B-Тран Корман, наставник воинов' FROM `page_text` WHERE `ID`=2442 AND MD5(`Text`)='4a10335b0473fd06468b05d91d21d17e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2442 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2443, 'ruRU', 'Многие наши соплеменники считают, что тайная магия и чародейство – единственные источники силы. Но ты-то так не думаешь, |3-6($c)? Клинки – наша магия, щиты – наши обереги, броня – наша мудрость.$B$BБудучи мертвыми, мы сохраняем и умножаем свою силу. Ищи меня в таверне в Могильнике. Там мы обо всем и поговорим.$B$B-Даннал Штерн, наставник воинов' FROM `page_text` WHERE `ID`=2443 AND MD5(`Text`)='96fd0484f105b11bc988fd1505750d1b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2443 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2445, 'ruRU', 'Существует четыре правила магии:$B$B Магия могущественна.$B Магия развращает.$B Магия порождает зависимость.$B Магия притягивает обитателей Круговерти Пустоты к тому, кто ее применяет.$B$BЭти правила неизменны. Этим правилам ты $gдолжен:должна; будешь подчинить всю свою жизнь, если захочешь продолжить путь магов…$B$BЕсли у тебя хватит глупости не внять этому предупреждению, приходи ко мне в библиотечное крыло Североземского аббатства. Я буду ждать тебя на втором этаже.$B$BКельден Бремен, наставник магов' FROM `page_text` WHERE `ID`=2445 AND MD5(`Text`)='f026dd18127e79f58ab62d2735f82478' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2445 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2446, 'ruRU', 'Кому: Всем новым студентам тайных искусств$BВы должны явиться к своему преподавателю, гному Маррайку Нуррибиту, и находиться в его распоряжении до того момента, пока вы не будете призваны на помощь своему народу в освоении новых земель. Будьте готовы к предельно жестким экзаменам и изнурительным тренировкам одновременно с поиском жилья и (или) установкой контактов с местным населением.$B$BС вопросами по поводу ваших обязанностей и возможностей обращайтесь к Маррику Нуррибиту.' FROM `page_text` WHERE `ID`=2446 AND MD5(`Text`)='814e1ba34690d36ab8bee743df3a9269' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2446 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2447, 'ruRU', 'Скверна и зло, с которыми, как принято считать, сопряжена тайная магия, – ничто по сравнению с тем, что мы уже пережили. Мы больше не жертвы, <имя>. Мы сами выбираем свою судьбу. Сильвана указала нам путь – она доказала, что у нас есть своя воля и что мы не обязаны подчиняться этому ублюдку Артасу.\r\n\r\nНайди меня в церкви – я расскажу тебе больше… если захочешь.\r\n\r\n- Изабелла, наставница магов' FROM `page_text` WHERE `ID`=2447 AND MD5(`Text`)='bf633a01d24e53a30aabf8e4681a63a9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2447 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2448, 'ruRU', 'Поздравляю с пробуждением! Все хитрости и премудрости тайной магии будут твоими – если, конечно, у тебя хватит силенок их удержать.$B$BКак будешь готов, ступай к Май\'ах.$B$BОна расскажет тебе про такую магию и заклинания, с которыми тебе любой враг не страшен!$B$BМай\'ах живет возле Логова, в Долине Испытаний. Ты придешь, ее найдешь, а она тебе силу даст. А потом ты покажешь всем остальным, что ты крутишь магией как хочешь, а не наоборот.' FROM `page_text` WHERE `ID`=2448 AND MD5(`Text`)='20d0d9c35aa9a9dc237acd4a99fc35f7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2448 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2449, 'ruRU', 'Частенько последователи Священного Света запугивают тех, кто интересуется настоящей силой, пытаясь убедить их, что тайная магия непознаваема. Но не все, что приходит извне, является злом. Не все сущности стремятся подчинить себе других. Если у тебя будет достаточно силы, те же самые сущности станут твоими слугами.$B$BОб этом я хотела бы поговорить с тобой. Жду тебя на кладбище справа от аббатства.$B$B-Друзилла ла Салле, наставница чернокнижников' FROM `page_text` WHERE `ID`=2449 AND MD5(`Text`)='24975551892ba84e585ba3fedbb5bf34' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2449 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2450, 'ruRU', 'ВНИМАНИЕ:$B$BНичего не говори! Не оглядывайся! За тобой могут следить.$B$B$N, меня зовут Аламар Гримм. Я обучаю тех, кого интересует мудрость и сила из… из других миров. Меня попросили связаться с тобой и предложить тебе услуги учителя.$B$BКогда будешь $gготов:готова;, ищи меня на задворках Старой Наковальни.$B$B-Аламар Мрачнн, наставник чернокнижников' FROM `page_text` WHERE `ID`=2450 AND MD5(`Text`)='8b9f28d3dc98569b0997f21cc1e913f6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2450 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2451, 'ruRU', '$N, я пишу это послание самыми могущественными чернилами, какие только могу создать. Они принесут проклятье любому, кроме тебя. Я вызываю могущественных демонов Круговерти Пустоты просто для развлечения. Я убиваю своих врагов, пока они спят. Ты уже видел могущество, которое можно обрести на моем пути. Мои братья этому рады.$B$BКогда освоишься, найдешь меня в глубине Логова. Нам надо поговорить о важных вещях.$B$B-Нарток, наставник чернокнижников' FROM `page_text` WHERE `ID`=2451 AND MD5(`Text`)='f900c59efb07cffdd9b49f4e96627437' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2451 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2452, 'ruRU', 'Мы в жутком положении, ты не находишь, $N? Отравленные проклятым принцем. Отвергнутые всеми, кого мы любили. Да, прекрасная Сильвана принесла нам свободу воли, но что это дает нам сейчас? Мы сменили хозяев, но остались рабами.$B$BА что если мы сами станем хозяевами? Ты ведь знаешь о чем я думаю, правда?$B$BМы ведь чужие даже среди Отрекшихся, $N. И потому нам обязательно нужно встретиться. Я буду в церкви Могильника.' FROM `page_text` WHERE `ID`=2452 AND MD5(`Text`)='e6a959d1add1c82df63357698594f045' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2452 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2453, 'ruRU', 'Могучие воины защищают наши дома. Мудрые шаманы охраняют наши души и ведут нас по дороге предков. Друиды сообщают нам волю Матери-Земли.$B$BНо ты – $gохотник:охотница;, а это призвание объединяет в себе умения воинов, шаманов и друидов. Такие, как ты, являются сердце нашего народа. К тебе будут обращаться за советом и защитой. Я должен удостоверится, что ты $gготов:готова; к этому. Приходи в Лагерь Нараче.$B$B-Ланко Дальний Выстрел, наставник охотников' FROM `page_text` WHERE `ID`=2453 AND MD5(`Text`)='86eb16583865a09ab0b9dff31ddc7b94' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2453 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2454, 'ruRU', 'Теперь ты в хороших руках. Джен\'шан знает, что ты любишь охотиться, и готова тебя научить… если ты будешь слушать.$B$BПриходи в Долину Испытаний. Джен\'шан будет учить тебя охотиться и покажет, какими могущественными бывают настоящие охотники.$B$B-Джен\'шан, наставница охотников' FROM `page_text` WHERE `ID`=2454 AND MD5(`Text`)='1738b79a3571cbd53d0f23794cda5703' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2454 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2455, 'ruRU', 'Укрощение зверей, меткая стрельба, чтение следов – как научиться всему этому за такую короткую жизнь? Умения охотника требует недюжинной смекалки и огромного терпения.\r\n\r\nПуть охотника не из легких, это точно. Тебе нужно много тренироваться, чтобы достичь уровня самого неуклюжего ружейника из нашего народа. Потому я тебе и пишу.\r\n\r\nПриходи в Старую Наковальню, что в Холодной долине. Я буду ждать тебя там.\r\n\r\n-Торгас Угрюмсон, наставник охотников' FROM `page_text` WHERE `ID`=2455 AND MD5(`Text`)='2ce770cc30a68491b70026143fadd7c8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2455 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2456, 'ruRU', 'Элуна с тобой, $N. Ветер прошептал мне твое имя, и я очень рада, что могу принять участие в обучении следующего поколения охотников.\r\n\r\nЯ знаю, что ты сейчас где-то недалеко от Альдрассила. Я буду ждать там.\r\n\r\nНаши старейшины поручили мне подготовить всех новых охотников к грядущим испытаниям. Ты входишь в их число. До встречи.\r\n\r\n-Аянна Вечнобродка, наставница охотников' FROM `page_text` WHERE `ID`=2456 AND MD5(`Text`)='01abdb6c582aeaeec3fcde2b9b08c7b9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2456 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2457, 'ruRU', 'Приятно слышать, что $gодин:одна; из $gбратьев:сестер; Джен\'шан $gявился:явилась; в долину испытать свои способности. Джен\'шан ждет этого с нетерпением!$B$BНе мне тебе рассказывать, $gкакой ты сильный и ловкий охотник:какая ты сильная и ловкая охотница;. Дело Джен\'шан – сделать тебя еще более $gсильным и ловким:сильной и ловкой;.$B$BНайди Джен\'шан в Долине Испытаний. Она научит тебя, как укрощать самых сильных зверей.$B$B-Джен\'шан, наставница охотников' FROM `page_text` WHERE `ID`=2457 AND MD5(`Text`)='4ffc520ae8f100768ca993bd60edc1d1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2457 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2458, 'ruRU', 'Прошлой ночью мне во сне явились духи. Они сообщили мне о твоем прибытии и о том, что я должен помогать тебе. Нам нужно о многом поговорить: о природе, духах, Матери-Земле и ночных эльфах. Но для этого нужна личная встреча. Мой долг – подготовить тебя к грядущим испытаниям.\r\n\r\nМоя мудрость поможет тебе. Я буду ждать.\r\n\r\n-Гарт Вестник Туманов, наставник друидов' FROM `page_text` WHERE `ID`=2458 AND MD5(`Text`)='3220990b428773047aa33292b2c15ffa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2458 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2459, 'ruRU', 'Как только мне стало известно, что ты $gготов:готова; к обучению, я тотчас же послал тебе знак. Друиды Кенария рады любому пополнению своих рядов. Даже духи становятся сильнее, когда нас больше. Рано или поздно, проявив должное терпение, мы вернем былое величие. Найди меня возле верхушки Альдрассила. Я буду твоим проводником, пока ты живешь в Тенистой долине.$B$B- Мардант Крепкий Дуб, наставник друидов' FROM `page_text` WHERE `ID`=2459 AND MD5(`Text`)='abc75acd0539c2abcfb0b0c3c546b406' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2459 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2460, 'ruRU', 'Приветствую тебя, $gмолодой:молодая; |3-6($c). Ветер нашептал мне, что ты $gпришел:пришла;. Земля рассказала о твоей силе. И теперь древние духи говорят о том, что ты $gготов:готова; учиться. Наш народ нуждается в мудрых и могущественных наставниках – и находит их среди нас. Если хочешь, я научу тебя большему.$B$BИщи меня в Лагере Нараче на плато Красного Облака – нам есть, о чем поговорить.$B$B-Мила Рассветная Странница, наставница шаманов' FROM `page_text` WHERE `ID`=2460 AND MD5(`Text`)='fc067c055439424ab51641ecc060c457' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2460 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2461, 'ruRU', 'Лок-тар, $gбрат:сестра;. Стихии указали на тебя и поручили мне показать тебе путь шамана. Духи наших предков смотрят на нас и гордятся тем, что ты $gвступил:вступила; в наши ряды.\r\n\r\nКогда будешь $gготов:готова;, найди меня у входа в Логово. Я обучаю там наших собратьев. Да будет тебе попутный ветер.\r\n\r\n-Шикрик, наставница шаманов' FROM `page_text` WHERE `ID`=2461 AND MD5(`Text`)='1b2cb82b4ef2f2367839dab063dc07a1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2461 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2462, 'ruRU', 'Привет тебе, $gбрат:сестра;. Духи говорят, ты $gготов:готова; нам помочь. Ты очень здорово управляешься со стихиями – гораздо лучше, чем когда только начинал учиться у меня.$B$BСтупай к Шикрик, наставнице орочьих шаманов в Долине Испытаний. Она уже знает о тебе. Пусть наши предки гордятся тобой. Да согреет тебя огонь, и да будет тебе попутный ветер.$B$B-Иши-йо' FROM `page_text` WHERE `ID`=2462 AND MD5(`Text`)='408de2384826a5654f897f87d438e7ee' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2462 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2463, 'ruRU', 'Надеюсь, это письмо дошло до тебя, |3-6($c). Я обращаюсь к тебе с гордостью, потому что немногие обладают столь крепкой верой и готовы войти в число величайших защитников Азерота.$B$BНикогда не забывай, твой главный долг – сражаться с теми, кто угрожает нашему миру и несет скверну в наши дома.$B$BМеня назначили твоим наставником на первое время. Когда будешь $gготов:готова;, ищи меня в Аббатстве Североземья.$B$B-Брат Самуэль, наставник паладинов.' FROM `page_text` WHERE `ID`=2463 AND MD5(`Text`)='12ef9e1322c9a4f723cc511c7db0dd33' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2463 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2464, 'ruRU', 'Одни боятся нас больше, чем драконов. Другие завидуют нам больше, чем самым искусным кузнецам. Третьи превозносят нас за подвиги на поле боя. Четвертые преклоняются перед нашей верой. А пятым просто обидно, что мы можем с легкостью перепить любого из них! Но помни, |3-6($c), что на самом деле мы – величайшие защитники Азерота. Божественный Свет дает нам тем больше силы, чем больше мы служим ему. Я расскажу тебе больше, когда ты освоишься. Ищи меня в Старой Наковальне над долиной.$B$B-Бромос Груммнер, наставник паладинов' FROM `page_text` WHERE `ID`=2464 AND MD5(`Text`)='ca8f41796119296b3c53fef54afda36d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2464 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2465, 'ruRU', 'Секрет успеха жреца – в его связи с миром. Мудрость и сострадание позволят тебе помогать тем, кто действительно в этом нуждается, а поспешность и необдуманные решения причинят только вред. Но к этому ты $gдолжен прийти сам:должна прийти сама;.$B$BКогда ты это осознаешь, тебе понадобятся новые способности и заклинания. Вот с этим я могу тебе помочь. Приходи в библиотечное крыло Аббатства Североземья.$B$B-Жрица Анетта, наставница жрецов' FROM `page_text` WHERE `ID`=2465 AND MD5(`Text`)='71691ea75b8e08e840130fab1957e765' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2465 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2466, 'ruRU', 'В это время, когда Божественный Свет согревает наши души, а каждый день дарит нам новые открытия, особенно хорошо быть <одним из сыновей/одной из дочерей> Стальгорна. Лига Исследователей с каждым днем все более продвигается вперед, находя давно потерянные ответы на еще более древние вопросы. А еще теперь среди нас есть ты, <способный/способная> помочь в борьбе с троггами и всеми другими врагами.\r\n\r\nНайди меня, когда у тебя будет время. Я буду в Старой Наковальне, что находится выше по склону.\r\n\r\n- Брансток Халдер, наставник жрецов' FROM `page_text` WHERE `ID`=2466 AND MD5(`Text`)='11535ccb1f89f3a8c56f5cfa830bb7bf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2466 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2467, 'ruRU', 'Рад, что твоя душа не попала в Пустоту, $N. Я полагаю, ты стоишь усилий, затраченных на написание этого свитка.$B$BПомни: людей, которых ты $gзнал и любил:знала и любила;, больше нет в живых! Ты $gдолжен:должна; пронести этот груз через все свое дальнейшее существование. Советую тебе смириться с этим с самого начала.$B$BЕсли ты $gготов:готова; к испытаниям, найди меня в церкви Могильника.$B$B- Темный священник Дьюстен, наставник жрецов' FROM `page_text` WHERE `ID`=2467 AND MD5(`Text`)='4efb36049bebf6b90398b86b398e8709' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2467 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2468, 'ruRU', 'Надеюсь, этот знак застанет тебя в добром здравии, $N. Духи поведали мне о твоем приходе, и я сразу же стала писать это письмо. Хочу скорее передать тебе часть моих знаний и направить тебя на верный путь, пока ты готовишься покинуть Тельдрассил для более важных дел.$B$BПосле всего что случилось за последние несколько лет, очень многие народы Азерота нуждаются в нашей помощи. Когда будешь $gготов:готова;, разыщи меня в Альдрассиле, на втором уровне.$B$B-Шанда, наставница жрецов.' FROM `page_text` WHERE `ID`=2468 AND MD5(`Text`)='97f55c731a3943231c4e804e6c7f7fb5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2468 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2469, 'ruRU', 'Надеюсь, духи исправно тебя защищали. Тебе предстоит еще много испытаний, поэтому я хочу вот обучить тебя тому, что сам знаю. $gСам:Сама; решай, хочешь ли обладать нашими силами, и если да, то приходи. Выбирать тебе – я могу только вести тебя.$B$BНу, одни-то, конечно, учатся быстро, а другие вот… помедленней. Но ты не волнуйся заранее. Как захочешь меня увидеть – приходи, поговорим.$B$B-Кен\'джай, наставница Жрецов.' FROM `page_text` WHERE `ID`=2469 AND MD5(`Text`)='43ce5f75e468aa48f229f3f8a74e4a37' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2469 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2471, 'ruRU', 'Тысячелетиями мы скрывались от чужаков. Я буду первой из нас, кто признает, что в прошлом мы ошибались. Нельзя было открывать людям магию. Я не отрицаю этого, но и не желаю приговаривать нас к заточению за промахи предшественников. Совместное существование Кель\'дорай и других народов этого мира может принести много пользы. Мы должны учиться терпимости.\r\n\r\n(продолжение следует)' FROM `page_text` WHERE `ID`=2471 AND MD5(`Text`)='9dafccc8077642e5be1538c8feb1a07d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2471 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2472, 'ruRU', 'Настоящим я отказываю Кел\'Тасу в просьбах касательно Натаноса Марриса. Он будет бесценным союзником. Помяните мое слово.\r\n\r\nПодписано:\r\n\r\nСильвана Ветрокрылая\r\nПредводитель следопытов Луносвета.' FROM `page_text` WHERE `ID`=2472 AND MD5(`Text`)='b95558bafa198746b8cb8bd89ce1af19' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2472 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2491, 'ruRU', 'Гриш, твоя просьба об отпуске удовлетворена. Посылаю тебе на смену таурена-воина, чтобы он занял твой пост, пока ты будешь проводить время с семьей. Через неделю доложи о возвращении!$B$B-Землепряд Маггран' FROM `page_text` WHERE `ID`=2491 AND MD5(`Text`)='c37b50d1b3d4247fa6a4dfaa58001193' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2491 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2512, 'ruRU', 'Озрик, ниже приведен перечень доспехов, которые нам требуются: \r\n\r\n10 Панцирных Рубах\r\n20 Шлемов\r\n30 Накладок на Доспех\r\n15 Бронированных Ботинок\r\n\r\nМы, как обычно, у тебя в долгу. И если Западный Край когда-нибудь избавится от досаждающих ему воров, я сочту себя просто обязанным пригласить тебя в наш дом на вкусный обед, достойный былой щедрости, что некогда прославляла эту страну.\r\n\r\n-Льюис\r\nИнтендант, Сторожевой Холм.' FROM `page_text` WHERE `ID`=2512 AND MD5(`Text`)='eeedd28453f8ba7c09d111bc451f2f1b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2512 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2513, 'ruRU', 'Несса, рад был получить от тебя весточку.\r\n\r\nКоллекция костей и чешуек, которую ты послала мне, превосходна. Никогда еще я не видел за пределами материка рыб такого размера. Должно быть, рыбаки деревни Руттеран с легкостью выуживают по тонне за день!\r\n\r\nЯ хоть и завидую размеру их добычи, но все же немного обеспокоен. Может ли наше новое древо Жизни сделать так, чтобы наша рыба дорастала до таких же размеров? И если может, то чего еще следует ожидать?\r\n\r\nЭто стоит обдумать.\r\n-Лайрд' FROM `page_text` WHERE `ID`=2513 AND MD5(`Text`)='2d65e7e6e9d6fcc3f63c1470c35b4c5d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2513 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2514, 'ruRU', 'Ниже приведен список учеников, получивших Платиновую звезду в Школе Горного Дела и Геодезии Брока и заработавших Почетную Шахтную Кирку:$b$bМелия Потрясательница камней$bБардин Железняк$bУми Триггервольт$bРуми Триггервольт$bВорел Стальной Шип' FROM `page_text` WHERE `ID`=2514 AND MD5(`Text`)='067b57fdce227624d7c7f75409f3ca9d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2514 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2531, 'ruRU', 'Этот трехстраничный документ пуст.' FROM `page_text` WHERE `ID`=2531 AND MD5(`Text`)='8cfd20292e3e707b83c51c201feca0bc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2531 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2551, 'ruRU', 'Лайо, мы получили щедрую помощь от этого доброго странника. Я направил его к тебе в Силитус. Используй его способности во благо себе и раскрой все нужные тебе тайны. Круг с нетерпением ждет новостей о твоих успехах.$B$BДа убережет тебя Кенарий…$BРабин' FROM `page_text` WHERE `ID`=2551 AND MD5(`Text`)='87d6e3da0f8fa5760352f0661948c256' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2551 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2571, 'ruRU', 'Праздник Зимнего Покрова.$B$BОкончание года среди многих народов Азерота считается временем перемен. Дворфы и Таурены особенно любят отмечать появление Зимнего Покрова, когда земля покрывается белым убранством, провозглашая тем самым время обновления. И хотя сами сказания, сложенные по этому поводу разными народами Азерота, не слишком различны, способы, которыми они воздают почести этим легендам, многообразны, как и придумавшие их народности.' FROM `page_text` WHERE `ID`=2571 AND MD5(`Text`)='774eb3995d55e03c48bffd8d6baa5b1c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2571 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2572, 'ruRU', 'Легенда о Дедушке Зиме.$B$BГоворят, что название "Зимний Покров" происходит от сверхъестественного существа, именуемого во многих культурах Дедушкой Зимой. Считается, что, когда на исходе года он шествует по земле, за ним вздымающимся шлейфом ложится снежный покров. Говорят, что просыпается Дедушка Зима под одеялом из снега и укрывает снежной вуалью землю. Месяцы, когда Азерот частично укрыт снегом, дают земле время обновиться и переродиться.' FROM `page_text` WHERE `ID`=2572 AND MD5(`Text`)='1091bc557c87de70d25b2b9fd0b4f4e5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2572 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2573, 'ruRU', 'Дворфы$B$BОни, неустанно исследуя свои собственные корни, предпочитают отмечать праздник, восхваляя самого Дедушку Зиму. Его дворфы считают воплощением древних жителей Азерота – титанов. Полагая, что сами они приходятся в какой-то мере родней этим таинственным существам, дворфы объявили свое снежное обиталище Дун Морог главным доказательством благосклонности Дедушки Зимы.' FROM `page_text` WHERE `ID`=2573 AND MD5(`Text`)='7d3ce440e209a9e87bdabc69b11b600d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2573 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2574, 'ruRU', 'Таурены$B$BТаурены с их шаманистическим отношением к зиме и интересом к делам друидов, буквально подтверждают собой легенду о Зимнем Покрове. Они, однако же, видят в ней прежде всего путь обновления знаний, а поклонение собственно легенде оставляют тем народам, что, по их мнению, не так глубоко познали природу вещей. Многие таурены считают, что именно во время этого праздника им приличествует благодарить судьбу за благословение их нового обиталища, Мулгора.' FROM `page_text` WHERE `ID`=2574 AND MD5(`Text`)='7b2b16cb1f2a8949fdf99e0fdcd9c50d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2574 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2575, 'ruRU', 'Пиршество$B$BОбычай устраивать на этот праздник пиршества тянется корнями в глубь самой легенды. Она гласит, что, когда Дедушка Зима шел по Азероту, укрывая его снегами, тех, кто приветствовал его появление, он осыпал дарами. И потому традиция пировать на Зимний Покров объединила между собой общины, члены которых совместно вкушали на пиру разные яства. Обычно обновление и перерождение земли приветствовали весельем и празднеством в течение целого дня.' FROM `page_text` WHERE `ID`=2575 AND MD5(`Text`)='19ff10682ed9527f12fe6af29d1ec339' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2575 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2576, 'ruRU', 'Современные наблюдения$B$BСо временем и другие народы начали признавать праздник Зимнего Покрова временем великого празднества, хотя отмечать праздник они стали не совсем так, как описано в легенде. Сегодня этому торжеству в разных уголках мира соответствует множество обычаев, часто ставящих своей целью лишь собственно празднество и обмен подарками. Иногда на праздниках появляются и портреты Дедушки Зимы, но, как правило, затем, чтобы бойче шла торговля, а не ради восхваления могущественного титана.' FROM `page_text` WHERE `ID`=2576 AND MD5(`Text`)='2a7cfdc73b8286d4f62d835735c9c736' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2576 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2591, 'ruRU', 'Далеко в Долине Копий стоит святой храм Мародона. Мало того, скоро ты узнаешь, почему я попросил тебя о помощи в делах.$B$BТам, за дверями, проходить за которые могут лишь духи и самые чтимые жрецы, есть некто по имени Безымянный Пророк. Он превыше всех в духовных делах и старше многих старейшин.' FROM `page_text` WHERE `ID`=2591 AND MD5(`Text`)='f27cd22ff723ab1143c1fb2e4f973ea6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2591 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2592, 'ruRU', 'Пророк обладает большим могуществом и общается с духами наших предков. Но он глуп! Он сам не знает, насколько силен. Он носит Амулет Духов, в котором и содержится большая часть его силы.\r\n\r\nЯ узнал, что Амулет силен, но не полон.' FROM `page_text` WHERE `ID`=2592 AND MD5(`Text`)='c11d1480b2fb51ffae9a9da4bd6d3efb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2592 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2593, 'ruRU', 'В амулете не хватает пяти камней. Если их найти и вставить на место, сила амулета возрастет многократно. Я узнал, где находятся пять камней, но для того чтобы их собрать, мне понадобится один из твоих навыков. Разумеется, убийство Безымянного Пророка – тягчайший грех, как и воровство с его бездыханного тела, но о том, о чем я тебя сейчас попрошу, всякому кентавру запрещено даже думать.' FROM `page_text` WHERE `ID`=2593 AND MD5(`Text`)='8e5562a1e025691e651c61fecb7e1d64' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2593 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2595, 'ruRU', 'В пещерах Мародона блуждают духи наших первых Ханов. Они – первые дети наших Матери и Отца и наши величайшие вожди, их зовут Гелк, Колк, Магра, Мародос и Венг. Каждый из этих духов хранит один из пропавших камней.' FROM `page_text` WHERE `ID`=2595 AND MD5(`Text`)='b3825304644f21eae078f993e4be90fd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2595 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2596, 'ruRU', 'Используй силу Амулета духов, чтобы они выдали себя, и забери у них камни! Затем вставь камни в Амулет Духов и верни его мне. Когда у меня будет Амулет Соединения, я стану достаточно силен, чтобы изменить жизнь племен, и мы наконец-то сможем жить по заветам предков!' FROM `page_text` WHERE `ID`=2596 AND MD5(`Text`)='a95924840c4e54ee8c4a32481871e220' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2596 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2611, 'ruRU', '…и там ты найдешь легендарный меч Командира Алых – Пеплоносец.$b$bРазве не замечательно добыть такое на обычной рыбалке?' FROM `page_text` WHERE `ID`=2611 AND MD5(`Text`)='f7ce8fce2ca61f4e03299577b052e468' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2611 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2631, 'ruRU', '<Страницы исписаны древними эльфийскими рунами>\r\n\r\nНа этих страницах описаны события, случившиеся при сборе и создании ингредиентов, нужных для изготовления магического камня.\r\n\r\nПусть же наши враги никогда не заполучат эти манускрипты. \r\n\r\nПусть же я доживу до того дня, когда снова увижу Кель\'Талас, озаренный бледным светом луны.\r\n\r\nПусть же я умру, но умру во славу Кель\'таса.\r\n\r\nПусть же я убью во славу Иллидана.\r\n\r\n-Кариэль Винтхалус' FROM `page_text` WHERE `ID`=2631 AND MD5(`Text`)='826af2c882bc6087cea350532e1eb592' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2631 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2632, 'ruRU', '<Вы не можете разобрать надписи на этих страницах.>' FROM `page_text` WHERE `ID`=2632 AND MD5(`Text`)='8c1c7e7f8e8a802dc7469c24841cdc9e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2632 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2633, 'ruRU', '<Страницы исписаны древними эльфийскими рунами>\r\n\r\nНа этих страницах описаны события, случившиеся при сборе и создании ингредиентов, нужных для изготовления магического камня.\r\n\r\nПусть же наши враги никогда не заполучат эти манускрипты.\r\n\r\nПусть же я доживу до того дня, когда снова увижу Кель\'Талас, озаренный бледным светом луны.\r\n\r\nПусть же я умру, но умру во славу Кель\'таса.\r\n\r\nПусть же я убью во славу Иллидана.\r\n\r\n-Кариэль Винтхалус' FROM `page_text` WHERE `ID`=2633 AND MD5(`Text`)='826af2c882bc6087cea350532e1eb592' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2633 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2634, 'ruRU', '<Письмена на странице кружатся и перемещаются. Вам кажется, будто книга дразнит вас.>' FROM `page_text` WHERE `ID`=2634 AND MD5(`Text`)='1239478cb2a8e53c9495a22014c573ff' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2634 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2635, 'ruRU', '<Страницы исписаны древними эльфийскими рунами>\r\n\r\nНа этих страницах описаны события, случившиеся при сборе и создании ингредиентов, нужных для получения мощного зелья.\r\n\r\nПусть же наши враги никогда не заполучат эти манускрипты. \r\n\r\nПусть же я доживу до того дня, когда снова увижу Кель\'Талас, озаренный бледным светом луны.\r\n\r\nПусть же я умру, но умру во славу Кель\'таса.\r\n\r\nПусть же я убью во славу Иллидана.\r\n\r\n-Кариэль Винтхалус' FROM `page_text` WHERE `ID`=2635 AND MD5(`Text`)='6b7a83db675337009861d9fb5d79fc1f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2635 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2636, 'ruRU', '<Глядя на эти страницы, вы чувствуете жгучую боль.>' FROM `page_text` WHERE `ID`=2636 AND MD5(`Text`)='feb60cd407902ed452e9798523c1feea' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2636 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2655, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<P align="center">Часть 1</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\r\n<P align="right">Главнокомандующий</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\r\n<P align="right">Фельдмаршал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\r\n<P align="right">Маршал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\r\n<P align="right">Командир</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\r\n<P align="right">Лейтенант-командор</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2655 AND MD5(`Text`)='c916473a457a2514615764e8ca444f5b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2655 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2656, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<P align="center">Часть 2</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\r\n<P align="right">Рыцарь-защитник</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\r\n<P align="right">Рыцарь-капитан</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\r\n<P align="right">Рыцарь-лейтенант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\r\n<P align="right">Рыцарь</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2656 AND MD5(`Text`)='f590d7312da2bf11a2cc14552219893c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2656 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2657, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">РЯДОВЫЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\r\n<P align="right">Старший Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\r\n<P align="right">Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\r\n<P align="right">Младший Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\r\n<P align="right">Капрал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\r\n<P align="right">Рядовой</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2657 AND MD5(`Text`)='58bc2cc591b1a879ae97b4dbc71a61b0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2657 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2658, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<P align="center">Часть 1</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\r\n<P align="right">Верховный Вождь</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\r\n<P align="right">Вождь</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\r\n<P align="right">Генерал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\r\n<P align="right">Лейтенант-генерал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\r\n<P align="right">Защитник</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2658 AND MD5(`Text`)='3706b4969014155fa9231b604f1d0477' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2658 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2659, 'ruRU', 'Когда вы вглядываетесь в Око, перед вами встают картины великой битвы.\r\n\r\nПохоже, что эта ужасная схватка происходит где-то в Лордероне.\r\n\r\nВы с трудом можете разглядеть одинокий силуэт женщины, стоящей среди тысячи трупов, отгоняющей полчища Плети. Полчища эти несметны.\r\n\r\nИз ее рук исходят лучи света, разя нежить сотнями.' FROM `page_text` WHERE `ID`=2659 AND MD5(`Text`)='8fb928b6b6b48d8d84dbf815340afc04' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2659 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2661, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">ВОИНСКИЕ ЗВАНИЯ ОРДЫ И АЛЬЯНСА</H1>\r\n<BR/>\r\n<BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRankHorde" align="left"/>\r\n<BR/>\r\n<P align="right">Тром\'ка! В этой</P>\r\n<P align="right">книге ты найдешь</P>\r\n<P align="right">подробный перечень</P>\r\n<P align="right">воинских званий</P>\r\n<P align="right">Орды и</P>\r\n<P align="right">жалкого Альянса.</P>\r\n<P align="right">Сначала в списках идет</P>\r\n<P align="right">Орда, а затем Альянс,</P>\r\n<P align="right">и для обеих сторон перечислены офицерские и рядовые звания. Как и подобает, вверху списка располагаются старшие чины, а младшие – ниже.</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2661 AND MD5(`Text`)='dd3baec98c369f255d744967adabfad0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2661 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2662, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<P align="center">Часть 1</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\r\n<P align="right">Верховный Вождь</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\r\n<P align="right">Вождь</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\r\n<P align="right">Генерал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\r\n<P align="right">Лейтенант-генерал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\r\n<P align="right">Защитник</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2662 AND MD5(`Text`)='3706b4969014155fa9231b604f1d0477' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2662 AND x.`locale`='ruRU');
