INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2664, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">РЯДОВЫЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\r\n<P align="right">Высший Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\r\n<P align="right">Старший Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\r\n<P align="right">Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\r\n<P align="right">Рубака</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\r\n<P align="right">Разведчик</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2664 AND MD5(`Text`)='e3c1097219fa32f2b541ad5d98aef926' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2664 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2665, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<P align="center">Часть 1</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\r\n<P align="right">Главнокомандующий</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\r\n<P align="right">Фельдмаршал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\r\n<P align="right">Маршал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\r\n<P align="right">Командор</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\r\n<P align="right">Лейтенант-командор</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2665 AND MD5(`Text`)='c916473a457a2514615764e8ca444f5b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2665 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2666, 'ruRU', 'Похоже, все было напрасно. Мгновения спустя жрицу поглотила толпа окруживших ее мертвых крестьян... Павшие восстали.' FROM `page_text` WHERE `ID`=2666 AND MD5(`Text`)='1ca7daba16d61cd4b4c70db3b81be99a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2666 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2671, 'ruRU', 'Симон Совратительница:\r\n\r\nСимон ты застанешь за осквернением Кратера Ун\'Горо. Не поддавайся на ее уловки. Приближайся к ней с осторожностью, а потом вступай в бой.' FROM `page_text` WHERE `ID`=2671 AND MD5(`Text`)='0bd65936ee24ad087a4823c47db8c02f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2671 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2672, 'ruRU', 'Клинфран Безумный:\r\n\r\nКлинфран блуждает по Пылающим степям. Приближайся к нему с осторожностью и вынуди его показать истинное лицо.' FROM `page_text` WHERE `ID`=2672 AND MD5(`Text`)='6dd7ee06233c573eea56935e03e7c139' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2672 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2673, 'ruRU', 'Соленор Душегуб:\r\n\r\nВ безводных землях Силитуса рыщет наш враг, Соленор Душегуб. Он дьявольски хитер и очень опасен. Подберись к нему и вынуди его принять свой облик.' FROM `page_text` WHERE `ID`=2673 AND MD5(`Text`)='c9a7e108de89d9a6454fb3bbc05f3fd3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2673 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2674, 'ruRU', 'Арториус Судьбоносный:\r\n\r\nВсему, чего Арториус касается в Зимних Ключах, он приносит смерть и разрушение. Найди его и убей.' FROM `page_text` WHERE `ID`=2674 AND MD5(`Text`)='30cdc39f279de53d9076fd8f0fdbc50f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2674 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2675, 'ruRU', 'Знай, $gохотник:охотница;, эти демоны дерутся только по своим правилам. Если им покажется, что одолеть тебя нельзя, они сбегут.\r\n\r\nИДИ К НИМ $gОДИН:ОДНА;.' FROM `page_text` WHERE `ID`=2675 AND MD5(`Text`)='7ec694bf4e7c5a6741651e70c33756b1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2675 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2676, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">ВОЕННЫЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<P align="center">ОФИЦЕРЫ</P><BR/>\r\n<P align="center">Главнокомандующий</P>\r\n<P align="center">Фельдмаршал</P>\r\n<P align="center">Маршал</P>\r\n<P align="center">Командор</P>\r\n<P align="center">Лейтенант-командор</P>\r\n<P align="center">Рыцарь-защитник</P>\r\n<P align="center">Рыцарь-капитан</P>\r\n<P align="center">Рыцарь-лейтенант</P>\r\n<P align="center">Рыцарь</P><BR/>\r\n<P align="center">РЯДОВЫЕ</P><BR/>\r\n<P align="center">Старший Сержант</P>\r\n<P align="center">Сержант</P>\r\n<P align="center">Младший Сержант</P>\r\n<P align="center">Капрал</P>\r\n<P align="center">Рядовой</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2676 AND MD5(`Text`)='f5cfa029b3ef219b65ae0f1256a91c27' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2676 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2677, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">ВОЕННЫЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<P align="center">ОФИЦЕРЫ</P><BR/>\r\n<P align="center">Верховный Вождь</P>\r\n<P align="center">Вождь</P>\r\n<P align="center">Генерал</P>\r\n<P align="center">Лейтенант-генерал</P>\r\n<P align="center">Защитник</P>\r\n<P align="center">Центурион</P>\r\n<P align="center">Легионер</P>\r\n<P align="center">Кровавый Страж</P>\r\n<P align="center">Каменный Страж</P><BR/>\r\n<P align="center">РЯДОВЫЕ</P><BR/>\r\n<P align="center">Высший Сержант</P>\r\n<P align="center">Старший сержант</P>\r\n<P align="center">Сержант</P>\r\n<P align="center">Рубака</P>\r\n<P align="center">Разведчик</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2677 AND MD5(`Text`)='61349b55a3d4e7d746dcb988bf1a520e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2677 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2691, 'ruRU', 'Чтобы подчинить коня погибели, нужно сделать три вещи:\r\n\r\nсотворить Круг Великого Призыва.\r\n\r\nВнутри этого круга открыть портал в Зорот и вывести коня через него.\r\n\r\nПобедить его и покорить его дух.\r\n\r\nНа следующих страницах подробно описан каждый из трех шагов. Сделать это непросто, но ты $gдоказал:доказала;, что способности у тебя есть. Я уверен, что ты со своей целеустремленностью подчинишь себе коня гибели.\r\n\r\nЧитай дальше.\r\n-Мор\'зул Вестник Крови' FROM `page_text` WHERE `ID`=2691 AND MD5(`Text`)='6d5a4b4017f412634477ded4b060a306' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2691 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2692, 'ruRU', 'Составляющие Ритуала\r\n\r\nПеред началом ритуала у тебя должны быть следующие компоненты:\r\n\r\nКувшин Д\'жииви\r\nЧёрный Магнит\r\nЗоротианские Иероглифы\r\n\r\nЗа определённую цену мой слуга Горзиеки добудет их для тебя. Без них ни одно действие ритуала выполнять нельзя. Каждый компонент очень важен.\r\n\r\nНа следующих страницах я подробно опишу их применение.' FROM `page_text` WHERE `ID`=2692 AND MD5(`Text`)='929a730c9cb60449e4c9e57a31513304' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2692 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2693, 'ruRU', 'Круг большего Единения\r\n\r\nСоздавать Круг Большего Единения нужно там, где сильна магия. Такое место есть в глубине развалин Эльдре\'Таласа, называемого также Забытым Городом. В Эльдре\'Таласе пленено существо великой силы, Бессмер\'тер; именно у подножия его темницы и надо создавать Круг.\r\n\r\nПроберись к Подножию и выпусти Д\'жииви на свободу.' FROM `page_text` WHERE `ID`=2693 AND MD5(`Text`)='ffd69186c071c0e620496568b4f0d09a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2693 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2694, 'ruRU', 'Колокол, Колесо и Свеча\r\n\r\nОсвободившись, Д\'жииви разместит Колокол, Колесо и Свечу, после чего появится круг. Так начинается ритуал. Нужно сохранять бдительность: упомянутые предметы испускают мощные потоки энергии и могут разрушиться. Если это случится, скорее используй Черный магнит, чтобы восстановить их, прежде чем весь ритуал пойдет насмарку.\r\nЕсли все три предмета разрушатся прежде, чем ты сумеешь их восстановить, ритуал закончится и его надо будет начинать заново.' FROM `page_text` WHERE `ID`=2694 AND MD5(`Text`)='8634ec7cbb43c093dd4ecdfc989317ad' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2694 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2695, 'ruRU', 'Колокол, Колесо и Свеча не только хранят энергию для ритуала, но и обладают собственными уникальными свойствами.\r\n\r\nКолокол Детмуры, испуская звон, дарует чернокнижникам в круге силу и энергию.\r\n\r\nКолесо Черного Похода при вращении защищает тех, кто стоит в круге, от урона.\r\n\r\nКогда горит Свеча Судного Дня, она поражает врагов, вступивших в круг, магической энергией.\r\n\r\nЭти предметы очень полезны, и потому очень важно следить за тем, чтобы во время ритуала они работали бесперебойно.' FROM `page_text` WHERE `ID`=2695 AND MD5(`Text`)='ec756834d836355cb87bf694dfd08ea9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2695 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2696, 'ruRU', 'Нужно заметить, что Черному магниту, используемому для восстановления Колокола, Колеса и Свечи в случае их поломки, нужны Осколки душ. При каждом восстановлении ритуального предмета с помощью Магнита расходуется один Осколок души, поэтому перед ритуалом стоит запасти их побольше.' FROM `page_text` WHERE `ID`=2696 AND MD5(`Text`)='efbe5a01e166836b449d9a61213583cd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2696 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2697, 'ruRU', 'Завершение ритуала\r\n\r\nХод ритуала можно проследить по волшебным рунам на краю круга. Когда там проступят девять рун, ритуал полностью завершится, и ты увидишь, как из заряженного Круга исходит энергия.\r\n\r\nЗатем ты сможешь использовать Зоротианские Иероглифы, чтобы открыть портал в Зорот и вывести через него коня погибели.\r\n\r\nПобеди коня и выпусти его дух. Одержи победу над духом, и тогда он будет порабощен, а ты узнаешь секрет его призыва.' FROM `page_text` WHERE `ID`=2697 AND MD5(`Text`)='3a87b9ae2180d456a26e2122f96a63dd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2697 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2731, 'ruRU', 'Здесь покоится Дуротан – вождь клана Северного Волка и отец нашего почтенного Военного Вождя Тралла. Он был храбрейшим среди нас, и его предали те, кто жаждал нашего порабощения. Дуротан отдал свою жизнь, чтобы мы могли обрести свободу. Мы чтим его и заветы, что он передал нам через своего сына.\r\n\r\n\r\nДрек\'Тар, шаман клана Северного Волка' FROM `page_text` WHERE `ID`=2731 AND MD5(`Text`)='87ab8c2f85910d84b7a88536778daca5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2731 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2771, 'ruRU', 'Как очистить луковицу\r\nПодробное руководство по сражению с Грозовой Вершиной\r\n-Написано Дрек\'Таром\r\n\r\nНа этих страницах читатель найдет обширные сведения о политике и боевой тактике. Хороший солдат – это тот солдат, что понимает важность накопленного опыта. Пусть же эта книга послужит читателю руководством по сражению за Альтеракскую Долину.' FROM `page_text` WHERE `ID`=2771 AND MD5(`Text`)='988f34b7133bafafd0855dbd886301d7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2771 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2772, 'ruRU', 'Глава 1 – Линия фронта\r\n\r\nАтаковать армию Грозовой Вершины – все равно что снимать кожицу с луковицы. Чтобы пробраться к сердцевине, нужно сперва разделаться с внешними слоями.\r\n\r\nПередняя линия обороны, состоящая в основном из горных пехотинцев Грозовой Вершины и Часовыми Альянса, связана с Капитанским Укрытием. Снабжает войска и посылает им в случае осады подкрепление Капитан Балинда Каменный Очаг. Срази капитана, и передовые линии падут.' FROM `page_text` WHERE `ID`=2772 AND MD5(`Text`)='5fca9ee22811f880416c8a1d801263b5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2772 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2773, 'ruRU', 'Глава 2 – Башни-близнецы\r\n\r\nУчти: Вандар Грозовая Вершина – враг умный и хитрый. Разрушив передовые укрепления, надо помнить о том, что впереди еще вторая линия обороны. Это – башни-близнецы Каменный Очаг и Ледяное Крыло, из которых командиры управляют стражниками Грозовой Вершины вне Дун Болдара и патрулями Грозовой Вершины.' FROM `page_text` WHERE `ID`=2773 AND MD5(`Text`)='ab85f3c95db70802e8714372af58f848' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2773 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2774, 'ruRU', 'Будь осторожен, воин, ведь обе эти башни сильно укреплены и управляются элитным командорами Вандара. И если твои войска прорвут укрепления, сделай так, чтобы командор в башне был… устранен. Это – следующий важный шаг на пути к победе над Грозовой Вершиной.' FROM `page_text` WHERE `ID`=2774 AND MD5(`Text`)='c9a8f5b67bb4eb00ce01a9d92f3a94c4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2774 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2775, 'ruRU', 'Глава 3 – Четыре Командора\r\n\r\nТретий слой луковицы под названием Грозовая Вершина – четыре Командора. В этом отношении Вандар перенял нашу славную тактику обороны Северного Волка. Сам он, конечно, считает по-другому… Но я отвлекся. \r\n\r\nЧетыре Командора повелевают Стражниками Грозовой Вершины, неусыпно охраняющими Дун Болдар. Устрани их всех, и Стражники падут.\r\n\r\nПосле этого останется лишь один, последний слой.' FROM `page_text` WHERE `ID`=2775 AND MD5(`Text`)='0dc6de076c8a0b9769e3151798e517f6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2775 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2776, 'ruRU', 'Глава 4 – Укрытия Дун Болдара\r\n\r\nКак ты, несомненно, заметил, линии обороны Грозовой Вершины выстроены так, чтобы не дать массированному удару сокрушить сразу всю армию. Сразу отвечу на твои вопросы. Да, именно так организована и наша оборона, и нет, менять ее расположение я не стану. Они переняли все у нас, с чего бы нам меняться?' FROM `page_text` WHERE `ID`=2776 AND MD5(`Text`)='c8ad0ab228775410f7e7ed6a48dcbc5e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2776 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2777, 'ruRU', 'Так о чем я? В общем, Укрытиями Дун Болдара (расположены они в Дун Болдаре) управляют защитники из клана Грозовой Вершины – лучшие стражи Вандара, которым он доверяет больше всех. Уничтожь две башни, и подкрепление, которее выходит на помощь Вандару, прекратит свое существование.' FROM `page_text` WHERE `ID`=2777 AND MD5(`Text`)='512f524624ef9b7fd52823f8a530395e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2777 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2778, 'ruRU', 'Эпилог\r\n\r\nПроделав все это, ты доберешься до самой цели, до центра луковицы. Вандар Грозовая Вершина будет один и безо всякой защиты. Правила ведения войны требуют нам предложить ему сдаться в плен, прежде чем убивать. Поэтому, как увидишь его, обязательно предложи ему сдаться… а потом убей.' FROM `page_text` WHERE `ID`=2778 AND MD5(`Text`)='84d8539bf4d474ed283204d6feb6d59e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2778 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2779, 'ruRU', 'Артишок клана Северного Волка: Повести о славе Грозовой Вершины\r\n-Автор Вандар Грозовая Вершина\r\n\r\nЧто такое клан Северного Волка? Ответ прост: клан Северного Волка – сборище дикарей, жаждущих низвергнуть нас, своих законных повелителей.\r\n\r\nОн, подобно артишоку, окружен колючим и твердым защитным слоем, сняв который, можно добраться до сердцевины и съесть ее с доброй чесночной подливой.\r\n\r\nВкусно!' FROM `page_text` WHERE `ID`=2779 AND MD5(`Text`)='10c3402c160c678dead3bc541f9b6810' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2779 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2780, 'ruRU', 'Глава 1 – Линия фронта\r\n\r\nПередние линии обороны Клана Северного Волка состоят из воинов клана. Эти воины отправляются на передовую из крепости капитана Гальвангара под названием гарнизон Стылой Крови. Проще всего расправиться с этой линией обороны, разрушив гарнизон.\r\n\r\nОсади крепость и убей капитана Гальвангара. После этого передовые линии падут.' FROM `page_text` WHERE `ID`=2780 AND MD5(`Text`)='176f95cb4ae3a0fe2039ddb2c08dd956' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2780 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2781, 'ruRU', 'Глава 2 – Стылая Кровь и Смотровая башня\r\n\r\nКогда ты разделаешься с первым слоем "артишока", тебе будет открыт второй. Если уничтожить Башни Северного Волка, стоящие у линии фронта, то ослабнут вражеские легионеры и патрули с задних флангов.\r\n\r\nЭти башни сильно укреплены, и в каждой из них находится по одному из элитных командоров Дрек\'Тара. Их надо убить. Так ты ускоришь крах обороны клана Северного Волка.' FROM `page_text` WHERE `ID`=2781 AND MD5(`Text`)='a26d24b9dccf8c785cd1d29c8a0dd3c7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2781 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2782, 'ruRU', 'Глава 3 – Четыре командора\r\n\r\nЕсли ты следовал мудрым советам этого руководства, то сейчас двое из командоров Дрек\'Тара уже мертвы. Так держать, солдат! Решимость врага уже пошатнулась. Теперь нужно окончательно разделаться с командным звеном неприятеля и убить двух оставшихся командоров.\r\n\r\nКогда будут убиты все четыре командора, в рядах легионеров Северного Волка, охраняющих Крепость Северного Волка наступит сумятица – ведь командовать ими будет некому. Можно брать голыми руками!' FROM `page_text` WHERE `ID`=2782 AND MD5(`Text`)='d06c93ec57d618a252744fcf33f7a1c2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2782 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2783, 'ruRU', 'Глава 4 – Восточная и Западная башни Северного Волка\r\n\r\nТеперь от победы тебя отделает только один рубеж – самые преданные и сильные стражи Дрек\'Тара, стражи Северного Волка.\r\n\r\nИх присылают из резервных отрядов, что содержатся в Восточной и Западной Башнях Северного Волка. Уничтожь эти башни – и увидишь, как позорно побегут оставшиеся Стражи.' FROM `page_text` WHERE `ID`=2783 AND MD5(`Text`)='673e2573307fe3573160adbec53910ac' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2783 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2784, 'ruRU', 'Эпилог\r\n\r\n"Сдобрить сердцевину артишока маслом с чесноком и майонезом. Запивать блюдо лучше крепким, выдержанным элем."\r\n\r\nТеперь Дрек\'Тар совсем один, если не считать двух болванов-подопечных по обе руки. Захвати Приют Северного Волка и убей Дрек\'Тара. Когда Генерал падет, его земли наконец-то перейдут к их истинному владельцу – Грозовой Вершине.' FROM `page_text` WHERE `ID`=2784 AND MD5(`Text`)='a75d9b8418ed8b5bcff03325a54d4a3d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2784 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2785, 'ruRU', 'Мы призываем тебя, Занза Зулдазара.\r\n\r\nБлагослови тех, что помощи твоей ищут, Лоа Занза. Благослови тех, что хотят помочь Зандаларскому\r\nнароду.\r\n\r\nПомоги нам в эти трудные времена. Помоги нам, Лоа. Дай нам силу сразить врагов наших. Дай нам силу сокрушить Кровавого Бога еще раз.' FROM `page_text` WHERE `ID`=2785 AND MD5(`Text`)='c0db5dafde724d985a0673163c65e254' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2785 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2786, 'ruRU', 'Рыболовный чемпионат Тернистой долины!\r\nПроводится по воскресеньям, с 14-00 до 16-00.\r\n\r\nЗакиньте удочки где угодно на побережье Тернистой долины (кроме Пиратской бухты) и ищите косяки вкуснорыбы, что появляются вдоль берега! Старайтесь забросить удочку как можно ближе к стайке рыб, и тогда у вас будет возможность поймать особенную рыбу вместо обычных, которых полно в Тернистой долине. Первый, кто выловит сорок вкуснорыб, сможет сдать их Мастеру Мормышу в Пиратской бухте и получить вознаграждение!\r\n\r\nДаже если вам не удалось поймать сорок вкуснорыб первому, вы сможете обменять их на деньги, а за некоторых рыб можно получить ценные призы!' FROM `page_text` WHERE `ID`=2786 AND MD5(`Text`)='9343bfbc0d9c81249a02f5f3227923b0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2786 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2787, 'ruRU', 'Имя его принесло Свет во тьму Азерота.$B$BДоблесть его победила всякое отчаяние.$B$BСеребряная Длань не могла сделать большего,$B$Bчем дать миру рыцаря, что отдал миру себя.' FROM `page_text` WHERE `ID`=2787 AND MD5(`Text`)='9f41cb19c03ba35e6370015a46dd8818' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2787 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2788, 'ruRU', 'Он не искал себе почет и славу$B$Bи не хотел сородичами править.$B$BРешил он биться за Лордерон,$B$Bчтоб после уж народ его жил в мире.' FROM `page_text` WHERE `ID`=2788 AND MD5(`Text`)='50d195f53a60a0ae5c762adada269a81' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2788 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2789, 'ruRU', 'Рассказ о добродетели его$B$Bсо смертью рыцаря не будет завершен.$B$BЕго мы чтим и воздаем хвалу!$B$BПусть Утер в славе почиет и в Свете!' FROM `page_text` WHERE `ID`=2789 AND MD5(`Text`)='0af0b774d93c8369095e88dedcd08561' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2789 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2790, 'ruRU', 'Имя его не умрет.$BЖертва его всегда$Bнам будет указывать путь.$B$BОковы, что крепко держали$Bчесть, отвагу и смелость,$Bнас не стесняют теперь.' FROM `page_text` WHERE `ID`=2790 AND MD5(`Text`)='d787c7c4fbb9b1604dbd8ab0f3b7eac0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2790 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2791, 'ruRU', 'Слышишь ли ты его крик?$BКлич боевой за Орду:$BПобеда или смерть!$B$BДолжны мы вовек запомнить,$Bкак отважно презрел он смерть.$BМечты его воплотились.' FROM `page_text` WHERE `ID`=2791 AND MD5(`Text`)='76a6c9cca6f4f9ff7f5f9b82ebefbb10' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2791 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2792, 'ruRU', 'Здесь опасность кругом!$BЖаждут враги заковать$Bнас обратно в оковы.$B$BПомни же в яростной битве$Bо том, кто свой выполнил долг.$BАдский Крик вечно живет!' FROM `page_text` WHERE `ID`=2792 AND MD5(`Text`)='1b256fc8bd19c36439f926fe82386ad0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2792 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2793, 'ruRU', 'Прошло около тысячи лет после "Войны Зыбучих песков". Именно на этой войне в сердце пустыни Силитуса случилось великое горе и великое бремя пало на Фэндрала Олений Шлем. Считается, что именно описанные здесь события отвратили от добра верховного Друида.' FROM `page_text` WHERE `ID`=2793 AND MD5(`Text`)='0cb3bea33d2a5d13a414edf1a09d690b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2793 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2794, 'ruRU', 'Некогда за власть над большей частью Калимдора боролась древняя раса разумных насекомых, известная под именем киражи. Именно напыщенный Олений Шлем со своим войском ночных эльфов и сошелся в бою с ними.' FROM `page_text` WHERE `ID`=2794 AND MD5(`Text`)='43e499e7167a031233b9ca8364d50d90' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2794 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2795, 'ruRU', 'Отец и сын неистово дрались бок о бок, чтобы сдержать напор насекомых в Силитусе. Из крепости Ан\'Кираж тек, казалось, нескончаемый поток силитидов, пополняя ряды захватчиков-киражей. Весь Силитус был осажден.' FROM `page_text` WHERE `ID`=2795 AND MD5(`Text`)='e2f64be9f80845f06024d8363c6bd69b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2795 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2796, 'ruRU', 'Настал роковой для Оленьего Шлема момент – младшему Оленьему Шлему, Вальстану, было приказано оборонять заставу ночных эльфов в деревне Южного Ветра. Увы, в тот же день Вальстан расстался с жизнью: Деревня Южного Ветра пала под натиском армий Ан\'Киража.' FROM `page_text` WHERE `ID`=2796 AND MD5(`Text`)='56f8d8b467d2415f8f1cb68dec7c4e17' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2796 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2797, 'ruRU', 'С тяжелым сердцем, обуянный жаждой мести, могучий Фэндрал Олений Шлем усилил натиск. Поражение в Силитусе стало бы великой бедой для ночных эльфов и, вполне возможно, для всего мира.\r\n\r\nБитва кипела несколько месяцев. Весь Силитус был захвачен киражами. Оленьего Шлема и его армию отбросили к Танарису. Видя, как уменьшилось его войско и сколько невинных жертв погибло, Фэндрал Олений Шлем утратил ту самонадеянность, что двигала им.' FROM `page_text` WHERE `ID`=2797 AND MD5(`Text`)='a8b4c63bac00508eb9b9b8322d9a1ccc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2797 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2798, 'ruRU', 'Гордость Оленьего Шлема была растоптана. Во второй раз за всю свою жизнь он почувствовал в животе трепетание, которое могло быть вызвано лишь страхом. Позже, в Танарисе, он пришел к Анахроносу, отпрыску Ноздорму, и попросил Бронзовых драконов о помощи.' FROM `page_text` WHERE `ID`=2798 AND MD5(`Text`)='048ccba1c6a362c50be4b5147b75d984' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2798 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2799, 'ruRU', 'Сначала Анахронос отказывался вовлекать свой народ в дела низших рас. Лишь после дерзкого нападения киражей на Пещеры Времени он согласился выступить сообща с ночными эльфами.' FROM `page_text` WHERE `ID`=2799 AND MD5(`Text`)='f6d643558e71a38eace4084f61c6e3f6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2799 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2800, 'ruRU', 'Скоро Анахронос понял, что даже могущественные Бронзовые драконы не смогут сдержать напор киражских войск. На место каждой полусотни насекомых, изничтоженных его дыханием, вставала сотня новых. Видя, как трудно приходится ночным эльфам, и понимая, что перед ними маячит угроза отступления на север, в глушь Фераласа, Анохронос решил, что надо предупредить детей Аспектов.' FROM `page_text` WHERE `ID`=2800 AND MD5(`Text`)='7c8a967326ca620112d93e43b221741b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2800 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2801, 'ruRU', 'Сначала он воззвал к Выводку Изеры. Меритра из Сна ответила на его зов, и затем весть дошла до выводков Алекстразы и Малигоса.' FROM `page_text` WHERE `ID`=2801 AND MD5(`Text`)='56fa03c15630f30c246f905f01f6081b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2801 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2802, 'ruRU', 'Драконы встретились высоко в небе над Силитусом, в тысячах метров над твердыней Ан\'Кираж.\r\n\r\nТам был Анахронос, дитя Ноздорму, Аспекта Времени.\r\n\r\nИз Изумрудного Сна явилась Меритра, дитя Изеры, Аспекта Природы.\r\n\r\nКелестраз, отпрыск Алекстразы, Аспекта Жизни, представлял Красных драконов.\r\n\r\nАригос же, дитя Малигоса, Аспекта Магии, говорил от имени Синих драконов.' FROM `page_text` WHERE `ID`=2802 AND MD5(`Text`)='4a6147df0590945fef9a483844eb6fe8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2802 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2803, 'ruRU', 'Драконы смотрели, как из Ан\'Киража исторгался нескончаемый поток силитидов и киражей. Им стало ясно, что никакая армия, сколь угодно большая, эту войну не выиграет. В главном храме ждали своего часа десятки тысяч воинов. С каждой секундой вылуплялись и вставали под знамена все новые их бойцы, готовые ринуться в сечу.' FROM `page_text` WHERE `ID`=2803 AND MD5(`Text`)='3c0bad91baeaf3dba0f3b252179f838d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2803 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2804, 'ruRU', 'Аригос первым заметил странное излучение. Массивный храм на юге Ан\'Киража испускал слабые магические волны, не похожие ни на что, исходящее прежде от киражей. Как союзники ни пытались, никому не удалось проникнуть в храм и найти источник этой энергии. Окружить себя такой непробиваемой защитой могло лишь нечто, обладающее огромной силой. Возможно, это было нечто, управляющее насекомыми. Нечто, управляющее даже киражей.' FROM `page_text` WHERE `ID`=2804 AND MD5(`Text`)='0fe6d2851d4cbb6329c62f9fd0eece39' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2804 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2805, 'ruRU', 'Драконы знали, что действовать им надо быстро, не то мир постигнет новая ужасная катастрофа. Тщательно взвесив все, они решили, что лучше всего будет остановить враждебные армии на этом источнике энергии или рядом с ним.' FROM `page_text` WHERE `ID`=2805 AND MD5(`Text`)='eed34690312d0fffb1f2bd94180f9b01' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2805 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2806, 'ruRU', 'Был создан огромный заслон, питаемый энергией как ночных эльфов, так и драконов, – магический барьер, которому под силу было удержать силитидов и их повелителей в пределах стен Ан\'Киража и выдерживать напор снаружи. Ан\'Кираж сам стал тюрьмой для врагов.' FROM `page_text` WHERE `ID`=2806 AND MD5(`Text`)='d5f09542c9fc5e64605ab48b731a212d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2806 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2811, 'ruRU', 'Для немедленного распространения среди всех членов Сумеречного Молота.\r\n\r\nВ связи с текущим положением дел в Силитусе, всякое распространение текстов Истинно Верующего отныне должно проводиться в сопровождении не менее чем четырех вооруженных бойцов Сумеречного Молота.\r\n\r\nВсе, уличенные в нарушении этого нового приказа, будут без промедления наказаны.\r\n\r\n-Д\'Сак Сумеречный Владыка.' FROM `page_text` WHERE `ID`=2811 AND MD5(`Text`)='9451015f6e9f7ec1388d2bc527155115' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2811 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2812, 'ruRU', 'Для немедленного распространения среди всех членов Сумеречного Молота.\r\n\r\nНиже описан порядок применения Ветровых Камней для связи с нашими повелителями из Совета Бездны.\r\n\r\nВсякое неподобающее использование Ветровых Камней будет караться самым жестоким образом.\r\n\r\n-Хранитель Хавунт из культа Сумеречного Молота' FROM `page_text` WHERE `ID`=2812 AND MD5(`Text`)='ea08cdc2507934aaf035d50230fa7e6c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2812 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2813, 'ruRU', 'Храмовники Бездны\r\n\r\nТебе, как новичку, разрешается обращаться к Храмовникам Бездны для проведения обычных ритуалов. Не забывай надевать подобающее убранство при обращении с Ветровыми Камнями, чтобы на тебя не подействовали наши защитные чары.\r\n\r\nЕсли вдруг случится нечто непредвиденное в отсутствие старших, тебе разрешается вызвать Храмовника Бездны.\r\n\r\nЗа подробностями о проведении соответствующих ритуалов призыва обращайся к выпуску Истинно Верующего за прошлый месяц.' FROM `page_text` WHERE `ID`=2813 AND MD5(`Text`)='03074e19eef4fb724f15330ab0315fba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2813 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2814, 'ruRU', 'Герцоги Бездны\r\n\r\nТолько послушникам, имеющим медальон статуса, разрешено обращаться к Герцогам Бездны. Медальоны статуса могут использовать лишь те, кому они были выданы изначально.\r\n\r\nЧлены Сумеречного Молота, замешанные в неправомерном общении с Герцогами бездны либо в использовании без разрешения медальонов статуса будут наказаны мной лично.' FROM `page_text` WHERE `ID`=2814 AND MD5(`Text`)='88f985332ce58a90659625d25a0cd2af' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2814 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2815, 'ruRU', 'Высокий Совет Лордов Бездны\r\n\r\nОбращаться к Принцу Скальдреноксу, Верховному маршалу Круговерту, Барону Казуму или Лорду Скволу позволено лишь Сумеречным Лордом.\r\n\r\nНи при каких обстоятельствах нижние чины Сумеречного Молота не могут начать общение с Высоким Советом. Любой чужак, застигнутый за использованием с этой целью ветровых камней, будет испепелен на месте.' FROM `page_text` WHERE `ID`=2815 AND MD5(`Text`)='a436f98ba9a21130b7b128cd39eeeac0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2815 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2816, 'ruRU', 'Дела культа, том 92\r\n\r\nС радостным сердцем приветствую я вас, братья мои, ибо дела нашего культа идут сейчас наилучшим образом. Имя нам – легион, и всякие замыслы наши все ближе к воплощению.\r\n\r\nВ ряды наши встает все больше новичков. Хвалебная песнь возносится к нашим господам на Темных берегах, и склоняются они в радостных грезах среди Выжженной теснины, и обнимают они слугу наших господ, Аку\'май, в Непроглядной Пучине. Поистине, братья мои и сестры, скоро вера наша разнесется по всему Азероту!' FROM `page_text` WHERE `ID`=2816 AND MD5(`Text`)='dab7c5d483a68687df09c96de41c05d4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2816 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2817, 'ruRU', 'Дела культа, том 127\r\n\r\nВоистину, это счастливый день! Нас испытали в Силитусе, и мы прошли испытание!\r\n\r\nРассказы о разгроме нашего северного лагеря могут наполнить страхом сердца неверных, но для нас эта резня эта не должна быть несчастьем, нет!' FROM `page_text` WHERE `ID`=2817 AND MD5(`Text`)='93f8f1dc981768292995bad151679ded' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2817 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2818, 'ruRU', 'Пролитие крови нашей одним из Высокого Совета Бездны есть благословение! Мы должны завидовать нашим павшим товарищам, ибо души их теперь покоятся во чреве самого добродетельного зверя!\r\n\r\nВосславим же Древних Богов! Восславим слуг их! Восславим Сумеречный Молот!' FROM `page_text` WHERE `ID`=2818 AND MD5(`Text`)='91a075776485758db40c31fc177464cb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2818 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2819, 'ruRU', 'Дела культа, том 233\r\n\r\nНам снова выпала редкая возможность, о братья мои и сестры! Круг Кенария, мерзостный культ почитателей природы, посылает на нас своих приспешников. Они хотят воспрепятствовать нам добыть красные камни-приманки. Мы не можем этого допустить!\r\n\r\nКрасные камни очень нужны нашим новым союзникам. Нельзя, чтобы шавки из Круга Кенария добились своего. Держитесь, преданные друзья мои. Держитесь!' FROM `page_text` WHERE `ID`=2819 AND MD5(`Text`)='335896bc94ca6ce3055e7c4896e4b441' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2819 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2829, 'ruRU', 'Дорогой дневник, сегодня мой злейший враг Нарайн Причудень пытался меня обмануть, послав вместо себя друзей на казнь. На СВОЮ казнь. Ты можешь в это поверить?$B$BЯ, несмотря ни на что, разрабатывал свой дьявольский план, чтобы выманить его из этой проклятой хижины, а он выкинул такое! Да что там… Больше писать не могу, слишком зол. Продолжу позже.' FROM `page_text` WHERE `ID`=2829 AND MD5(`Text`)='e5db167d440bfc7176290b783614f05b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2829 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2830, 'ruRU', 'Дорогой дневник, написав последнюю запись, я вышел из убежища в сильном гневе. Ох, как же я был зол. Хочу, придумать для своих прислужников новую униформу, что отражала бы мою ярость. Мне уже лучше, но чего-то не хватает. Скоро вернусь…' FROM `page_text` WHERE `ID`=2830 AND MD5(`Text`)='2c3af3fdf55de14ef98445a906ce90c2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2830 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2831, 'ruRU', 'Дорогой дневник, теперь я в порядке. Я бил своего прислужника до тех пор, пока он не начал рыдать, словно девчонка.$B$BХм… Что-то на душе тоскливо. Минутку! Демоны! Я же ЗЛОЙ гений! Злой, понимаешь? Как я в себе разочарован. Скоро вернусь.' FROM `page_text` WHERE `ID`=2831 AND MD5(`Text`)='7586872e77648a62fc771667884cbf5e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2831 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2832, 'ruRU', 'Дорогой дневник, я обнял прислужника и сказал, что очень им доволен. Теперь мне лучше. Только никому ни слова, дневничок.$B$BТак о чем я? Ах, да, НАРАЙН! Р-р-р!!! Ненавижу его. Ведь это он так выделывался на каждом экзамене, когда мы учились в Гномреганском Институте Механики.$B$BОтчислили меня, значит? Гномреган, насколько мне известно, получил по заслугам!$B$BНа сегодня все. Спокойной ночи, дневник!' FROM `page_text` WHERE `ID`=2832 AND MD5(`Text`)='0cbb1aab982f4bfee2d9e37c56aac975' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2832 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2833, 'ruRU', 'Дорогой дневник, наверное, я старею. Я совершенно забыл, что говорил тебе о Нарайне и его обмане. Как бы то ни было, я так разозлился, когда увидел вместо самого Нарайна его копию, что приказал Номеру Два умертвить глупца!$B$BПотом я сел в свой ветролет и начал вырывать страницы из его драгоценной, глупой, идиотской книге на драконьем. Что за бахвальство? Кто сейчас читает на драконьем? Как я его ненавижу!' FROM `page_text` WHERE `ID`=2833 AND MD5(`Text`)='ddaf890503d213e51b061e935c53a507' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2833 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2834, 'ruRU', 'Дорогой дневник, прости, я заснул. Когда я в ярости летал и разбрасывал листы из этой глупой книги, то увидел под собой в Теснине Зловещего Шепота демона и решил сделать из страниц первой главы магическое торнадо, чтобы разорвать его тело на миллион кусочков! Я слово заново родился. Магия + бумага = веселье.$B$BЭтот случай меня изрядно развеселил, и я решил полететь в Восточные королевства. Первой моей остановкой были Огненные Недра. Нарайн постоянно о них твердил! "А вот когда я был в Огненных Недрах, да в Рагнаросе..."' FROM `page_text` WHERE `ID`=2834 AND MD5(`Text`)='25274d58de4443a0c568818a7190ea20' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2834 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2835, 'ruRU', 'И знаешь что? Если уж ему так там нравится, пусть попробует восстановить главу из книги, отправившись в Огненные Недра и покопавшись в куче пепла! Ха!$B$BПока я там летал, обнаружил пресмыкающихся механиков в Лаборатории Виктора Нефариуса – им могут пригодиться Драконьи штуки. Сбросить бомбы!' FROM `page_text` WHERE `ID`=2835 AND MD5(`Text`)='143e3e08e445ea79e279dadf11ae3c8f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2835 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2836, 'ruRU', 'Это стало неплохой забавой. Мне так понравилось рвать проклятую книгу на куски!$B$BДальше уже дело пошло просто.$B$BОдна глава отправилась в Подгород, обиталище зловонных мертвецов и место, где я пробовал самый, пожалуй, лучший чили. Другая – в Штормград, столицу сыра. Дневник, а ты не пробовал заедать сыром из Штормграда, чили из Подгорода? Эй? Там, никак, тревога.' FROM `page_text` WHERE `ID`=2836 AND MD5(`Text`)='86e6596735e46456b1c0b464597d68b8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2836 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2837, 'ruRU', 'Я в это время уже начал уставать – и потому развернул ветролет и направился домой, но по пути сделал еще две остановки. Я пролетел мимо Владыки Каззака и его демонов в Гниющем Шраме (он этого терпеть не может) и сбросил груз в трубу Ониксии.$B$BУстал. Пойду спать.' FROM `page_text` WHERE `ID`=2837 AND MD5(`Text`)='2d1e6ee59be4c0271cebaed5e391c7a2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2837 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2841, 'ruRU', 'Спасибо тебе еще раз от имени Пастбищ Дымного Леса за твою помощь. Мы не уверены, у кого именно Метцен, и потому определенно стоит проверить обе банды!$B$BВремя – деньги, и сейчас нам его очень не хватает. Пожалуйста, постарайся спасти оленя скорее, ведь недооценивать жестокость этих бандитов нельзя.$B$BДальше идут две записки с требованием выкупа, которые мы получили. Удачи…' FROM `page_text` WHERE `ID`=2841 AND MD5(`Text`)='0f276c206ff37bb34c15da95b36759ba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2841 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2842, 'ruRU', 'Если хочешь получить оленя в целости и сохранности, советуем не медлить с выкупом. Пираты Южных морей очень плохо относятся к задержкам платежей, а нам известно, как ценен зверь для ТВОЕГО разбоя.$B$BПринеси 1000 золотых ко входу в Бухту Сорванных Парусов в Танарисе. Если кто-то попытается спасти оленя, то Метцену придется прогуляться по очень короткой доске.$B$BДа-да…$B$BПираты Южных морей.' FROM `page_text` WHERE `ID`=2842 AND MD5(`Text`)='2cc323d01c52fc2812ed75f4736cb7cd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2842 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2843, 'ruRU', 'Твой драгоценный зверь не очень-то хорошо себя чувствует в обжигающем жаре Выжженной Теснины… лучше тебе незамедлительно выполнить наши требования.$B$BТы принесешь нам 5 звездных рубинов и 700 золотых, и положишь все это в один пакет без пометок. Пакет не позже чем через неделю оставь у входа на Подгорную тропу.$B$BЕсли наши требования не будут выполнены, Метцен украсит собой традиционный дворфийский стол на Праздник Зимнего Покрова.$B$BОлень… вкуснятина…' FROM `page_text` WHERE `ID`=2843 AND MD5(`Text`)='157cd5e690c6778613c0dcae77c7ce62' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2843 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2844, 'ruRU', 'И ветра быстрей прискакали они,$B$BИ громко он их имена возгласил:$B$B"Ну, Мерсер! Ну, Чилтон! Ну, Джордан и Каплан!$B$BНо, Нэйгл! Но, Пардо! Но, Гудман и Метцен!$B$BБегом на крыльцо! На стену скорей!$B$BИ мчитесь, мчитесь, мчитесь резвей!"' FROM `page_text` WHERE `ID`=2844 AND MD5(`Text`)='d28241d2464f16f424dcdbe31c81bd60' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2844 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2846, 'ruRU', 'Я очень надеюсь, что мои изыскания помогут мне найти дополнительный источник магической энергии, который будет безопасен для моего народа. Теперь, когда Солнечного Колодца нет, нам надо научиться жить по-новому, не поддаваясь соблазнам магических чар.\r\n\r\nЯ верю, что судьба син\'дорай еще станет примером, вдохновляющим всех!' FROM `page_text` WHERE `ID`=2846 AND MD5(`Text`)='ec26b9027997d2418dfa68c1839368b3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2846 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2847, 'ruRU', 'Пока мне не везет. То небольшое количество магии, что я добыл, должно быть, утекло через Утес. Но у меня еще есть несколько интересных идей. Я привлеку к своим изысканиям своих лучших учеников и посмотрю, чего мы сможем добиться.' FROM `page_text` WHERE `ID`=2847 AND MD5(`Text`)='850fa6b4cffa7f56a4d0e0f0a6d65e88' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2847 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2848, 'ruRU', 'Давненько мне не приходилось здесь ничего писать. У нас по-прежнему никаких результатов. Вчера до меня дошел слух, что один из учеников на острове Солнечного Скитальца, Фелендрен, не подчинявшийся своим наставникам, заразился этой ужасной болезнью.\r\n\r\nПридется удвоить усилия.' FROM `page_text` WHERE `ID`=2848 AND MD5(`Text`)='7a66792c76d3efb872ab296e255b253c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2848 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2849, 'ruRU', 'По-прежнему безуспешно. Но я не собираюсь сдаваться. Син\'дорай не могут позволить себе полагаться на чью-либо магию, особенно сейчас, когда противники окружают нас.\r\n\r\nЯ разрабатываю совершенно новый метод, и если все пойдет по плану, он позволит мне очистить те источники магии Скверны, которые мне удалось обнаружить. Но действовать нужно осторожно.' FROM `page_text` WHERE `ID`=2849 AND MD5(`Text`)='714eb37a9e58f6eb82330ad199b20af4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2849 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2850, 'ruRU', 'Это удивительно! Хотя количество магии, которую нам удалось извлечь, очень скромное, это уже большой шаг вперед. Я немедленно привлеку всех учеников к изучению моего нового метода.\r\n\r\nЕсли нам повезет, мы сможем усовершенствовать процедуру и убить сразу двух зайцев: у нас в руках будет практически нескончаемый источник энергии, и мы сможем противостоять магии Скверны.' FROM `page_text` WHERE `ID`=2850 AND MD5(`Text`)='0a6e3bf9733e76253653c065d07ea9f6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2850 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2851, 'ruRU', 'Случилась беда! Во время одного из экспериментов мой лучший ученик Телетайон заразился и впал в то же состояние, что и многие из моих собратьев. Мои попытки помочь ему не увенчались успехом: было слишком поздно. У меня не оставалось выбора, и мне пришлось избавить его от страданий.\r\n\r\nСлишком дорогой ценой далось нам это открытие.' FROM `page_text` WHERE `ID`=2851 AND MD5(`Text`)='753752f9cc669f5bee0bd2327f60f3dd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2851 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2852, 'ruRU', 'Я не могу больше этого выносить… еще двое учеников погибли. Мы же были так осторожны… Не понимаю, в чем дело.\r\n\r\nПридется остановить исследования и начать все сначала.' FROM `page_text` WHERE `ID`=2852 AND MD5(`Text`)='145642137f1133d84e38ae39de0219b9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2852 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2853, 'ruRU', 'Слишком поздно. Втайне от меня мой третий ученик продолжал наши неудачные исследования и вовлек в них еще нескольких. Я попытаюсь не дать ситуации выйти из-под контроля, но сначала нужно отстранить от исследования всех здоровых учеников.\r\n\r\nЯ скажу им, что уезжаю в Обитель Странников в надежде разработать новый подход к нашей проблеме.\r\n\r\nИз-за моей оплошности уже многие погибли, и мне нужно постараться искупить вину.' FROM `page_text` WHERE `ID`=2853 AND MD5(`Text`)='ab5ddabe4966e6ba31285ff9dcf6866d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2853 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2854, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<P align="center">Часть 2</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\r\n<P align="right">Центурион</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\r\n<P align="right">Легионер</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\r\n<P align="right">Кровавый страж</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\r\n<P align="right">Каменный страж</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2854 AND MD5(`Text`)='7d0cae044b38d745bfbb65e8f2ee300a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2854 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2855, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ ОРДЫ</H1><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\r\n<P align="right">Высший сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\r\n<P align="right">Старший сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\r\n<P align="right">Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\r\n<P align="right">Рубака</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\r\n<P align="right">Разведчик</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2855 AND MD5(`Text`)='17fa37489723a1cae4cb7ffefdebb3aa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2855 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2856, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center"> ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<P align="center">Часть 2</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\r\n<P align="right">Рыцарь-защитник</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\r\n<P align="right">Рыцарь-капитан</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\r\n<P align="right">Рыцарь-лейтенант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\r\n<P align="right">Рыцарь</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2856 AND MD5(`Text`)='f590d7312da2bf11a2cc14552219893c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2856 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2857, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ АЛЬЯНСА</H1><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\r\n<P align="right">Старший сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\r\n<P align="right">Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\r\n<P align="right">Младший сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\r\n<P align="right">Капрал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\r\n<P align="right">Рядовой</P><BR/><BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2857 AND MD5(`Text`)='c1606986940c382a574f28bc149a6321' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2857 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2858, 'ruRU', '<HTML>\n<BODY>\n<H1 align="center">\nЭнтони Рэй Старк\n</H1>\n<H2 align="center">\n1961 – 2005\n</H2>\n</BODY>\n</HTML>' FROM `page_text` WHERE `ID`=2858 AND MD5(`Text`)='cc4f543c81346dd9f622b14d06ecebbf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2858 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2859, 'ruRU', 'ЖАРОВНЯ ВЫЗЫВАНИЯ ДУХОВ: ИНСТРУКЦИЯ К ИСПОЛЬЗОВАНИЮ\r\nГде найти места с привидениями\r\n\r\nВСТУПЛЕНИЕ\r\n\r\nНа этих страницах написано, где можно найти падших духов и призраков, участвовавших в событии, связанном с амулетом Лорда Вальтхалака. Ты уже $gспас:спасла; моих бывших товарищей, но, боюсь, отголоски того зла, что поработило их души, еще не покинули эти места. Таково могущество злобного духа Лорда Вальтхалака.\r\n\r\nС помощью жаровни также можно вызвать Лорда Вальтхалака, но нужно соблюдать крайнюю осторожность.' FROM `page_text` WHERE `ID`=2859 AND MD5(`Text`)='b90320cd246b16e3f67175cb9cd638b3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2859 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2860, 'ruRU', 'ВСТУПЛЕНИЕ, продолжение...\r\n\r\nЖаровню нужно использовать так же, как и Жаровню Призыва. Просто помести ее в любом из пяти мест с привидениями, и в ней пробудятся духи мертвецов.\r\n\r\nДумаю, тебе будет интересно знать, что Знамя Вызова можно также использовать на арене в глубинах Черной горы. Преподай Телдрену и этим болванам хороший урок, когда будешь там.\r\n\r\n\r\nЕсли тебя это заинтересовало, читай дальше.' FROM `page_text` WHERE `ID`=2860 AND MD5(`Text`)='476aea168d9849bc450eac3fca7927ab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2860 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2861, 'ruRU', 'ИЗАЛИЕН\r\nЖрица Луны ночных эльфов\r\n\r\n\r\nИзалиен решила распрощаться со своими товарищами и отправиться в Забытый Город, разоренный город ночных эльфов, некогда известный как Эльдре\'Талас. В нем сохранилась огромная библиотека, святая святых, которую небольшой группе ночных эльфов удалось спасти от разрушения. Там Изалиен надеялась найти информацию о своем наследии и о частях амулета. Стоит заметить, что она была хорошим другом Фарлина Садовника Дерева.' FROM `page_text` WHERE `ID`=2861 AND MD5(`Text`)='fdcfe5c90bbc5938e79ec1033324a97c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2861 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2862, 'ruRU', 'ИЗАЛИЕН, продолжение...\r\n\r\nНо когда она со своим гиппогрифом Неземным входила в город, них напал Алззин Перевертень и его воины. И в этом бою ее глаза закрылись навеки. Может быть, это и к лучшему, что ей не удалось раскрыть секрет того зловещего проклятия, которое Лорд Вальтхалак наложил на амулет, чтобы заключить там свою душу.\r\n\r\nЛогово Алззина – одно из мест с привидениями.' FROM `page_text` WHERE `ID`=2862 AND MD5(`Text`)='873af9d91a850855ffa43de5cbb7f9f6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2862 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2863, 'ruRU', 'МОР СЕРОЕ КОПЫТО\r\nДруид тауренов и Первый из Павших\r\n\r\n\r\nМор Серое Копыто всегда был верен Тайным клинкам. Но случилось так, что он первым пал от рук воинов зловещего Лорда Вальтхалака.\r\n\r\nКогда мы спасались бегством от Вальтхалака, нас преследовала армия его призраков-убийц. Побег из Пика Черной горы был настоящим кошмаром. В суматохе Мор оступился и упал (хотя я подозреваю, что его кто-то толкнул). Но как бы то ни было, он упал на нижний уровень крепости и выбраться оттуда уже не мог.' FROM `page_text` WHERE `ID`=2863 AND MD5(`Text`)='aa8f1e0c2f28ce4eb550db89ac81c5f4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2863 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2864, 'ruRU', 'МОР СЕРОЕ КОПЫТО, продолжение…\r\n\r\nПозже мы узнали, что Мор тогда выжил. Но после этого его ждала еще более страшная участь, чем смерть: его взяли в плен тролли Тазз\'Алаора. Там его подверг страшным пыткам Воевода Вун, а потом его нашли убийцы Вальтхалака и избавили, наконец, от мучений.\r\n\r\nДух Мора Серого Копыта ты найдешь в логове Воеводы Вуна; это еще одно из мест с привидениями.' FROM `page_text` WHERE `ID`=2864 AND MD5(`Text`)='a7b85b9fc1f2a4e03de10fc4ca7bee9b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2864 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2865, 'ruRU', 'ДЖАРИЕН И СОТОС\r\nБрат и сестра, последователи Алого ордена\r\n\r\n\r\nЯ не знаю людей более нетерпимых, чем Джариен и Сотос. Но воины они, надо признать, непревзойденные, если им хорошо платят; думаю, именно поэтому Антион, глава Тайных клинков, их так ценит.\r\n\r\nЭтих двоих завораживали учения Алого ордена. Мы всегда подозревали, что их родители имели какое-то отношение к этой организации; да и они сами с необыкновенным рвением вступали в сражения с Плетью.' FROM `page_text` WHERE `ID`=2865 AND MD5(`Text`)='5069d49de80df9ba04fb9977accb82c4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2865 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2866, 'ruRU', 'ДЖАРИЕН И СОТОС, продолжение…\r\n\r\nИ вот они, наконец, начали проходить испытания, обязательные для всех, кто желает присоединиться к Алому маршу. Они хотели, чтобы их приняли в рыцари, а для этого, по-видимому, и испытания были более сложными. И Сотос не смог справиться со своим последним заданием. Но Джариен заступилась за брата и настаивала на том, чтобы ему также позволили стать рыцарем. По нашим сведениям, за такую дерзость Верховный рыцарь Датрохан лишил их жизни прямо у себя в покоях.\r\n\r\nПосему Кровавый трон в Бастионе Алого ордена, что в Стратхольме, – еще одно место с привидениями.' FROM `page_text` WHERE `ID`=2866 AND MD5(`Text`)='48a412ebc851d6b705b3b5a82545f670' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2866 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2867, 'ruRU', 'KОРМОК\r\nДвухголовый огр некромант\r\n\r\n\r\nЧто сказать о Кормоке? Это двухголовый огр-заклинатель, который, кстати, не всегда был так уж плох. Когда мы его приняли к себе, мы взялись за одну работу в Пылающих степях, и он был нашим пленником. Но он оказал нам неоценимую помощь, когда мы попали там в небольшую переделку, и после этого стал одним из наших главных магов.\r\n\r\nЧто нас в нем немало удивило, так это то, что две его головы вели себя совершенно по-разному. Одна из них была вечно веселая, даже немного глуповатая, вторая же – коварная и расчетливая, а взгляд в ее глазах был совершенно безжизненным. Пугающее зрелище, скажу я тебе.' FROM `page_text` WHERE `ID`=2867 AND MD5(`Text`)='7881a765374f3ff1c49a143c89f8d1fa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2867 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2868, 'ruRU', 'KОРМОК, продолжение…\r\n\r\nПутешествуя вместе с нами, Kормок стал все больше интересоваться некромантией. Его жутковатой голове очень нравилось возвращать к жизни духи умерших; наибольшее удовольствие ему доставляло пробуждать духов острова Очищения и командовать ими.\r\n\r\nПосле того как наша компания распалась, Kормок отправился в Некроситет, чтобы продолжить там свое "обучение". Призрачные убийцы с легкостью нашли эту школу и убили Кормока прямо на глазах у его нового учителя, Раса Снегошепота.\r\n\r\nТак вот, покои Раса Снегошепота – еще одно из мест с привидениями, где можно использовать жаровню.' FROM `page_text` WHERE `ID`=2868 AND MD5(`Text`)='af4d8543c420a4f8252c8332ec5da4a1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2868 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2869, 'ruRU', 'ЛОРД ВАЛЬТХАЛАК\r\nБлагородный драконид и бывший генерал Пика Черной горы\r\n\r\nЛорд Вальтхалак, невероятно могущественный волшебник-драконид, жил еще до генерала Драккисата. Пик часто переходил из рук в руки, но, к сожалению, в этот раз нам суждено было сыграть свою роль в смене власти.\r\n\r\nОдин гоблин-контрабандист из Пиратской бухты, Гремник Риззлшмыг, дал нам задание украсть книгу заклинаний Вальтхалака. Мы не знаем, хотел ли он ее продать или изучить сам (или и то, и другое), да теперь это и неважно. Важно то, что мы проникли на верхние уровни Пика Черной горы и убили Вальтхалака прямо в его логове. Тогда-то и началось настоящее веселье.' FROM `page_text` WHERE `ID`=2869 AND MD5(`Text`)='aa32770a643aa8f6a213ffdd85efe04a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2869 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2870, 'ruRU', 'ЛОРД ВАЛЬТХАЛАК, продолжение…\r\n\r\nЕсли бы мы представляли себе, насколько могущественным волшебником был Вальтхалак (особенно по части подчинения себе душ), то ни за что на свете не согласились бы на это задание. Но судьба распорядилась иначе, и эта работа оказалась для нас последней.\r\n\r\nУбив Лорда Вальтхалака и забрав его книгу заклинаний, Kормок, должно быть, почувствовал, что с его амулетом что-то не так. Он чуть не затеял драку из-за того, что хотел забрать амулет себе. Тогда мы еще не знали, что в амулете была заключена часть души Вальтхалака; выяснили мы это, к сожалению, намного позже.' FROM `page_text` WHERE `ID`=2870 AND MD5(`Text`)='9737917765f591fd880dab2aa3370b84' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2870 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2872, 'ruRU', 'Обращаюсь ко всем мужчинам и женщинам, способным держать в руках оружие:\r\n\r\nПлеть вновь объединила свои силы, и мы вместе должны дать ей достойный отпор, отбросив в сторону все наши разногласия.\r\n\r\nКаждый, кто готов сражаться, должен прийти на сбор к часовне Последней Надежды, что в Восточных чумных землях. Вместе мы победим.\r\n\r\nХранитель архивов\r\nСеребряного Рассвета' FROM `page_text` WHERE `ID`=2872 AND MD5(`Text`)='a8537f5a2eb59ace895174dab4eb0f8a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2872 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2878, 'ruRU', 'Моя дорогая Эмили!$b$bНесколько дней назад мы снялись с лагеря в этом покинутом Светом месте и по приказу короля отправились домой. Даже эти мрачные пейзажи не могли омрачить моей радости, ибо я знал, что после тяжелого путешествия ты наконец-то сможешь заключить меня в обьятья.$b$bСегодня мы добрались до берега, но обнаружили, что от наших кораблей остались одни лишь дымящиеся угли; лишенные единственного шанса вернуться домой, мы вынуждены идти в самое сердце этой бескрайней пустыни.$b$bЭмили, ради тебя я отправлялся в самые дальние уголки этого мира, а теперь… теперь я всей душой желаю повернуть время вспять и вновь оказаться рядом с тобой.$b$bКаждое мгновение я думаю о тебе. Любимая, мысли о тебе согревают мою душу в этом ледяном краю, и никто никогда не отнимет их у меня.$b$bМаксвелл' FROM `page_text` WHERE `ID`=2878 AND MD5(`Text`)='711aa86c93ad504a7cfaece652c47d68' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2878 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2880, 'ruRU', 'Милая Ройбен!\r\n\r\nЗнаю, скорее всего ты никогда не получишь это письмо, но мне просто нечем больше заняться. Мне надо как-то отвлечься от этих чудовищных звуков, доносящихся из-за крепостных стен, окружающих Дольный Очаг. Нежить окружила нашу деревню и не собирается отступать, а нам поручено защищать жителей и ждать подкрепления.\r\n\r\nВ последнем сражении я сломал ногу и теперь совершенно беспомощен; мне остается только сидеть и ждать, когда наша оборона падет. Вокруг только стоны и смерть… это ужасно. Страх повсюду, даже в воздухе.\r\n\r\nНа нашей стороне сражается принц Артас. Если бы не он, нам бы уже давно пришел конец. Его преданность и любовь к родине завораживает; я с радостью буду сражаться и погибну рядом с ним.\r\n\r\nБой идет уже у наших ворот, и я не могу больше сидеть тут, жалея сломанную ногу. Нам нужен каждый, кто может держать в руках меч. Надеюсь, эти строки ты будешь читать в лучшие времена.\r\n\r\nТвой друг,\r\nЛеагрем' FROM `page_text` WHERE `ID`=2880 AND MD5(`Text`)='11f1b5b5f4cc75421dd8add89305d8be' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2880 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2881, 'ruRU', '$b$bЛюбезная Гелиана!$b$bЖаль вас разочаровывать, но я, Варгус, все еще пребываю в добром здравии. Мне надоело быть посмешищем для всех и бродить по деревням в этих шутовских доспехах.$b$bТеперь нам приказали отправиться в Андорал за зерном или еще за чем-то там. Скажите, пожалуйста, какое мне дело до зерна в Андорале? Да вся эта служба в армии – просто бред сумасшедшего.$b$bБудьте уверены, тетя Гелиана, что я вернусь, и ваше наследство будет моим; даже если я буду истекать кровью и умирать от голода, моя злоба не даст мне умереть.$b$bВаргус$b$b' FROM `page_text` WHERE `ID`=2881 AND MD5(`Text`)='76f29c3a6f31d99c8942ea3aa9b8ee18' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2881 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2882, 'ruRU', 'Моя дорогая Амелия!$b$bТо, что я увидел сегодня, навсегда останется в моей памяти.$b$bСтратхольм охвачен огнем… и в этом наша вина.$b$bСегодня ночью мы вышли на городские улицы, и наш принц велел нам врываться в дома мирных жителей и… убивать их, пока они спят. Принц Артас сказал, что они поражены чумой и их нужно лишить жизни, пока они не сделали то же самое с нами.$b$bНачалась резня. Сотни людей погибли от рук тех, кто поклялся их защищать. Я просто не мог на это смотреть и сбежал.$b$bДа, я теперь дезертир, но у меня не поднялась рука совершить столь ужасное злодеяние. Смотря на лица этих несчастных, обреченных на смерть горожан, я видел тебя… и наших детей… И если противостоять подобной жестокости – предательство, значит так тому и быть.$b$bНадеюсь, мне удастся вернуться к тебе вовремя, но на дорогах сейчас небезопасно. Передай детям, что я люблю их.$b$bДжеймс$b$b' FROM `page_text` WHERE `ID`=2882 AND MD5(`Text`)='3d4e94a5e184ca80fd7d0ffee0acad3c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2882 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2883, 'ruRU', 'Самла!$b$bПринц Артас ведет нас все дальше и дальше на север, и у меня на сердце становится совсем тяжело. Когда-то в этом молодом паладине ярко сиял Свет, а теперь я чувствую, как его поглощает тьма. От его былого рвения и бесстрашия не осталось и следа, его преследует что-то ужасное; как бы мне хотелось знать, что это…$b$bСкоро мы выберемся из этой ледяной пустыни. Многие солдаты замерзли насмерть и пали от когтей местных хищников, но Артас говорит, что если наши поиски увенчаются успехом, всему этому кошмару придет конец. Но его слова не придали мне никакой уверенности: после окончания речи на лице Артаса появилась мрачная улыбка, от которой у меня на душе стало еще холоднее.$b$bМолись за нас, Самла, и за наш мир,$b$bТоргал$b$b' FROM `page_text` WHERE `ID`=2883 AND MD5(`Text`)='e587c374008a4a4d1d7bb4590ce144ba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2883 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2884, 'ruRU', 'Дорогая Памела!$b$bЗавтра мы доберемся до Андорала, и, боюсь, я не буду тебе больше писать. Нежить не знает усталости, а мы… мы – всего лишь люди. Нам их не победить. Но не надо печалиться, любовь моя: хотя нам и суждено погибнуть, наша надежда остается. Свет победит!$b$bИ мне греет душу мысль о том, что, когда наша защита падет и враг сокрушит нас, страх смерти не будет терзать меня. Все мои мысли будут о тебе, дорогая, и моя душа обретет покой.$b$bКристоф' FROM `page_text` WHERE `ID`=2884 AND MD5(`Text`)='1604ca3bcaf42dc4f3e786891c8d6936' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2884 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2886, 'ruRU', 'Приветствую тебя, $n. Думаю, тебя заинтересуют результаты моего расследования.$b$bОказывается, и у Ройбена, и у Леагрема есть родные. Советую навестить кого-нибудь из них, даже если они и знают, что случилось с пропавшими солдатами.$b$bБывшую жену Ройбена, Джоанну Вайтхолл, ты найдешь в Квартале Воинов Подгорода; там она проводит большую часть времени. А вот как она воспримет твою новость – это вопрос.$b$bЧто касается Леагрема – у него есть тетя, которая теперь хозяйка сиротского приюта в Штормграде.$b$bКакой бы путь в жизни ты ни $gвыбрал:выбрала;, желаю удачи во всех твоих делах.$b$b' FROM `page_text` WHERE `ID`=2886 AND MD5(`Text`)='791c31ab8ea302598efb9a69eebb8476' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2886 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2889, 'ruRU', 'Приветствую. Мне, наконец, удалось выкроить время, чтобы изучить послание, которое ты <нашел/нашла> у Плети. Это было нелегко, и вот результаты моих трудов – информация о живом родственнике погибшего.\r\n\r\nСестру Максвелла зовут Зарена Кромвинд, она – кузнец в Пиратской бухте. Не знаю, насколько они с братом были близки, но тебе стоит заглянуть к ней, если вдруг окажешься рядом. Сейчас такая информация выясняется очень редко, так что ты можешь сделать доброе дело.' FROM `page_text` WHERE `ID`=2889 AND MD5(`Text`)='b2bf958ffe54766c2f02bb1a56f391c9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2889 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2890, 'ruRU', 'Мне, наконец, удалось найти кое-какие сведения о солдате, с которым ты сражался. Его родословная сохранилась очень плохо, так что мне пришлось постараться.$b$bПредставляешь, что выяснилось: управляющий Ален в часовне Последней Надежды, оказывается, сын Кристофа! Ты можешь облегчить его боль, если расскажешь, что случилось с его отцом. Так что, если будешь на службе у Серебряного Рассвета, поговори с ним. Сделай доброе дело.$b$b' FROM `page_text` WHERE `ID`=2890 AND MD5(`Text`)='0732d674f55a0b36577a132d7b3c1d76' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2890 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2891, 'ruRU', 'В память о Главнокомандующем сил Альянса, Андуине Лотаре: Это человек, который был готов на все ради своего короля, своего народа и своей родины…\r\n\r\nПусть враги запомнят наши имена. Пусть друзья чтят нашу память. Мы – Дети Лотара. \r\n\r\n- Генерал Туралион' FROM `page_text` WHERE `ID`=2891 AND MD5(`Text`)='bd12aa53f6ecdc5cbfacb3c17fe336ca' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2891 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2892, 'ruRU', 'Лежит здесь батрак; он смел очень был. Сражаться хотел, но лишь газы пустил.' FROM `page_text` WHERE `ID`=2892 AND MD5(`Text`)='d1e3b23532c0ea697a560584f873f086' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2892 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2905, 'ruRU', 'Вот урна с прахом. Внутри – останки моего рассудка, моей страсти и моего честолюбия. Все это погибло, уничтожило само себя. Пусть все, чья нога ступит на пустынные земли Адского Пламени, помнят этого раба. Он сражался за Альянс, храбро бился за Орду, но отплатили ему за это лишь злостью и жестокостью; все, чем он дорожил, у него отнимали. Пусть те, кто пожинают плоды его стараний, познают его гнев. Быть может, не в этой жизни, но им придется поплатиться за свое бездушие. Клянусь, справедливость восторжествует. Я отомщу за свои страдания.' FROM `page_text` WHERE `ID`=2905 AND MD5(`Text`)='741c30b2ebfbaa4775fb0f5b3d577c15' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2905 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2906, 'ruRU', 'Изучи острова и доложи мне о результатах.$B$BПомни: попадаться нельзя!$B$BНе подведи меня, Кандресс!$B$BS.' FROM `page_text` WHERE `ID`=2906 AND MD5(`Text`)='bedd806faf1f2e01fe7abb29d1da6bf5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2906 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2907, 'ruRU', 'Это – план Шадра\'Алора и трех здешних церквей; крестиками помечены местонахождения украденных яиц. Вот они: в южной части восточной церкви, возле хижины к северо-востоку от восточной церкви, возле алтаря к востоку от озера в центре и на склоне южной церкви возле надписи "изгнанник"\r\n\r\nСудя по записям Пероборода, он рассчитывал передать эти сведения Фалстаду Громовому Молоту; он надеялся, что именно его отряд воинов пошлет спасать яйца.' FROM `page_text` WHERE `ID`=2907 AND MD5(`Text`)='2dc02cd7759407fe0f11232223837d42' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2907 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2911, 'ruRU', 'Диатор,\r\n\r\nНадеюсь, это письмо все-таки достигнет тебя. Эти демоны невероятно глупы. Они способны думать лишь о своих когтях, хлыстах и шипах на головах, которыми они то и дело норовят что-нибудь проткнуть. И я не мог положиться на инферналов, иначе бы письмо сгорело.\r\n\r\nКак я скучаю по тем временам, когда мы использовали орков! У них была хоть капля мозгов, и они могли подчиняться приказам. Быть может, нам удастся завладеть несколькими местными рабами?' FROM `page_text` WHERE `ID`=2911 AND MD5(`Text`)='ef2f9380e77df2861e05bbf23463e88c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2911 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2912, 'ruRU', 'Думаю, пришло время начать завоевание младших рас. Застава Расщепленного Дерева на северо-западе – весьма заманчивая добыча. Нам нужно приготовиться к нападению до того, как полная луна озарит своим светом этот никчемный мир. Если мы сейчас подчиним их себе, они навсегда запомнят, что значило слово \'Орда\' в былые времена.\r\n\r\nГорганнон\r\n\r\np.s. – И хватит тратить кровавые чернила на любовные письма моим суккубам! В наши дни непорочные ночные эльфийки – большая редкость.' FROM `page_text` WHERE `ID`=2912 AND MD5(`Text`)='b32f3d5f8d3a64af997f8230aaf77b9a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2912 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2913, 'ruRU', 'На волосок от смерти,$BНеустрашим он был.$BТолпой напали черти,$BНо он их победил!$B$BС той битвы стародавней$BНи меч, ни копий твердь$BДворфа сего славного$BНе сумели одолеть' FROM `page_text` WHERE `ID`=2913 AND MD5(`Text`)='5bd7b65c78c4a78248aa62f23cfa9291' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2913 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2914, 'ruRU', '…но она это уже знала. Она продала свою душу и выбрала жизнь изгоя. Она думала, что месть того стоит.$B$BИ вот, незнакомец предлагает ей вернуть себе доброе имя, и все, что он просит взамен, – довериться ему.$B$B"Я согласна," – сказала Катрейн. "Терять мне уже нечего".' FROM `page_text` WHERE `ID`=2914 AND MD5(`Text`)='06c1efec2856b93a8cb5e479a75c1aea' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2914 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2916, 'ruRU', 'Вазруден!\r\n\r\nС тех пор как вновь открылся Темный портал, Оплот Чести и Траллмар стали получать значительную поддержку из Азерота. Судя по всему, они готовятся напасть на крепость, но нам еще нужно справиться с Пылающим Легионом. Это никуда не годится!\r\n\r\nНи в коем случае нельзя подвергать опасности операцию в Кузне Крови! Орки Скверны, которых там создают, – залог нашего успеха. Усиль защиту крепости и расставь стражников по всему периметру!\r\n\r\nПоверь, будет лучше, если мне не придется навещать тебя лично.\r\n\r\n-- Иллидан' FROM `page_text` WHERE `ID`=2916 AND MD5(`Text`)='1bdd66bc5e29ef6cb5c7006f1ac8953b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2916 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2917, 'ruRU', 'Вазруден!\r\n\r\nС тех пор как вновь открылся Темный портал, Оплот Чести и Траллмар стали получать значительную поддержку из Азерота. Судя по всему, они готовятся напасть на крепость, но нам еще нужно справиться с Пылающим Легионом. Это никуда не годится!\r\n\r\nНи в коем случае нельзя подвергать опасности операцию в Кузне Крови! Орки Скверны, которых там создают, – это залог нашего успеха. Усиль защиту крепости и расставь стражников по всему периметру!\r\n\r\nПоверь, будет лучше, если мне не придется навещать тебя лично.\r\n\r\n-- Иллидан' FROM `page_text` WHERE `ID`=2917 AND MD5(`Text`)='db84042e774795017729642580c52460' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2917 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2918, 'ruRU', 'Дело сделано. Не помню как, но результат налицо.$B$BМне доводилось грешить и раньше. Однажды невинный человек пал от моей руки.$B$BНо в этот раз все по-другому. $B$BВсе изменилось, и я тоже. $B$BЭти убийства произошли не по моей воле. Во мне живет свирепый зверь. Меня будут бояться и пытаться убить. Мне нужно прятаться. Бежать. Закопать трупы.$B$BКогда я осознаю, что на самом деле мучает меня, я выхожу на улицу.$B$BНет в этом моей вины.' FROM `page_text` WHERE `ID`=2918 AND MD5(`Text`)='40c8f99958ef984f518e51a00eba049d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2918 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2923, 'ruRU', 'Уважаемые главы Орды!$B$BЯ, Лор\'темар Терон, правящий лорд Кель\'Таласа, с превеликим удовольствием сообщаю вам о разгроме военачальника Плети, известного нам под именем Дар\'Кхан Дратир.$B$BНа прошлых переговорах син\'дорай много раз попрекали его присутствием на наших землях. Мы надеемся, что вышеупомянутое событие снимет все вопросы, имевшиеся у уважаемых соправителей.$B$B<Подпись>Лор\'темар Терон' FROM `page_text` WHERE `ID`=2923 AND MD5(`Text`)='f230cfbac73ea881133816d992e4bbf4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2923 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2924, 'ruRU', 'Уважаемые главы Орды!$B$BЯ, Лор\'темар Терон, правящий лорд Кель\'Таласа, с превеликим удовольствием сообщаю вам о разгроме военачальника Плети, известного нам под именем Дар\'Кхан Дратир.$B$BНа прошлых переговорах син\'дорай много раз попрекали его присутствием на наших землях. Мы надеемся, что вышеупомянутое событие снимет все вопросы, имевшиеся у уважаемых соправителей.$B$B<Подпись>Лор\'темар Терон' FROM `page_text` WHERE `ID`=2924 AND MD5(`Text`)='f230cfbac73ea881133816d992e4bbf4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2924 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2925, 'ruRU', 'Ремонт Межпространственного Лайнера для начинающих, Джамус Кэси$b$b<На тонких страницах этой книги множество диаграмм, показывающих, как содержать в исправности и ремонтировать межпространственный лайнер. Книга открыта на главе под названием "Как Избежать Поломки Навигационного Комплекса".>' FROM `page_text` WHERE `ID`=2925 AND MD5(`Text`)='2e3961e1e777d536a0fa2ea93cf70f11' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2925 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2926, 'ruRU', '$B$BPS – нашему магистру прислали из Запределья ответ на вопрос Тралла. Ответ утвердительный.' FROM `page_text` WHERE `ID`=2926 AND MD5(`Text`)='ae4818e9bb31be2ed196903fdc1584dc' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2926 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2927, 'ruRU', 'PS: нашему магистру прислали из Запределья ответ на вопрос Тралла. Ответ утвердительный.$B$B<На письме стоит печать Леди Сильваны Ветрокрылой>' FROM `page_text` WHERE `ID`=2927 AND MD5(`Text`)='5aea7d945b98fefb50bd85f98d2422c3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2927 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2930, 'ruRU', '$N,\r\n\r\nЧтобы создать закаленный кровью протазан, нужно немало очень редких материалов, но в итоге ты получишь оружие непревзойденной силы. Я перечислю необходимые материалы, начиная с тех, которые легче всего найти.\r\n\r\nНе забывай, что орден Рыцаря Крови нужно хранить до тех пор, пока ты не соберешь все материалы, необходимые для этого оружия.' FROM `page_text` WHERE `ID`=2930 AND MD5(`Text`)='0d1cd8cdb5bd03be0de78faf929d36c1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2930 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2931, 'ruRU', 'Кровь Разгневанных – чтобы подготовить металл к ковке, его нужно закалить в Крови Разгневанных. Кровь большинства демонов содержит достаточное количество энергии, но здесь нужна не обычная кровь.\r\n\r\nВолшебники из Оргриммара поделились сведениями о том, где можно найти подходящую для твоего оружия кровь. У сектантов Пламенеющего Клинка из Огненной бездны есть сфера с кровью, которая нам как раз нужна. По слухам, эту сферу охраняет орк по имени Жергош Призыватель Духов.\r\n\r\nДействуй осторожно, ведь ты имеешь дело с демоническими силами. Невозможно предугадать, что может случиться с таким мощным веществом, как это.' FROM `page_text` WHERE `ID`=2931 AND MD5(`Text`)='7f3dea7c7bdffe6688c864b5ad91bafd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2931 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2932, 'ruRU', 'Ящик со слитками, закаленными в крови... Сталь, конечно, металл неплохой, но без особой закалки ничем не примечательный. Слитки, закаленные в крови, – материал высочайшего качества, способ его изготовления держится в строжайшей тайне. Ходят слухи, что любой кузнец, осмелившийся работать с металлом такой закалки, навлекает на себя страшное проклятье, но наши мастера доказали, что это не так.\r\n\r\nНеудивительно, что столь ценный материал очень сложно достать, но от Отрекшихся мы получили сведения о том, что его можно найти в Крепости Темного Клыка. Умелый кузнец по имени Ландэн Стилвелл сумел раздобыть этот металл и теперь хранит его в крепости. Где именно он его спрятал, остается тайной, но наш осведомитель сообщил, что Ланден Стилвелл сейчас заключен в тюрьме, что в подземелье крепости. Раздобудь этот металл любым способом.' FROM `page_text` WHERE `ID`=2932 AND MD5(`Text`)='2f90ebcec0e396f28026eff007485fde' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2932 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2933, 'ruRU', 'Оскверненный самоцвет Кора – в книгах магистра говорится, что в этих редких драгоценных камнях некоторые из наиболее могущественных волшебников хранили свою магию. В очищенном виде такие камни найти очень легко, но они слишком слабы для твоего оружия.\r\n\r\nВ пещерах Непроглядной Пучины волшебники-наги хранят самоцветы Кора со своей могучей темной магией – они-то нам и нужны. Убей этих волшебников и забери их камни.' FROM `page_text` WHERE `ID`=2933 AND MD5(`Text`)='02165417aa61ece6b3d1bd379c26b6ae' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2933 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2934, 'ruRU', 'Орден, который ты будешь носить, раньше принадлежал храброму и бесстрашному рыцарю крови из семьи Утренней Звезды. Его верная служба – доброе знамение для твоей.\r\n\r\nРыцарь крови Утренняя Звезда храбро повел свое войско на атаку крепости Плети Смертхольм, но потерпел поражение. Его тело покоится там, где он умер, – на месте битвы с нашими заклятыми врагами. Найди его, $N, и принеси мне его орден.' FROM `page_text` WHERE `ID`=2934 AND MD5(`Text`)='cc8f14496c1accfd931212fb93d5005b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2934 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2939, 'ruRU', 'Мне хотелось кричать, но лишь приглушенный стон сорвался с моих губ. За неповиновение меня незамедлительно избили. Лежа на полу, я видел, как Матис вышагивает перед телом Саруана. У него был обеспокоенный вид. Он сказал, что если Саруан умрет во время пыток, то Сиронас – или Сирона? – спустит с него семь шкур.' FROM `page_text` WHERE `ID`=2939 AND MD5(`Text`)='036a1e8c88cc8681db2ef15e55fbb606' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2939 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2941, 'ruRU', 'Леди Лиадрин!\r\n\r\nУ нас возникли некоторые проблемы с пойманным существом, и в результате пострадало очень ценное оборудование. Мне удалось восстановить контроль над ним, хоть и немалыми усилиями. Составленный мной рапорт об этом инциденте был направлен верховному магистру Роммату, но он до сих пор мне не ответил. Боюсь, что без некоторых материалов, которые были утрачены, я не смогу продолжать свои исследования, а вы понимаете, насколько они важны для ваших рыцарей.\r\n\r\nНадеюсь, вы сможете помочь мне получить некоторые из материалов, перечисленных ниже. Любая помощь будет принята с благодарностью.\r\n\r\nМагистр Асталор Кровавая Клятва' FROM `page_text` WHERE `ID`=2941 AND MD5(`Text`)='3ef7837b01383d1c89fc8bb613325f19' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2941 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2942, 'ruRU', '* 40 отрезов рунической ткани\r\n* 6 слитков арканита\r\n* 10 солнечников\r\n* 5 темных рун\r\n* 150 золотых' FROM `page_text` WHERE `ID`=2942 AND MD5(`Text`)='83c4f7034546ea603167ab4fe3f608ba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2942 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2943, 'ruRU', 'Заявление Солнечного короля\r\n\r\nСолнечный Ястреб, мои милые, преданные дети, ваш король очень доволен вами. Ваше присутствие на Азероте очень важно как для меня, так и для Повелителя.\r\n\r\nУже скоро солнечный портал сможет переместить подкрепления из Крепости Бурь прямо на остров Кровавой Дымки. \r\n\r\nМы вернем Экзодар. Мы убьем всех этих синекожих полукровок на месте. Велен заплатит за то, что он совершил. \r\n\r\n-Король Кель\'тас Солнечный Скиталец' FROM `page_text` WHERE `ID`=2943 AND MD5(`Text`)='45c24e19ac6cdc791a3bf0eeb98ddaaa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2943 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2945, 'ruRU', '<HTML>\r\n<BODY>\r\n<BR/>\r\n<BR/>\r\n<H1 align="center">ЗЕЛЕНЫЕ ХОЛМЫ ТЕРНИСТОЙ ДОЛИНЫ</H1>\r\n<BR/>\r\n<H3 align="center">Хеминг Эрнестуэй</H3>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2945 AND MD5(`Text`)='02f88b700afbddbb9e593f64ec9e320d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2945 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2946, 'ruRU', 'Наш первый день прошел, как обычно проходят первые дни. Большую часть времени мы обустраивали лагерь. Мне удалось найти идеальное место у небольшой чистой заводи. Старые обветшавшие мостки указывали на то, что в этом месте когда-то жили. Кто именно там жил, мы пока не знали.' FROM `page_text` WHERE `ID`=2946 AND MD5(`Text`)='3462a21366c030407f4484533bf37833' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2946 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2947, 'ruRU', 'В эту экспедицию со мной отправились Ажек Руак и сэр С. Дж. Эрлгедин, а также мой верный слуга Барнил Каменный Горшок. С отцом Ажек мы когда-то сражались за Альянс плечом к плечу. Удивительно, как она выросла за это время. Отец обучил ее искусству владения оружием. Ее навыки стрельбы из лука настолько хороши, что невольно заставляют задуматься, не течет ли в ее жилах кровь эльфов.' FROM `page_text` WHERE `ID`=2947 AND MD5(`Text`)='b4090a7a462222a90ee69d49b0187f52' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2947 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2948, 'ruRU', 'Сэр С. Дж. Эрлгедин принадлежит к знатному людскому роду. Его отец, граф Эрлгедин, славился своей щедростью. Именно граф выступал за улучшение условий труда для Гильдии каменщиков во время восстановления Штормграда после Второй Великой войны.' FROM `page_text` WHERE `ID`=2948 AND MD5(`Text`)='6e7b3d50d846bb58f48c2c2813421549' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2948 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2949, 'ruRU', 'В последующие годы, после того как Штормград обманул братство Каменщиков, сэр Эрлгедин разочаровался в аристократии Королевства. Он больше не хотел принадлежать к Благородным Домам, хотя право это унаследовал от отца.\r\n\r\nНо не будем отвлекаться. Мое повествование не политический трактат и не биография. Я всего лишь делюсь опытом участия в большой охоте среди зеленых холмов Тернистой долины.' FROM `page_text` WHERE `ID`=2949 AND MD5(`Text`)='a24fb4446d6303fed5c56ad866cc79e8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2949 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2950, 'ruRU', 'Мы проснулись чуть свет. Барнил занялся приготовлением завтрака. Мне показалось, что мысли Ажек в этот момент были где-то далеко. Впереди нас ждал долгий день и немало опасностей. Нужна была полная сосредоточенность, иначе последствия могли быть печальными. Но Ажек была не в состоянии отвести взгляд от Барнила, занятого мытьем столовых принадлежностей.' FROM `page_text` WHERE `ID`=2950 AND MD5(`Text`)='f08abea0fb51c139a2d1c90ad19e37a1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2950 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2951, 'ruRU', 'Когда я уже собирался спросить, почему Ажек не участвует в обсуждении плана сегодняшней охоты, она выхватила стрелу из колчана, натянула тетиву и выстрелила в бедного Барнила. Однако стрела пролетела мимо. Разинув рот, Барнил наблюдал за тем, как возле него на поверхность реки всплыл огромный кроколиск, а между глаз у него торчала стрела Ажек.' FROM `page_text` WHERE `ID`=2951 AND MD5(`Text`)='b06829c3540ca6431fda409001d368b2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2951 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2952, 'ruRU', 'Мы отправились на запад через дикие непроходимые джунгли. В поисках добычи мы медленно, но верно прокладывали себе путь сквозь густую растительность. К нашему сожалению, утром все было тихо. Даже ветер не шумел в кронах деревьев. К полудню мы начали волноваться. Шаги Барнила уже не были столь осторожными и тихими, как раньше. Теперь он неуклюже переваливался с ноги на ногу, с треском ломая упавшие на землю сухие ветки.' FROM `page_text` WHERE `ID`=2952 AND MD5(`Text`)='9cd1bd27560e7f643d7dac21f83b73d5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2952 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2953, 'ruRU', 'После очередного неверного шага Барнила Эрлгедин положил свою тяжелую руку ему на плечо. Мы с Ажек переглянулись, уверенные, что он решил-таки напомнить Барнилу о необходимости соблюдать осторожность. Но вместо этого Эрлгедин кивнул головой в сторону лежащего неподалеку дерева. Оттуда на нас пристально смотрели два черных глаза, а под ними была пасть, полная острых зубов.' FROM `page_text` WHERE `ID`=2953 AND MD5(`Text`)='5af5e05a9bf7d48ecdcb8a67e4bd76bd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2953 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2954, 'ruRU', 'Этим чудищем был самец тигра Тернистой долины. Прежде чем мне удалось взвести винтовку, Эрлгедин поднял свой арбалет и выстрелил в зверя. Стрела ушла немного в сторону и вонзилась в левый бок тигра. Зверь попытался убежать, но его рана была слишком глубокой. Он сумел сделать лишь несколько шагов, а затем его настиг метательный топор Барнила.' FROM `page_text` WHERE `ID`=2954 AND MD5(`Text`)='61555a5421df7a9662e83d325bdb6e4e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2954 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2955, 'ruRU', 'Первый успех взбодрил нашу команду. Барнил налил всем меда, чтобы отметить его. Но нашему празднованию не суждено было продолжаться долго. Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рев. Я в жизни не слышал такого леденящего кровь звука.' FROM `page_text` WHERE `ID`=2955 AND MD5(`Text`)='8810377a7bd978746aa49a74848466ae' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2955 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2956, 'ruRU', 'На скалистом склоне, возвышавшемся над нами, в лучах заходящего солнца вырисовывался силуэт самой большой кошки, которую я когда-либо видел. Мне удалось сделать неловкий выстрел из ружья, но кошка не двинулась с места. Она издала еще один ужасный рык, громче прошлого, и исчезла.\r\n\r\nМы собрали вещи и мрачно двинулись в лагерь.' FROM `page_text` WHERE `ID`=2956 AND MD5(`Text`)='bde7b7989d4533f00d0b017e619f554e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2956 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2957, 'ruRU', 'Я обещал своим товарищам, что на следующий день мы отправимся охотиться на пантер, так как их мех очень высоко ценится по всему Азероту. Учитывая, что большинство охотников и торговцев мехом сейчас храбро отдавали свои жизни, сражаясь за Альянс, этот мех еще больше возрос в цене.' FROM `page_text` WHERE `ID`=2957 AND MD5(`Text`)='23d416448ffb0e86cb1bcea1b1b3d8c0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2957 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2958, 'ruRU', 'Ажек и сэр Эрлгедин страстно желали научиться стрелять из дворфийских винтовок. Я велел им оставить свое примитивное оружие в лагере. Мы с Барнилом снарядили их лучшими образцами стальгорнских ружей.' FROM `page_text` WHERE `ID`=2958 AND MD5(`Text`)='8436af36243c5f93d91000309ef7097e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2958 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2959, 'ruRU', 'В тот день мы пошли на юг, двигаясь по свежим следам пантеры. Вскоре мы пришли к ущелью, через которое был перекинут длинный веревочный мостик. При виде этого чуда инженерной мысли мне сразу вспомнилось, как описывал этот район Бранн. Тролли, коренные жители этих мест, всегда считались примитивной расой, но мастерство, с которым они сконструировали этот мост через непреодолимую пропасть, было неоспоримо.' FROM `page_text` WHERE `ID`=2959 AND MD5(`Text`)='490dc9bcd57f6341368eb12b451fe4b3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2959 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2960, 'ruRU', 'Ажек не понадобилось много времени, чтобы выследить пантеру; она ушла на юго-запад. Мы шли быстрым шагом, с оружием наготове, и уже предвкушали успех. Треск веток, донесшийся из рощи неподалеку, немедленно привлек наше внимание. Там кто-то был. Одного взгляда на Барнила хватило, чтобы он понял меня. Он медленно опустил винтовку. Эта добыча – не для нас, а для наших спутников-людей. Сколько пантер уже погибло от наших пуль! Нет, эта добыча – не для нас.' FROM `page_text` WHERE `ID`=2960 AND MD5(`Text`)='875d1975aa75219c53d14f3e19595bf4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2960 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2961, 'ruRU', 'Ажек и сэр Эрлгедин стояли наготове, направив ружья в сторону колючего кустарника у подножия раскачивающихся деревьев. Полуденное солнце нещадно палило. Капля пота медленно скатилась по виску Эрлгедина, когда он взводил курок. В момент щелчка из кустов на поляну выпрыгнула огромная черная пантера – невероятно грациозное животное.' FROM `page_text` WHERE `ID`=2961 AND MD5(`Text`)='0f98685bbcbe6525ec950e980f13ee49' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2961 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2962, 'ruRU', 'Пантера понеслась вдоль опушки леса, а люди ни на секунду не спускали с нее взгляда. Стволы их ружей медленно двигались, оставаясь идеально параллельными друг другу. Барнил посмотрел на меня нетерпеливым взглядом, но я отрицательно покачал головой. Это была охота людей, а не наша. Эрлгедин выстрелил. Раздался оглушительный грохот, но пантера осталась цела. Вероятно, Эрлгедин не был готов к такой мощной отдаче.' FROM `page_text` WHERE `ID`=2962 AND MD5(`Text`)='8ba8b7a43dfe61c5155add2ecad226c1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2962 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2963, 'ruRU', 'Ружье резко подалось назад в его руках. Дуло ушло в сторону и попало под ствол ружья Ажек. И именно в этот момент Ажек спустила курок. Неуклюже вздернувшееся к кронам деревьев ружье отчетливо и громко выстрелило. Стая птиц, крича, вспорхнула в небо, разлетаясь во все стороны. Струйка дыма вилась из дерева. Мы в оцепенении смотрели, как гигантская ветка рухнула прямо на убегающую пантеру и сломала ей хребет.' FROM `page_text` WHERE `ID`=2963 AND MD5(`Text`)='38ac1548038316112729f084e0dcef33' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2963 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2964, 'ruRU', 'Шли недели, шкур пантер и тигров становилось все больше. Мне показалось, что настало время сосредоточить наши силы на более серьезной добыче: ящерах.\r\n\r\nЛюди поблагодарили нас с Барнилом за уроки, но отказались использовать огнестрельное оружие. Ажек чувствовала себя куда более уверенно с луком в руках, а сэр Эрлгедин не расставался со своим мощным арбалетом.' FROM `page_text` WHERE `ID`=2964 AND MD5(`Text`)='6ffc5c746d7b1522f8300a310aa45879' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2964 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2965, 'ruRU', 'С первыми лучами солнца мы отправились на охоту на юг, за руины Ткаши. Барнил беспокоился, что мы можем наткнуться на троллей племени Кровавого Скальпа. Мои слова о том, что это племя сейчас занято войной со своими заклятыми врагами из племени Дробителей Черепов, конечно же, ничуть не успокоили его. Меня же возможность засады беспокоила гораздо меньше: в моих руках была заряженная винтовка, на поясе – полная сумка пороха, а рядом – трое отличных охотников.' FROM `page_text` WHERE `ID`=2965 AND MD5(`Text`)='1df3f1a94c66d612cab3e8de53861be3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2965 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2966, 'ruRU', 'Я помню битву с армией Пылающего Легиона: враги надвигалась со всех направлений, а прямо передо мной возвышался огромный инфернал. Толпа злобных троллей по сравнению с этим кажется безобидной, как заяц в горах Дун Морога.\r\n\r\nК величайшей радости Барнила, мы миновали руины Ткаши без всяких приключений. Мы продолжали двигаться на запад к Великому морю, обходя руины Зул\'Кунды. Взобравшись на высокий утес над морем, мы увидели нашего первого ящера.' FROM `page_text` WHERE `ID`=2966 AND MD5(`Text`)='887731e4dde01a75e08aaa682d2bc501' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2966 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2967, 'ruRU', 'Зверь даже не обнаружил нашего присутствия. Если быть честным, единственное приветствие, которое он получил от экспедиции, – это пулю между глаз.\r\n\r\nАжек одобрительно кивнула мне, а сэр Эрлгедин радостно крикнул: “Ура!” Настало время отпраздновать успех, выкурив трубку, затерявшуюся в глубинах моего рюкзака. Барнил отправился на вершину утеса за трофеем. Вид поверженного чудища доставлял мне немалое удовольствие, как и любая значительная победа.' FROM `page_text` WHERE `ID`=2967 AND MD5(`Text`)='b478d833baf244dc60f1329e5b0ec909' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2967 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2968, 'ruRU', 'Но мне не пришлось долго наслаждаться успехом. На вершине утеса, прямо над несчастным Барнилом, появились несколько силуэтов.\r\n\r\n“Беги, Барнил!” – закричали мы. Ажек, сэр Эрлгедин и я выстрелили поверх головы Барнила в сторону преследующих его ящеров. Кто-то даже убил одного из них.' FROM `page_text` WHERE `ID`=2968 AND MD5(`Text`)='9fff6131cc66ad5472f2deff87da7e1d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2968 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2969, 'ruRU', 'Наших суматошных выстрелов оказалось достаточно, чтобы дать Барнилу время убежать. Барнил скатился с холма и присоединился к нашей группе. Мы побежали в джунгли, преследуемые стаей свирепых ящеров-кнутохвостов.\r\n\r\nОхотники превратились в добычу.' FROM `page_text` WHERE `ID`=2969 AND MD5(`Text`)='d6ba293ae9a04ae586b5a0574edeae10' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2969 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2970, 'ruRU', 'Я вел отряд по направлению к морю в надежде, что вода остановит ящеров. Но в спешке мы зашли слишком далеко на север, на возвышенность. Исправлять ошибку было уже поздно. И вина была в этом моя. Мы остановились на краю отвесной скалы, а ящеры были уже в нескольких шагах от нас.' FROM `page_text` WHERE `ID`=2970 AND MD5(`Text`)='83b0c102184f5fc5106e053cdb889af1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2970 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2971, 'ruRU', 'Я медленно шагнул вперед, держа ружье наготове. Я привел этих отважных охотников к гибели. И готов был погибнуть сам, защищая их. Ящеры-кнутохвосты известны своей свирепостью и неумолимой жаждой крови. Их было намного больше нас. Но я бы себе не простил, если бы позволил расправиться с собой и моими товарищами, не прикончив сначала несколько этих тварей!' FROM `page_text` WHERE `ID`=2971 AND MD5(`Text`)='b668df41d172f751ad83d06c88e4646d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2971 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2972, 'ruRU', 'Ажек и сэр Эрлгедин вскинули свое оружие, прикрывая меня с боков, спиной к морю. Барнил обреченно вздохнул и обнажил свой топор. Кнутохвосты были практически рядом с нами. Их уверенные шаги замедлились. Они крадучись подбирались к своим жертвам, зная, что загнали нас в ловушку.' FROM `page_text` WHERE `ID`=2972 AND MD5(`Text`)='213fcdcdbd112997b010ce2945623ce9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2972 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2973, 'ruRU', 'И тогда случилось чудо. Прямо рядом с нами раздался резкий, ужасающий рев огромного белого тигра. Несмотря на количество, ящеры развернулись и бросились врассыпную. Мы увидели лишь белый сполох, когда тигр минул нас и помчался за одним из ящеров. Нам не требовалось команды. Все четыре члена нашего отряда знали, что пришло время бежать.' FROM `page_text` WHERE `ID`=2973 AND MD5(`Text`)='3b4b676a8566883dd22ea2d1e6a0e58f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2973 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2974, 'ruRU', 'Мы без остановки мчались назад, к нашему лагерю. Позже той ночью мы тихо сидели у костра, зная, что наши жизни были спасены по странной прихоти судьбы. Этому риску подвергается любой участник большой охоты. Мы – игрушки в руках судьбы. Когда-нибудь каждый из нас встретится с хищным оскалом смерти. И ваш покорный слуга рад, что эта встреча не произошла на зеленых холмах Тернистой долины.\r\n\r\n--Конец--' FROM `page_text` WHERE `ID`=2974 AND MD5(`Text`)='752be83d3f8fc54fecaa321cc6ddace9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2974 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2975, 'ruRU', 'Глупый,\r\n\r\nнайди еду. Синие вкусные. Лантрезор говорит, они хорошие. Неси еду Глыбу. Сначала ест Глыб, потом ест глупый. Ясно? Быстро, а то Глыб будет есть тебя.\r\n\r\n-Глыб' FROM `page_text` WHERE `ID`=2975 AND MD5(`Text`)='654023cbbf25a7f2fa9ce219c8b01129' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2975 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2979, 'ruRU', 'Корень олембы довольно часто встречается в лесу Тероккар. Ищи выступающие над землей корни деревьев олембы, из которых этот лес и состоит.\r\n\r\nКлюква растет только в Зангартопи. Ее можно найти возле крепости Анго\'рош, что в северо-западной части болота. Опасайся огров, охраняющих эти ценные ягоды.\r\n\r\nТелаарский папоротник, наверное, самое легкодоступное растение в списке. Его можно найти в котловине Телаари к югу от Гарадара. Листья находятся возле воды. \r\n\r\nПоследнее растение есть только в Острогорье к северу от Зангартопи. Драконий шип растет на вершинах скалистых утесов у входа в ущелья Острогорья. Ты поймешь, о чем я говорю, когда увидишь эти горы: утесы похожи на ряды огромных острых зубов.' FROM `page_text` WHERE `ID`=2979 AND MD5(`Text`)='14d1421b1e171a0e5f037876f5488c35' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2979 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2983, 'ruRU', 'Чтобы настойка позволила увидеть мертвецов, нужно собрать кое-какие ингредиенты.\r\n\r\nПрежде всего нужен глаз горного гронна из западного Награнда, что возле проклятых кузниц Пылающего Легиона, к югу от холма Боевого Молота.\r\n\r\nТакже понадобятся большие ветрухи, которые можно найти на западе Награнда. Подойдут только безупречные особи!\r\n\r\nНаконец, нужен жир старого копытня, обитающего на западе и юго-западе Награнда.\r\n\r\nСобери эти ингредиенты и принеси их мне! Торопись!\r\n\r\n-Нитрин' FROM `page_text` WHERE `ID`=2983 AND MD5(`Text`)='48c18c941942edf5af97a2affe7a25d3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2983 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2984, 'ruRU', '*В конце невообразимо скучной книги, в которой изложена всякая ученая бессмыслица, на последней странице написано неразборчивым почерком…*\r\n\r\nПростите, шеф. Судя по всему, от Пустоверти скоро ничего не останется. Возможно, взрыв поглотит и все остальное Запределье.\r\n\r\nЯ не уверен на все сто, но, по-моему, во всем виноваты эти эльфы крови с их темными делишками в Манагорнах.\r\n\r\nХорошо, что вы строите эту ракету!\r\n\r\n-- Медноклеппер\r\n\r\np.s. – а в ракете случайно не найдется места для меня? Вам наверняка понадобится хороший пустолог во время путешествия по Круговерти Пустоты!' FROM `page_text` WHERE `ID`=2984 AND MD5(`Text`)='4658bc5814c4c7ed92fd7c88438fe297' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2984 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2985, 'ruRU', 'Генерал!$B$BМы держим оборону у Ступеней Судьбы, но Легион не жалеет на нас своих солдат. Наверное, у них где-то поблизости расположена военная база, которую еще не обнаружили наши разведчики. Боюсь, Легион прорвет нашу оборону – даже несмотря на то, что на нашей стороне войска Альянса. Пошлите нам на помощь всех, кого сможете, иначе врата будут потеряны и мы останемся в этом кошмарном мире навсегда.$B$BЛейтенант-генерал Орион' FROM `page_text` WHERE `ID`=2985 AND MD5(`Text`)='2df99564ac0c90428adc35b6c4256503' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2985 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2986, 'ruRU', 'Нани медленно подошла к седому воину, и он бросил на нее холодный взгляд. "Ты, наверное, хочешь награду за то, что убила этих мурлоков?"\r\n\r\nВзгляд Нани остановился на его светящемся мече: "Все зависит от того, что это за награда, Марк". Она игриво провела рукой по волосам, делая вид, что не заметила, как он начал нервничать в ее присутствии: "Мне она может не понравиться".' FROM `page_text` WHERE `ID`=2986 AND MD5(`Text`)='9781ef160f67ba8f8aaab761f3c772b8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2986 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2987, 'ruRU', 'Марк сделал шаг ей навстречу; он был зол, но, в то же время, боялся ее. "Награда не подлежит обсуждению!" На мгновение он остановился, а потом резко прижал ее маленькое тело к своему. Их губы встретились в пламенном поцелуе, который в одно мгновение растопил ее ледяную броню.\r\n\r\n"Так у этого приключения все-таки будет продолжение?" – ехидно спросила она; ее глаза весело блестели.\r\n\r\n<Это продолжается несколько сотен страниц без каких-либо поворотов сюжета.>' FROM `page_text` WHERE `ID`=2987 AND MD5(`Text`)='d4ecb7e6d48991d9c3098154afd9bdbd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2987 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2989, 'ruRU', 'Командир,\r\n\r\nКод нужно доставить Зулухеду. Он будет охранять его до дальнейших распоряжений.\r\n\r\n-Владыка Иллидан Ярость Бури' FROM `page_text` WHERE `ID`=2989 AND MD5(`Text`)='5c9d950f57202780ef382c425bca3633' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2989 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2992, 'ruRU', '<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Текст на талассийском...</P>\r\n<BR/>\r\n<P>Анар\'ала, анар\'ала белоре,</P>\r\n<P>Син\'дорай,</P>\r\n<P>Шинду фалла на.</P>\r\n<P>Син\'дорай,</P>\r\n<P>Анар\'ала,</P>\r\n<P>Шинду син\'дорай,</P>\r\n<P>Шинду фалла на.</P>\r\n<P>Син\'дорай,</P>\r\n<P>Анар\'ала белоре.</P>\r\n<P>Шинду син\'дорай,</P>\r\n<P>Шинду фалла на.</P>\r\n<P>Син\'дорай,</P>\r\n<P>Анар\'ала белоре,</P>\r\n<P>Белоре.</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=2992 AND MD5(`Text`)='1fe21e83620b1bbfd3afbca7d7346434' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2992 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2993, 'ruRU', 'Дорогая советница,\r\n\r\nПривлечь великанов долины Призрачной Луны на нашу сторону – ваша задача. Я не сомневаюсь, что вы с ней справитесь. Используйте ваше эльфийское обаяние, пусть они посмотрят на мир с нашей точки зрения. Если это не сработает, истребите их всех до одного…\r\n\r\n-Владыка Иллидан Ярость Бури' FROM `page_text` WHERE `ID`=2993 AND MD5(`Text`)='6a55de1dae6f4a2072be123d14347816' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2993 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2994, 'ruRU', 'Паладины всегда должны отражать Свет, который дает нам силу. Стремиться быть святыми для нас не значит стремиться быть богами. Наша цель – совершать добрые поступки всегда и везде' FROM `page_text` WHERE `ID`=2994 AND MD5(`Text`)='5a2b2dad5752e8b3af5198b5ca68a0f4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2994 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2995, 'ruRU', 'Хотя в эти трудные времена тебе приходится сражаться с врагами, помни, что отличает тебя от всех остальных жителей этого мира. Ты помогаешь другим. Сострадание, терпение и храбрость для паладина так же важны в бою, как и сила.$B$BЗапомни это и никогда не забывай.' FROM `page_text` WHERE `ID`=2995 AND MD5(`Text`)='d5d8c4369d2af6bb466b8ec39a1dc60a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2995 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2997, 'ruRU', 'Приветствую тебя, мой ученый коллега Антонивич!\r\n\r\nНадеюсь, это письмо дойдет до тебя в Траллмар. Условия здесь, на Хребтоломе, вполне удовлетворительные для проведения моих экспериментов, хотя иногда мне все-таки хочется обратно в Подгород, где у меня было все необходимое оборудование и слуги…\r\n\r\nЭх, все это – жалобы трупа.\r\n\r\nНо отложим любезности в сторону. У меня интересные новости: в крови орков Скверны, которую $gдобыл:добыла; $N, обнаружилась высокая концентрация демонической инфекции. Она практически идентична инфекции первых орков Скверны на Азероте… инфекции Маннорота.' FROM `page_text` WHERE `ID`=2997 AND MD5(`Text`)='de2aa54c528dfe6cbcacce13e8471428' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2997 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 2998, 'ruRU', '$N!\r\n\r\nКод Проклятия – очень мощное заклинание. Оно стало причиной многих трагедий в истории наших миров. Да, оно известно не только на Дреноре…$B$BПылающий символ, который ты $gвидел:видела;, – это знак Кель\'таса. Он знает древние слова, это многое объясняет.$B$BТвое открытие взбудоражило наару. А\'дал хочет, чтобы ты $gприбыл:прибыла; в Шаттрат. Если ты согласишься, найди меня на террасе Света.\r\n\r\nТвой покорный слуга,\r\n\r\nКадгар' FROM `page_text` WHERE `ID`=2998 AND MD5(`Text`)='22089ea28ad1d9e51b213d5c6243784d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=2998 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3000, 'ruRU', 'Судьба обитателей Цитадели Адского Пламени изменилась, и я это чувствую. Как говорится, время покажет.\r\n\r\nВы, эмигранты из Азерота, из этого жуткого места, вечно покрытого зеленью, где для таких, как я, слишком много света и жизни, предстанете перед лицом демона. И вы поймете, что ужасы цитадели всего лишь – простите такую метафору – верхушка айсберга.\r\n\r\nВпереди нас ждут славные битвы! Жаль, что я не смогу быть там и чувствовать всю эту боль и страх!\r\n\r\nНу ладно, довольно скучных речей; подумай над моими словами, дорогой аптекарь: твое тело уже умерло, но душа осталась невредима, и я завладею ей и буду наслаждаться ее сладким вкусом, как только твоя оборона падет… и я найду способ поработить тебя!\r\n\r\nЕсли нужно, я буду ждать до четвертого судного дня, но ты будешь моим!\r\n\r\nВсего наилучшего,\r\n-Д' FROM `page_text` WHERE `ID`=3000 AND MD5(`Text`)='8e75f671972dff19e07b2d6a6bb67e06' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3000 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3001, 'ruRU', 'Большая часть этой страницы сгорела, и слов разобрать невозможно.' FROM `page_text` WHERE `ID`=3001 AND MD5(`Text`)='03ff3aef133e85509ef6a6e9558677ab' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3001 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3002, 'ruRU', 'После твоего ухода мне удалось продолжить изучение Книги Ворона и найти кое-какие сведения, которые могут помочь тебе победить бога-ворона.\r\n\r\nТы <освободил/освободила> духов, и теперь они связаны с тобой, так что они наверняка помогут тебе в битве с богом.\r\n\r\nКогда ты выпустишь духов в первый раз, они мало чем смогут тебе помочь, ведь они не один век находились в заточении. Восстановить их силы можно с помощью заклинаний постепенного лечения: это вернет их к жизни, и ты сможешь рассчитывать на их помощь. Но когда магия ослабеет, они вновь погрузятся в сон.\r\n\r\nДалее следуют мои заметки о каждом из духов птиц:' FROM `page_text` WHERE `ID`=3002 AND MD5(`Text`)='fbb475e605802e32916cec19f2ecd4fb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3002 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3003, 'ruRU', 'Дух сокола\r\n\r\nДух сокола обладает невероятной скоростью и ловкостью, его высоко ценят араккоа за отличные охотничьи навыки. Если ты пробудишь этого духа заклинанием постепенного лечения, он повысит твою скорость в ближнем бою и во время применения заклинаний.' FROM `page_text` WHERE `ID`=3003 AND MD5(`Text`)='a8c32d1286577cc7ed581b5b0e652a48' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3003 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3004, 'ruRU', 'Дух орла\r\n\r\nПо традиции араккоа дух орла считается более медленным, чем его брат-сокол, но по охотничьим навыкам превосходит его. Если ты пробудишь этого духа заклинанием постепенного лечения, он будет сражаться на твоей стороне.' FROM `page_text` WHERE `ID`=3004 AND MD5(`Text`)='e22f3b2dcc926b2d144ed555273248b9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3004 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3005, 'ruRU', 'Дух ястреба\r\n\r\nВ книге очень благосклонно отзываются о ястребе; возможно, он когда-то был в союзе с вороном. Дух сокола – древний символ мести араккоа, поэтому его часто призывали те, кто пострадал от рук злодеев. Если ты пробудишь духа ястреба заклинанием постепенного лечения, он даст тебе свои силы, и враги сами будут получать урон, нападая на тебя.' FROM `page_text` WHERE `ID`=3005 AND MD5(`Text`)='1f00b5b72b01a3ede73a45cc95fd7b62' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3005 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3007, 'ruRU', 'Не отчаивайся. Твой огр где-то поблизости.' FROM `page_text` WHERE `ID`=3007 AND MD5(`Text`)='20d24d777792fa36deb0fdc449f67345' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3007 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3008, 'ruRU', 'Опустите меч, булаву и копье. Кристаллы велели нам решить дело миром.' FROM `page_text` WHERE `ID`=3008 AND MD5(`Text`)='60ce5b22e2de80ce8c9c2176725233d2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3008 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3009, 'ruRU', 'Выпьешь пива – и все нипочем!' FROM `page_text` WHERE `ID`=3009 AND MD5(`Text`)='c946942902b2b804ca9aaaed342f53b2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3009 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3010, 'ruRU', 'Две головы лучше, чем одна! Потому что у тебя всегда есть рядом друг.' FROM `page_text` WHERE `ID`=3010 AND MD5(`Text`)='5bbf30e7204d7adda98ee91227fbc7c6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3010 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3011, 'ruRU', 'Мудрость имеет много обличий, но исходит она всегда от кристаллов.' FROM `page_text` WHERE `ID`=3011 AND MD5(`Text`)='d81016df3a101f1138dcbad3742f9100' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3011 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3012, 'ruRU', 'Будь оптимистичнее! При должном воображении жирное брюхо может превратиться в милое пузико.' FROM `page_text` WHERE `ID`=3012 AND MD5(`Text`)='8d79a3407c10a2288775c7570969ed0b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3012 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3014, 'ruRU', 'Счастливые числа: 13 9 17 4 n' FROM `page_text` WHERE `ID`=3014 AND MD5(`Text`)='091b6ffb03ede7b6fe26bbfffd6da00a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3014 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3015, 'ruRU', 'Твоя любовь к танцам многих веселит.' FROM `page_text` WHERE `ID`=3015 AND MD5(`Text`)='5dcc2e96fad6f596f65ffdc7c7f4edae' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3015 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3016, 'ruRU', 'Ты $gособенный:особенная;, и неважно, что говорят тебе друзья, родственники, товарищи, незнакомцы или твоя совесть.' FROM `page_text` WHERE `ID`=3016 AND MD5(`Text`)='f6574698c30f1459e20c97d10265f6b4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3016 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3017, 'ruRU', 'Если другого выхода нет, надо линять.' FROM `page_text` WHERE `ID`=3017 AND MD5(`Text`)='7c944fdd06bb9d41a5543bc46d574a4a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3017 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3019, 'ruRU', 'Внимание: эти потроха не предназначены для употребления в пищу людьми.' FROM `page_text` WHERE `ID`=3019 AND MD5(`Text`)='b3e33ab2675c9a05805a4064eb76937f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3019 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3020, 'ruRU', 'Ты <был/была> <избран/избрана> великой металлической небесной рукой! Теперь отправляйся работать.' FROM `page_text` WHERE `ID`=3020 AND MD5(`Text`)='02a67fe0e575fa4ef57639906cfd951a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3020 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3021, 'ruRU', 'Не буди спящего гронна.' FROM `page_text` WHERE `ID`=3021 AND MD5(`Text`)='83e8af2c0a48fc7c15de6550dd8e1c74' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3021 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3022, 'ruRU', 'Это послание доставлено вам Эксплуатационным комитетом Огри\'лы. Сделано в Прибамбасске.' FROM `page_text` WHERE `ID`=3022 AND MD5(`Text`)='78293605780b28ed005a62e6966dd7c0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3022 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3023, 'ruRU', 'Смысл жизни в том, что… (остальная часть письма случайно съедена)' FROM `page_text` WHERE `ID`=3023 AND MD5(`Text`)='633ba57ce8d99f5c1b80e1edffc9f083' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3023 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3024, 'ruRU', 'Извините, но в этот раз вы проиграли. Попробуйте еще раз.' FROM `page_text` WHERE `ID`=3024 AND MD5(`Text`)='12de1565707fc3bfe51458f01e9d0db5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3024 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3025, 'ruRU', 'Сегодня у тебя появится враг, и ты сразу же его убьешь.' FROM `page_text` WHERE `ID`=3025 AND MD5(`Text`)='31a669d39555aa3d39d8410bfce3203f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3025 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3027, 'ruRU', 'Ищи в жизни возвышенный путь. Так ты избежишь встречи с отбросами общества.' FROM `page_text` WHERE `ID`=3027 AND MD5(`Text`)='616161f6206c4d80f63fcf4eefac1e78' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3027 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3028, 'ruRU', 'Во имя нашего великого владыки… Во славу Иллидана!\r\n\r\nДетали, необходимые для пушки души, можно найти в разных местах. За слитками оскверненной стали, кориевым сердечников и адамантитой рамкой обратись к горнякам и инженерам.\r\n\r\nЗа безупречной чародейской сущностью придется отправиться в лес Тероккар. В центре этого леса, над ордынским Фортом Камнеломов, ты найдешь дом Сар\'тиса, араккоа-еретика. Это место известно под названием озеро Йорун.\r\n\r\nПоговори с Сар\'тисом и скажи ему, что ты ищешь. Не забудь упомянуть, что тебя прислал я, потому что за ним есть должок, и не один.\r\n\r\nСделай так, как скажет Сар\'тис, и получишь сущность.\r\n\r\n-Балтаз' FROM `page_text` WHERE `ID`=3028 AND MD5(`Text`)='efdde311b482df9e5035f09318bf85b0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3028 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3029, 'ruRU', 'Когда мне последний раз доводилось бывать в чертогах, король воронов Айкисс носил перо Терокка как знак своей власти. Наверное, это перо до сих пор у него, ведь для его последователей это доказательство того, что он перерожденный Терокк.$B$BМаска Терокка была на лице моего брата Темнопряда Сита, когда он проводил сетеккские ритуалы.$B$BЧто касается Саги о Терокке, она хранится в огромном чертоге рядом с обиталищем короля Айкисса, окруженная кольцом рун.' FROM `page_text` WHERE `ID`=3029 AND MD5(`Text`)='c0ed8f67fa92c635d41a5832f53ac4c0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3029 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3030, 'ruRU', 'Не может быть, чтобы влияние Маннорота дошло до Запределья, ведь этот монстр мертв уже много лет. Боюсь, у нас появился новый демон, по силе не уступающий Маннороту… И он может привлечь местных орков на свою сторону.\r\n\r\nЯ продолжу изучать кровь орков Кровавой Глазницы, но прошу тебя как можно быстрее начать поиски. Хотя, боюсь, они могут завести тебя в Цитадель Адского Пламени.\r\n\r\nТвой ученый друг,\r\nАптекарь Албрек' FROM `page_text` WHERE `ID`=3030 AND MD5(`Text`)='ee0e70f0d3e5ec39cf86db643545f43b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3030 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3031, 'ruRU', 'Слушай сюда, Бадд!\r\n\r\nЭто последний болван, которого я тебе посылаю; надо еще – плати! \r\n\r\nБольше никаких отмазок! \r\n\r\nГрифта' FROM `page_text` WHERE `ID`=3031 AND MD5(`Text`)='0de037c42e50256ee7f4beccaa90c2e3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3031 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3033, 'ruRU', 'Старейшина, я послал тебе на помощь большое войско, но ты должен соблюдать осторожность. Твоя первостепенная задача – не дать этим мерзавцам из Альянса продвинуться вглубь наших земель. Некоторые особо безрассудные люди уже начали строить большое здание на границе Степи.\r\n\r\nДай им понять, что за пределами их проклятого Терамора им не рады. И напоследок предупреждаю тебя, старейшина: не позволяй ограм из Гиблотопи узнать о твоих планах. У этих животных нет ни капли благоразумия.\r\n\r\n- Агашем' FROM `page_text` WHERE `ID`=3033 AND MD5(`Text`)='e44905b7cbfee756d1ed796511154994' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3033 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3037, 'ruRU', 'Дети: Джоэль и Джина. Жена: Сюзанна.' FROM `page_text` WHERE `ID`=3037 AND MD5(`Text`)='1f9c637b9624ce8d4fce3cb9fd9e0c87' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3037 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3039, 'ruRU', 'Не надо рыдать у могилы моей, \r\nЗнай: меня нет давно уже в ней.\r\n\r\nЯ – ветер, летящий над морем и сушей, \r\nСнегами Нордскола, лесной темной гущей.\r\n\r\nЯ – капли дождя на зеленых ветвях, \r\nПросторных лугах и полях.\r\n\r\nЯ – ласковый шепот вечерней зари, \r\nЧто в джунглях далеких, как пламя, горит.\r\n\r\nЯ – бой барабана, я – звон курантов,\r\nЯ – топот копыт на просторах Награнда.\r\n\r\nЯ – звезды, светящие в каждый дом,\r\nКогда в Дарнассе все спят крепким сном.\r\n\r\nЯ – звонкое пение птиц на заре,\r\nЯ – все чудеса, что есть на земле.\r\n\r\nНе надо рыдать у могилы моей, \r\nНе умер я, нет. Я живых всех живей!' FROM `page_text` WHERE `ID`=3039 AND MD5(`Text`)='913311b1381a1e05b060a0fc83aac08f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3039 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3040, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<P>Итак, $N, вот список вещей, необходимых мне для создания нашего нового суперсекретного... эээ... супероружия. Для начала назовем его "ультрасовременный прототип укорачивающего излучателя Умейки".</P>\n<BR/>\n<P>Поверь, по сравнению с этим изобретением наш старый-добрый увеличитель будет казаться детской игрушкой!</P>\n<BR/>\n<P>Впрочем, не стоит сейчас мечтать о славе. Просто добудь мне все необходимое – и мы с тобой будем купаться в золоте!</P>\n</BODY>\n</HTML>' FROM `page_text` WHERE `ID`=3040 AND MD5(`Text`)='7f617f6a15a09c0b83fec0ae11d51082' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3040 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3041, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Инструменты</H1>\n<BR/>\n<P>Итак, для начала тебе придется найти мои инструменты. Никакими другими орудиями не выполнить столь тонкую работу!</P>\n<BR/>\n<P>Я тебе не рассказывала, как мне пришлось спасаться бегством с насосной станции? Там-то я и оставила мои чудесные инструменты... Нет, ну ты же понимаешь, речь шла о моей жизни! Помню только, что в последний момент я успела спрятать их под восточным насосом.</P>\n</BODY>\n</HTML>' FROM `page_text` WHERE `ID`=3041 AND MD5(`Text`)='4b4f8960aa00d14f222eb63e97379ee0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3041 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3042, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Перегруженный конденсатор</H1>\n<BR/>\n<P>Эту штуковину может смонстрячить любой инженер, способный держать в руках отвертку. Да я бы сама ее сделала, были бы у меня инструменты. Но у меня их нет, как ты помнишь; смотри пункт первый.</P>\n<BR/>\n<P>Так что умри, но достань мне перегруженный конденсатор. Мы без него как без рук! Если уж совсем не будет иного выхода – возвращайся на южные земли и купи его на аукционе. </P>\n</BODY>\n</HTML>' FROM `page_text` WHERE `ID`=3042 AND MD5(`Text`)='bbd11ec07a8145084e13f074a750c3db' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3042 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3043, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<H1 align="center">Горсть песка Рокнара</H1>\n<BR/>\n<P>Последний компонент будет нелегко достать, но ты же понимаешь – линзы бластера нужно полировать только самым лучшим песком. А стрясти его можно только с первоклассного элементаля. </P>\n<BR/>\n<P>Пожалуй, Рокнар сгодится для этой цели. В последний раз его видели на юго-востоке, возле Студеного Предела, где он бродил между Уну\'пе и Стонущим Зиккуратом. Проделай дырку в его ледяной броне и доберись до каменистого сердца, в котором найдется для нас пригоршня песка.</P>\n</BODY>\n</HTML>' FROM `page_text` WHERE `ID`=3043 AND MD5(`Text`)='c60a5abe497411afab36991e6cb47a54' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3043 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3044, 'ruRU', 'Первая вахта, седьмая склянка\r\nСедрик снова рылся в шкафу для рома. Наказан.' FROM `page_text` WHERE `ID`=3044 AND MD5(`Text`)='c16e10d528bd3102b7c42c7a3323a671' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3044 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3045, 'ruRU', 'Первая вахта, восьмая склянка\r\nСмена вахты. Все спокойно.' FROM `page_text` WHERE `ID`=3045 AND MD5(`Text`)='23810185494081171e9f4a0833246bb1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3045 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3046, 'ruRU', 'Ночная вахта, первая склянка\r\nСедрика заметили пытающимся открыть винный шкаф капитана. Наказан.' FROM `page_text` WHERE `ID`=3046 AND MD5(`Text`)='9ddd36d182ece11d7bae4fa232f9122d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3046 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3047, 'ruRU', 'Ночная вахта, вторая склянка\r\nСедрик полез на мачту, запутался и упал. Потребовалась помощь хирурга. Отпустили, чтобы протрезвел.' FROM `page_text` WHERE `ID`=3047 AND MD5(`Text`)='0bff1234d6dadb61f695f66408d0fd85' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3047 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3049, 'ruRU', 'Ночная вахта, пятая склянка\r\nНашли одежду Седрика. Самого Седрика нашли отдельно. Седрик наказан.' FROM `page_text` WHERE `ID`=3049 AND MD5(`Text`)='72d0d3909cabb8820f4324b3bb8a7375' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3049 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3050, 'ruRU', 'Ночная вахта, шестая склянка\r\nСедрик громко поет. Разбудил капитана. Капитан наказал Седрика.' FROM `page_text` WHERE `ID`=3050 AND MD5(`Text`)='37cfebcf1a07b251fb85b0b5de015ba1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3050 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3051, 'ruRU', 'Первая вахта, восьмая склянка\r\nСмена вахты. Все тихо. Двоих послали искать Седрика.' FROM `page_text` WHERE `ID`=3051 AND MD5(`Text`)='ff273bd049863de1f98c0191169126e1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3051 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3052, 'ruRU', 'Утренняя вахта, первая склянка\r\nПожар в каюте капитана. Все подняты по тревоге. Выбрасываем порох за борт.' FROM `page_text` WHERE `ID`=3052 AND MD5(`Text`)='0bc467fa9f2a2bbe4170c2e014f3242f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3052 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3053, 'ruRU', 'Утренняя вахта, первая склянка\r\nПожар в каюте капитана. Все подняты по тревоге. Выбрасываем порох за борт.' FROM `page_text` WHERE `ID`=3053 AND MD5(`Text`)='444c1dcf3812a62840997775e2065e92' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3053 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3057, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">Разыскивается: Хеминг Эрнестуэй</H1>\r\n<H1 align="center">ЗА ПРЕСТУПЛЕНИЯ ПРОТИВ ПРИРОДЫ!</H1>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\obj_nesingwary_256" align="center"/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<H1 align="center">Фоторобот Уничтожителя в естественной среде обитания: среди адского пламени подземного мира.</H1>\r\n<BR/>\r\n<H1 align="left">Последнее известное местонахождение: Награнд, Запределье</H1>\r\n<BR/>\r\n<H1 align="left">Также известен как: Участник Великой Охоты, Мясник Бесплодных земель, Потрошитель Тернистой долины, Убийца стариков, Хеминг, Эрни, Дуцл, Дядька-добытчик, Уничтожитель.</H1>\r\n<BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=3057 AND MD5(`Text`)='a313429ee41fd6d7880e4b226069a57f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3057 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3065, 'ruRU', 'Верные слуги повелителей элементалей, НАШЕ ВРЕМЯ ПРИШЛО.\r\n\r\nСлишком долго таились мы в тенях, выжидали, прислуживали нашим хозяевам, дожидаясь неизбежного. Теперь, когда в ночи запылало жертвенное пламя Рагнароса, мы в силах начать войну и низвергнуть мир в пучину хаоса!\r\n\r\nПовелитель Огня заточен в нашем мире, он лишен своей подлинной силы, но все равно могуч. Если сыщется ему достойный противник, то начнется великая война элементалей, которая приведет к долгожданному концу света.' FROM `page_text` WHERE `ID`=3065 AND MD5(`Text`)='7c6b1ba1c4b42c31883e102dc1e2884c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3065 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3066, 'ruRU', 'Нептулону служит великий Повелитель Холода по имени Ахун. Он собирается с силами, чтобы начать войну против Рагнароса. Ему осталось лишь найти врата в наш мир; мы с радостью ему поможем. У нас есть союзники. Мы выбрали поле боя. У нас в достатке могущества и силы воли.\r\n\r\nМы проведем последние переговоры с нашими новыми союзниками и гостями в тихом, укромном местечке, в Ясеневом лесу.\r\n\r\nНе успеют жалкие смертные напраздноваться вдоволь, как Ахун сразится с Рагнаросом под сенью Черной горы. Когда сойдутся эти силы, весь мир содрогнется.' FROM `page_text` WHERE `ID`=3066 AND MD5(`Text`)='5fd71c8d9ccaafce996d707fb7d55de6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3066 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3072, 'ruRU', 'Мы долго ждали этого момента. Наши повелители выступят друг против друга, и эта славная битва раздерет Азерот на части.\r\n\r\nМы дождались конца времен, братья. Не опускайте оружия. Боритесь до конца. Победа будет за нами!' FROM `page_text` WHERE `ID`=3072 AND MD5(`Text`)='5b0455adbc7bbeacde50fca39fc38676' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3072 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3073, 'ruRU', 'Моя Королева!\r\n\r\nМы обнаружили, что синие драконы более не блокируют пересечение силовых линий в Садах Лунного Покоя. Они пытались разрушить замковый камень с помощью волноловов, но вместо того, чтобы отвести энергию назад, в нексус, они воспользовались ей, чтобы сбежать назад, в Лазуритовое святилище драконов, заключив в земле остатки силы.\r\n\r\nПолагаю, вы понимаете, какое ужасное воздействие оказали пучки магической энергии, пронзившие почву. Пострадали древние обитатели лесов, Калу\'аки и прочие существа, обитающие в этих краях. К счастью для нас, $gстоящий перед вами:стоящая перед вами:r; |3-6($r) по имени $n, уже $gразобрался:разобралась; с источником этих бед.\r\n\r\nПо моему скромному мнению, $N может пригодится Храму Драконьего Покоя в решении проблем, с которыми мы сейчас столкнулись. Нижайше прошу рассмотреть $gего:ее; кандидатуру в качестве нашего союзника.\r\n\r\nС глубочайшим уважением,\r\n\r\nМодера\r\nВерховный маг и член Шести' FROM `page_text` WHERE `ID`=3073 AND MD5(`Text`)='20cafeddc995f47bb3725bc8a594183d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3073 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3074, 'ruRU', 'Моя Королева!\r\n\r\nМы обнаружили, что синие драконы более не блокируют пересечение силовых линий в Садах Лунного Покоя. Они пытались разрушить замковый камень с помощью волноловов, но вместо того, чтобы отвести энергию назад, в нексус, они воспользовались ей, чтобы сбежать назад, в Лазуритовое святилище драконов, заключив в земле остатки силы.\r\n\r\nПолагаю, вы понимаете, какое ужасное воздействие оказали пучки магической энергии, пронзившие землю. Пострадали древние обитатели лесов, Калу\'аки и прочие существа, обитающие в этих краях. К счастью для нас, $gстоящий перед вами:стоящая перед вами:r; |3-6($r) по имени $n, уже $gразобрался:разобралась; с источником этих бед.\r\n\r\nПо моему скромному мнению, $N может пригодится Храму Драконьего Покоя в решении проблем, с которыми мы сейчас столкнулись. Нижайше прошу рассмотреть $gего:ее; кандидатуру в качестве нашего союзника.\r\n\r\nС глубочайшим уважением,\r\n\r\nЭтас Похититель Солнца\r\nВерховный маг и член Шести' FROM `page_text` WHERE `ID`=3074 AND MD5(`Text`)='fc24ccf0110f6a2f59701ebe0ce5f345' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3074 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3075, 'ruRU', 'Привет!\r\n\r\nЯ не очень хорошо умею писать, поэтому пришлось просить о помощи попечительницу. Я просто хочу ПОБЛАГОДАРИТЬ тебя, потому что ты $gнастоящий герой:настоящая героиня;. Когда я вырасту, я тоже буду спасать людей!\r\n\r\nЛадно, побегу играть. Еще раз СПАСИБО ОГРОМНОЕ за то, что ты $gтакой сильный и хороший:такая сильная и хорошая;, да еще и $gкрасивый:красивая;!\r\n\r\n--$GТайная почитательница:Тайный почитатель;.' FROM `page_text` WHERE `ID`=3075 AND MD5(`Text`)='3129308f2e10baf4d7b39d6b9cac8301' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3075 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3077, 'ruRU', 'А\'туза ползла по широкому подземному туннелю, стараясь производить как можно меньше шума и оборачиваясь на каждый звук, доносившийся из-за спины. "Где же он..." – раздраженно пробормотала она, и тут же резко остановилась, почувствовав какое-то движение за спиной. Ее глаза настороженно сузились, и в воздухе повис звон стали, извлеченной из ножен. \r\n\r\n"Я-то думал, что разбойники предпочитают подкрадываться сзади к своей жертве," – раздался хриплый голос, эхом откликнувшийся от стен пустой пещеры. Она молниеносно развернулась, и ее меч яростно обрушился на окованный железом щит. "Я думала, что паладинам полагается быть смиренными," – парировала она с самоуверенной ухмылкой на устах.' FROM `page_text` WHERE `ID`=3077 AND MD5(`Text`)='884b755a300a6c66dd6555845b86b82b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3077 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3078, 'ruRU', 'Наклонившись вперед, А\'туза громко начала считать вслух, пока невидимый кокон не лопнул с характерным звуком. "Двенадцать секунд? По-моему, ты способен на большее," – съязвила она. \r\n\r\nТонкие, костлявые пальцы умело проникли под его броню, расстегивая кирасу и обнажая грудь. "Не бойся, милый Маркус, это еще только начало. Я всего лишь разогреваюсь..." Он обвил руками то, что осталось от ее талии и провел пальцем по позвонкам, вызвав нервный смешок...\r\n\r\n<Остаток книги зачитан настолько, что текст практически невозможно разобрать.>' FROM `page_text` WHERE `ID`=3078 AND MD5(`Text`)='cddee3bccacea4e1ea99378a501b9ae5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3078 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3079, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">Дневник верховного генерала Аббендис</H1>\r\n<BR/>\r\n<IMG src="InterfaceFlavorImagesScarletCrusadeLogo"/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=3079 AND MD5(`Text`)='fddbd705f32b7da715ffbbd699f0df51' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3079 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3083, 'ruRU', 'Содержание\r\n\r\nГлава 1 – Смерть и вы\r\n\r\nГлава 2 – Создаем вурдалака: семь простых примеров\r\n\r\nГлава 3 – Вечный покой: выбираем гроб по размеру\r\n\r\nГлава 4 -Любовь до гроба: пятьдесят верных признаков\r\n\r\n<Похоже, эту книгу никогда не открывали>' FROM `page_text` WHERE `ID`=3083 AND MD5(`Text`)='68e06f484f4c408e9bd9cc2416e9bb6b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3083 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3092, 'ruRU', '<HTML>\r\n<BODY>\r\n<H1 align="center">Дневник верховного генерала Аббендис</H1>\r\n<BR/>\r\n<IMG src="Interface\\FlavorImages\\ScarletCrusadeLogo"/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=3092 AND MD5(`Text`)='289b38aa273bb66be1a4b4d6c232b2a6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3092 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3093, 'ruRU', '<HTML>\r\n<BODY>\r\n<P>Голос сказал мне: "Приди!" – и в тот же момент я поняла, что это был сам Великий Свет, взывающий ко мне во сне. Наконец-то! После стольких лет молитв и добрых деяний, после того, как я очистила землю от нежити, оскверняющей Азерот, после многих поражений и воскрешений я наконец-то удостоилась этой великой чести! </P>\r\n<BR/>\r\n<P>Наконец-то!</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=3093 AND MD5(`Text`)='eabad3aa1c8b8713d116419ab565843e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3093 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3094, 'ruRU', 'Я снова слышала голос. "Приди..." – воззвал ко мне Свет.\r\n\r\nЯ проснулась, дрожа до кончиков пальцев, но причиной тому был не холод моих покоев. Я должна удвоить усилия! Сегодня же скажу верховному настоятелю, что желаю возносить в два раза больше молитв. Хватит полумер!\r\n\r\nВеликий Свет возрадуется нашим добрым деяниям. Теперь я это знаю наверняка!' FROM `page_text` WHERE `ID`=3094 AND MD5(`Text`)='89c45349e11989aafd520c278b04fcee' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3094 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3095, 'ruRU', 'Это произошло снова! Теперь я уже не спала. Чуть больше минуты я внимала голосу Света, и посреди теплого летнего дня с моих губ вдруг сорвалось облачко холодного пара. Это заметил один из жрецов и пал на колени в благоговейной молитве.\r\n\r\nПравда, никто, кроме меня, не слышал священный глас. Но теперь я точно знаю, что не сошла с ума. Может быть, мне попросить Ландгрена помолиться за меня?\r\n\r\nНадо сказать Джордану и Стриту, чтобы они более тщательно подходили к набору добровольцев. Наша армия переполнена скептиками и неверующими, желающими только сражаться с нежитью. Довольно! Больше я не потерплю такого кощунства.' FROM `page_text` WHERE `ID`=3095 AND MD5(`Text`)='18eb24c6f4f9e219d8e5aa7392c405da' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3095 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3096, 'ruRU', 'Епископ и главнокомандующий приняли мое предложение – правда, у них не было выбора. Епископ Стрит особенно воодушевленно отнесся к моим словам, и все время говорил о том, что нашей армии не помешает небольшая чистка. \r\n\r\nЯ велела ему успокоиться. В мои намерения не входит уничтожение всего ордена. Однако, мне по душе идея создания элитного отряда преданных Свету солдат, которые будут выполнять его волю в Нордсколе. Боюсь, дружба с Лекрафтом очень сильно на него влияет. Впрочем, оба они еще мне пригодятся.\r\n\r\nОднако слова Стрита о новом Ордене заставили меня задуматься. Если бы мы создали новую силу, я дала бы ей другое имя, гордое, отражающее нашу великую цель, но все же связанное с прошлым орденом. Я буду молиться, чтобы на меня снизошло вдохновение.' FROM `page_text` WHERE `ID`=3096 AND MD5(`Text`)='3602936499a3ea50a2fe9cb109da047b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3096 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3097, 'ruRU', 'Я намереваюсь оставить здесь большую часть Ордена, чтобы они продолжали зачистку земель от нежити за нашей спиной. Надеюсь, что когда начатое нами дело будет завершено, они смогут отправиться по домам, к своим семьям, и жить отныне в мире и согласии.\r\n\r\nКажется, я правильно поступаю. В конце концов, только на нас держалась эта земля, склонившаяся под гнетом омерзительной Плети, и только мы могли вернуть Лордерону его былую славу. Вернуть те времена, когда нежить не ходила по нашим полям, когда еще не было Артаса и его предательства... когда еще не было Короля-лича.' FROM `page_text` WHERE `ID`=3097 AND MD5(`Text`)='e07a6b8f08f371edb8dcc5867a2bb11e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3097 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3098, 'ruRU', 'Мои люди верят, что вскоре настанет решающий день для всего Алого ордена. Епископ Стрит дал имя этому событию, назвав его в проповеди Багровым Рассветом.\r\n\r\nМне надо поразмыслить над происходящим – хотя у меня нет сомнений в том, что все идет так, как задумано. Я буду молиться, чтобы это событие обернулось во благо нашему Ордену.' FROM `page_text` WHERE `ID`=3098 AND MD5(`Text`)='a1db0cf4f6ac1290c2b2318e2bc90219' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3098 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3099, 'ruRU', 'Свет снова говорил со мной, с настойчивостью и убедительностью. Я проснулась в тревоге, боясь его подвести. Больше медлить нельзя. Мы должны выступать!\r\n\r\nКакое совпадение – признаться, я с трудом сдерживаю вздох облегчения, но именно сегодня капитан Шели предоставил нам новый флот для путешествия. Хотя, возможно, это было вовсе не совпадение? Неисповедимы пути Света, и я могу лишь надеяться, что это он руководит моими действиями.\r\n\r\nМоим флагманом будет "Глупость Грешника". По-моему, вполне подходящее название.' FROM `page_text` WHERE `ID`=3099 AND MD5(`Text`)='8c90535349b521f1f43556dc31489c4a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3099 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3100, 'ruRU', 'Теперь я знаю, почему Свет так настойчиво побуждал меня к действию. Под покровом ночи в небесах появились некрополи Плети и обрушили тысячи демонов на наши головы!\r\n\r\nЗахватчиков возглавляет новый выводок рыцарей смерти, и мы потеряли множество людей в сражении с этими тварями. Теперь, когда Плеть может нападать на нас повсюду, и даже с небес, нам будет гораздо сложнее удерживать оборону.\r\n\r\nБоюсь, наша экспедиция в Нордскол закончится, не успев начаться.' FROM `page_text` WHERE `ID`=3100 AND MD5(`Text`)='2a681b580b6b793d4c9e1a400ee37a04' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3100 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3101, 'ruRU', 'Мне сообщили, что Дольный Очаг готов оказать нам поддержку. Спасательную операцию намеревается возглавить сам главнокомандующий Галвар Чистокров, но усилия его напрасны.\r\n\r\nНадо отправить моих лучших курьеров, чтобы они прорвались за линию огня и передали мой приказ к отступлению. Дольный Очаг должен сосредоточиться на обороне, чтобы иметь возможность принять под свою защиту остатки Ордена.\r\n\r\nНадеюсь, мое послание достигнет их еще до наступления ночи.' FROM `page_text` WHERE `ID`=3101 AND MD5(`Text`)='3504cdafd0fda6bdca7367bbd1ed8ef0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3101 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3103, 'ruRU', 'День 1: Как я и рассчитывал, жалкие людишки не заметили моего присутствия. Они готовятся к бомбежке, и мне не составит труда составить карту их диспозиций. .\r\n\r\nДень 2: Карты готовы – право, для такого опытного шпиона, как я, это было слишком просто. Не понимаю, зачем такое задание поручили мне – с нам справился бы и Дж. С. Правда, у него ужасный акцент. \r\n\r\nДень 3: Первый глоток воздуха уже слегка застоялся. Пожалуй, через несколько дней мне придется снова выглянуть на поверхность. Какая тоска – сидеть здесь и ждать сигнала.\r\n\r\n< Продолжение следует... >' FROM `page_text` WHERE `ID`=3103 AND MD5(`Text`)='20d8feb8de2f494fb3674bb2f23992d0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3103 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3104, 'ruRU', 'День 12: Ах, наконец-то. Второй глоток воздуха показался мне чище детской слезы. Сигнала по-прежнему нет; к тому же, на моем большом пальце устроился какой-то наглый краб.\r\n\r\n< Записи становятся более путаными... >' FROM `page_text` WHERE `ID`=3104 AND MD5(`Text`)='e4dfc836d9a350fcb98cf5ad48cfb67a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3104 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3105, 'ruRU', 'День 36: Закончился третий глоток воздуха, и вены в моем левом локте чуть не вскипели, пока я пробивал себе дорогу вверх. Трескотня крабов не прекращается ни днем, ни ночью – омерзительное музыкальное сопровождение для моей личной преисподней. Не могу поверить, что эти мерзавцы про меня забыли! Если бы на моем месте был Дж. С., они бы не осмелились бросить его здесь. Даже Ганса и Сильвию наверняка бы вытащили отсюда! Так в чем я провинился? \r\n\r\n< Дальнейшие записи практически невозможно разобрать... >' FROM `page_text` WHERE `ID`=3105 AND MD5(`Text`)='4e328c7d3fc4e4bcf7eb61432755a0a5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3105 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3106, 'ruRU', '1. Если вас не устраивает эффективность яда, удвойте количество ингредиентов или уменьшите их наполовину. \r\n2. Если яд не работает так, как задумано, вы совершили вдвое больше ошибок, чем предполагаете.\r\n3. Опыты, опыты и еще раз опыты (из гномов получаются отличные подопытные).\r\n4. Яды должны быть просты в использовании и трудны в поиске противоядия. \r\n5. Экспериментируйте с ингредиентами в поисках неожиданных сочетаний.' FROM `page_text` WHERE `ID`=3106 AND MD5(`Text`)='fe5e2a181094f02de17f269eccd44478' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3106 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3120, 'ruRU', 'Госпожа верховный генерал,\r\n\r\nспешу сообщить вам, что войска Дольного Очага и Тирисфальских лесов находятся менее, чем в одном дне езды от Нового Авалона. Путь наш озарен Светом, и ветра дуют нам в спину. Скоро Плеть узреет истинную мощь Алого Ордена!\r\n\r\nБлагослови вас Свет,\r\n\r\n Главнокомандующий Галвар Чистокров' FROM `page_text` WHERE `ID`=3120 AND MD5(`Text`)='758f91e63babf1dea61d7775324c1d4c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3120 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3121, 'ruRU', '<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Путь искупления</H1>\r\n<BR/>\r\n<IMG src="Interface\\FlavorImages\\ScarletCrusadeLogo"/>\r\n<BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=3121 AND MD5(`Text`)='d4e143e64a9d49e6607163aeeef4155b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3121 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3122, 'ruRU', '<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Голос сказал мне: "Приди!" – и в тот же момент я поняла, что это был сам Великий Свет, взывающий ко мне во сне. Наконец-то! После стольких лет молитв и добрых деяний, после того, как я очистила землю от нежити, оскверняющей Азерот, после многих поражений и воскрешений я наконец-то удостоилась этой великой чести! </P>\r\n<BR/>\r\n<P>Свершилось!</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=3122 AND MD5(`Text`)='1543596a2a3ae0af066910a7d9d3acd9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3122 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3123, 'ruRU', 'Я снова слышала голос. "Приди..." – воззвал ко мне Свет.\r\n\r\nЯ проснулась, дрожа до кончиков пальцев, но причиной тому был не холод моих покоев. Я должна удвоить усилия! Сегодня же скажу верховному настоятелю, что желаю возносить в два раза больше молитв. Хватит полумер!\r\n\r\nВеликий Свет возрадуется нашим добрым деяниям. Теперь я это знаю наверняка!' FROM `page_text` WHERE `ID`=3123 AND MD5(`Text`)='295fa20b8c1acf6596ff7f8f840404ef' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3123 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3124, 'ruRU', 'Это произошло снова! Теперь я уже не спала. Чуть больше минуты я внимала голосу Света, и посреди теплого летнего дня с моих губ вдруг сорвалось облачко холодного пара. Это заметил один из жрецов и пал на колени в благоговейной молитве.\r\n\r\nПравда, никто, кроме меня, не слышал священный глас. Но теперь я точно знаю, что не сошла с ума. Может быть, мне попросить Ландгрена помолиться за меня?\r\n\r\nНадо сказать Джордану и Стриту, чтобы они более тщательно подходили к набору добровольцев. Наша армия переполнена скептиками и неверующими, желающими только сражаться с нежитью. Довольно! Больше я не потерплю такого кощунства.' FROM `page_text` WHERE `ID`=3124 AND MD5(`Text`)='2467e2883397f2cfeb9529303850ef87' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3124 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3126, 'ruRU', '<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Наши молитвы услышаны. Верховный настоятель был поражен силой гласа Света, его чистотой и убежденностью. </P>\r\n<BR/>\r\n<P>Лишь самые преданные воины отправятся с нами на Север и войдут в историю под именем Алого Натиска.</P>\r\n<BR/>\r\n<P>Мы начинаем наступление на Нордскол! Скверна Плети угрожает захватить власть над миром и погубить все живое. Настало время дать ей отпор! Скоро мы будем стоять у подножия трона самого Короля-лича! </P>\r\n<BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=3126 AND MD5(`Text`)='244ca4d9e70d135a4c204190b313a5e2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3126 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3129, 'ruRU', '<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>С трепетом взираю я на Новый Авалон, ибо мне кажется, что вижу его в последний раз. Наша судьба решится в Нордсколе, но меня обуревает гнетущее чувство неминуемой беды. Я надеюсь, что наши грядущие деяния очистят мою душу от смятений. Я должна выбросить сомнения прочь из головы.</P>\r\n<BR/>\r\n<P>Нас ждет Багровый Рассвет.</P>\r\n<BR/>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=3129 AND MD5(`Text`)='f7c324060721dfa70b6e7f5fbd8386e1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3129 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3143, 'ruRU', 'К утру от моих курьеров не поступило ни единого донесения. Очевидно, никто из них не добрался до Дольного Очага. Чумные земли потеряны для нас. Скоро сюда прибудет Чистокров, но его войска будут разбиты еще на подходе.\r\n\r\nСегодня днем мне было видение, посланное Светом. Я видела гибель всего, что мы возвели собственными руками. Теперь я знаю, что должна забрать с собой самых преданных воинов и предоставить остатки Ордена на откуп судьбе.' FROM `page_text` WHERE `ID`=3143 AND MD5(`Text`)='562d7d3c339c96afd533b4d75c5b251f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3143 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3144, 'ruRU', 'Позже Ландгрен сказал, что видел то же, что и я. Не понимаю, почему Свет побуждает нас совершить столь бесчестное деяние, но не имею права сомневаться в его повелении. Я должна повиноваться, и я повинуюсь.\r\n\r\nС трепетом взираю я на Новый Авалон, ибо мне кажется, что вижу его в последний раз. Наша судьба решится в Нордсколе, но меня обуревает гнетущее чувство неминуемой беды. Я надеюсь, что наши грядущие деяния очистят мою душу от смятений. Я должна выбросить сомнения прочь из головы.' FROM `page_text` WHERE `ID`=3144 AND MD5(`Text`)='cb2ce75da000fb541f1695c99ef52103' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3144 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3145, 'ruRU', 'Молюсь Свету, чтобы главнокомандующий Чистокров избежал страшной участи на поле боя. Я же чувствую себя предательницей. Трусливым псом, поджавшим хвост от страха.\r\n\r\nГоворят, что путешествие займет около двух месяцев – остальные корабли не столь быстроходны, как "Грешник". На них находится большая часть наших войск и экипировки, но они должны доплыть в целости и сохранности.\r\n\r\nМеня совсем не тянет к воде, но во имя Света я должна перетерпеть морскую болезнь. Просто не буду никому показываться на глаза.' FROM `page_text` WHERE `ID`=3145 AND MD5(`Text`)='3d502a21d7aa48e85cddfa643b8725fb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3145 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3146, 'ruRU', 'Я давно уже ничего не писала в дневнике – в последнее время мне с трудом удается удержаться на ногах, чтобы не почувствовать очередной приступ тошноты. Солдаты начинают волноваться за меня – ведь я практически не покидаю своей каюты. Но я не могу позволить им увидеть себя в таком плачевном состоянии.\r\n\r\nК счастью, терпеть осталось недолго. Молю Свет, чтобы наше путешествие поскорее закончилось. Мы плывем вот уже шесть недель, и с каждым днем погода становится все хуже и хуже. Надеюсь, в Нордсколе будет немного теплее – с детства ненавижу холод.\r\n\r\nИ глас Великого Света давно уже ко мне не обращался.' FROM `page_text` WHERE `ID`=3146 AND MD5(`Text`)='560d504820192103ca9b7e5af960dc29' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3146 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3147, 'ruRU', 'На нас напали без единого предупреждения! Эти великаны в грубо выточенных каноэ выплыли из тумана подобно призракам! Бесшумные, как мертвецы...\r\n\r\nМы потеряли один корабль со всей командой. Они сражались отважно и умело, учитывая, что до сих пор им не приходилось участвовать в реальных морских сражениях.\r\n\r\nВопли наших моряков, захваченных великанами, еще долго отражались от прибрежных скал. Потом все стихло. Епископ Стрит созвал команду на панихиду.' FROM `page_text` WHERE `ID`=3147 AND MD5(`Text`)='272949a8e6038987ce52e98d1c982c9b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3147 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3148, 'ruRU', 'Сегодня утром я проснулась и обнаружила себя склонившейся над морскими картами. Сам Свет водил моей рукой, прокладывая путь к цели.\r\n\r\nМы почти на месте!' FROM `page_text` WHERE `ID`=3148 AND MD5(`Text`)='3877d3378a71b06e0ee0effa09b0e451' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3148 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3149, 'ruRU', 'Наконец-то, земля!\r\n\r\nСойдя со шлюпки на берег, я установила наш флаг, и тут же услышала глас Великого Света. Он говорил моими устами. Сегодня великий день, сказал он – день Багрового Рассвета. Здесь, в этом самом месте, будет основан Новый Дольный Очаг. Отныне мы носим иное имя. Мы – Алый Натиск!\r\n\r\nТак мы начинаем наступление на Нордскол! Скверна Плети угрожает захватить власть над миром и погубить все живое. Настало время дать ей отпор. Скоро мы будем стоять у подножия трона самого Короля-лича!' FROM `page_text` WHERE `ID`=3149 AND MD5(`Text`)='0d1936eda703be77fcfb42df1daef2d7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3149 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3150, 'ruRU', 'Прошел уже месяц, и я вполне довольна темпами строительства. Ничего не писала в дневнике – было не до того. Разведчики докладывают, что в этих землях полно драконов и прочих странных зверей. Мы должны быть настороже.\r\n\r\nСегодня, во время проповеди верховный настоятель провозгласил пришествие посланника Света, который поведет нас к победе.\r\n\r\nНе знаю даже, что и думать об этом. Почему Свет не обращается больше ко мне? Неужто я чем-то прогневила небеса, и меня хотят заменить каким-то чужестранцем?' FROM `page_text` WHERE `ID`=3150 AND MD5(`Text`)='61898192260d3ddacfae0a48c5e67bfd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3150 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3151, 'ruRU', 'Сегодня меня посетил сам адмирал Бареан Вествинд! По всем сведениям он считался погибшим много лет назад.\r\n\r\nОн выглядел довольно молодо, но я все равно узнала его с первого взгляда. Адмирал рассказал мне, что остался единственным выжившим человеком из всего обреченного флота, и что он спасся только благодаря милости Света.\r\n' FROM `page_text` WHERE `ID`=3151 AND MD5(`Text`)='6cda8267dc33f8b466a5818e0b2bab15' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3151 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3152, 'ruRU', 'Мы провели за беседой всю ночь и все утро. Адмирал заверил меня, что не собирается покушаться на мой авторитет, но Свет повелел ему отправиться в Драконий Погост, чтобы стать моим советником и формальным главнокомандующим. Он утверждает, что скоро в Нордсколе произойдут великие перемены. Альянс и Орда объединятся перед лицом единой опасности – страшной чумы, которую намеревается наслать на них проклятый Король-лич.\r\n' FROM `page_text` WHERE `ID`=3152 AND MD5(`Text`)='fd8609988df3052816bde855bbc4325f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3152 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3153, 'ruRU', 'Солдаты восторженно приняли нового главнокомандующего – особенно верховный настоятель Ландгрен и епископ Стрит. Не иначе, Свет нашептал им благословения адмиралу, пока они спали. Некоторые воины приняли постриг и теперь именуют себя "жрецами-воронами".\r\n\r\nКажется, только Джордан остался в стороне от всеобщего ликования, и я вполне его понимаю. Он тоже чувствует, насколько шатко наше положение.' FROM `page_text` WHERE `ID`=3153 AND MD5(`Text`)='9506e44aa267a2993b10bba8eea11724' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3153 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3154, 'ruRU', 'Что-то не так. Я не могу понять, что именно, но я не могу полностью доверять адмиралу. Он не сделал ничего плохого. Совсем наоборот! И всё же, я должна доверять своей интуиции.\r\n\r\nЯ буду молиться о понимании. Свет послал адмирала, чтобы привести нас к победе, и не мне подвергать сомнению его решения. Я продолжу подчиняться. Я верена.' FROM `page_text` WHERE `ID`=3154 AND MD5(`Text`)='8e00ccf6dd867fb3b9378b17da6a9a2b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3154 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3155, 'ruRU', 'Прошло еще несколько месяцев. Мы достигли больших успехов в строительстве Нового Дольного Очага. Стена почти завершена, впрочем как и казармы. Люди Калейки просто чудесные работники.\r\n\r\nЯ давно не делала здесь никаких записей – не хотелось. По какой-то причине я даже этого избегала. В последнее время Свет не говорит со мной, однако адмирал уверяет, что здесь не о чем волноваться.\r\n' FROM `page_text` WHERE `ID`=3155 AND MD5(`Text`)='1bdbb0bd2b5eb4e130aabb79c7fd4fc0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3155 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3156, 'ruRU', 'Мои люди сообщают, что небольшая группа Отрекшихся разбила лагерь вдоль склона холма на севере. По другую сторону холма Альянс, по-видимому, начал строительство гораздо более крупной базы.\r\n\r\nАдмирал говорит, что нам следует оставить их в покое. На западе собрались другие силы Орды, которые наверняка придут им на помощь, если мы нападем. Мне это не нравится, но я вижу логику в его рассуждениях.' FROM `page_text` WHERE `ID`=3156 AND MD5(`Text`)='7dc33d8c422f0415b7561c4151198080' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3156 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3157, 'ruRU', 'Скор\'зад осторожно выглянул из-за колонны. Как он и ожидал, она парила в одиночестве по центру комнаты. Правильно ли он поступил, придя столь поздно ночью в покои банши? Если бы некроманты обнаружили его здесь, то закопали бы обратно под землю. Что хуже всего – он не был уверен во взаимности своих чувств, а мадам Сиднари славилась вспыльчивым нравом.' FROM `page_text` WHERE `ID`=3157 AND MD5(`Text`)='707fab64f10f895a3c60353298399049' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3157 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3158, 'ruRU', 'Но узрев свою богиню во всей красе, зомби отбросил последние сомнения. Ее тонкий профиль все еще хранил изящные, эльфийские черты как напоминание о прошлой жизни, но теперь ее лицо было испещрено струпьями и червоточинами. Багровую, почти прозрачную кожу едва прикрывали лохмотья истлевшего савана, оставляя мало простора для воображения. Ее безногое тело буквально светилось энергией, исходившей от синеватой сферы, зависшей в нескольких футах от холодного, гранитного пола. Скор\'зад заставил себя слегка расслабиться и облегченно вытер пот вперемешку со слизью, сочившейся из треснувшей кожи над бровью.' FROM `page_text` WHERE `ID`=3158 AND MD5(`Text`)='206737433214a262f154170e0a624f27' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3158 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3159, 'ruRU', 'Не заметив его присутствия, она проплыла над полом к единственному окну, открывавшему великолепный вид на поле битвы. Пред ней предстала великолепная картина смерти и разрушений. Всего шесть часов назад эти земли содрогались от криков убиенных младенцев, но сейчас над полем царила замогильная тишина.' FROM `page_text` WHERE `ID`=3159 AND MD5(`Text`)='b1e517e3e2065a41619f2d2bcf052e1c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3159 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3160, 'ruRU', 'Ветер развевал ее длинные волосы, играя змееподобными локонами, обрамляющими пустые глазницы. Скор\'зад внезапно осознал, что в порыве страсти слишком сильно высунулся из-за колонны, и в ужасе отшатнулся, боясь, что Темная Плакальщица может его увидеть. Она и впрямь почувствовала движение у себя за спиной, но ему незачем было волноваться.' FROM `page_text` WHERE `ID`=3160 AND MD5(`Text`)='f0a03bb3aed6298cfc12d151b26a28ba' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3160 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3161, 'ruRU', '"Скор\'зад!" – позвала она. – "Я ждала тебя. Сегодня ты храбро сражался." Банши бросила на него томный взгляд, позволяя трепещущим лоскуткам савана слегка сползти с гниющего плеча. "Подойди сюда. Настало время... вознаградить тебя за отвагу."' FROM `page_text` WHERE `ID`=3161 AND MD5(`Text`)='37bf8de93f061499e1c0c390e9b525b4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3161 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3162, 'ruRU', '<Похоже, следующие несколько страниц намертво склеились.>' FROM `page_text` WHERE `ID`=3162 AND MD5(`Text`)='e9f03770d3068503006ae40bbd77e14b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3162 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3163, 'ruRU', 'Тартек Бешеный. Одно из самых могущественных поганищ, когда-либо сотворенных Плетью. Был создан личом Амненнаром Хладовеем для помощи в возведении укреплений на Курганах Иглошкурых. Лично освежевал более 1200 иглошкуров прежде, чем был побежден их многочисленной армией. Его жертва позволила Амненнару быстро собрать армию из неживых иглошкуров и стать первым главнокомандующим Плети в Калимдоре. Останки Тартека были использованы для создания Обжоры, нынешнего лейтенанты Амненнара.' FROM `page_text` WHERE `ID`=3163 AND MD5(`Text`)='fb6a149326e66c680c31cb5bc6bf876e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3163 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3164, 'ruRU', 'Обрахиим Странник. Гениальный архитектор, участвовавший в создании Наксрамаса и спроектировавший Акерус. Совершил головокружительную карьеру, пройдя путь от чернорабочего до одного из самых преданных советников Кел\'Тузада.\r\n\r\nОбуреваемый жаждой знаний, Обрахиим обогнул весь мир в поисках неизведанного. Он черпал вдохновение в нерубской архитектуре и магии чернокнижников. В последний раз его видели несколько лет назад, когда он направлялся к Руинам Зин-Ажхари в Калимдоре.' FROM `page_text` WHERE `ID`=3164 AND MD5(`Text`)='f9ae72399352f7fc0c515455838fd059' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3164 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3165, 'ruRU', 'Диодор Проклятый. Человек-некромант, один из первых приверженцев культа Проклятых и герой Первой войны. Возглавил войска Плети и привел их к победе по время Первого и второго летнего штурма Монастыря Алого ордена. Был убит во время третьего штурма, успешно отраженного Алым орденом, который наконец-то смог вычислить его тактику.' FROM `page_text` WHERE `ID`=3165 AND MD5(`Text`)='0de56cd7aa114f8b11e6f36684b6dd3a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3165 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3166, 'ruRU', 'Киркессен Жаждущий. Могущественный лич, правая рука самого Короля-лича. Ветеран бесчисленных сражений, Киркессен лично спланировал и возглавил Кровавую осаду часовни Последней Надежды. Несмотря на численное превосходство, его войска были разбиты и понесли значительные потери. Лорд Максвелл Тиросс не простил Киркессену этой ошибки и лично лишил его права на физическое обличье.' FROM `page_text` WHERE `ID`=3166 AND MD5(`Text`)='2cd9ba3a6154c1fd3749af4a09e40aed' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3166 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3169, 'ruRU', 'Разлом Смерти, Восточные королевства – На этой неделе инструктор Разувий довольно резко высказался по поводу многочисленных случаев неподчинения и нарушения субординации в войсках. Цитирую, "Любой рыцарь смерти, осмелившийся предать Плеть, будет обречен на вечные страдания, по сравнению с которыми смерть покажется недостижимым блаженством. Я лично прослежу за этим."' FROM `page_text` WHERE `ID`=3169 AND MD5(`Text`)='a686370e8ccb4d6872a58507c259946c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3169 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3173, 'ruRU', 'Подгород – Наши источники в Подгороде докладывают, что Орда готовится выступить на Нордскол. "Войска Орды, недавно вернувшиеся из Запределья, готовятся нанести удар по Ледяной Короне," – сообщают наши агенты.' FROM `page_text` WHERE `ID`=3173 AND MD5(`Text`)='f75d046a9a4b1ecc54d36602c47597e7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3173 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3174, 'ruRU', 'Помимо этого, шпионы докладывают о необычайной активности Королевского Фармацевтического Сообщества. "Хотя у нас нет прямых доказательств, нельзя игнорировать слухи о том, что Отрекшимся удалось добиться значительных успехов в изобретении новой чумы. По тем же донесениям, всем войскам Орды приказано оказывать максимальное содействие алхимикам Сообщества."' FROM `page_text` WHERE `ID`=3174 AND MD5(`Text`)='8b4eafa4dc4e58785879cd10c7b5c373' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3174 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3175, 'ruRU', 'Рыцари смерти Акеруса\r\n\r\nИмя: Джейд\r\nСтатус: жива\r\nПримечание: крайне жестока' FROM `page_text` WHERE `ID`=3175 AND MD5(`Text`)='5b38f027e9bc236e95ca0ade835dccbe' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3175 AND x.`locale`='ruRU');
