INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3178, 'ruRU', 'Имя: Кобальт\r\nСтатус: мертв\r\nПримечание: упал с лестницы, разбился насмерть. Жаль, мог бы еще помучиться.' FROM `page_text` WHERE `ID`=3178 AND MD5(`Text`)='35950fb0aa161fbdec2f3e50ba0c454b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3178 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3179, 'ruRU', 'Имя: Гармония\r\nСтатус: мертва\r\nПримечание: имя этого рыцарь смерти упоминается в связи с нарушением правил поведения солдата Плети. Была убита лично Королем-личом.' FROM `page_text` WHERE `ID`=3179 AND MD5(`Text`)='680d158fbf2975dde0e9671418a2d1ca' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3179 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3180, 'ruRU', 'Имя: Мелт\r\nСтатус: жив*\r\nПримечание: обращен в вурдалака.' FROM `page_text` WHERE `ID`=3180 AND MD5(`Text`)='754b9ace360ff6bb1adcc8224f70e2fd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3180 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3181, 'ruRU', 'Имя: Милтон\r\nСтатус: жив\r\nПримечание: любит долгие прогулки' FROM `page_text` WHERE `ID`=3181 AND MD5(`Text`)='08d50aa241aff9693385c7ff91393ec9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3181 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3182, 'ruRU', 'Имя: Миниталис\r\nСтатус: жива\r\nПримечание: видит несуществующее.' FROM `page_text` WHERE `ID`=3182 AND MD5(`Text`)='00d7aca71fdf9c841240b4a9ffeda3d7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3182 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3183, 'ruRU', 'Имя: $N\r\nСтатус: $gжив:жива;\r\nПримечание: требует присмотра\r\n\r\n<В книге несколько сотен страниц.>' FROM `page_text` WHERE `ID`=3183 AND MD5(`Text`)='3f496697cccceeaab541cc01e52cbd73' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3183 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3184, 'ruRU', 'Рыцари смерти Акеруса\r\n\r\nИмя: Джейд\r\nСтатус: жива\r\nПримечание: неудержимая' FROM `page_text` WHERE `ID`=3184 AND MD5(`Text`)='ae9bc5f0d31e1d383426d4306bf5da26' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3184 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3185, 'ruRU', 'Имя: Сикстен\r\nСтатус: мертв\r\nПримечание: умер, пока ловил ворон.' FROM `page_text` WHERE `ID`=3185 AND MD5(`Text`)='9d5b7e66fb8b6e05cc4b00c27dd01a92' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3185 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3187, 'ruRU', 'Имя: Кобальт\r\nСтатус: мертв\r\nПримечание: упал с лестницы, разбился насмерть. Жаль, мог бы еще помучиться.' FROM `page_text` WHERE `ID`=3187 AND MD5(`Text`)='35950fb0aa161fbdec2f3e50ba0c454b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3187 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3188, 'ruRU', 'Имя: Гармония\r\nСтатус: мертва\r\nПримечание: имя этого рыцарь смерти упоминается в связи с нарушением правил поведения солдата Плети. Была убита лично Королем-личом.' FROM `page_text` WHERE `ID`=3188 AND MD5(`Text`)='5ad6559b7ff991c3bdcd58fa62c22a5c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3188 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3189, 'ruRU', 'Имя: Мелт\r\nСтатус: мертв\r\nПримечание: обращен в вурдалака. Убит крестьянином из Алого Натиска.' FROM `page_text` WHERE `ID`=3189 AND MD5(`Text`)='d18ff0c6d68399bac293550c3d08a9d8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3189 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3190, 'ruRU', 'Имя: Милтон\r\nСтатус: пропал без вести\r\nПримечание: трусливый гном.' FROM `page_text` WHERE `ID`=3190 AND MD5(`Text`)='2b337fe3ac1bb9dc63147a30ae7b518d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3190 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3191, 'ruRU', 'Имя: Миниталис\r\nСтатус: жива\r\nПримечание: любит гоняться за бабочками.' FROM `page_text` WHERE `ID`=3191 AND MD5(`Text`)='7d0ba4da5a10347539f95a3d53cd6d56' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3191 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3192, 'ruRU', 'Имя: $N\r\nСтатус: g$жив:жива;\r\nПримечание: несет отвественность за смерть сотен рыцарей Алого Натиска. Все всякого сомнения, это только начало.\r\n\r\n<В книге несколько сотен страниц.>' FROM `page_text` WHERE `ID`=3192 AND MD5(`Text`)='039222eb79e71d48e9f8ce3215e19a1e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3192 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3211, 'ruRU', 'Трупеус – хороший повар из Акеруса, готовит вкусную еду. Он гордится тем, что кормит великую Плеть. Не зли Трупеуса, а то он не даст тебе еды.\r\n\r\nПравила:\r\n\r\nРыцари смерти едят первыми, вурдалаки потом.\r\n\r\nНе ешь сразу за вурдалаком. Сначала помой за ним тарелку.\r\n\r\nМожно добавлять в пищу своих червей и личинок. Трупеус не обидится.\r\n\r\nПоймал крысу? Принеси Трупеусу!\r\n\r\nМожно есть людей и эльфов. У эльфов – диетическое мясо.' FROM `page_text` WHERE `ID`=3211 AND MD5(`Text`)='104ab7177ff607983e6bd6f01bf583d4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3211 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3212, 'ruRU', 'Перемешай еду. Если найдешь салфетку – Трупеусу будет стыдно.\r\n\r\nМожно приносить обратно недостаточно сгнившую пищу. У Трупеуса есть три свободные подмышки.\r\n\r\nМожно есть руками, можно есть с ножа. Нельзя есть руки и ножи. \r\n\r\nЗомби нужна разнообразная пища. Мозгами сыт не будешь.\r\n\r\nНе ешь сам себя.' FROM `page_text` WHERE `ID`=3212 AND MD5(`Text`)='8b1101df9ea668c6fd1aa44a92399cea' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3212 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3213, 'ruRU', 'Свидетельство воскрешения ледяного змея\r\n\r\nГигантские кости были практически полностью скрыты под толстой шапкой снегов, но их принадлежность можно было безошибочно определить по выступающим вперед черным когтям, сжатым в предсмертной агонии. Вокруг тела дракона беззвучно собирались некроманты, образовывая широкий круг. Несколько мгновений они молча стояли, словно бы прислушиваясь к завываниям ветра, вздымавшего клубы снежной пыли вокруг их неподвижных фигур. Затем Ритуал начался.' FROM `page_text` WHERE `ID`=3213 AND MD5(`Text`)='632f04e5a24bf9e8266b1c595606fad8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3213 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3214, 'ruRU', 'Всполохи нечестивого пламени срывались с заледеневших костей, вспахивая снег и обнажая громадный скелет. Наконец, повинуясь жесту верховного некролорда Антиока, кости содрогнулись и медленно воспарили над землей, собираясь в нечто единое.' FROM `page_text` WHERE `ID`=3214 AND MD5(`Text`)='75110b6f207f1ac8fbd263eb31afbea1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3214 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3215, 'ruRU', 'Голоса некромантов усилились, вплетая эфемерную ткань заклинаний в останки великого существа. По телу ледяного змея пробегали страшные судороги, словно плоть его отказывалась принимать дар порочного воскрешения. Наконец, тонкий крик хлыстом прорезал застывший воздух, и зверь покорился своей судьбе. Ледяное сияние окружало его обнаженные ребра, окутывая конечности и отражаясь в пустых глазницах зловещим отблеском тайных знаний.' FROM `page_text` WHERE `ID`=3215 AND MD5(`Text`)='c84c0dd3564f16951179565ed7076d5e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3215 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3216, 'ruRU', 'Вперед вышел верховный некролорд и обратился к змею: "Король-лич счел нужным воскресить тебя, дабы ты служил Плети. Ты станешь величественным символом ужаса, источником страданий, грозой для наших врагов, ты будешь питаться самой жизнью, и с гордостью переносить на себе наших лучших рыцарей смерти".' FROM `page_text` WHERE `ID`=3216 AND MD5(`Text`)='a5860c5f2bce61a87615938a0ab52839' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3216 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3217, 'ruRU', 'Ледяной змей внимал его словам, покорно склоняя голову. Обращение было завершено. Встав на дыбы, он распахнул крылья, и они заслонили небо подобно двум стальным веерам.' FROM `page_text` WHERE `ID`=3217 AND MD5(`Text`)='3bfaafadebb9175403804d6a37717120' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3217 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3226, 'ruRU', 'Добро пожаловать, новые солдаты Плети! Чувствуете ли вы восторг освобождения от смертных предрассудков и презренных желаний плоти? Отныне вам не надо тратить время на сон, укрывать свое тело от причуд стихий, беспокоиться о красе волос и ногтей. Не правда ли, это восхитительно?' FROM `page_text` WHERE `ID`=3226 AND MD5(`Text`)='898e933935c03d344557c394cabb8446' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3226 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3227, 'ruRU', 'Однако, в жизни нежити есть несколько незначительных деталей, на которые вам необходимо обратить внимание.\r\nВсегда следите за состоянием своей плоти. Гниющие конечности, несомненно, могут напугать противника, но рука, отвалившаяся в разгар боя, может повлиять на его исход не в вашу пользу. \r\nПривыкайте к своему запаху. Это не вонь, это аромат.\r\nИзбегайте живых существ, особенно собак.' FROM `page_text` WHERE `ID`=3227 AND MD5(`Text`)='4fae0f9e2f537ec6d9cf3df80758fe80' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3227 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3228, 'ruRU', 'Следите за речью. Если вы потеряете нижнюю челюсть, это может привести к переводу на менее почетную должность, на которой ваша косноязыкость будет не столь заметна.\r\nК сожалению, алкогольные напитки больше не будут оказывать на вас желаемого эффекта.\r\nПринимайте кровавые ванны каждый день (добавлять пену не рекомендуется). \r\nИзбегайте пастельных тонов в одежде. Они не подходят под цвет вашей кожи. \r\nЭти штаны больше не будут вас полнить.' FROM `page_text` WHERE `ID`=3228 AND MD5(`Text`)='01ff9f12471ccbf7ef6f71ead2828518' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3228 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3229, 'ruRU', 'Уход за кожей вурдалаков\r\nПособие по санобработке и утилизации отходов' FROM `page_text` WHERE `ID`=3229 AND MD5(`Text`)='17c815ba59a9f0c36ed81e7cb3bab037' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3229 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3230, 'ruRU', 'Повязки\r\n\r\nРаны, кровоточащие чаще трех раз в день, рекомендуется перевязывать. Некоторые вурдалаки предпочитают для этой цели руническую ткань благодаря ее натуральному пурпурному цвету, который приобретает восхитительно мерзкий багровый оттенок в контакте с кровью. Однако многие отдают предпочтение современным тенденциям моды и выбирают дерзкую желтизну льняной корпии. Не бойтесь экспериментировать!' FROM `page_text` WHERE `ID`=3230 AND MD5(`Text`)='1332631ee08386e600cc16a3ffc0c57f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3230 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3231, 'ruRU', 'Струпы и язвы\r\n\r\nОтдайте дань вашему переменчивому настроению и выразите его с помощью слегка покрытых коростой, гниющих ран, щедро покрывающих все тело. Однако не позволяйте им засыхать полностью! Зажившая рана – это признак дурного вкуса.' FROM `page_text` WHERE `ID`=3231 AND MD5(`Text`)='e4ea6961daad2e670e898741af723f1b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3231 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3232, 'ruRU', 'Черви и насекомые\r\n\r\nОх, неужели вы откажетесь завести себе нескольких домашних животных? Они неприхотливы, мало едят и прекрасно дополняют ваш разлагающийся облик. Однако если в вас завелись пчелы или осы, немедленно обратитесь на ближайшую скотобойню для дезинфекции.' FROM `page_text` WHERE `ID`=3232 AND MD5(`Text`)='86c1003c07c1ca89ba139e6bdfbcb863' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3232 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3233, 'ruRU', 'Недостающие конечности\r\n\r\nЕсли в разгар боя у вас отвалилась рука или нога, не спешите ее подбирать! Сражайтесь тем, что осталось. Наши специалисты подберут вам наилучшую замену, идеально отвечающую всем особенностям вашей анатомии. Но это будет после драки; пока же, в худшем случае, позаимствуйте недостающую часть тела у своего коллеги!' FROM `page_text` WHERE `ID`=3233 AND MD5(`Text`)='0bcd7b399e5840368623cb884967476b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3233 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3234, 'ruRU', 'Каннибализм\r\n\r\nВо избежание поедания своих же коллег, выждите пять секунд после того, как тело упало на землю, и только после этого приступайте к трапезе. Осторожно, не спутайте мертвые тела со спящими послушниками!' FROM `page_text` WHERE `ID`=3234 AND MD5(`Text`)='ee8136655181d8161a8c6e96d1126bf1' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3234 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3235, 'ruRU', 'Запись 1:\r\n\r\nВерховный генерал нашла отличный источник вербовки среди крестьян! Теперь флот Ордена растет с каждым днем, и в наших рядах нет недостатка в крепких воинах. Мы готовы нанести удар по Нордсколу и завершить эту бесконечную войну. И все же положение наше оставляет желать лучшего. Бастион Алого ордена объят пламенем, и я не могу не ощущать дыхание смерти у себя за спиной.' FROM `page_text` WHERE `ID`=3235 AND MD5(`Text`)='d9daa0a7937939447b2be03f053f706e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3235 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3236, 'ruRU', 'Запись 15:\r\n\r\nАббендис сошла с ума. Она собирается расколоть Орден и напасть на цитадель Короля-лича с горсткой преданных рыцарей. Значит ли это, что она намерена бросить Новый Авалон и Длань Тира на откуп судьбе и забрать на край света наших последних защитников?' FROM `page_text` WHERE `ID`=3236 AND MD5(`Text`)='4bb9d92330e23a2ffddfd01983c57a08' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3236 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3237, 'ruRU', 'Запись 23:\r\n\r\nЭто было солнечное утро, отражавшееся в блеске лопат и мотыг, вздымавшихся над полем, где мужчины и женщины трудились не покладая рук. Но потом на нас пала тень некрополя, и то был не Наксрамас. Плеть разбила лагерь недалеко от нашего укрепления, Аббендис приказала нам сражаться до последней капли крови. Неужели я клялся в верности Ордену только для того, чтобы погибнуть, покрывая бегство нашего генерала?' FROM `page_text` WHERE `ID`=3237 AND MD5(`Text`)='defa1a9049a21a70ed9d908d8905e5f8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3237 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3238, 'ruRU', '<Меж последних страниц дневника лежит неаккуратно сложенная карта. Похоже, автор собирался обогнуть вплавь северо-восточное побережье Лордерона и достичь Тирисфальских лесов!>' FROM `page_text` WHERE `ID`=3238 AND MD5(`Text`)='7ee66828c56c6dbdc3af37c597478970' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3238 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3239, 'ruRU', 'Я вас предупреждал: если в следующем походе мне снова придется проводить большую часть времени за чисткой сапог, кому-то придется за это ответить! С этого момента дежурства в отхожих местах будут удвоены как по времени, так и по количеству служащих! \r\n\r\n--Инструктор Разувий' FROM `page_text` WHERE `ID`=3239 AND MD5(`Text`)='ba10241b682379c5d9a611aede110967' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3239 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3240, 'ruRU', 'О, величайшая ирония! Смертные приписывают нежити самые жалкие проявления своего существования – рабское покорство, жестокость и равнодушие. Да, мы служим! Но смертные служат не меньше нас. Они поклоняются королям, богам, друидам, жрецам, людям и зверям. Мы же повинуемся только могучей воле Короля-лича, которая объединяет и сплочает всех нас!' FROM `page_text` WHERE `ID`=3240 AND MD5(`Text`)='553784fc5b95691a09a4ab8da3e691c2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3240 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3241, 'ruRU', 'Вся история человечества пронизана свидетельствами жестокости, предательства, ненависти и эгоизма. Для Плети же существует только результативность и единство. Мы служим Королю-личу в жизни и продолжаем служить ему после смерти. Он – единственный властелин, который ведет нас к победе.' FROM `page_text` WHERE `ID`=3241 AND MD5(`Text`)='e64ee00b3bc94f58fbee19d7c6572071' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3241 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3242, 'ruRU', 'Наша плоть мертва, но наше единство живет. Могущественная Плеть – это один народ, один разум, одна душа. Истинная смерть живет в бессердечных взглядах стражей, что бросают на произвол судьбы беженцев из собственной страны, оставляют увечных на поле боя. Разве люди едины? Только холодом своих сердец.' FROM `page_text` WHERE `ID`=3242 AND MD5(`Text`)='991d9d6cd65bd838687f57e996a53bd0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3242 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3243, 'ruRU', 'Так поднимем же наши знамена и низвергнем врагов! Пусть их сломленные тела примкнут к нашей армии, и вскоре все живые существа склонят колени перед Ледяным Троном!' FROM `page_text` WHERE `ID`=3243 AND MD5(`Text`)='6761fb5028adf24ffe8b96a674026950' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3243 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3244, 'ruRU', 'Наконец-то я заслужил милость настоятеля! Сегодня мне было позволено посещать Некроситет. Это будет первой ступенькой на пути к моему величию!' FROM `page_text` WHERE `ID`=3244 AND MD5(`Text`)='96be982d4f50ccd0c4f8b9d9717c7444' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3244 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3245, 'ruRU', 'Я не ожидал, что дела в Некроситете настолько запущены. Повсюду валяются груды исследовательских материалов и свитков, порой совершенно заляпанных воском от чадящих свечей. Духи, големы и демоны неприкаянно бродят по коридорам. Надо сказать, я ожидал большей ответственности от столь опытных некромантов!' FROM `page_text` WHERE `ID`=3245 AND MD5(`Text`)='4a3e7ed8c2d872bae68a2af590b3df07' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3245 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3246, 'ruRU', 'Сегодня в школу ворвалась группа бандитов и попыталась проникнуть в склепы. Подумайте только, пока они сражались с небольшой группой защитников в фойе, стоящие рядом студенты даже пальцем не пошевелили, чтобы помочь своим учителям! Их силы хватило бы на то, чтобы одолеть небольшую армию – а они продолжали свои занятия, будто ничего не не происходило! Какие болваны!' FROM `page_text` WHERE `ID`=3246 AND MD5(`Text`)='611cab8671132da4eb628bff7c6097ec' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3246 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3247, 'ruRU', 'Во время урока в классе темного магистра Гандлинга случилось еще одно происшествие. Захватчики проникли в Некроситет через смотровую комнату и достигли склепов, а этот псих спрятался за книжным шкафом и хихикал, глядя, как убивают наших школьных управляющих, одного за другим. Затем он вдруг выбежал вперед и заорал: "У нас идут занятия!". Он что, совершенно съехал с катушек? Все, я перевожусь в Стратхольм!' FROM `page_text` WHERE `ID`=3247 AND MD5(`Text`)='6acb01b774f9f75367e9e6ae34e005cb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3247 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3248, 'ruRU', 'Меня приняли на место Тузадинского некроманта в Стратхольм! Странное тут место. Не понимаю, почему никто не гасит огни. А сумасбродная система зиккуратов, связанная с вратами скотобойни, меня совершенно озадачила. Если цель в том, чтобы не подпускать никого к скотобойне – почему бы просто не запереть ворота?' FROM `page_text` WHERE `ID`=3248 AND MD5(`Text`)='3faa84ad161333901953412952ea2533' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3248 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3249, 'ruRU', 'Теперь я начинаю понимать, в чем причина всех этих недоразумений. Это наглый, заносчивый урод на гнилой кобыле, который провозглашает себя "Бароном" Ривендером, повелителем Стратхольма. По-моему, этот парень перепутал плеть с личным зоопарком, потому что каждое утро он проводит среди послушников, миньонов и големов, строя их в отряды и распределяя по разным кварталам города!' FROM `page_text` WHERE `ID`=3249 AND MD5(`Text`)='0376de4e476dd5399d8d227ef0b10a3f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3249 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3250, 'ruRU', 'После завершения ежедневного баронского парада по городу шатаются множество бездельников, круша и сжигая все вокруг. Я не раз говорил ему: "Заприте ворота!", но он продолжает настаивать, что его миньоны защитят скотобойню. В общем, мне это надоело. Немедленно собираю вещички и уматываю через задние ворота!' FROM `page_text` WHERE `ID`=3250 AND MD5(`Text`)='aeb42c6df2c42a1e550a6e31c61fb538' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3250 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3251, 'ruRU', 'Похоже, моего побега никто не заметил. Судя по клубам дыма, поднимающимся со стороны города, я ушел как нельзя вовремя. Сколько времени потрачено зря в этом Стратхольме! Небольшим утешением может служить только печатка Барона, которую я украл у этого мерзавца. Полагаю, столь благородное украшение с личным баронским гербом поможет мне уютно обосноваться в Наксрамасе.' FROM `page_text` WHERE `ID`=3251 AND MD5(`Text`)='e3c5f776585d5b6af19d9f64be6bdaef' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3251 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3252, 'ruRU', 'Сегодня я устроился на работу на военную фабрику великой Плети! Деятельность в Наксрамасе бьет ключом. К сожалению, я обнаружил, что здесь используются какие-то непонятные механизмы для питания критически важных телепортов, но, очевидно, до более элегантного решения они не додумались. Я уже задумался о том, какие выгоды могло бы принести мне такое изобретение... но присутствие этого назойливого неруба не дает мне сосредоточиться!' FROM `page_text` WHERE `ID`=3252 AND MD5(`Text`)='5c002b2dcdd61ede8be188a7f879079d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3252 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3253, 'ruRU', 'Неруб все никак не угомонится. То и дело я слышу его жуткий, монотонный голос, взывающий ко мне. Постоянно приглашает зайти к нему "заняться исследованиями". В последнее время я прячусь от него в сломанной трубе за комнатой Глута – это единственное место, где я могу побыть в одиночестве. Мой мозг скоро лопнет!' FROM `page_text` WHERE `ID`=3253 AND MD5(`Text`)='1eef031059d2aeb3f8c7ac5fb0676c1e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3253 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3254, 'ruRU', 'И как эти жалкий набор суповых костей и гниющих трупов собирается покорить весь Азерот? Они не в состоянии даже уберечь свои тела от распадания! А я не могу и надеяться на то, что мне удастся воплотить в жизнь мои планы, пока этот мерзкий нерубыц таскается за мной по пятам и отравляет все мое существование!' FROM `page_text` WHERE `ID`=3254 AND MD5(`Text`)='8806c2712ba0d851b6609baa59ef7aad' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3254 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3255, 'ruRU', 'Я уже начинаю привыкать к неожиданным нападениям во время работы. Сегодня очередная банда искателей приключений ворвалась в некрополь и стала убивать моих коллег. Увы, пали даже отважные служители культа Фарлины, прежде чем этот мерзкий паук позволил мне с ней поговорить! Ненавижу это место! Стану нежитью – сразу унесу отсюда ноги. А пока что – пора взять в руки оружие!' FROM `page_text` WHERE `ID`=3255 AND MD5(`Text`)='5c0a0aba7e6b6007fba5d666ba11576a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3255 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3256, 'ruRU', 'После нескольких попыток послужить Плети я осознал, что моим требованиям не отвечают даже самые высшие эшелоны данной организации. Учитывая неотъемлемое отсутствие гибкости, присущее любому социальному строю, усилия по внедрению перемен не приносят желаемого эффекта.' FROM `page_text` WHERE `ID`=3256 AND MD5(`Text`)='bb53cde9388ebe0e6dfcb62ba5724b6d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3256 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3257, 'ruRU', 'К счастью, данная организация предоставляет возможности для трудоустройства даже увечным, неизлечимо больным или – как в моем случае – усопшим индивидуумам.' FROM `page_text` WHERE `ID`=3257 AND MD5(`Text`)='744fbef44aff06015626547f2c0ea652' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3257 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3258, 'ruRU', 'Мне пришлось познать на себе одну истину: ледяное прикосновение смерти не приносит ничего, кроме разочарования. Да, теперь я свободен от смертных обязательств, но не испытываю от этого облегчения, ибо мне больше нечем его испытывать. Я просто существую. Я могу лишь надеяться погибнуть вновь, в эпической битве, от руки благородного и чистого духом воина.' FROM `page_text` WHERE `ID`=3258 AND MD5(`Text`)='675725b34a4bf2d775c89034a7aba504' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3258 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3259, 'ruRU', 'Некрополь был отозван назад, к Ледяной Короне. Мы получили подкрепление и продовольствие, и город снова ожил! Но я изменился. Я чувствую себя более собранным. Более живым, чем когда-либо. Меня восхищает совершенство моего Господина. Теперь я знаю, в чем заключается мой долг, и когда воины придут, им придется пережить встречу со мной.' FROM `page_text` WHERE `ID`=3259 AND MD5(`Text`)='6ce6e5c0b79b30d851c93ca3ce01b0b4' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3259 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3260, 'ruRU', 'Моооооооооззззг. Моооооооосссссзззззг. МОООЗЗЗЗЗССССГ!!!\r\n\r\n<И так еще на сорок страниц.>' FROM `page_text` WHERE `ID`=3260 AND MD5(`Text`)='97ded25946552e9f4851015bba6801b7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3260 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3261, 'ruRU', 'Мой рунический меч: один из многих, но только мой.\r\nМонография леди Бломе\r\n\r\nПриветствую тебя, новобранец. Скорее всего, инструктор Разувий уже преподал тебе первый урок о том, что значит быть рыцарем смерти. Позволь же мне познакомить тебя с самым главным сокровищем твоей новой жизни: руническим мечом.' FROM `page_text` WHERE `ID`=3261 AND MD5(`Text`)='f2b1ee8be0c7ddade1136e2a8d4d2011' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3261 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3262, 'ruRU', 'Без тебя этот клинок – всего лишь кусок железа. По отдельности вы слабы, беспомощны и не представляете угрозы. Если ты окажешься в ситуации, когда твоего рунического меча не окажется под рукой, твоя первая задача – найти ему замену, и как можно быстрее.' FROM `page_text` WHERE `ID`=3262 AND MD5(`Text`)='9e5bbe8ebfb62fc18d61ab9943f39e3e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3262 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3263, 'ruRU', 'Для рыцаря смерти рунический меч является воплощением воли самого Короля-лича. Именно с его помощью ты обрушишь гнев своего повелителя на головы неверных, и потому обладание подобным оружием – не только высочайшая привилегия, но и огромная ответственность. Поэтому тебе крайне необходимо усвоить следующие вещи:' FROM `page_text` WHERE `ID`=3263 AND MD5(`Text`)='bfceaeec684ff93079ebfb8d904547d6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3263 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3264, 'ruRU', '1) Этот клинок является продолжением твоего тела. А твое тело принадлежит Королю-личу. \r\n$B$B\r\n2) Рунический клинок в твоей руке является физическим воплощением твоей воли. А твоя воля едина с волей Короля-лича. \r\n$B$B\r\n3) Рунический клинок – это проводник смерти, наполняющей твою душу. А твоя душа – это воплощение воли Короля-лича.' FROM `page_text` WHERE `ID`=3264 AND MD5(`Text`)='ee2e96d19609e3ab87b304ac0d12f0b0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3264 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3265, 'ruRU', 'В процессе обучения тебе предстоит впитать многие знания, доступные нашему пониманию. Относись к учению с должным усердием, не пренебрегая ни единым предметом, ибо подобная беспечность свойственна лишь глупой гордыне, которая погубила не одного рыцаря смерти на поле битвы.' FROM `page_text` WHERE `ID`=3265 AND MD5(`Text`)='de2284c942204020ce42fe7dd72f5d24' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3265 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3266, 'ruRU', 'Возможно, многие из вас вскоре ощутят силу рунического меча, подпитывающую вашу ярость. Однако этого недостаточно. Не воспринимай свой клинок только как точку приложения силы. Самые могущественные рыцари смерти способны управлять клинком одним усилием разума. Вместе они способны сражаться как единое целое, как средоточие воли, пред которым не устоит ни одно смертное существо.' FROM `page_text` WHERE `ID`=3266 AND MD5(`Text`)='195bb9332c13e805c6499dbb88026c84' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3266 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3267, 'ruRU', 'Другие могут отметить, что клинок действует более эффективно, будучи заряженным энергией ледяной стужи. Даже острейшее оружие не сможет сравниться по силе с руническим мечом, наполненным силой льда. Знай же, рыцарь смерти, что тебе подвластна магия, пронизывающая саму великую цитадель – Ледяную Корону. Если ты пожелаешь совершенствоваться в искусстве управления этой стихией, у твоих врагов не будет и шанса подойти к тебе на расстояние удара, ибо холод и лед скуют их движения.' FROM `page_text` WHERE `ID`=3267 AND MD5(`Text`)='5fbbd65a4e51c85192957a766220e553' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3267 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3268, 'ruRU', 'Однако многие из вас почувствуют в себе призвание нести смерть и разрушение болезнью и чумой, пропитывающей ваши клинки. Эта специализация подвластна только самым искусным рыцарям смерти. Порой тебе будет казаться, что ты столкнулся с защитой, которую невозможно преодолеть. Но любая защита призвана скрывать слабость, и у любой брони есть уязвимые места. Помни, рыцарь смерти, что Лордерон разрушила не великая армия, но простая чума.' FROM `page_text` WHERE `ID`=3268 AND MD5(`Text`)='91e64a32fe4874ba68ef1ce532b6e5dd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3268 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3269, 'ruRU', 'Догматы Плети\r\nРаздел 1\r\nАвтор – Кел\'Тузад\r\n\r\nПлеть пустила корни вглубь каждой живущей расы, и грехи смертных питают ее стремление к величию. Так называемые "герои" склонятся перед нами, ибо их идеалы не способны привести к победе. Их победа – это мираж, путь к которому устлан горьким разочарованием, ибо Плеть выигрывает всегда, даже проиграв битву. Когда смертные, наконец, поймут эту истину, они неизбежно покорятся нашей воле.' FROM `page_text` WHERE `ID`=3269 AND MD5(`Text`)='ec2dbd8c9ba3cf666d8df4d381b9e458' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3269 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3270, 'ruRU', 'Наш Повелитель, Король-лич, был рожден под властью этих идеалов.\r\n\r\nЗавоевание – это разрушение. Разрушение – это обладание тем, что принадлежит тебе по праву, это существование и обращение в оружие недостатков смертных. Все признаки живых существ имеют синонимы, которые отражают их несовершенство: надежда – это догма, правота – это фанатизм, а существование – это жалость. Познайте, что движет смертными – и вы обретете оружие против них.' FROM `page_text` WHERE `ID`=3270 AND MD5(`Text`)='5238779b2247d9503f863efb27f1fa6b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3270 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3271, 'ruRU', 'Величайшая мудрость – знать прямой путь, ведущий к цели. Душевная слабость, физические увечья, даже болезнь могут подкосить многих смертных. Но цель Повелителя – не покорение многих, а полное подчинение. Глупо тратить бесценные ресурсы, воздействуя на жалких крестьян – с этим справится обычная чума, однако ей не под силу сломить сильных духом. Для них нужен отдельный поход, основывающийся на наших знаниях о слабости человеческой души.' FROM `page_text` WHERE `ID`=3271 AND MD5(`Text`)='a2392e75d5a3bb0018cb758cf7195474' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3271 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3272, 'ruRU', 'Догматы Плети\r\nГлава 2\r\n\r\nОценивая действия Плети, смертные пребывают в плену величайшей ошибки, коей является их определение "зла". В целях деморализации мы не собираемся развеивать это заблуждение, и даже намерены подкреплять его своими силами. Но истинное могущество Плети заключается в том, что мы свободны от моральных оков, мешающих смертным процветать.' FROM `page_text` WHERE `ID`=3272 AND MD5(`Text`)='03d051e7ccf13876bece4a65f46318a6' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3272 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3273, 'ruRU', 'Скажите мне, например, в чем сила эмоций и польза благородства? Они служат лишь для самооценки смертных, позволяют им чувствовать себя праведными. Но какую цену они вынуждены платить за эти чувства? Эмоции напрямую связаны с отрицанием логики и здравого смысла. Благородство же зачастую приводит к гибели во время заведомо проигрышной схватки. Ах, если бы смертные знали, с какой готовностью мы приветствуем их заблуждения, как культивируем их недостатки, которые лежат в основе их иррационального и глупого поведения.' FROM `page_text` WHERE `ID`=3273 AND MD5(`Text`)='8f09fb85b5b0f2cc149ea558666f8c2b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3273 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3274, 'ruRU', 'Нас нельзя очистить от душевной холодности. Нельзя смягчить нашу злость, излечить гнев и преодолеть ненависть. Они стали нашей неотъемлемой частью, хотя некоторые глупцы все еще полагают, что они способны победить Плеть и стереть любое воспоминание о ней с лица земли. До тех пор, пока смертные не очистятся от своих грехов, они сами будут воплощением нашей идеологии, кормовой базой и источником наших сил.\r\n\r\nЯ сам был рожден под властью этих идеалов.' FROM `page_text` WHERE `ID`=3274 AND MD5(`Text`)='1c803048f4511d93706a95c8ef2e9f70' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3274 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3275, 'ruRU', 'Догматы Плети\r\nГлава 3\r\n\r\nПотенциал Плети бесконечен, однако мы не безупречны. Помните о том, что наши силы и ресурсы не безграничны. Всегда думайте на шаг вперед и ищите возможные пути отступления. Жертвовать пешками для достижения победы – вот основа философии Плети. Храбрость, мученичество и патриотизм недопустимы для наших солдат, и могут быть присущи только нашему Повелителю.' FROM `page_text` WHERE `ID`=3275 AND MD5(`Text`)='7abafb53545d19a5e447623ba9eb8727' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3275 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3276, 'ruRU', 'Еще одно заблуждение смертных, касающееся Плети – это убежденность, что мы паразитируем на их обществе и не можем выжить без их участия. И снова мы не намерены избавлять их от предрассудков, хотя подобные заявления предельно далеки от истины. Мы – постоянно совершенствующая форма жизни, оптимально адаптированная к раздираемому войной миру. Бесчисленные пороки человечества не имеют над нами власти; нам не грозят перенаселение, раскол, эгоизм, недальновидность и даже смерть. Мы служим воле Повелителя, и в этом весь смысл нашей жизни.' FROM `page_text` WHERE `ID`=3276 AND MD5(`Text`)='bfa1af6ceeddc106e28c0cf922b52d7d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3276 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3277, 'ruRU', 'Действительно, мы перенимаем технологии, архитектуру и физические возможности поглощаемых нами цивилизаций, но делаем это только из присущего нам чувства прагматизма. У Плети нет ни времени, ни желания создавать собственную культуру. Существо, созидающее нечто новое, вкладывает в акт творения частичку себя, равно как желание оберегать и насаждать свое изобретение. Это ведет к появлению индивидуальности и, в свою очередь, к расколу. Созидание – это порок общества, которое должно стремиться только к обеспечению себя базовыми нуждами вроде жилья и оружия. Мы не должны задаваться вопросом, откуда берутся ресурсы; важно лишь то, насколько они полезны.' FROM `page_text` WHERE `ID`=3277 AND MD5(`Text`)='ecce1ac314c12cc3462dc0d45e34d904' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3277 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3278, 'ruRU', 'Плеть – это движущая сила земли. Рано или поздно все живые существа склонятся перед нами в простом осознании: мы необходимы им, ибо Плеть – это ключ к выживанию. От нашей воли нет противоядия, и нет силы, способной нам сопротивляться, ибо мы воплощаем в себе самую неизбежную и безграничную мощь природы – саму Смерть. Смерть – это неотъемлемая часть жизни, а загробная жизнь является неотъемлемой частью смерти. Чем скорее смертные осознают эту непреложную истину, тем проще им будет перейти на нашу сторону.' FROM `page_text` WHERE `ID`=3278 AND MD5(`Text`)='2c27fea4713a8b020d784cc1b62daef5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3278 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3279, 'ruRU', 'Прислужники, слушайте зов вашего повелителя! Король-лич даровал Дракуру всю власть над армиями Плети в Зул\'Драке. Наш приказ – убить всех!$B$BУМЕРЕТЬ ДОЛЖНЫ ВСЕ!$B$BВсе трупы будут обрабатываться в Мертвых полях и посылаться к Принцу Навариусу в Зерамас для превращения в воинов Плети! Ничто не должно пропасть зря!$B$BСкоро мы будем пить кровь пророков и станем самым сильными! Плеть раздавит Зул\'Драк и Гундрак!' FROM `page_text` WHERE `ID`=3279 AND MD5(`Text`)='f15696024fa5924076a69609e661e582' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3279 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3284, 'ruRU', '<Большая часть страниц в книге отсутствует, а оставшиеся невозможно отчистить от налипшей грязи. Однако несколько первых записей все еще можно разобрать, как и имя некоего Дариуса Ориона.>' FROM `page_text` WHERE `ID`=3284 AND MD5(`Text`)='6629280d9894467b647c897ec08293ca' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3284 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3286, 'ruRU', 'Сегодня с фермы возле Андорала доставили группу рабочих и положили в лазарет при Аметистовой цитадели. Не знаю, чем они заболели, но кто-то из них жаловался на слабость и тошноту. Надеюсь, наставники разрешат мне помогать им ухаживать за фермерами.' FROM `page_text` WHERE `ID`=3286 AND MD5(`Text`)='cd9134a66873668cfa83f878bafc40ff' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3286 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3291, 'ruRU', 'Я вышел прогуляться по террасе, и свежий воздух слегка остудил мой пыл. Жаль, мне нельзя надолго отлучаться – через пару минут надо будет возвращаться к работе. Снаружи так холодно, что мои руки мгновенно онемели, а в горле запершило. В следующий раз надо будет одеться теплее.' FROM `page_text` WHERE `ID`=3291 AND MD5(`Text`)='c1fc6282f57c0d92bf7cd809851f3f75' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3291 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3296, 'ruRU', 'Мне велели закрыться в комнате и не выходить до особого распоряжения наставника. Не понимаю, что происходит? Все сошли с ума?' FROM `page_text` WHERE `ID`=3296 AND MD5(`Text`)='71d840e3841a7ddb6ac8111305bdd1c7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3296 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3301, 'ruRU', '<Дальнейшие записи дневника разобрать невозможно.>' FROM `page_text` WHERE `ID`=3301 AND MD5(`Text`)='b03499648c9b424105ad66b556bbc917' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3301 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3306, 'ruRU', 'Многие считают магов замкнутыми и необщительными эгоистами, но это совершенно не так. Большинство волшебников – очень заботливые и внимательные к нуждам других люди. Они посвящают себя изучению тайных знаний, чтобы служить на благо другим. Хотите знать, чем маг может вам помочь? Спросите меня!' FROM `page_text` WHERE `ID`=3306 AND MD5(`Text`)='8b539a0e03253b5050bf6ef01e2dbb79' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3306 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3307, 'ruRU', 'Допустим, вы боитесь выступать перед публикой. Представьте себе вашу аудиторию в виде стада овец. Не помогает? Обратитесь к магу, и он действительно превратит ваших слушателей в баранов! \r\n\r\nПопросите вашего друга-волшебника наложить на вас чары медлительности и наслаждайтесь спокойным течением времени. Очень рекомендую подобные чары на скачках!\r\n\r\nСамый удобный способ добраться до нужного места – это телепортация. И помните – ничто так не понижает ваши шансы у противоположного пола, как исходящий от вас ЗДП. (запах дракона пустоты).' FROM `page_text` WHERE `ID`=3307 AND MD5(`Text`)='65799c5eec49660f47d59985f4cfcab2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3307 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3308, 'ruRU', 'Друг мага никогда не будет страдать от голода, жажды и ожирения – ведь волшебная пища не содержит трансгенных жиров.\r\n\r\nВы все еще думаете, что эль лучше всего охлаждать в замороженной кружке? Вы просто еще не видели кружку из чистого льда! \r\n\r\nИсследования показывают, что самые шедевральные произведения искусства были созданы под магическим воздействием.' FROM `page_text` WHERE `ID`=3308 AND MD5(`Text`)='0e39d4b6afac3418462f92f7e97de9f8' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3308 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3309, 'ruRU', 'Попросите знакомого мага создать снежную бурю на праздник Зимнего Покрова. (Внимание: нахождение в центре магической снежной бури может привести к обморожению и смерти.)\r\n\r\nИ самое главное, никогда не забывайте о том, что магам все нипочем!\r\n\r\nЭтот буклет напечатан на волшебной бумаге.' FROM `page_text` WHERE `ID`=3309 AND MD5(`Text`)='7ca644e076e95ad2544c99ba6c3182f7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3309 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3346, 'ruRU', 'Жил-был однажды маг-недоучка, который не мог создать ни огненного шара, ни ледяной стрелы. Когда он призывал воду – на него выливалась грязь, и каждая новая попытка создать что-нибудь волшебное приводила к еще более плачевным последствием. Наконец, все его учителя пришли к выводу, что их ученик, Бангледорф – самый безнадежный маг во всем Даларане.' FROM `page_text` WHERE `ID`=3346 AND MD5(`Text`)='d477b9191ddcd87ba61c6ee4d0631348' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3346 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3351, 'ruRU', 'Бангледорф зарделся от стыда и сделал шаг назад, но споткнулся о подол своего плаща. Сопровождаемый издевательским смехом, он напялил на голову свою остроконечную шляпу и побрел в свою комнату, повесив голову.' FROM `page_text` WHERE `ID`=3351 AND MD5(`Text`)='e4c7f0794f5d40bb7dc5e506aeb8ae99' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3351 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3352, 'ruRU', 'Ночная эльфийка долго смотрела ему вслед, думая о незадачливом волшебнике. Но когда она уже собралась уходить, ее нога зацепилась за что-то, чего раньше не было. Изумленная, она посмотрела на землю и обнаружила роскошный куст магорозы, расцветающий во всей своей красе. Девушка восторженно обернулась, чтобы окликнуть Бангледорфа, но юного мага уже и след простыл.' FROM `page_text` WHERE `ID`=3352 AND MD5(`Text`)='ebb08ac4ca3616aa16288cc3b695ee02' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3352 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3358, 'ruRU', '<Написано рукой верховного мага Ансарема Руноплета>' FROM `page_text` WHERE `ID`=3358 AND MD5(`Text`)='30dd739111cfd78551faccaeced6ac2f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3358 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3366, 'ruRU', '<Написано рукой верховного мага Ансарема Руноплета>' FROM `page_text` WHERE `ID`=3366 AND MD5(`Text`)='30dd739111cfd78551faccaeced6ac2f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3366 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3367, 'ruRU', 'Созидание – это наука о сотворении существ и объектов. Вам приходилось когда-нибудь умирать от жажды или испытывать муки голода? Эти неудобства неведомы магам, искусным в созидании. Призвать ломоть свежего хлеба или стакан воды – что может быть проще даже для начинающего волшебника?' FROM `page_text` WHERE `ID`=3367 AND MD5(`Text`)='e34bea142d3f3a4478f154b2068e6bee' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3367 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3368, 'ruRU', 'Более опытные заклинатели могут создать сразу несколько стаканов воды – или даже бочку. А некоторые бесстрашные маги призывали потоки воды, забыв про создание вместилища – и таким образом создавали водяных элементалей. Элементали – в отличие от гончих скверны – это лучшие друзья волшебника: они не ведают страха в бою, всегда готовы вас выслушать и к тому же приятны на вкус!' FROM `page_text` WHERE `ID`=3368 AND MD5(`Text`)='3f7d03489d53906d4fa904d63c25d5cb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3368 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3369, 'ruRU', 'Среди волшебников, специализирующихся на школе созидания, можно выделить несколько ярких личностей. Капитан Балинда Каменный Очаг – превосходный пример боевого мага, использующего созидание на поле битвы. Однако, среди наиболее известных созидателей нашего времени нельзя не упомянуть верховного мага Нилеаса Арана. Он известен не только выдающимися способностями созидать нескольких элементалей одновременно, но и своим знаменитым рецептом магического игристого сидра.' FROM `page_text` WHERE `ID`=3369 AND MD5(`Text`)='97086a35329ff988d47db1a19477f324' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3369 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3370, 'ruRU', '<Написано рукой верховного мага Ансарема Руноплета>' FROM `page_text` WHERE `ID`=3370 AND MD5(`Text`)='30dd739111cfd78551faccaeced6ac2f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3370 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3371, 'ruRU', 'Ясновидение – это искусство сбора информации. Могучие провидцы могут мысленно преодолевать огромные расстояния и даже видеть то, что недоступно человеческому глазу. Один из наиболее очевидных способов применения ясновидения – это гадание: предсказание событий, происходящих за гранью досягаемого, порой даже в иных мирах.' FROM `page_text` WHERE `ID`=3371 AND MD5(`Text`)='f537a55b443c18a0f92455d5b2461de7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3371 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3373, 'ruRU', 'Легендарный верховный маг Медив считается наиболее могущественным провидцем нашего времени. С помощью заклинаний он может заглянуть в Дренор, не покидая пределы Азерота. Мы можем только предполагать, насколько далеко простираются его способности.' FROM `page_text` WHERE `ID`=3373 AND MD5(`Text`)='4ef80a6174357008c429ad4f57475578' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3373 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3376, 'ruRU', 'Распыление – это процесс рассеивания магии, способный зачастую обратить вспять катастрофический эффект неверно прочитанного заклинания. С его помощью можно также снять чары с предмета, наделенного вошебной силой, в результате чего энергия превращается в кристаллизированную ману, которую можно использовать для наложения чар на другой предмет. Несмотря на довольно высокую стоимость подобной волшебной пыли, я рекомендую своим студентам использовать ее для практики в наложении чар.' FROM `page_text` WHERE `ID`=3376 AND MD5(`Text`)='359a65cfd2bee90c11001483e38a8998' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3376 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3378, 'ruRU', 'НЕПОБЕДИМЫЙ\r\n\r\nЗдесь покоится любимый скакун принца Артаса Менетила.\r\n\r\nПокойся с миром, мой верный и отважный друг.\r\n\r\nПусть на той стороне тебя ждут бескрайние пастбища и чистые ручьи.' FROM `page_text` WHERE `ID`=3378 AND MD5(`Text`)='fc7f198bc2fb4d6ddb7196d2ff821277' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3378 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3379, 'ruRU', '<Написано рукой верховного мага Ансарема Руноплета>' FROM `page_text` WHERE `ID`=3379 AND MD5(`Text`)='30dd739111cfd78551faccaeced6ac2f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3379 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3380, 'ruRU', 'Иллюзии – это искусство искажения самой ткани реальности. Туманные миражи могут сделать мага невидимым и неслышимым для окружающих – или наоборот, изменить человека или место до неузнаваемости. Иллюзии крайне полезны для маскировки и обмана противника, хотя школа ясновидения располагает многочисленными заклинаниями противодействия. Поэтому я категорически не рекомендую вам строить карьеру исключительно на иллюзионной магии.' FROM `page_text` WHERE `ID`=3380 AND MD5(`Text`)='56a436ff6e6b5addac8a57143512e169' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3380 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3381, 'ruRU', 'Несмотря на распространенное мнение, иллюзии – это не просто обман зрения. Заклинание невидимости – одно из наиболее важных в арсенале любого волшебника, оказавшегося в опасной ситуации, из которой наилучшим выходом является отступление. Иллюзии могут обмануть вашего врага и заставить нескольких неприятелей наброситься друг на друга. Обучиться подобным заклинаниям нелегко, но опытные иллюзионисты могут с легкостью превращать противников в союзников – и наоборот.' FROM `page_text` WHERE `ID`=3381 AND MD5(`Text`)='3d5a0f074eb5b55f297c977185d36dbe' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3381 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3382, 'ruRU', 'Бывший верховный маг Джандис Барова, пусть земля ей будет пухом, была исключительно талантливой иллюзионисткой. Незадолго до смерти ей удалось изобрести заклинание, с помощью которого она смогла создать несколько иллюзорных копий самой себя и разместить их в разных местах. Таким образом ее противники столкнулись с почти неразрешимой задачей – как найти настоящую Джандис среди множества практически неотличимых от оригинала подобий. Увы, магия – это не та дисциплина, где можно пренебрегать даже незначительными мелочами, о чем красноречиво свидетельствует прискорбное окончание этой истории.' FROM `page_text` WHERE `ID`=3382 AND MD5(`Text`)='0a32f1544c1cf517f10c4d92948f2138' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3382 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3383, 'ruRU', '<Написано рукой верховного мага Ансарема Руноплета>' FROM `page_text` WHERE `ID`=3383 AND MD5(`Text`)='062f3d0dcd4814b2211ca8de63f6bf00' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3383 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3384, 'ruRU', 'Некромантия – это раздел магии, изучающий смерть и ее последствия. Подобные изыскания незаконны и крайне опасны, и поэтому я упоминаю эту школу только для вашего общего развития. Любой волшебник должен досконально знать, какими видами магии может владеть его противник – а любой маг, практикующий некромантию, должен быть автоматически зачислен в список ваших врагов. Некроманты и их последователи отрицают саму идею жизни, и столкновения с ними лучше избегать любой ценой.' FROM `page_text` WHERE `ID`=3384 AND MD5(`Text`)='144f36a3784c496ed1cb1488cc3cb1ff' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3384 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3385, 'ruRU', 'Эта магия способна не только оживлять умерших и создавать ходячих мертвецов. Мастера некромантии могут насылать болезни, превращать тени в стрелы обжигающей энергии и даже осквернять живущих прикосновением смерти. А благодаря заклинаниям, возрождающим плоть неживых существ, созданных с помощью этой магии чудовищ крайне тяжело уничтожить.' FROM `page_text` WHERE `ID`=3385 AND MD5(`Text`)='c5065d8bd1a4e349d51fb08a956284bf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3385 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3386, 'ruRU', 'Наиболее известным последователем некромантии является бывший верховный маг Кел\'Тузад, причастный к распространению Плети и падению Лордерона. В настоящий момент Кел\'Тузад в облике лича правит парящей крепостью Наксрамас и по-прежнему представляет угрозу для всех живых существ.' FROM `page_text` WHERE `ID`=3386 AND MD5(`Text`)='ecf9b1ef6c2ff0e5f1743a4f723ccbbd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3386 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3387, 'ruRU', '<Написано рукой верховного мага Ансарема Руноплета>' FROM `page_text` WHERE `ID`=3387 AND MD5(`Text`)='062f3d0dcd4814b2211ca8de63f6bf00' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3387 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3388, 'ruRU', 'Девятая и последняя школа магии занимается преобразованием. Это одна из самых популярных дисциплин, позволяющих магу манипулировать временем и пространством. Наиболее известное заклинание этой школы – Превращение, с помощью которого волшебник может изменить форму любого существа или предмета. К счастью для многих моих учеников, действие этого заклинания легко обратимо. Мне приходилось видеть студентов, случайно превративших себя в овцу, свинью или кое-что похуже – даже не спрашивайте меня, что это значит.' FROM `page_text` WHERE `ID`=3388 AND MD5(`Text`)='29a737cf8ddb16bb0331bcc474950bf5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3388 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3389, 'ruRU', 'Второе и не менее важное изобретение школы преобразования – телепортация (и его базовая разновидность, известная как "скачок"). Это заклинание спасло жизнь не одному магу, столкнувшемуся с превосходящим по силам противником или случайно упавшему со скалы. Однако я не рекомендую вам злоупотреблять такой возможностью – телепортатор, как и сапер, ошибается только раз в жизни.' FROM `page_text` WHERE `ID`=3389 AND MD5(`Text`)='857df4d3714211838cf102c33d0ab792' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3389 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3390, 'ruRU', 'Перед активированием телепорта убедитесь, что вы точно рассчитали место назначения. Именно по этой причине я рекомендую пользоваться заклинаниями с привязкой к конкретному месту – спонтанные телепортации чаще всего заканчиваются смертью мага, оказавшегося внутри скалы, мебели или другого мага. К сожалению, бывали и такие случаи.' FROM `page_text` WHERE `ID`=3390 AND MD5(`Text`)='233d3a3ab4e249f7f2bbf8acc576da9f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3390 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3391, 'ruRU', 'К этой же школе относятся заклинания, управляющие ходом времени – например, известное всем "замедленное падение", способное уберечь мага, сорвавшегося с большой высоты (и гораздо более надежное, чем Скачок). Более опытные волшебники способны значительно замедлить противника. До меня доходили слухи о существовании заклинания, ускоряющего ваши собственные движения, но я никогда не видел ничего подобного на практике.' FROM `page_text` WHERE `ID`=3391 AND MD5(`Text`)='03dd5967d74504e9a044d0e8b3b3e5bb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3391 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3392, 'ruRU', 'Леди Джайна Праудмур – наиболее опытная волшебница, посвятившая себя искусству преобразовательной магии. Она разработала эффективную вариацию заклинания массовой телепортации, которая способна переместить значительную часть армии в другое место с минимальной затратой энергии, что делает ее весьма непредсказуемым соперником на поле битвы.' FROM `page_text` WHERE `ID`=3392 AND MD5(`Text`)='56d5cd96f9478d3378793d8854a726ad' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3392 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3393, 'ruRU', 'Автор – Илюстриэль Зеленый Лист\r\n\r\nОстановись! Подумай, что ты делаешь! Не губи свою жизнь тайной магией!' FROM `page_text` WHERE `ID`=3393 AND MD5(`Text`)='d89f8dc7e97862da90107f74045b60d7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3393 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3394, 'ruRU', 'Чистая правда:\r\n- Магия – это опасное увлечение, которое ежегодно уносит жизни миллионов людей.\r\n- Тайная магия вызывает тяжелую зависимость, от которой практически невозможно избавиться уже после прочтения первого заклинания.\r\n- Простенькое волшебство поначалу кажется невинной забавой, но в дальнейшем это приводит к употреблению все более сложных заклинаний. В худшем случае вы можете даже пристраститься к магии скверны!\r\n- Занятие магией во время беременности может нанести непоправимый вред вашему будущему ребенку.\r\n- Магическая зависимость приводит к жестокости и увлечению некромантией.\r\n- Тайная магия – это уже не модно!' FROM `page_text` WHERE `ID`=3394 AND MD5(`Text`)='6aa1bc2a2173e6738e6804646a7c804d' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3394 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3397, 'ruRU', 'В современном Азероте нас подстерегает много соблазнов, которые могут побудить вас отказаться от спокойной жизни и ступить на опасную тропу изучения магии. Но мы всегда поможем вам вернуться на путь истинный! Десятки людей уже примкнули к нашему движению и отказались от увлечения магией ради более полезных, духовных альтернатив. Хотите стать одним из нас?' FROM `page_text` WHERE `ID`=3397 AND MD5(`Text`)='28976dfffde8866950acd022f3e306f7' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3397 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3403, 'ruRU', 'Антонидас перешагнул порог академии Кирин-Тора юным, неопытным отроком, но уже тогда в нем горела жажда знаний. Он был прилежным учеником и самым частым посетителем магических библиотек Даларана. Всего через несколько лет обучения Антонидас значительно обогнал своих сверстников по учебе, чем завоевал их уважение и внимание наставников.' FROM `page_text` WHERE `ID`=3403 AND MD5(`Text`)='d9fdd6800808460dd9c7cf4fd1af06bb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3403 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3405, 'ruRU', 'Повзрослев, Антонидас не оставил своего увлечения тайной наукой. Природный дар юноши к защитной магии и несвойственная столь юному возрасту мудрость сделали его идеальным кандидатом на должность в Совете Шести, и вскоре он занял в нем заслуженное место. Антонидас проявил себя не только как рассудительный и справедливый советник, но и как глашатай просвещения. Вскоре к его голосу прислушивался весь Даларан.' FROM `page_text` WHERE `ID`=3405 AND MD5(`Text`)='76eb0d8600c16f754a1b4d60b3f261d0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3405 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3406, 'ruRU', 'Незадолго до Второй войны правители всех азеротских королевств собрались в Лордероне, чтобы обсудить угрозу нападения со стороны орков. На этом совещании Совет Шести представлял Антонидас, и именно он принес клятву верности Альянсу со стороны Даларана. Он также принимал участие в судьбе чрезвычайно талантливого мага Кадгара, который был учеником Медива во время первой войны. После окончания Второй войны Антонидас пожаловал Кадгару звание верховного мага и поручил ему важную миссию по исследованию Темного портала и Дренора.' FROM `page_text` WHERE `ID`=3406 AND MD5(`Text`)='d76424ab033c7e5558ad7fd0bdcf9cdf' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3406 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3408, 'ruRU', 'К сожалению, результаты всех этих исследований были неутешительными. Антонидас лично признавал, что исцеление орков от послевоенной депрессии – практически невыполнимая задача. Во всех своих работах он неоднократно подчеркивал, что ключ к возрождению оркской расы лежит в области духовного самосовершенствования.' FROM `page_text` WHERE `ID`=3408 AND MD5(`Text`)='7e86c3a84226cb773bf9d6a3cc74e252' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3408 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3409, 'ruRU', 'Последствия Второй войны затронули и хрупкий Альянс, затрещавший под гнетом увеличившихся налогов на содержание лагерей для военнопленных. В отсутствии общего врага на первый план снова вышли тонкости политики и мелкие стычки между расами, которые беспокоили азеротские государства еще до вторжения орков с Дренора во время Первой войны.' FROM `page_text` WHERE `ID`=3409 AND MD5(`Text`)='037aa2f1f5ff87c977bed258bd4fdcd9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3409 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3410, 'ruRU', 'Вдобавок ко всему с севера нагрянула чума. Взявшись за расследование причин возникновения эпидемии, Антонидас обнаружил, что за распространением заболевания стоит бывший член Кирин-Тор, некий Кел\'Тузад, увлекшийся изучением некромантии. Так Антонидас пришел к выводу, что чума может быть магической по происхождению. Возглавляемые верховным магом, правители Даларана решили объявить карантин на зараженных территориях.' FROM `page_text` WHERE `ID`=3410 AND MD5(`Text`)='f0e3b1754462e9182f09820fb737e5dd' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3410 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3411, 'ruRU', 'Опасаясь за последствия такого решения, король Теренас отказался последовать решению совета. И именно в тот момент к верховному магу пожаловал пророк, который предупредил Антонидаса о распространении чумы и предсказал падение Азерота. Он велел Антоидосу собрать своих людей и отправить на запад, в Калимдор, утверждая, что это единственный способ спасти народ Даларана.' FROM `page_text` WHERE `ID`=3411 AND MD5(`Text`)='46240e173c9df70cfc3fd381b5778810' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3411 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3412, 'ruRU', 'Антонидасу на тот момент уже минуло семьдесят лет. Он был мудр, но в то же самое время крайне осторожен и упрям. Его ученица, леди Джайна Праудмур, почувствовала великую силу пророка и посоветовала прислушаться к его словам, но верховный маг не принял во внимание ее рекомендации и посчитал старца обычным безумцем.' FROM `page_text` WHERE `ID`=3412 AND MD5(`Text`)='062f1a1c74ac71771ede1cabd60d95ad' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3412 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3413, 'ruRU', 'Антонидас принял решение продолжить расследование причин возникновения чумы на севере, ибо в этих исследованиях он видел путь к спасению своего города. Результаты этих изысканий можно прочитать в книге "Дневник верховного мага Антонидаса". Известно то, что он привлек к своей работе Дажйну, к которой должен был вскоре присоединиться принц Артас Менетил.' FROM `page_text` WHERE `ID`=3413 AND MD5(`Text`)='50431dca3dc723aa7354a2c6d69a684a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3413 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3414, 'ruRU', 'Пока Антонидас искал возможность остановить распространение чумы, Артас сошел с ума, разрушил Стратхольм и отправился в Нордскол в погоне за повелителем ужаса Мал\'Ганисом. Прежде, чем стареющий верховный маг смог найти вакцину, Артас в сопровождении лича Кел\'Тузада и его армии нежити проследовал на юг через Тирисфаль и Лордерон, уничтожая все на своем пути и пополняя свое войско новыми мертвецами.' FROM `page_text` WHERE `ID`=3414 AND MD5(`Text`)='bab807af91b7ce224ac3f858b16a0d37' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3414 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3420, 'ruRU', 'Жил-был однажды маленький зайчик. Его звали Пушок.' FROM `page_text` WHERE `ID`=3420 AND MD5(`Text`)='4d070a90c3a104ad975019e1fa70f05a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3420 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3443, 'ruRU', 'Мы не ставим перед собой цель полностью вытеснить из употребления традиционные методы перемещения – корабли, дирижабли и ездовых животных. Данные виды транспорта дешевы, удобны и безопасны. Однако правильно установленный портал не менее надежен и гораздо более практичен. К сожалению, открытие порталов для общего пользования – крайне энергоемкий процесс. Из всех заклинаний, придуманных и разработанных Кирин-Тором, телепортация наиболее близко подошла к тому, чтобы быть включенной в список чар, используемых только в крайних случаях.' FROM `page_text` WHERE `ID`=3443 AND MD5(`Text`)='93f08234eb5256b9c6f57aa53742379e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3443 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3469, 'ruRU', 'Доводим до вашего сведения, что наша организация проводит регулярные рейды по очистке Круговерти Пустоты от пропавших предметов. Зачастую мы находим разнообразные утерянные сокровища – от расколотых магических кристаллов силы до полных комплектов брони и оружия, но в последнее время нам все чаще приходится иметь дело с бытовым мусором.' FROM `page_text` WHERE `ID`=3469 AND MD5(`Text`)='41564f2a295d14df08c206d11e5b1a43' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3469 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3471, 'ruRU', 'Если подобное будет продолжаться, мне придется ввести ограничение, вследствие которого любой путешественник будет вынужден сдавать все свое вооружение и предметы личной гигиены перед использованием портала. А если в следующий раз я обнаружу среди мусора конспекты со своих лекций, я лично превращу головы повинных в этом студентов в ночные урны. \r\n\r\n--Верховный маг Руноплет' FROM `page_text` WHERE `ID`=3471 AND MD5(`Text`)='bc0e1611bd5ede1886ba339100baf562' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3471 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3488, 'ruRU', 'Если же вы желаете отобедать в менее популярном и шумном месте, загляните в "Фокус-Покус", расположенный недалеко от центра города. В этом светлом и уютном баре вас ждут легкие закуски в приятной атмосфере, напоминающей библиотеку. В это место частенько наведываются студенты магической школы, поэтому коронное блюдо сего заведения появляется само по себе и готовится прямо у вас на глазах.' FROM `page_text` WHERE `ID`=3488 AND MD5(`Text`)='22b2f7ae75154e6c7a09021ed1014156' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3488 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3489, 'ruRU', 'А коли вам хочется просто снять комнату, предварительно угостившись в баре, ищите заведение с вывеской "Грязное животное". Непередаваемая атмосфера самого злачного бара в городе буквально притягивает к себе подозрительных личностей и криминальных элементов. Меню изобилует такими деликатесами, как соленый заплесневевший сыр, а для придания жилого вида комнатам понадобится не меньше дюжины зачарованных метел и несколько дней работы. Истинный рай для ордынцев!' FROM `page_text` WHERE `ID`=3489 AND MD5(`Text`)='eff427543b65632c38bd0b4b39fbf41f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3489 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3490, 'ruRU', '<Многие записи в этом потрепанном дневнике вырваны или их просто невозможно разобрать.>\r\n\r\nЧто подумает Николай? Я не могу рассказать ему про голос, хотя меня так и подмывает поделиться с ним. Впрочем, не исключено, что это ко мне взывает моя совесть.' FROM `page_text` WHERE `ID`=3490 AND MD5(`Text`)='efb7b0bca51851c448846024c5d4e08b' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3490 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3491, 'ruRU', 'Голос этот не похож на эхо – скорее на мягкий шепот в голове, которые уверяет меня, что все только начинается. Как головная боль – только наоборот (если это вообще имеет смысл): такая теплая волна мыслей и идей. Например, я точно знаю, что библиотекарша прячет какие-то книги, а голос подсказывает мне, что это литература по демонам, и что она в них разбирается так же, как свинья в апельсинах.' FROM `page_text` WHERE `ID`=3491 AND MD5(`Text`)='e3e368b6187f77f3e5b06d25a47cb15a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3491 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3492, 'ruRU', 'Моя совесть вновь была права. Я достоин большего, чем просто быть адептом занюханной школы магии. Вместо каждого бисквита, который могут создать мои одноклассники, я могу призвать целый обед. Кажется, Николай заметил произошедшие со мной перемены. Неужели он испуган? Совесть говорит, что старшие маги называют это уважением.' FROM `page_text` WHERE `ID`=3492 AND MD5(`Text`)='67d7b17beb931cbd1fc9c9595b36fd50' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3492 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3493, 'ruRU', 'Я мог бы найти его – он сейчас на севере. Я буквально вижу путь к нему. Искупление возможно. Еще не слишком поздно... Я могу снова воссоединить его, сделать лучше, чем когда-либо! Мои силы растут с каждым днем... я могу осчастливить нас всех! Мама, папа, Николай... все мы...' FROM `page_text` WHERE `ID`=3493 AND MD5(`Text`)='9c0d720dce019c735db6b88f559dbb49' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3493 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3494, 'ruRU', 'Николай меня боится; его глаза выдают то, что не отваживаются сказать губы. Ничего; знания и совесть подтверждают, что страх и уважение лежат в одной плоскости. Если он меня покинет, я сделаю так, что никто не сможет прикоснуться к тому, что мне принадлежит. В конце концов, мои сестры будут с нами.' FROM `page_text` WHERE `ID`=3494 AND MD5(`Text`)='9c285fa7d494f3d20708b34e5820006e' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3494 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3495, 'ruRU', '... угрожает пожаловаться на меня или даже исключить, если я не исправлю то, что сделал с его кошкой. Не понимаю, почему его так волнует эта старая мохнатая мышеловка? О себе бы лучше позаботился. Как они смеют защищать его, когда он набросился на меня прямо перед Николаем?' FROM `page_text` WHERE `ID`=3495 AND MD5(`Text`)='abad364781023d3604791ee7169963fa' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3495 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3496, 'ruRU', 'А мать еще имеет смелость отчитывать меня... Она что, не понимает, кто я такой? Я уже чувствую, как он зовет меня за собой. Этот город не заслуживает моего внимания. В кухне достаточно продуктов для дальней дороги... Николай с матерью и этой чертовой кошкой сделают то, что я им прикажу. Деньги в мамином шкафу – мои по праву. Только я могу ему помочь.\r\n\r\n<Это последняя запись. Следующие страницы пусты.>' FROM `page_text` WHERE `ID`=3496 AND MD5(`Text`)='b19f542cf3e4a3046737e6178f2eb155' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3496 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3536, 'ruRU', 'Ваше величество!\r\n\r\nО, милосердный король, да озарит Свет каждый ваш шаг, и да пребудет он вечно в вашем сердце. Я молю вас о пощаде для этого павшего рыцаря, и смиренно прошу выслушать меня до конца.\r\n\r\nПодатель сего письма некогда $gбыл:была; героем Альянса. Хотя отныне тело $gего:её; отмечено печатью смерти и обликом Плети, душой $gон остался верен:она осталась верна; вашему величеству.' FROM `page_text` WHERE `ID`=3536 AND MD5(`Text`)='aa121b465c60038bc71b3a5dcde84734' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3536 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3537, 'ruRU', '$N $gбыл избран:была избрана; мной в качестве представителя нового союза, сражающегося против Короля-лича. Этот орден носит имя Рыцарей Черного Клинка. Да, ваше величество, вы не ошибаетесь: рыцари смерти объединились против своего бывшего повелителя. Их возглавляет сын лорда Александроса Могрейна – сам Испепелитель, и жаждут они того же, что и все мы: положить конец Плети.\r\n\r\nЯ не смею просить вас принять $N и всех Рыцарей Черного Клинка в Альянс, но надеюсь, что вы проявите к ним снисхождение.' FROM `page_text` WHERE `ID`=3537 AND MD5(`Text`)='db181f8515ac5b83afc5593269daf673' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3537 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3538, 'ruRU', 'Помните, сир, что все мы служим кровью и честью во имя великой цели.\r\n\r\nС глубочайшим уважением,\r\n\r\nВерховный лорд Тирион Фордринг' FROM `page_text` WHERE `ID`=3538 AND MD5(`Text`)='c6444b0b989c1916e00a3c9609f1235a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3538 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3539, 'ruRU', '<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>О, великий вождь!<br /><br />да озарит Свет каждый ваш шаг, и да пребудет он вечно в вашем сердце. Я молю вас о пощаде для этого павшего рыцаря, и смиренно прошу выслушать меня до конца.<br /><br />Податель сего письма некогда &lt;был/была&gt; героем Орды. Хотя отныне чело &lt;его/ее&gt; отмечено печатью смерти и обликом Плети, душой &lt;он остался верен/она осталась верна&gt; нашему делу.' FROM `page_text` WHERE `ID`=3539 AND MD5(`Text`)='514f84a6f894ca7ccdaf178804356c14' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3539 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3541, 'ruRU', '<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Помните, вождь, что все мы служим кровью и честью во имя великой цели.<br /><br />С глубочайшим уважением,<br /><br />Верховный лорд Тирион Фордринг<br />P.S. Передайте Эйтриггу мои пожелания долгого здравия и скажите ему, что мне не помешает такой союзник в Нордсколе – разумеется, если вы не будете возражать.' FROM `page_text` WHERE `ID`=3541 AND MD5(`Text`)='9503a0fee53238451cea1553fdc98236' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3541 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3543, 'ruRU', 'Долгие годы я был заключен в этой магической тюрьме. Сегодня я вырвусь на свободу. Теперь у меня есть все, что нужно для побега.\r\n\r\n<В этой части письма чернила расплылись под воздействием воды>\r\n\r\nПочему меня заключили здесь? Чем я заслужил такое наказание? День за днем я задавал себе эти вопросы. Что можно было натворить, чтобы заслужить такую кару?\r\n\r\n<В этой части письма чернила расплылись под воздействием воды>\r\n\r\nВозможно, я найду ответы в следующей жизни.' FROM `page_text` WHERE `ID`=3543 AND MD5(`Text`)='51a0f3acd227d2db9636d8303be51540' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3543 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3545, 'ruRU', 'Ветхие страницы книги хранят лишь хозяйственные записи с фермы Валган. Смена времен года, проращивание семян и укоренение саженцев, рождение и смерть детей.\r\n\r\nЗаписи неожиданно прерываются, оканчиваясь сумбурным описанием чумы. Вряд ли хоть один из ребятишек успел пройти рыцарское обучение, если даже и пережил чуму.' FROM `page_text` WHERE `ID`=3545 AND MD5(`Text`)='49ca79d52487e1f16a95681e8afa4db9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3545 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3546, 'ruRU', 'Первая половина дневника - всего лишь амбарная книга мистера Купера. Колонки цифр, относящихся к производству и сбыту товаров жителям Луноречья и даже нескольким штормградским горожанам.$B$Bво второй половине тетради - дневник Купера, где он говорит о том, что оставляет семейное дело младшему брату. Здесь упоминаются и дети.' FROM `page_text` WHERE `ID`=3546 AND MD5(`Text`)='db3799082f20b2f6f71fb653a5febde3' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3546 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3558, 'ruRU', '<HTML>\r\n<BODY>\r\n<P>Первая фаза строительства завершена. Адмирал Вествинд приказал моим людям основать на севере несколько укреплений. Зачем это надо – он не объяснил, сославшись на "повеление свыше".</P>\r\n<BR/>\r\n<P>Сегодня днем поймали четырех шпионов Отрекшихся из Ядозлоби. Надо бы приказать Лекрафту вытянуть из них информацию под пытками. Если мы поймали четверых – то сколько еще могли проскользнуть мимо нас?</P>\r\n<BR/>\r\n<P>Почему у меня такое чувство, будто все катится под откос?</P>\r\n</BODY>\r\n</HTML>' FROM `page_text` WHERE `ID`=3558 AND MD5(`Text`)='f01d85d2b6d5b03e510d99cffcd95256' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3558 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3562, 'ruRU', 'Из-за ограды даларанского палисадника выглянула крошечная гномка.\r\n\r\n"Вид с балкона чудесный! Иди сюда, погляди!"\r\n\r\nЗаскрипели латные поножи – это Марк стал подниматься наверх. Поднявшись, он вздохнул и задумчиво почесал подбородок.\r\n\r\n"В "Благодарности за отвагу" так уютно. В этой комнате тебе кое-что очень понравится!"\r\n\r\nТави вбежала в комнату, замерев лишь на мгновенье перед тем, как броситься в огромную кровать. Оттуда она стала посылать влажные выразительные взгляды Марку, то широко распахивая глаза, то игриво прикрывая их. Ее нежная улыбка сменилась дьявольской усмешкой.' FROM `page_text` WHERE `ID`=3562 AND MD5(`Text`)='a811d1cf69b0cf50db6cb5aa02c6b33c' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3562 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3563, 'ruRU', '"Позовем еще кого-нибудь?" – промурлыкала Тави, производя руками замысловатые пассы ритуала призыва. Почувствовав наконец присутствие призванного, она замерла.\r\n\r\nНа лице Марка не осталось ни кровинки, он всеми силами пытался выразить протест. "Я... не думаю, что это удачная мысль."\r\n\r\nОзадаченная Тави оглянулась посмотреть, в чем дело. За ее спиной стояла гончая Скверны, капая слюной на пол и пожирая глазами полуодетого паладина.\r\n\r\n"Нет! Я совсем не ее хотела призвать", – запинаясь, пробормотала она, изгоняя голодного монстра. "Прости, я не совсем по этой части..."' FROM `page_text` WHERE `ID`=3563 AND MD5(`Text`)='cc1dbe97294419fce91ec8917f934bc5' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3563 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3564, 'ruRU', 'Марк сжал ее ручки в своей и постарался успокоить девушку. "Все в порядке. А какая у тебя специализация?"\r\n\r\nОна вскинула голову и глаза ее загорелись: Тави заставила Марка скорчиться на коленях перед собой от болезненной темной энергии, которой она его наполнила.\r\n\r\n"Вообще-то колдовство."' FROM `page_text` WHERE `ID`=3564 AND MD5(`Text`)='536dd1cd017ca2d376896164d703e26f' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3564 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3565, 'ruRU', 'Заскрипев зубами, Марк выпрямился и осветился внутренним сиянием.\r\n\r\nТави беспокойно взглянула на него, когда он встал во весь рост и накрыл ее своей тенью. Паладин выбросил вперед руку и направил волну праведной силы сквозь гномку. Ее глаза закатились, и она беспомощно покачнулась, теряя сознание.\r\n\r\n"Недавно я выбрал путь... воздаяния."\r\n\r\nВероломная бесстыдница постаралась овладеть собой. "Ну что ж, скучать не придется."\r\n\r\n<Для прочтения остальных страниц требуется 99 уровень.>' FROM `page_text` WHERE `ID`=3565 AND MD5(`Text`)='50e2d599a0afda2f00ee554591197b64' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3565 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3569, 'ruRU', 'Добрейший доктор Колер!$B$BЧерный Рыцарь еще не исполнил своего предназначения. Соберите его останки на Ристалище и используйте свое искусство, чтобы вернуть его к жизни. Мы обратим силу крестоносцев и их последователей против них самих.$B$BЗахватите пленных и вдохните их  души в моего верного слугу. Принесите рыцаря Кула, прозванного боевыми товарищами "отчаянным", в жертву на вашем алтаре. Его дух наделит Черного Рыцаря ужасающей силой и мощью. После этого доставьте Черного Рыцаря ко мне.' FROM `page_text` WHERE `ID`=3569 AND MD5(`Text`)='d4fdcc7b8738f376b5ae55dead0972e2' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3569 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3596, 'ruRU', 'Поистине редки радужные клинки, созданные по объединенной воле пяти драконьих родов. Среди величайших из них – мечи-братья Кель\'Серрар и Кель\'Делар.$B$BМудрая королева драконов Алекстраза подарила их эльфам Азерота: каждому из двух эльфийских народов досталось по мечу. Кель\'Серрар был создан для доблестных калдорайских воителей, а Кель\'Деларом владели кель\'дорайские герои.$B$BВ руках своих обладателей клинки менялись, магическим образом усиливая их способности...' FROM `page_text` WHERE `ID`=3596 AND MD5(`Text`)='b2720da6bed20cd6c10a7d0791d65343' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3596 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3600, 'ruRU', 'Похоже, это предок здешних динозавров. Я провел несколько недель, выкапывая его, и это самая значительная из всех моих находок. По моим подсчетам, этот зверь был около 300 футов длиной от носа до хвоста. Он был крупнее самых крупных драконов и НАМНОГО крупнее любого динозавра, живущего в кратере в наши дни.' FROM `page_text` WHERE `ID`=3600 AND MD5(`Text`)='b1da60880c6209e3bf514abbf1c1afd9' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3600 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3605, 'ruRU', 'Памяти тех, кто пал от оружия Плети в войне на ледяных пустошах.' FROM `page_text` WHERE `ID`=3605 AND MD5(`Text`)='1cf939c83bf45f033aa1bc0bcce56337' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3605 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3611, 'ruRU', 'Куда отправитесь вы, когда пламя поглотит Азерот?$B$BНикому не хочется думать о грядущем судном часе, и все же о будущем следует позаботиться заранее.$B$BНаши волхвы предвидят, что конец этого мира близок, и спасутся только те, кто успеет подготовиться. Мы поможем вам пройти сквозь бушующий огонь преисподней, который очистит мир от зла. Вы согласны снова обрести душевный покой?' FROM `page_text` WHERE `ID`=3611 AND MD5(`Text`)='523fbab625516d8a3ce6e7318b14cf20' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3611 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3612, 'ruRU', 'Вам, конечно, приходилось слышать выражение "Все хорошее когда-нибудь обязательно заканчивается". Скоро вы лично сможете удостовериться в его правдивости... Близится тот час, когда весь Азерот погрузится в пучину хаоса и первородные силы вырвутся на поверхность.$B$BНо вы не должны страшиться грядущих кошмаров, ведь есть надежда на спасение. Мы поможем вам на пути к новой жизни: без потерь, без страха и бессилия, которое присуще всем смертным. Приходите сегодня.' FROM `page_text` WHERE `ID`=3612 AND MD5(`Text`)='146d9e4a86bdc6bdc1f61e4af4eeba0a' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3612 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3613, 'ruRU', 'Мы живем в неспокойные времена. Войны, агрессия и голод захлестнули мир. Однако настоящее испытание еще впереди: гибель Азерота!$B$BКак пережить потерю всего, что вам дорого?! Выход кроется в том, что вам, возможно, и не придется страдать. Приходите на одно из наших собраний вместе с семьей и друзьями – и вы узнаете, как с нашей помощью можно пережить апокалипсис вместе.' FROM `page_text` WHERE `ID`=3613 AND MD5(`Text`)='34611d981004c64f220b31c431abf0cb' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3613 AND x.`locale`='ruRU');
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`) SELECT 3622, 'ruRU', 'Обворожительная девушка перешла озеро и, помахивая хвостом, плывущей походкой направилась к мужчине, отдыхающему на берегу. При ее появлении он поднялся, его лицо озарилось светом счастья. Голубые руки скользнули по его плечам, а гладкий хвост недвусмысленно обвился вокруг пояса. "Объяснишь, ради чего мне пришлось искать тебя... " В ее речи слышался резкий, но вместе с тем очаровательный акцент.$b$bШироко улыбаясь, он мягко отстранил ее от себя, откровенно любуясь ее чертами в лучах солнца.$b$b"...в этой глуши?" – закончила она гневно, но при этом лукавые огоньки заиграли в ее глазах.$b$bОбезоруживающе пожав плечами, он потянулся к сумке и достал оттуда небольшой мешочек. "Моя прекрасная Соола, я хочу подарить тебе одну вещь," – его слова прозвучали твердо и уверенно.' FROM `page_text` WHERE `ID`=3622 AND MD5(`Text`)='bc9e3ebf97b0b2131be6e5f9fe3ce7c0' AND NOT EXISTS (SELECT 1 FROM `page_text_locale` x WHERE x.`ID`=3622 AND x.`locale`='ruRU');
